@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700;800;900&display=swap');

.connectivity-gate {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background: radial-gradient(circle at top, #eefbf5 0, #f8fafc 48%, #e2e8f0 100%);
  font-family: Poppins, system-ui, sans-serif;
}

