/* VPAA insight accordions: accessible, consistent header contrast. */
.department-ai-page .department-ai-accordion {
  border-color: #b7ddca;
  background: #ffffff;
}

.department-ai-page .department-ai-accordion:hover,
.department-ai-page .department-ai-accordion.is-open {
  border-color: #69b58f;
  box-shadow: 0 8px 22px rgba(20, 105, 70, 0.1);
}

.department-ai-page .department-ai-accordion-trigger,
.department-ai-page .department-ai-accordion-trigger:hover,
.department-ai-page .department-ai-accordion-trigger:focus-visible {
  background: linear-gradient(135deg, #effaf4 0%, #e4f5ec 100%);
  color: #153c2c;
}

.department-ai-page .department-ai-accordion-trigger strong {
  color: #153c2c;
}

.department-ai-page .department-ai-accordion-trigger small {
  color: #587064;
}

.department-ai-page .department-ai-accordion-trigger svg {
  color: #168358;
}

.admin-body.dark-mode .department-ai-page .department-ai-accordion,
.admin-dashboard-body.dark-mode .department-ai-page .department-ai-accordion,
body:has(.admin-dashboard-body.dark-mode) .department-ai-page .department-ai-accordion {
  border-color: rgba(94, 234, 212, 0.28);
  background: #111827;
}

.admin-body.dark-mode .department-ai-page .department-ai-accordion-trigger,
.admin-dashboard-body.dark-mode .department-ai-page .department-ai-accordion-trigger,
body:has(.admin-dashboard-body.dark-mode) .department-ai-page .department-ai-accordion-trigger {
  background: linear-gradient(135deg, #183b35 0%, #172f2d 100%);
  color: #f0fdfa;
}

.admin-body.dark-mode .department-ai-page .department-ai-accordion-trigger strong,
.admin-dashboard-body.dark-mode .department-ai-page .department-ai-accordion-trigger strong,
body:has(.admin-dashboard-body.dark-mode) .department-ai-page .department-ai-accordion-trigger strong {
  color: #f0fdfa;
}

.admin-body.dark-mode .department-ai-page .department-ai-accordion-trigger small,
.admin-dashboard-body.dark-mode .department-ai-page .department-ai-accordion-trigger small,
body:has(.admin-dashboard-body.dark-mode) .department-ai-page .department-ai-accordion-trigger small {
  color: #b7d8ce;
}

.department-card-cover {
  position: relative;
  min-height: 120px;
  display: grid;
  place-items: start;
  padding: 18px;
  background:
    linear-gradient(135deg, rgba(18, 61, 53, 0.78), rgba(15, 23, 42, 0.72)),
    url('/assets/images/pmas-campus-bg.jpg');
  background-size: cover;
  background-position: center;
  color: white;
}

.department-card-cover span {
  position: relative;
  z-index: 1;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.18);
  padding: 6px 12px;
  font-weight: 800;
}

.department-card-body {
  padding: 18px;
}

.department-card-body h3 {
  margin: 0;
  color: #123d35;
  font-size: 1.1rem;
  font-weight: 900;
}

.people-management-page {
  display: grid;
  gap: 20px;
}

.department-ai-page {
  display: grid;
  gap: 20px;
}

.department-ai-hero {
  display: grid;
  gap: 18px;
  border-radius: 18px;
  background: linear-gradient(135deg, #123d35, #1f7a4f 58%, #2e965f);
  padding: 26px;
  color: #ffffff;
  box-shadow: 0 18px 45px rgba(18, 61, 53, 0.12);
}

.department-ai-hero h2 {
  margin: 0;
  color: #ffffff;
  font-size: clamp(1.8rem, 4vw, 3rem);
  font-weight: 900;
}

.department-ai-hero p {
  max-width: 760px;
  color: rgba(255, 255, 255, 0.86);
}

.department-ai-hero label {
  display: grid;
  gap: 7px;
  color: #d1fae5;
  font-size: 0.78rem;
  font-weight: 900;
  text-transform: uppercase;
}

.department-ai-hero select {
  min-height: 44px;
  min-width: min(300px, 100%);
  border: 1px solid rgba(255, 255, 255, 0.28);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.96);
  padding: 0 12px;
  color: #123d35;
  outline: none;
}

.department-ai-scope {
  display: grid;
  gap: 6px;
  min-width: min(300px, 100%);
  border: 1px solid rgba(255, 255, 255, 0.24);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.14);
  padding: 12px 14px;
  color: #ffffff;
  backdrop-filter: blur(12px);
}

.department-ai-scope span {
  color: #d1fae5;
  font-size: 0.72rem;
  font-weight: 900;
  text-transform: uppercase;
}

.department-ai-scope strong {
  color: #ffffff;
  font-size: 0.95rem;
}

.department-ai-grid {
  display: grid;
  gap: 18px;
}

.department-ai-card {
  display: grid;
  gap: 16px;
  border: 1px solid #dfeae4;
  border-radius: 18px;
  background: #ffffff;
  padding: 18px;
  box-shadow: 0 14px 30px rgba(18, 61, 53, 0.08);
}

.department-ai-card-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: start;
}

.department-ai-card-head span,
.department-ai-recommendation span {
  color: #1f7a4f;
  font-size: 0.76rem;
  font-weight: 900;
  text-transform: uppercase;
}

.department-ai-card-head h3 {
  margin: 4px 0 0;
  color: #123d35;
  font-size: 1.15rem;
  font-weight: 900;
}

.department-ai-summary {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.department-ai-summary > div,
.department-ai-recommendation {
  border-radius: 16px;
  padding: 14px;
}

.department-ai-summary .weak {
  border: 1px solid #fde68a;
  background: #fffbeb;
  color: #92400e;
}

.department-ai-summary .strong {
  border: 1px solid #b5e5c9;
  background: #effaf3;
  color: #18584c;
}

.department-ai-summary span,
.department-ai-summary small {
  display: block;
  font-size: 0.78rem;
  font-weight: 900;
}

.department-ai-summary strong {
  display: block;
  margin-top: 4px;
  font-size: 1rem;
}

.department-ai-ranking {
  display: grid;
  gap: 10px;
}

.department-ai-ranking h4 {
  margin: 0;
  color: #334155;
  font-size: 0.92rem;
  font-weight: 900;
}

.department-ai-rank-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px 12px;
  align-items: center;
}

.department-ai-rank-row span {
  color: #475569;
  font-weight: 800;
}

.department-ai-rank-row strong {
  color: #123d35;
  font-weight: 900;
}

.department-ai-rank-row .mini-progress {
  grid-column: 1 / -1;
  margin-top: 0;
}

.department-ai-recommendation {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 12px;
  border: 1px solid #b5e5c9;
  background: linear-gradient(135deg, #effaf3, #ffffff);
  color: #18584c;
}

.department-ai-recommendation strong {
  display: block;
  color: #123d35;
}

.department-ai-recommendation p {
  margin: 6px 0 0;
  color: #52635b;
  font-size: 0.9rem;
  line-height: 1.5;
}

.people-management-hero {
  display: grid;
  gap: 20px;
  overflow: hidden;
  border-radius: 18px;
  padding: 28px;
  border: 1px solid var(--theme-border, #dbe7e1);
  background: var(--theme-surface, #ffffff);
  color: var(--theme-text, #10201b);
  box-shadow: 0 12px 28px rgba(31, 54, 45, 0.08);
}

.people-management-hero .eyebrow {
  color: var(--theme-primary, #166a45);
}

.people-management-hero h2 {
  margin: 0;
  font-size: clamp(1.8rem, 4vw, 3rem);
  font-weight: 900;
  color: var(--theme-text, #10201b);
}

.people-management-hero p:not(.eyebrow) {
  max-width: 760px;
  color: var(--theme-muted, #4d5f57);
}

.admin-body.dark-mode .people-management-hero {
  display: grid;
  gap: 20px;
  overflow: hidden;
  border-radius: 18px;
  background: linear-gradient(135deg, #123d35, #1f7a4f 58%, #2e965f);
  padding: 28px;
  color: #ffffff;
  box-shadow: 0 18px 45px rgba(18, 61, 53, 0.1);
}

.admin-body.dark-mode .people-management-hero h2 {
  color: #ffffff;
}

.admin-body.dark-mode .people-management-hero p:not(.eyebrow) {
  color: rgba(255, 255, 255, 0.86);
}

.people-management-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: end;
}

.people-management-actions button,
.people-card-actions button,
.people-modal-panel .compact-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.people-filter-panel,
.people-section {
  border: 1px solid #e5ece8;
  border-radius: 18px;
  background: #ffffff;
  box-shadow: 0 12px 28px rgba(31, 54, 45, 0.08);
}

.people-filter-panel {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  gap: 14px;
  padding: 18px;
}

.people-search-field {
  grid-column: span 2;
}

.people-period-scope-notice {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  padding: 14px 18px;
  border: 1px solid rgba(22, 140, 92, 0.24);
  border-radius: 16px;
  background: linear-gradient(135deg, rgba(231, 248, 240, 0.96), rgba(239, 249, 255, 0.96));
  color: #145c42;
  box-shadow: 0 10px 24px rgba(31, 93, 70, 0.08);
}

.people-period-scope-notice div {
  display: grid;
  gap: 2px;
}

.people-period-scope-notice span {
  color: #526b61;
  font-size: 0.86rem;
}

.people-period-scope-notice > b {
  padding: 7px 11px;
  border-radius: 999px;
