.people-filter-panel label {
  display: grid;
  gap: 7px;
  color: #334155;
  font-size: 0.86rem;
  font-weight: 800;
}

.people-filter-panel input,
.people-filter-panel select {
  min-height: 44px;
  width: 100%;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  background: #ffffff;
  padding: 10px 12px;
  color: #1e293b;
  outline: none;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.people-filter-panel input:focus,
.people-filter-panel select:focus {
  border-color: #2e965f;
  box-shadow: 0 0 0 4px #d9f2e2;
}

.people-search-field div {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  padding: 0 12px;
}

.people-search-field input {
  border: 0;
  padding-left: 0;
}

.people-search-field input:focus {
  box-shadow: none;
}

.people-section {
  overflow: hidden;
}

.people-department-grid,
.people-user-grid {
  display: grid;
  gap: 12px;
  padding: 14px;
}

.people-department-card,
.people-user-card {
  display: grid;
  gap: 0;
  border: 1px solid #e5ece8;
  border-radius: 16px;
  background: #ffffff;
  overflow: hidden;
  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}

.people-department-card:hover,
.people-user-card:hover {
  transform: translateY(-3px);
  border-color: #b5e5c9;
  box-shadow: 0 18px 45px rgba(18, 61, 53, 0.1);
}

.people-card-cover,
.people-department-card-cover {
  position: relative;
  min-height: 88px;
  display: grid;
  place-items: start center;
  padding: 12px;
  background:
    linear-gradient(135deg, rgba(18, 61, 53, 0.58), rgba(15, 23, 42, 0.80)),
    url('/assets/images/pmas-campus-bg.jpg');
  background-size: cover;
  background-position: center;
  color: white;
}

.people-card-cover::after,
.people-department-card-cover::after,
.department-card-cover::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(15, 23, 42, 0.04), rgba(15, 23, 42, 0.50));
  pointer-events: none;
}

.people-card-cover span,
.people-department-card-cover span {
  position: relative;
  z-index: 1;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.18);
  padding: 5px 10px;
  font-weight: 800;
  font-size: 0.68rem;
}

.people-card-body,
.people-department-card-body {
  padding: 14px;
  display: grid;
  gap: 10px;
}

.people-department-card-body {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 10px;
  align-items: start;
}

.people-department-card-body .people-department-logo {
  grid-row: 1 / 3;
}

.people-department-card-body .people-department-copy {
  grid-row: 1 / -1;
  display: grid;
  gap: 8px;
}

.people-user-copy {
  display: grid;
  gap: 4px;
}

.people-department-logo,
.people-user-avatar,
.people-upload-preview {
  display: grid;
  place-items: center;
  overflow: hidden;
  background: #effaf3;
  color: #1f6f5f;
  font-weight: 900;
}

.people-department-logo {
  width: 56px;
  height: 56px;
  border-radius: 12px;
  background: #ffffff;
  border: 1px solid #dbe6f3;
  padding: 6px;
}

.people-user-avatar img,
.people-upload-preview img {
  width: 100%;
  height: 100%;
