}

.people-card-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.danger-action,
.archive-action {
  min-height: 34px;
  border: 1px solid #fde68a;
  border-radius: 12px;
  background: #fffbeb;
  padding: 0 10px;
  color: #92400e;
  box-shadow: none;
}

.danger-action:hover,
.archive-action:hover {
  background: #fef3c7;
  box-shadow: none;
}

.people-user-card {
  position: relative;
  grid-template-columns: auto;
}

.people-user-avatar {
  width: 44px;
  height: 44px;
  border-radius: 999px;
}

.people-status {
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  border-radius: 999px;
  padding: 5px 10px;
  font-size: 0.68rem;
  font-weight: 900;
  z-index: 2;
}

.people-status.active {
  background: #dcfce7;
  color: #166534;
}

.people-status.inactive {
  background: #fef3c7;
  color: #92400e;
}

.people-user-card .people-user-info {
