  gap: 10px;
  align-items: center;
  padding: 12px;
}

.people-user-card .people-card-actions {
  grid-column: 1 / -1;
  padding: 0 12px 12px;
}

.people-user-list {
  display: grid;
  padding: 14px;
}

.people-user-list-head,
.people-user-row {
  display: grid;
  grid-template-columns: minmax(220px, 1.4fr) minmax(110px, 0.7fr) minmax(180px, 1fr) minmax(86px, auto) minmax(160px, auto);
  gap: 12px;
  align-items: center;
}

.people-user-list-head {
  min-height: 38px;
  border-bottom: 1px solid var(--theme-border, #dbe7e1);
  padding: 0 10px;
  color: var(--theme-muted, #4d5f57);
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0;
  text-transform: uppercase;
}

.people-user-row {
  min-height: 68px;
  border-bottom: 1px solid color-mix(in srgb, var(--theme-border, #dbe7e1) 72%, transparent);
  padding: 10px;
  background: transparent;
  transition: background-color 180ms ease;
}

.people-user-row:hover {
  background: color-mix(in srgb, var(--theme-primary, #166a45) 5%, transparent);
}

.people-user-identity {
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr);
  gap: 10px;
  align-items: center;
  min-width: 0;
}

.people-user-row .people-user-avatar {
  width: 40px;
  height: 40px;
}

.people-user-row .people-user-copy h3 {
  font-size: 0.92rem;
}

.people-user-role,
.people-user-assignment {
  color: var(--theme-muted, #4d5f57);
  font-size: 0.82rem;
  font-weight: 750;
  line-height: 1.35;
}

.people-user-assignment {
  overflow-wrap: anywhere;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.42rem;
}

.people-user-assignment-department {
  color: var(--theme-text, #173d31);
}

.people-user-program-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.32rem;
}

.people-user-program-chip {
  display: inline-flex;
  align-items: center;
  min-height: 1.45rem;
  padding: 0.15rem 0.48rem;
  border: 1px solid color-mix(in srgb, var(--theme-accent, #198754) 30%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--theme-accent, #198754) 11%, transparent);
  color: var(--theme-accent-strong, #146c43);
  font-size: 0.72rem;
  font-weight: 850;
  line-height: 1;
