.people-user-row .people-status {
  position: static;
  justify-self: start;
  transform: none;
}

.people-user-row .people-card-actions {
  justify-content: flex-end;
}

.people-program-list {
  display: grid;
  padding: 14px;
}

.people-program-list-head,
.people-program-row {
  display: grid;
  grid-template-columns: minmax(220px, 1.4fr) minmax(120px, 0.7fr) minmax(180px, 1fr) minmax(110px, auto);
  gap: 12px;
  align-items: center;
}

.people-program-list-head {
  min-height: 38px;
  border-bottom: 1px solid var(--theme-border, #dbe7e1);
  padding: 0 10px;
  color: var(--theme-muted, #4d5f57);
  font-size: 0.72rem;
  font-weight: 900;
  text-transform: uppercase;
}

.people-program-row {
  min-height: 64px;
  border-bottom: 1px solid color-mix(in srgb, var(--theme-border, #dbe7e1) 72%, transparent);
  padding: 10px;
}

.people-program-row:hover {
  background: color-mix(in srgb, var(--theme-primary, #166a45) 5%, transparent);
}

.people-program-row h3 {
  margin: 0;
  color: var(--theme-text, #10201b);
  font-size: 0.92rem;
  font-weight: 900;
  line-height: 1.25;
}

.people-program-row small,
.people-program-row > span:not(.people-status) {
  color: var(--theme-muted, #4d5f57);
  font-size: 0.82rem;
  font-weight: 750;
  line-height: 1.35;
}

.people-program-row .people-status {
  position: static;
  justify-self: start;
  transform: none;
}

@media (max-width: 920px) {
  .people-user-list-head {
    display: none;
  }

  .people-user-row {
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 8px 12px;
    align-items: start;
    padding: 12px 10px;
  }

  .people-user-identity {
    grid-column: 1 / -1;
  }

  .people-user-role,
  .people-user-assignment {
    grid-column: 1 / -1;
  }

  .people-user-role::before,
  .people-user-assignment::before {
    display: inline;
    margin-right: 6px;
    color: var(--theme-subtle, #64748b);
    font-size: 0.7rem;
    font-weight: 900;
    text-transform: uppercase;
  }

  .people-user-role::before {
    content: "Role:";
  }

  .people-user-assignment::before {
    content: "Assignment:";
