  .people-user-row .people-card-actions {
    grid-column: 1 / -1;
    justify-content: flex-start;
  }

  .people-program-list-head {
    display: none;
  }

  .people-program-row {
    grid-template-columns: 1fr;
    gap: 7px;
    align-items: start;
    padding: 12px 10px;
  }
}

