  border-radius: 8px;
  background: #ffffff;
  padding: 8px 12px;
  color: #10201b;
  outline: none;
  font-size: 0.95rem;
}

.profile-form input:focus {
  border-color: #2e965f;
  box-shadow: 0 0 0 3px #d9f2e2;
}

.profile-form input[readonly] {
  background: #f8fafc;
  color: #64748b;
  cursor: default;
}

.profile-editor-head {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 16px;
  align-items: flex-start;
  padding-bottom: 12px;
  border-bottom: 1px solid #e2e8f0;
}

.profile-editor-avatar {
  display: grid;
  place-items: center;
  width: 92px;
  height: 92px;
  flex-shrink: 0;
  overflow: hidden;
  border: 2px solid #dbe7e1;
  border-radius: 12px;
  background: #e6f6ec;
  color: #0f6b46;
  font-size: 2.2rem;
  font-weight: 900;
}

.profile-editor-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.profile-buttons-row {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
  align-items: center;
  min-width: 0;
}

.profile-upload-button {
  position: relative;
  display: inline-flex !important;
  grid-template-columns: none !important;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 38px;
  border: 1px solid #168358;
  border-radius: 8px;
  background: #168358;
  padding: 0 12px;
  color: #ffffff !important;
  font-size: 0.85rem;
  font-weight: 800;
  min-width: 0;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease;
}

.profile-upload-button:hover {
  background: #0f5138;
  border-color: #0f5138;
}

.profile-remove-photo {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 38px;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  background: #ffffff;
  padding: 0 12px;
  color: #b42318;
  font-size: 0.85rem;
  font-weight: 800;
  min-width: 0;
  cursor: pointer;
  transition: all 0.15s ease;
}

.profile-remove-photo:hover:not(:disabled) {
  border-color: #b42318;
  background: #fee2e2;
}

.profile-remove-photo:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.profile-upload-button input {
  position: absolute;
  inset: 0;
  opacity: 0;
  cursor: pointer;
}

.profile-field-grid {
  display: grid;
  gap: 16px;
}

@media (min-width: 720px) {
  .profile-field-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .profile-field-grid label:first-child,
  .profile-field-grid label:last-child {
    grid-column: 1 / -1;
  }
}

.profile-password-section {
  display: grid;
  gap: 14px;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  background: #f8fafc;
  padding: 16px;
}

.profile-section-title {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  color: #10201b;
  margin: 0;
  font-size: 1rem;
}

.profile-section-title strong {
  font-weight: 900;
}

.profile-password-toggle {
  display: inline-flex !important;
  grid-template-columns: none !important;
  align-items: center;
  gap: 7px !important;
  color: #475569 !important;
  font-size: 0.8rem !important;
  font-weight: 800 !important;
  cursor: pointer;
  transition: color 0.15s ease;
}

.profile-password-toggle:hover {
  color: #334155 !important;
}

.profile-password-toggle input {
  width: 16px !important;
  min-height: 16px !important;
  accent-color: #168358;
  cursor: pointer;
}

.profile-password-strength {
  display: grid;
  gap: 8px;
  margin-top: 4px;
}

.profile-password-strength > span {
  display: block;
  height: 6px;
  overflow: hidden;
  border-radius: 3px;
  background: #e2e8f0;
}

.profile-password-strength i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: #94a3b8;
  transition: width 0.25s ease, background-color 0.25s ease;
}

.profile-password-strength small {
  display: block;
  color: #64748b;
  font-size: 0.8rem;
  font-weight: 800;
}

.profile-password-strength.strength-weak i {
  background: #ef4444;
}

.profile-password-strength.strength-good i {
  background: #f59e0b;
}

.profile-password-strength.strength-strong i {
  background: #16a34a;
}

/* Profile Modal Notice Elements */
.profile-form .notice {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 12px 16px;
  border-radius: 8px;
  font-size: 0.9rem;
  line-height: 1.5;
  animation: slideInDown 300ms ease-out;
}

.profile-form .notice p {
  margin: 0;
}

.profile-form .notice.error {
  background: #fef2f2;
  border: 1px solid #fca5a5;
  color: #991b1b;
  font-weight: 500;
}

.profile-form .notice.success {
  background: #f0fdf4;
  border: 1px solid #86efac;
  color: #166534;
  font-weight: 500;
}

@keyframes slideInDown {
  from {
    opacity: 0;
    transform: translateY(-8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.dark-mode .profile-form .notice.error {
  background: #3f0f0f;
  border-color: #7f1d1d;
  color: #fca5a5;
}

.dark-mode .profile-form .notice.success {
  background: #064e3b;
  border-color: #10b981;
  color: #86efac;
}

.profile-form-actions {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  padding: 4px 0 0;
  border-top: 1px solid #e2e8f0;
  background: transparent;
}

.profile-form-actions button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 40px;
  height: auto;
  border: 1px solid;
  border-radius: 8px;
  padding: 0 16px;
  font-size: 0.88rem;
  font-weight: 800;
  min-width: 0;
  white-space: normal;
  text-align: center;
  cursor: pointer;
  transition: all 0.15s ease;
}

.profile-form-actions button[type="submit"] {
  border-color: #168358;
  background: #168358;
  color: #ffffff;
}

.profile-form-actions button[type="submit"]:hover:not(:disabled) {
  background: #0f5138;
  border-color: #0f5138;
  box-shadow: 0 2px 8px rgba(22, 131, 88, 0.2);
}

.profile-form-actions .ghost-button {
  border-color: #dbe7e1;
  background: #ffffff;
  color: #334155;
}

.profile-form-actions .ghost-button:hover {
  border-color: #bfccbe;
  background: #f8fafc;
  color: #10201b;
}

.profile-form-actions button:disabled {
  cursor: not-allowed;
  opacity: 0.6;
}

/* Profile Modal Responsive Design */
@media (max-width: 640px) {
  .profile-modal-panel {
    width: min(100%, calc(100vw - 20px));
    max-height: calc(100dvh - 20px);
  }

  .profile-modal-panel > .box-title {
    padding: 16px 18px;
    gap: 12px;
  }

  .profile-modal-panel > .box-title h2 {
    font-size: 1.25rem;
  }

  .profile-modal-panel .profile-form {
    padding: 18px;
    gap: 16px;
  }

  .profile-editor-head {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .profile-editor-avatar {
    width: 80px;
    height: 80px;
    margin: 0 auto;
  }

  .profile-buttons-row {
    grid-template-columns: repeat(2, 1fr);
    gap: 8px;
  }

  .profile-upload-button,
  .profile-remove-photo {
    min-height: 36px;
    font-size: 0.8rem;
    padding: 0 10px;
  }

  .profile-upload-button svg,
  .profile-remove-photo svg {
    width: 14px;
    height: 14px;
  }

  .profile-field-grid {
    grid-template-columns: 1fr;
  }

  .profile-password-section {
    padding: 12px;
    gap: 12px;
  }

  .profile-form-actions {
    grid-template-columns: 1fr;
    gap: 10px;
    padding: 16px 18px;
  }

  .profile-form-actions button {
    min-height: 38px;
    font-size: 0.82rem;
  }
}

@media (min-width: 641px) and (max-width: 900px) {
  .profile-modal-panel {
    width: min(90vw, 680px);
  }

  .profile-form-actions {
    grid-template-columns: 1fr 1fr 1fr;
  }
}

.profile-form-actions button:disabled {
  cursor: not-allowed;
  opacity: 0.6;
}

@media (min-width: 760px) {
  .department-ai-hero {
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: end;
  }

  .people-management-hero {
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: end;
  }

  .people-filter-panel {
    grid-template-columns: minmax(240px, 1.6fr) repeat(3, minmax(150px, 1fr));
  }

  .people-department-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .people-user-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .department-ai-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .people-user-card .people-user-info {
    grid-template-columns: 44px minmax(0, 1fr);
  }
}

@media (min-width: 1220px) {
  .people-user-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .people-department-grid {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }

  .department-ai-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

.mini-progress {
  margin-top: 14px;
  height: 9px;
  overflow: hidden;
  border-radius: 999px;
  background: #e5ece8;
}

.mini-progress span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #1f7a4f, #4db47f);
}

.dipascaf-progress span,
.admin-report-progress span {
  width: var(--progress-value, auto);
}

.reports-analytics-content {
  background: var(--theme-surface, #ffffff);
}

.admin-report-intro.analytics-report-intro {
  border: 1px solid var(--theme-border, #dbe7e1);
  background: var(--theme-surface, #ffffff);
  box-shadow: 0 12px 28px rgba(31, 54, 45, 0.08);
}

.admin-report-intro.analytics-report-intro .eyebrow {
  color: var(--theme-primary, #166a45);
}

.admin-report-grid {
  align-items: stretch;
}

.admin-report-card {
  position: relative;
  display: flex;
  min-height: 310px;
  flex-direction: column;
  gap: 14px;
  overflow: hidden;
  border: 1px solid #dfeae4;
  background: #ffffff;
  color: #16221e;
  box-shadow: 0 14px 30px rgba(18, 61, 53, 0.08);
}

.admin-report-card::before {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  height: 5px;
  background: linear-gradient(90deg, #1f7a4f, #82d0a8);
}

.admin-report-card::after {
  display: none;
}

.admin-report-card h3 {
  color: #123d35;
  font-size: 1.05rem;
  line-height: 1.25;
}

.admin-report-card p {
  color: #52635b;
  line-height: 1.55;
}

.admin-report-card small {
  color: #64748b;
  font-weight: 800;
}

.admin-report-card-top,
.admin-report-title-row,
.admin-report-actions {
  position: relative;
  z-index: 1;
}

.admin-report-stat,
.admin-report-badge {
  border: 1px solid #b5e5c9;
  background: #effaf3;
  color: #18584c;
}

.admin-report-icon,
.admin-report-title-icon {
  background: #effaf3;
  color: #1f7a4f;
}

.admin-report-title-row {
  display: flex;
  min-height: 42px;
  align-items: center;
  gap: 10px;
}

.admin-report-progress {
  height: 10px;
  margin-top: auto;
  overflow: hidden;
  border-radius: 999px;
  background: #e5ece8;
}

.admin-report-progress span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #1f7a4f, #4db47f);
}

.admin-report-actions {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: end;
  margin-top: 4px;
  padding-top: 12px;
  border-top: 1px solid #e5ece8;
}

.admin-report-actions label {
  display: grid;
  gap: 6px;
  color: #475569;
  font-size: 0.78rem;
  font-weight: 900;
  text-transform: uppercase;
}

.admin-report-actions select {
  min-height: 42px;
  border: 1px solid #d7e4dd;
  border-radius: 12px;
  background: #ffffff;
  padding: 0 36px 0 12px;
  color: #16221e;
  outline: none;
}

.admin-report-actions button {
  min-height: 42px;
  border-radius: 12px;
  white-space: nowrap;
}

.admin-report-completion {
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 18px;
  background: var(--theme-primary-soft, #e6f6ec);
  padding: 18px;
  color: var(--theme-text, #10201b);
}

.completion-donut {
  background: rgba(22, 106, 69, 0.06);
}

.completion-donut-track {
  stroke: rgba(22, 106, 69, 0.16);
}

.completion-donut-progress {
  stroke: var(--theme-primary, #166a45);
}

.completion-donut strong,
.admin-report-completion > span {
  color: var(--theme-text, #10201b);
}

.completion-donut-progress {
  stroke-dasharray: var(--completion-rate) 100;
  animation: chartDraw 700ms ease-out both;
}

.evaluation-completion-done {
  stroke-dasharray: var(--completion-rate) 100;
  animation: chartDraw 700ms ease-out both;
}

.evaluation-completion-pending {
  stroke-dasharray: var(--pending-rate) 100;
  animation: chartDraw 700ms ease-out both;
}

/* ── Notification Center Styles ────────────────────────────────────────── */
.notification-panel-head-info {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  width: 100%;
}

.notification-panel-head-info strong {
  font-size: 0.92rem;
  font-weight: 900;
  color: var(--theme-text, #10201b);
}

.notification-panel-head-info span {
  font-size: 0.72rem;
  font-weight: 800;
  color: var(--theme-primary, #166a45);
}

.notification-mark-all-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 32px;
  border: 1px solid #dbe7e1;
  border-radius: 8px;
  background: #ffffff;
  padding: 0 10px;
  color: #475569;
  font-size: 0.72rem;
  font-weight: 800;
  cursor: pointer;
  transition: all 180ms ease;
}

.notification-mark-all-btn:hover {
  border-color: var(--theme-primary, #166a45);
  background: var(--theme-primary-soft, #e6f6ec);
  color: var(--theme-primary-strong, #0f5138);
}

.notification-empty {
  display: grid;
  place-items: center;
  gap: 8px;
  padding: 32px 20px;
  text-align: center;
  color: #94a3b8;
}

.notification-empty svg {
  opacity: 0.4;
}

.notification-empty p {
  margin: 0;
  font-size: 0.88rem;
  font-weight: 800;
  color: #64748b;
}

.notification-empty span {
  font-size: 0.78rem;
  color: #94a3b8;
  font-weight: 600;
}

.notification-item-icon {
  display: grid;
  width: 36px;
  height: 36px;
  flex-shrink: 0;
  place-items: center;
  border-radius: 10px;
  font-size: 0;
}

.notification-item-icon.type-system {
  background: #eff6ff;
  color: #2563eb;
}

.notification-item-icon.type-account {
  background: #effaf3;
  color: #166a45;
}

.notification-item-body {
  display: grid;
  gap: 2px;
  min-width: 0;
  flex: 1;
}

.notification-item-head {
  display: flex;
  align-items: center;
  gap: 6px;
}

.notification-type-badge {
  display: inline-flex;
  align-items: center;
  font-size: 0.6rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 2px 7px;
  border-radius: 4px;
  line-height: 1.3;
}

.notification-type-badge.type-system {
  background: #dbeafe;
  color: #1e40af;
}

.notification-type-badge.type-account {
  background: #d9f2e2;
  color: #166a45;
}

.notification-unread-dot {
  color: #f59e0b;
  flex-shrink: 0;
}

.notification-item-title {
  display: block;
  font-size: 0.85rem;
  font-weight: 800;
  line-height: 1.35;
  color: var(--theme-text, #10201b);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.notification-item-desc {
