/* ── Period Selector ──────────────────────────────────────────────────── */
.period-selector {
  display: flex;
  align-items: center;
  gap: 10px;
  width: fit-content;
  max-width: 100%;
  padding: 9px 12px;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 14px;
  background: var(--theme-surface, #ffffff);
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.08);
  flex-wrap: wrap;
}

.period-selector-compact {
  padding: 8px 10px;
  gap: 8px;
}

.period-selector-icon {
  color: var(--theme-primary, #166a45);
  flex-shrink: 0;
}

.period-selector-label {
  font-size: 0.78rem;
  font-weight: 800;
  color: var(--theme-muted, #4d5f57);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  white-space: nowrap;
}

.period-selector-select-wrapper {
  position: relative;
  display: inline-flex;
  align-items: center;
}

.period-selector-select {
  min-height: 34px;
  min-width: clamp(240px, 42vw, 560px);
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 10px;
  background: var(--theme-surface-soft, #f8fafc);
  padding: 0 30px 0 12px;
  color: var(--theme-text, #10201b);
  font-size: 0.88rem;
  font-weight: 700;
  outline: none;
  cursor: pointer;
  appearance: none;
  -webkit-appearance: none;
  transition: border-color 200ms ease, box-shadow 200ms ease;
}

.period-selector-select:focus {
  border-color: var(--theme-primary, #166a45);
  box-shadow: 0 0 0 3px rgba(22, 106, 69, 0.12);
}

.period-selector-chevron {
  position: absolute;
  right: 10px;
  pointer-events: none;
  color: var(--theme-muted, #64748b);
}

.period-selector-status {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.68rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 2px 8px;
  border-radius: 999px;
}

.period-selector-status.open {
  background: #dcfce7;
  color: #166534;
}

.period-selector-status.locked {
  background: #fef3c7;
  color: #92400e;
}

.period-selector-refresh {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 8px;
  background: transparent;
  color: var(--theme-muted, #64748b);
  cursor: pointer;
  transition: all 200ms ease;
  padding: 0;
}

.period-selector-refresh:hover {
  border-color: var(--theme-primary, #166a45);
  color: var(--theme-primary, #166a45);
  background: var(--theme-primary-soft, #e6f6ec);
}

/* Dark mode period selector */
.admin-body.dark-mode .period-selector {
  border-color: rgba(110, 231, 183, 0.55);
  background: #0f172a;
  box-shadow: 0 14px 30px rgba(0, 0, 0, 0.24);
}

.admin-body.dark-mode .period-selector-label {
  color: #94a3b8;
}

.admin-body.dark-mode .period-selector-select {
  border-color: #334155;
  background: #020617;
  color: #f8fafc;
}

.admin-body.dark-mode .period-selector-select:focus {
  border-color: #6ee7b7;
  box-shadow: 0 0 0 3px rgba(110, 231, 183, 0.12);
}

.admin-body.dark-mode .period-selector-chevron {
  color: #64748b;
}

.admin-body.dark-mode .period-selector-icon {
  color: #6ee7b7;
}

.admin-body.dark-mode .period-selector-refresh {
  border-color: #334155;
  color: #64748b;
}

.admin-body.dark-mode .period-selector-refresh:hover {
  border-color: #6ee7b7;
  color: #6ee7b7;
  background: rgba(110, 231, 183, 0.1);
}

/* ── Hero / Welcome cards — white mode overrides (light theme) ───── */
.hero-card {
  border: 1px solid var(--theme-border, #dbe7e1);
  background: var(--theme-surface, #ffffff);
  color: var(--theme-text, #10201b);
  box-shadow: 0 12px 28px rgba(31, 54, 45, 0.08);
}

.hero-card .eyebrow {
  color: var(--theme-primary, #166a45);
}

.hero-card h2 {
  color: var(--theme-text, #10201b);
}

.hero-card p:not(.eyebrow) {
  color: var(--theme-muted, #4d5f57);
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 16px;
}

.admin-body.dark-mode .hero-card {
  border: 1px solid rgba(167, 243, 208, 0.22);
  background: linear-gradient(135deg, rgba(8, 47, 73, 0.54), rgba(15, 23, 42, 0.58));
  box-shadow: 0 22px 50px rgba(0, 0, 0, 0.28);
}

.admin-body.dark-mode .hero-card .eyebrow {
  color: #bbf7d0;
}

.admin-body.dark-mode .hero-card h2 {
  color: #ffffff;
}

.admin-body.dark-mode .hero-card p:not(.eyebrow) {
  color: rgba(255, 255, 255, 0.84);
}

/* ── Admin dashboard metrics ───────────────────────────────────────── */
.dashboard-metric-grid {
  gap: 16px;
  border: 1px solid var(--theme-border, #dbe7e1);
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--theme-surface, #ffffff) 92%, #e6f6ec), var(--theme-surface, #ffffff));
  box-shadow: 0 16px 36px rgba(31, 54, 45, 0.08);
}

.dashboard-metric-card {
  position: relative;
  display: grid;
  min-height: 132px;
  align-content: space-between;
  gap: 16px;
  overflow: hidden;
  border-radius: 14px;
  padding: 20px;
  border-color: color-mix(in srgb, var(--metric-color, #166a45) 24%, var(--theme-border, #dbe7e1));
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--metric-color, #166a45) 9%, var(--theme-surface, #ffffff)), var(--theme-surface, #ffffff) 72%);
}

a.dashboard-metric-card {
  color: inherit;
  text-decoration: none;
}

.dashboard-metric-card.is-clickable {
  cursor: pointer;
  transition: border-color 180ms ease, box-shadow 180ms ease, transform 180ms ease;
}

.dashboard-metric-card.is-clickable:hover,
.dashboard-metric-card.is-clickable:focus-visible {
  border-color: var(--metric-color, #166a45);
  box-shadow: 0 18px 42px rgba(31, 54, 45, 0.12);
  transform: translateY(-2px);
  outline: none;
}

.dashboard-metric-card::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 4px;
  background: var(--metric-color, #166a45);
}

.metric-card-head {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 12px;
}

.metric-card-head span:first-child {
  max-width: 14rem;
  color: var(--theme-muted, #4d5f57);
  font-size: 0.88rem;
  font-weight: 800;
  line-height: 1.35;
}

.metric-card-icon {
  display: grid;
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 12px;
  background: color-mix(in srgb, var(--metric-color, #166a45) 13%, transparent);
  color: var(--metric-color, #166a45);
}

.dashboard-metric-card strong {
  color: var(--theme-text, #10201b);
  font-size: clamp(2rem, 4vw, 2.65rem);
  line-height: 1;
}

.dashboard-metric-card small {
  color: var(--theme-muted, #4d5f57);
  font-size: 0.78rem;
  line-height: 1.4;
}

.dashboard-metric-cta {
  display: inline-flex;
  width: fit-content;
  min-height: 28px;
  align-items: center;
  border-radius: 999px;
  background: color-mix(in srgb, var(--metric-color, #166a45) 12%, transparent);
  padding: 4px 10px;
  color: var(--metric-color, #166a45);
  font-size: 0.72rem;
  font-weight: 900;
}

.admin-dashboard-unified {
  display: grid;
  gap: 14px;
}

.admin-dashboard-unified .dashboard-metric-grid {
  padding: 16px;
}

.dashboard-metric-card.metric-primary { --metric-color: #166a45; }
.dashboard-metric-card.metric-warning { --metric-color: #b45309; }
.dashboard-metric-card.metric-info { --metric-color: #2563eb; }
.dashboard-metric-card.metric-success { --metric-color: #15803d; }
.dashboard-metric-card.metric-accent { --metric-color: #7c3aed; }

.admin-body.dark-mode .dashboard-metric-grid {
  border-color: rgba(148, 163, 184, 0.2);
  background: linear-gradient(135deg, rgba(16, 28, 25, 0.92), rgba(15, 23, 42, 0.74));
}

.admin-body.dark-mode .dashboard-metric-card {
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--metric-color, #6ee7b7) 18%, #101c19), var(--theme-surface, #101c19) 72%);
}

/* ── Admin action center ───────────────────────────────────────────── */
.admin-action-center {
  gap: 18px;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 18px;
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--theme-surface, #ffffff) 92%, #e6f6ec), var(--theme-surface, #ffffff));
  padding: 20px;
  box-shadow: 0 16px 36px rgba(31, 54, 45, 0.08);
}

.action-center-head {
  gap: 16px;
  padding: 0;
}

.action-center-head h2 {
  color: var(--theme-text, #10201b);
  font-size: clamp(1.35rem, 2.5vw, 1.8rem);
  letter-spacing: 0;
}

.action-center-head p:not(.eyebrow) {
  color: var(--theme-muted, #4d5f57);
}

.action-center-summary {
  min-width: 190px;
  border-radius: 14px;
  border-color: color-mix(in srgb, var(--summary-color, #166a45) 24%, var(--theme-border, #dbe7e1));
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--summary-color, #166a45) 11%, var(--theme-surface, #ffffff)), var(--theme-surface, #ffffff));
  box-shadow: 0 10px 24px rgba(31, 54, 45, 0.06);
}

.action-center-summary.has-alerts {
  --summary-color: #b45309;
}

.action-center-summary.is-clear {
  --summary-color: #15803d;
}

.action-center-summary strong {
  color: var(--summary-color, var(--theme-text, #10201b));
  font-size: clamp(2rem, 4vw, 2.65rem);
}

.action-center-summary span,
.action-center-summary small {
  color: var(--theme-muted, #4d5f57);
}

.action-center-grid {
  gap: 16px;
}

.action-card {
  --action-color: #2563eb;
  min-height: 132px;
  grid-template-columns: 46px minmax(0, 1fr) auto;
  gap: 14px;
  border-radius: 14px;
  border-color: color-mix(in srgb, var(--action-color) 24%, var(--theme-border, #dbe7e1));
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--action-color) 9%, var(--theme-surface, #ffffff)), var(--theme-surface, #ffffff) 72%);
  box-shadow: 0 10px 24px rgba(31, 54, 45, 0.06);
}

.action-card::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 4px;
  background: var(--action-color);
}

.action-card:hover {
  border-color: color-mix(in srgb, var(--action-color) 42%, var(--theme-border, #dbe7e1));
  box-shadow: 0 18px 38px rgba(31, 54, 45, 0.12);
}

.action-card-icon {
  border-radius: 12px;
  background: color-mix(in srgb, var(--action-color) 13%, transparent);
  color: var(--action-color);
}

.action-card-copy strong {
  color: var(--theme-text, #10201b);
  font-size: clamp(1.8rem, 3vw, 2.35rem);
}

.action-card-copy span {
  color: var(--theme-text, #10201b);
  line-height: 1.3;
}

.action-card-copy small {
  color: var(--theme-muted, #4d5f57);
}

.action-card-cta {
  border-color: color-mix(in srgb, var(--action-color) 18%, var(--theme-border, #dbe7e1));
  background: color-mix(in srgb, var(--action-color) 8%, var(--theme-surface, #ffffff));
  color: var(--action-color);
}

.action-card.danger {
  --action-color: #dc2626;
  border-left-width: 1px;
}

.action-card.warning {
  --action-color: #b45309;
  border-left-width: 1px;
}

.action-card.info {
  --action-color: #2563eb;
  border-left-width: 1px;
}

.action-card.is-done {
  --action-color: #15803d;
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--action-color) 9%, var(--theme-surface, #ffffff)), var(--theme-surface, #ffffff) 72%);
}

.admin-body.dark-mode .admin-action-center {
  border-color: rgba(148, 163, 184, 0.2);
  background: linear-gradient(135deg, rgba(16, 28, 25, 0.92), rgba(15, 23, 42, 0.74));
}

.admin-body.dark-mode .action-center-summary,
.admin-body.dark-mode .action-card {
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--action-color, var(--summary-color, #6ee7b7)) 18%, #101c19), var(--theme-surface, #101c19) 72%);
}

/* ── Assignment Workbench hero — white mode overrides (light theme) ── */
.assignment-workbench-hero {
  border: 1px solid var(--theme-border, #dbe7e1);
  background: var(--theme-surface, #ffffff);
  color: var(--theme-text, #10201b);
  box-shadow: 0 12px 28px rgba(31, 54, 45, 0.08);
}

.assignment-workbench-hero .eyebrow {
  color: var(--theme-primary, #166a45);
}

.assignment-workbench-copy h2 {
  color: var(--theme-text, #10201b);
}

.assignment-workbench-copy p {
  color: var(--theme-muted, #4d5f57);
}

.admin-body.dark-mode .assignment-workbench-hero {
  border: 1px solid rgba(167, 243, 208, 0.22);
  background: linear-gradient(135deg, rgba(8, 47, 73, 0.54), rgba(15, 23, 42, 0.58));
  color: #ffffff;
  box-shadow: 0 22px 50px rgba(0, 0, 0, 0.28);
}

.admin-body.dark-mode .assignment-workbench-hero .eyebrow {
  color: #bbf7d0;
}

.admin-body.dark-mode .assignment-workbench-copy h2 {
  color: #ffffff;
}

.admin-body.dark-mode .assignment-workbench-copy p {
  color: rgba(255, 255, 255, 0.84);
}

/* ── Evaluation hero — white mode overrides (light theme) ───────── */
.dipascaf-eval-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(320px, auto);
  gap: 18px;
  align-items: stretch;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 18px;
  background: var(--theme-surface, #ffffff);
  padding: clamp(18px, 2.4vw, 24px);
  color: var(--theme-text, #10201b);
  box-shadow: 0 12px 28px rgba(31, 54, 45, 0.08);
}

.evaluation-hero-copy {
  display: grid;
  align-content: start;
  gap: 8px;
  min-width: 0;
}

.dipascaf-eval-hero .eyebrow {
  margin: 4px 0 0;
  color: var(--theme-primary, #166a45);
}

.dipascaf-eval-hero h2 {
  margin: 0;
  color: var(--theme-text, #10201b);
}

.dipascaf-eval-hero p:not(.eyebrow) {
  margin: 0;
  color: var(--theme-muted, #4d5f57);
}

.evaluation-hero-chart {
  display: grid;
  grid-template-columns: 118px minmax(0, 1fr);
  align-items: center;
  gap: 16px;
  min-width: min(360px, 100%);
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 18px;
  background: var(--theme-primary-soft, #e6f6ec);
  padding: 16px;
  color: var(--theme-text, #10201b);
}

.evaluation-page-period-selector {
  display: flex;
  justify-content: flex-start;
  width: 100%;
  margin-bottom: 4px;
}

.evaluation-page-period-selector-bottom {
  margin-top: 14px;
  margin-bottom: 0;
}

.dipascaf-eval-hero .period-selector {
  width: 100%;
  max-width: 720px;
  border-color: color-mix(in srgb, var(--theme-primary, #166a45) 24%, var(--theme-border, #dbe7e1));
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--theme-primary, #166a45) 8%, transparent), transparent 52%),
    var(--theme-surface-soft, #f8fafc);
  box-shadow: none;
}

.dipascaf-eval-hero .period-selector-select-wrapper {
  flex: 1 1 260px;
  min-width: min(260px, 100%);
}

.dipascaf-eval-hero .period-selector-select {
  width: 100%;
  min-width: 0;
}

/* ── Locked Period Banner ──────────────────────────────────────────── */
.period-locked-banner {
  display: flex;
  align-items: flex-start;
  gap: 18px;
  margin-top: 18px;
  padding: 22px 24px;
  border: 1px solid rgba(245, 158, 11, 0.28);
  border-radius: 18px;
  background:
    radial-gradient(circle at 0% 0%, rgba(251, 191, 36, 0.2), transparent 34%),
