  box-shadow: 0 18px 42px rgba(146, 64, 14, 0.12), inset 0 1px 0 rgba(255, 255, 255, 0.84);
  animation: cardPop 320ms ease-out both;
}

.period-locked-icon {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  flex-shrink: 0;
  border-radius: 14px;
  border: 1px solid rgba(217, 119, 6, 0.28);
  background: linear-gradient(135deg, #f59e0b, #fbbf24);
  color: #7c2d12;
  box-shadow: 0 12px 26px rgba(217, 119, 6, 0.22);
}

.period-locked-content {
  display: grid;
  gap: 6px;
}

.period-locked-content h3 {
  margin: 0;
  color: #111827;
  font-size: 1.05rem;
  font-weight: 900;
}

.period-locked-content p {
  margin: 0;
  color: #475569;
  font-size: 0.92rem;
  line-height: 1.55;
}

.period-locked-content strong {
  color: #334155;
  font-weight: 900;
}

.admin-body.dark-mode .period-locked-banner,
.admin-dashboard-body.dark-mode .period-locked-banner,
body:has(.admin-dashboard-body.dark-mode) .period-locked-banner {
  border-color: rgba(251, 191, 36, 0.22);
  background:
    radial-gradient(circle at 0% 0%, rgba(251, 191, 36, 0.12), transparent 34%),
    linear-gradient(135deg, rgba(15, 23, 42, 0.98), rgba(11, 20, 38, 0.96));
  box-shadow: 0 18px 42px rgba(0, 0, 0, 0.34), inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.admin-body.dark-mode .period-locked-icon,
.admin-dashboard-body.dark-mode .period-locked-icon,
body:has(.admin-dashboard-body.dark-mode) .period-locked-icon {
  border-color: rgba(251, 191, 36, 0.28);
  background: linear-gradient(135deg, #92400e, #f59e0b);
  color: #fff7ed;
  box-shadow: 0 12px 26px rgba(245, 158, 11, 0.18);
}

.admin-body.dark-mode .period-locked-content h3,
.admin-dashboard-body.dark-mode .period-locked-content h3,
body:has(.admin-dashboard-body.dark-mode) .period-locked-content h3 {
  color: #f8fafc;
}

.admin-body.dark-mode .period-locked-content p,
.admin-dashboard-body.dark-mode .period-locked-content p,
body:has(.admin-dashboard-body.dark-mode) .period-locked-content p {
  color: #cbd5e1;
}

.admin-body.dark-mode .period-locked-content strong,
.admin-dashboard-body.dark-mode .period-locked-content strong,
body:has(.admin-dashboard-body.dark-mode) .period-locked-content strong {
  color: #fde68a;
}

