.admin-body.dark-mode .dipascaf-filters input,
.admin-body.dark-mode .dipascaf-filters select,
.admin-dashboard-body.dark-mode .dipascaf-filters input,
.admin-dashboard-body.dark-mode .dipascaf-filters select,
body:has(.admin-dashboard-body.dark-mode) .dipascaf-filters input,
body:has(.admin-dashboard-body.dark-mode) .dipascaf-filters select {
