  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.035), 0 8px 22px rgba(37, 99, 235, 0.12) !important;
}

.evaluation-hero-chart .evaluation-completion-chart {
  width: 112px;
  height: 112px;
  background: rgba(22, 106, 69, 0.06);
}

.evaluation-hero-chart h3 {
  margin: 0;
  color: var(--theme-text, #10201b);
  font-size: 1rem;
  font-weight: 900;
}

.evaluation-hero-chart p {
  margin: 6px 0 10px;
  color: var(--theme-muted, #4d5f57);
  font-size: 0.9rem;
}

.evaluation-hero-chart .evaluation-completion-track {
  stroke: rgba(22, 106, 69, 0.16);
}

.evaluation-hero-chart .evaluation-completion-pending {
  stroke: rgba(251, 191, 36, 0.8);
}

.evaluation-hero-chart .evaluation-completion-done {
  stroke: var(--theme-primary, #166a45);
}

.evaluation-hero-chart .evaluation-completion-chart strong {
  color: var(--theme-text, #10201b);
}

.evaluation-hero-chart .completion-legend {
  gap: 6px;
}

.evaluation-hero-chart .completion-legend span {
  background: rgba(22, 106, 69, 0.06);
  color: var(--theme-muted, #4d5f57);
}

/* Evaluation Assignment Workbench */
.assignment-workbench {
  display: grid;
  gap: 18px;
}

.assignment-workbench-hero {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(320px, 0.8fr);
  gap: 18px;
  align-items: stretch;
  padding: 22px;
  border-radius: 22px;
  background: linear-gradient(135deg, #123d35 0%, #1f7a4f 58%, #2e965f 100%);
  color: #ffffff;
  box-shadow: 0 18px 45px rgba(18, 61, 53, 0.12);
}

.assignment-workbench-copy h2 {
  margin: 8px 0 10px;
  color: #ffffff;
  font-size: clamp(1.8rem, 4vw, 3rem);
  font-weight: 900;
}

.assignment-workbench-copy p {
  max-width: 760px;
  color: rgba(255, 255, 255, 0.88);
}

.assignment-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 18px;
}

.assignment-hero-metrics {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.assignment-metric,
.questionnaire-preview-summary article,
.preview-result-grid article,
.preview-score-card,
.preview-assignment-card,
.assignment-rule-card,
.assignment-card,
.preview-questionnaire-category {
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 18px;
  background: #ffffff;
  padding: 16px;
  box-shadow: 0 14px 32px rgba(15, 23, 42, 0.08);
}

.assignment-metric {
  min-height: 112px;
}

.assignment-metric span,
.questionnaire-preview-summary span,
.preview-result-grid span,
.preview-assignment-card span,
.preview-questionnaire-label,
.assignment-card-top span,
.assignment-card-meta span,
.preview-breakdown-list span {
  display: block;
  color: #64748b;
  font-size: 0.76rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.assignment-metric strong,
.questionnaire-preview-summary strong,
.preview-result-grid strong,
.preview-score-card strong,
.preview-assignment-card h4,
.assignment-card h4,
.preview-questionnaire-category strong {
  color: #123d35;
  font-size: 1.35rem;
  font-weight: 900;
}

.assignment-metric small,
.preview-result-grid small,
.preview-assignment-card small,
.assignment-card small {
  color: #64748b;
}

.assignment-metric.success strong,
.preview-result-grid .success strong {
  color: #1f7a4f;
}

.assignment-metric.warning strong,
.assignment-rule-card ul li,
.questionnaire-weight-warning.warning {
  color: #b45309;
}

.assignment-metric.danger strong,
.questionnaire-weight-warning.danger {
  color: #b91c1c;
}

.assignment-tab-bar {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding: 10px;
  border: 1px solid #dbe7df;
  border-radius: 18px;
  background: #f8fbf9;
}

.assignment-tab-bar button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  border: 1px solid transparent;
  border-radius: 999px;
  background: transparent;
  padding: 0 16px;
  color: #475569;
  font-size: 0.88rem;
  font-weight: 800;
  cursor: pointer;
  transition: all 200ms ease;
  white-space: nowrap;
}

.assignment-tab-bar button:hover {
  background: rgba(31, 122, 79, 0.08);
  color: #123d35;
}

.assignment-tab-bar button.active {
  border-color: rgba(31, 122, 79, 0.2);
  background: linear-gradient(135deg, #123d35, #1f7a4f);
  color: #ffffff;
  box-shadow: 0 10px 24px rgba(18, 61, 53, 0.18);
}

.assignment-notice {
  margin: 0;
}

.assignment-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(320px, 0.9fr);
  gap: 18px;
}

.preview-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 18px;
}

.questionnaire-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 18px;
}

.questionnaire-builder-panel {
  gap: 18px;
}

.questionnaire-shell-copy {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  align-items: stretch;
}

.questionnaire-shell-copy > div,
.questionnaire-live-status,
.preview-questionnaire-stats article {
  border: 1px solid #dfeae4;
  border-radius: 8px;
  background: #f9fcfa;
  padding: 10px 12px;
  min-height: 74px;
}

.questionnaire-shell-copy span,
.questionnaire-live-status span,
.preview-questionnaire-stats span {
  display: block;
  color: #64748b;
  font-size: 0.74rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.questionnaire-shell-copy strong,
.questionnaire-live-status strong,
.preview-questionnaire-stats strong {
  display: block;
  margin-top: 4px;
  color: #123d35;
  font-size: 0.9rem;
  font-weight: 900;
  line-height: 1.3;
}

.questionnaire-live-status small {
  display: block;
  margin-top: 6px;
  color: #64748b;
  font-size: 0.82rem;
}

.assignment-panel {
  display: grid;
  align-content: start;
  gap: 16px;
  border: 1px solid #dfeae4;
  border-radius: 22px;
  background: #ffffff;
  padding: 20px;
  box-shadow: 0 14px 30px rgba(18, 61, 53, 0.08);
}

.assignment-panel-soft {
  background: linear-gradient(180deg, #fbfdfc 0%, #f7fbf8 100%);
}

.assignment-panel-header {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 12px;
}

.assignment-panel-header h3,
.assignment-rule-card h4,
.preview-score-card h4 {
  margin: 0;
  color: #123d35;
  font-size: 1.15rem;
  font-weight: 900;
}

.assignment-panel-header p,
.assignment-rule-card p,
.preview-score-card p,
.preview-questionnaire-category li {
  margin: 4px 0 0;
  color: #64748b;
  font-size: 0.92rem;
}

.assignment-form-grid,
.questionnaire-info-grid,
.preview-select-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.assignment-form-grid label,
.questionnaire-info-grid label,
.preview-select-grid label,
.assignment-filters label,
.questionnaire-category-body label,
.preview-category-questions label,
.preview-textarea,
.questionnaire-question label {
  display: grid;
  gap: 8px;
  color: #334155;
  font-size: 0.82rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.assignment-form-grid input,
.assignment-form-grid select,
.assignment-form-grid textarea,
.questionnaire-info-grid input,
.questionnaire-info-grid textarea,
.preview-select-grid input,
.preview-select-grid select,
.assignment-filters input,
.assignment-filters select,
.questionnaire-category-body input,
.questionnaire-category-body textarea,
.questionnaire-category-body select,
.preview-category-questions input,
.preview-category-questions select,
.preview-textarea textarea {
  min-height: 44px;
  border: 1px solid #d6e2da;
  border-radius: 14px;
  background: #ffffff;
  padding: 0 14px;
  color: #123d35;
  outline: none;
  transition: border-color 200ms ease, box-shadow 200ms ease, transform 200ms ease;
}

.assignment-form-grid textarea,
.questionnaire-info-grid textarea,
.questionnaire-category-body textarea,
.preview-textarea textarea {
  min-height: 96px;
  padding-top: 12px;
  padding-bottom: 12px;
}

.assignment-form-grid input:focus,
.assignment-form-grid select:focus,
.assignment-form-grid textarea:focus,
.questionnaire-info-grid input:focus,
.questionnaire-info-grid textarea:focus,
.preview-select-grid input:focus,
.preview-select-grid select:focus,
.assignment-filters input:focus,
.assignment-filters select:focus,
.questionnaire-category-body input:focus,
.questionnaire-category-body textarea:focus,
.questionnaire-category-body select:focus,
.preview-category-questions input:focus,
.preview-category-questions select:focus,
.preview-textarea textarea:focus {
  border-color: #1f7a4f;
  box-shadow: 0 0 0 3px rgba(31, 122, 79, 0.14);
}

.assignment-form-grid .full-field,
.questionnaire-info-grid .full-field,
.preview-textarea {
  grid-column: 1 / -1;
}

.assignment-rule-card {
  display: grid;
  gap: 12px;
  border-color: #dbe7df;
}

.assignment-rule-card ul {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.assignment-rule-card li {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: #334155;
  font-size: 0.92rem;
}

.assignment-rule-card li.success {
  color: #1f7a4f;
}

.assignment-button-row,
.questionnaire-toolbar,
.questionnaire-actions-row,
.assignment-card-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
}

.primary-button,
.ghost-button,
.icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 44px;
  border-radius: 14px;
  border: 1px solid transparent;
  padding: 0 16px;
  font-size: 0.88rem;
  font-weight: 900;
  cursor: pointer;
  transition: all 200ms ease;
}

.primary-button {
  background: linear-gradient(135deg, #123d35, #1f7a4f);
  color: #ffffff;
  box-shadow: 0 12px 24px rgba(18, 61, 53, 0.18);
}

.ghost-button {
  border-color: #d5e2db;
  background: #ffffff;
  color: #123d35;
}

.ghost-button:hover,
.icon-button:hover,
.primary-button:hover {
  transform: translateY(-1px);
}

.ghost-button.danger,
.icon-button.danger {
  border-color: #fee2e2;
  color: #b91c1c;
}

.icon-button {
  min-width: 44px;
  padding: 0;
  background: #ffffff;
  border-color: #d5e2db;
  color: #64748b;
}

.questionnaire-weight-warning {
  border-radius: 16px;
  padding: 14px 16px;
  font-size: 0.94rem;
  font-weight: 700;
}

.questionnaire-weight-warning.success {
  background: #effaf3;
  color: #1f7a4f;
  border: 1px solid #b5e5c9;
}

.questionnaire-weight-warning.warning {
  background: #fffbeb;
  border: 1px solid #fde68a;
}

.questionnaire-category-list,
.assignment-card-list,
.preview-breakdown-list,
.preview-form-shell {
  display: grid;
  gap: 14px;
}

.questionnaire-category {
  border: 1px solid #dfeae4;
  border-radius: 18px;
  background: #ffffff;
  overflow: hidden;
}

.questionnaire-category summary,
.preview-category summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  list-style: none;
  cursor: pointer;
  padding: 16px 18px;
  background: linear-gradient(180deg, #f9fcfa 0%, #ffffff 100%);
}

.questionnaire-category summary::-webkit-details-marker,
.preview-category summary::-webkit-details-marker {
  display: none;
}

.questionnaire-category summary strong,
.preview-category summary strong {
  display: block;
  color: #123d35;
  font-size: 1rem;
  font-weight: 900;
}

.questionnaire-category summary span,
.preview-category summary span {
  color: #64748b;
  font-size: 0.82rem;
  font-weight: 800;
}

.questionnaire-category-summary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.questionnaire-category-body,
.preview-category-body {
  display: grid;
  gap: 14px;
  padding: 18px;
  border-top: 1px solid #e6efea;
}

.questionnaire-question-list {
  display: grid;
  grid-column: 1 / -1;
  gap: 12px;
  width: 100%;
}

.questionnaire-question {
  display: grid;
  gap: 10px;
  width: 100%;
  box-sizing: border-box;
  padding: 14px;
  border: 1px dashed #dbe7df;
  border-radius: 16px;
  background: #fbfdfc;
}

.questionnaire-question label,
.questionnaire-question textarea,
.questionnaire-question .ghost-button {
  width: 100%;
  box-sizing: border-box;
}

.questionnaire-question textarea {
  resize: vertical;
}

.questionnaire-actions-row {
  grid-column: 1 / -1;
}

.questionnaire-hint {
  color: #64748b;
  font-size: 0.82rem;
  font-weight: 700;
}

.questionnaire-preview-summary,
.preview-result-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.preview-questionnaire-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.questionnaire-preview-summary article,
.preview-result-grid article {
  background: #fbfdfc;
  border-color: #dfeae4;
  box-shadow: none;
}

.preview-questionnaire-shell {
  display: grid;
  gap: 14px;
  padding: 16px;
  border: 1px solid #dfeae4;
  border-radius: 18px;
  background: #ffffff;
}

.preview-questionnaire-label {
  margin: 0;
}

.preview-questionnaire-shell h4 {
  margin: 0;
  color: #123d35;
  font-size: 1.05rem;
  font-weight: 900;
}

.preview-questionnaire-category ul {
  display: grid;
  gap: 8px;
  margin: 10px 0 0;
  padding-left: 18px;
  color: #475569;
}

.preview-questionnaire-category-head,
.preview-assignment-card,
.preview-score-card,
.preview-score-card > div {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
}

.preview-assignment-card {
  align-items: start;
}

.preview-assignment-card h4,
.assignment-card h4 {
  margin: 4px 0 0;
}

.preview-assignment-meta {
  display: grid;
  justify-items: end;
  gap: 8px;
}

.preview-form-shell {
  display: grid;
  gap: 14px;
  padding-top: 2px;
}

.preview-category {
  border: 1px solid #dfeae4;
  border-radius: 18px;
  background: #ffffff;
  overflow: hidden;
}

.preview-category-body {
  grid-template-columns: minmax(0, 1fr);
  gap: 14px;
}

.preview-category-questions {
  display: grid;
  gap: 12px;
}

.preview-question-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(180px, 240px);
  align-items: center;
  gap: 12px;
  border: 1px solid #dfeae4;
  border-radius: 14px;
  background: #fbfdfc;
  padding: 12px;
}

.preview-question-text {
  color: #1e293b;
  font-size: 0.94rem;
  font-weight: 800;
  line-height: 1.45;
  text-transform: none;
  letter-spacing: 0;
}

.preview-category-result {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  align-items: center;
  padding: 14px;
  border-radius: 16px;
  background: #effaf3;
  color: #18584c;
}

.preview-category-result strong {
  color: #123d35;
  font-size: 1.3rem;
}

.preview-score-card {
  align-items: center;
}

.questionnaire-preview-panel {
  position: static;
  align-self: stretch;
}

.preview-score-ring {
  --score-percent: 0;
  width: 128px;
  height: 128px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  padding: 12px;
  background:
    radial-gradient(circle at center, #ffffff 56%, transparent 58%),
    conic-gradient(#1f7a4f calc(var(--score-percent) * 1%), #dbe7df 0);
  box-shadow: inset 0 0 0 1px #dbe7df;
}

.preview-score-ring strong {
  font-size: 1.2rem;
}

.preview-score-ring span {
  color: #64748b;
  font-size: 0.74rem;
  font-weight: 800;
  text-transform: uppercase;
}

.preview-breakdown-list article {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: start;
  border: 1px solid #dfeae4;
  border-radius: 16px;
  background: #ffffff;
  padding: 14px;
}

.preview-breakdown-list article div {
  display: grid;
  gap: 4px;
}

.preview-breakdown-list article strong {
  color: #123d35;
}

.empty-state {
  border-style: dashed;
}

@media (max-width: 1080px) {
  .assignment-workbench-hero,
  .assignment-grid,
  .questionnaire-layout,
  .preview-layout,
  .questionnaire-shell-copy,
  .preview-category-body {
    grid-template-columns: 1fr;
  }

  .assignment-hero-metrics,
  .evaluation-form-meta,
  .questionnaire-preview-summary,
  .form-category-stats,
  .preview-result-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 720px) {
  .assignment-workbench-hero,
  .assignment-panel,
  .questionnaire-category-body,
  .preview-category-body {
    padding: 16px;
  }

  .assignment-hero-metrics,
  .assignment-form-grid,
  .questionnaire-info-grid,
  .preview-select-grid,
  .evaluation-form-meta,
  .form-category-nav,
  .form-category-stats,
  .form-question-row,
  .preview-question-row,
  .questionnaire-preview-summary,
  .preview-result-grid {
    grid-template-columns: 1fr;
  }

  .evaluation-form-modal {
    max-height: calc(100vh - 20px);
  }

  .evaluation-form-modal .dipascaf-modal-header,
  .evaluation-form-modal > .evaluation-form-meta,
  .evaluation-form-modal > .notice,
  .evaluation-form-modal > .dipascaf-empty,
  .evaluation-form-modal > .evaluation-form,
  .evaluation-form-modal > .dipascaf-analysis {
    margin-left: 14px;
    margin-right: 14px;
  }

  .evaluation-form-modal .dipascaf-modal-header {
    padding: 18px 0;
  }

  .form-category-panel {
    padding: 14px;
    min-height: 0;
  }

  .rating-btn-group {
    justify-content: flex-start;
    min-width: 0;
  }

  .rating-label-text {
    text-align: left;
  }

  .assignment-panel-header,
  .preview-assignment-card,
  .preview-score-card,
  .preview-questionnaire-category-head,
  .assignment-card-top {
    flex-direction: column;
    align-items: start;
  }

  .questionnaire-preview-panel {
    position: static;
  }

  .preview-assignment-meta {
    justify-items: start;
  }
}

/* Professional reviewer-signature action group. */
.dean-self-review-signature-actions {
  display: grid !important;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px !important;
  padding-top: 2px;
}

.dean-self-review-signature-actions .dean-self-review-signature-button {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 8px !important;
  width: 100% !important;
  min-width: 0 !important;
  min-height: 44px !important;
  margin: 0 !important;
