/* Rating-scale editor: balanced surfaces and semantic action colors */
.dynamic-scales {
  padding: 20px;
  border-color: #cfe1da;
  background: linear-gradient(145deg, #f7fbf9, #eef7f3);
  box-shadow: 0 12px 30px rgba(24, 77, 58, .07);
}
.dynamic-scales > header { align-items: center; margin-bottom: 16px; }
.dynamic-scales h3 { color: #183b2f; font-size: 1rem; }
.dynamic-scales > header p { margin-top: 3px; color: #687d75; }
.dynamic-scales > header > button {
  border-color: #197a5a;
  color: #fff;
  background: linear-gradient(135deg, #197a5a, #24966f);
  box-shadow: 0 6px 14px rgba(25, 122, 90, .18);
}
.dynamic-scales article {
  padding: 14px;
  border-color: #cddfd8;
  background: rgba(255, 255, 255, .92);
  box-shadow: 0 7px 18px rgba(22, 69, 52, .06);
}
.dynamic-scales .dynamic-scale-head { gap: 8px; }
.dynamic-scales .dynamic-scale-head input {
  border-color: #c7d9d2;
  color: #1f3b31;
  background: #f8fbfa;
  font-size: .84rem;
  font-weight: 750;
}
.dynamic-scales .dynamic-scale-options { gap: 8px; margin-top: 10px; }
.dynamic-scales .dynamic-scale-options label { grid-template-columns: 72px minmax(0, 1fr) 38px; gap: 8px; }
.dynamic-scales .dynamic-scale-options input {
  border-color: #d2e0db;
  color: #304b41;
  background: #fff;
}
.dynamic-scales .dynamic-scale-options input[type="number"] {
  color: #157052;
  background: #edf7f3;
  text-align: center;
  font-weight: 850;
}
.dynamic-scales .dynamic-scale-head button,
.dynamic-scales .dynamic-scale-options label button {
  width: 38px;
  padding: 0;
  color: #b53f4b;
  border-color: #f0cbd0;
