  border: 1px dashed #9fcbb9;
  background: #f1faf6;
  box-shadow: none;
}
.dynamic-scales button:hover:not(:disabled) { filter: brightness(.97); transform: translateY(-1px); }
.dynamic-scales button:disabled { opacity: .42; cursor: not-allowed; }

