/* Smooth sidebar open / close motion
   Keep the labels in the layout while the rail changes width. The older
   responsive rules used display:none, which made the animation snap. */
.admin-body .admin-sidebar,
.admin-dashboard-body .admin-sidebar,
.dean-body .admin-sidebar {
  will-change: width, transform;
  transition:
    width 360ms cubic-bezier(0.22, 1, 0.36, 1),
    transform 360ms cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 240ms ease !important;
}

.admin-body .admin-main,
.admin-dashboard-body .admin-main,
.dean-body .admin-main {
  transition: margin-left 360ms cubic-bezier(0.22, 1, 0.36, 1);
}

.admin-body .sidebar-brand-copy {
  display: grid;
  max-width: 190px;
  opacity: 1;
  transform: translateX(0);
  transition:
    max-width 300ms cubic-bezier(0.22, 1, 0.36, 1),
    opacity 180ms ease 90ms,
    transform 300ms cubic-bezier(0.22, 1, 0.36, 1),
    visibility 0s linear;
}

.admin-body .sidebar-item-label,
.admin-body .auto-badge {
  display: inline-block;
  max-width: 190px;
  opacity: 1;
  transform: translateX(0);
  transition:
    max-width 300ms cubic-bezier(0.22, 1, 0.36, 1),
    opacity 160ms ease 90ms,
    transform 300ms cubic-bezier(0.22, 1, 0.36, 1),
    visibility 0s linear;
}

@media (min-width: 1121px) {
  .admin-body.sidebar-collapsed :is(.sidebar-brand-copy, .sidebar-item-label, .auto-badge) {
    display: grid;
    max-width: 0;
    opacity: 0;
    overflow: hidden;
    visibility: hidden;
    transform: translateX(-8px);
    transition:
      max-width 260ms ease,
      opacity 120ms ease,
      transform 260ms ease,
      visibility 0s linear 260ms;
  }

  .admin-body.sidebar-collapsed :is(.sidebar-item-label, .auto-badge) {
    display: inline-block;
  }
}

@media (min-width: 721px) and (max-width: 1120px) {
  .admin-body:not(.sidebar-open) :is(.sidebar-brand-copy, .sidebar-item-label, .auto-badge) {
    display: grid;
    max-width: 0;
    opacity: 0;
    overflow: hidden;
    visibility: hidden;
    transform: translateX(-8px);
    transition:
      max-width 260ms ease,
      opacity 120ms ease,
      transform 260ms ease,
      visibility 0s linear 260ms;
  }

  .admin-body:not(.sidebar-open) :is(.sidebar-item-label, .auto-badge) {
    display: inline-block;
  }
}

