.people-department-modal>.people-modal-header { flex:0 0 auto; min-height:88px; padding:18px 24px; }
.people-department-modal>.people-department-form { display:flex; flex-direction:column; flex:1 1 auto; min-height:0; padding:0; gap:0; overflow:hidden; }
.people-department-form-scroll { flex:1 1 auto; min-height:0; overflow-y:auto; padding:20px 24px; display:grid; gap:16px; }
.people-department-form textarea,.people-form-field textarea { width:100%; min-height:88px; padding:11px 12px; resize:vertical; border:1px solid var(--theme-border,#d8e3dd); border-radius:11px; background:var(--theme-surface,#fff); color:var(--theme-text,#14231c); font:inherit; }
.people-department-logo-card { display:flex; align-items:center; gap:16px; margin-bottom:15px; padding:14px; border:1px dashed color-mix(in srgb,var(--theme-primary,#16845b) 35%,var(--theme-border,#dbe5df)); border-radius:14px; background:var(--theme-primary-soft,#effaf5); }
.people-department-logo-preview { flex:0 0 76px; width:76px; height:76px; display:grid; place-items:center; overflow:hidden; border:1px solid var(--theme-border,#dbe5df); border-radius:18px; background:var(--theme-surface,#fff); color:var(--theme-primary-strong,#08734d); font-size:1.15rem; font-weight:900; }
.people-department-logo-preview img { width:100%; height:100%; object-fit:contain; }
.people-department-logo-card>div:last-child { display:grid; gap:4px; min-width:0; }.people-department-logo-card small { color:var(--theme-muted,#64748b); font-size:.76rem; }
.people-linked-programs { display:flex; align-items:center; gap:11px; margin-top:14px; padding:12px 13px; border:1px solid var(--theme-border,#dbe5df); border-radius:12px; background:var(--theme-primary-soft,#effaf5); }.people-linked-programs>div{flex:1;display:grid;gap:2px}.people-linked-programs small{color:var(--theme-muted,#64748b)}.people-linked-programs button{min-height:36px;padding:0 11px;border:1px solid var(--theme-border,#dbe5df);border-radius:9px;background:var(--theme-surface,#fff);color:var(--theme-primary-strong,#08734d);font-weight:750}
.people-department-form-footer { flex:0 0 auto; min-height:70px; display:flex; justify-content:space-between; align-items:center; gap:10px; padding:13px 24px; border-top:1px solid var(--theme-border,#dbe5df); background:color-mix(in srgb,var(--theme-surface,#fff) 96%,transparent); backdrop-filter:blur(12px); }.people-department-form-footer button{min-height:43px;height:43px;padding:0 16px;display:inline-flex;align-items:center;justify-content:center;gap:7px;border:1px solid var(--theme-border,#dbe5df);border-radius:11px;background:var(--theme-surface,#fff);color:var(--theme-text,#14231c);font-weight:800}.people-department-form-footer .people-save-department{border:0;background:linear-gradient(135deg,#159764,#08734d);color:#fff}
.admin-body.dark-mode .people-department-modal,.admin-dashboard-body.dark-mode .people-department-modal,body:has(.admin-dashboard-body.dark-mode) .people-department-modal { --theme-surface:#111b2d;--theme-text:#f1f5f9;--theme-muted:#9aa9bd;--theme-border:#2d3b50;--theme-primary-soft:#152825;background:#0f1929;color:#f1f5f9;border-color:#304157 }.admin-body.dark-mode .people-department-modal .people-form-section,.admin-dashboard-body.dark-mode .people-department-modal .people-form-section,body:has(.admin-dashboard-body.dark-mode) .people-department-modal .people-form-section{background:#121e30}.admin-body.dark-mode .people-department-form-footer,.admin-dashboard-body.dark-mode .people-department-form-footer,body:has(.admin-dashboard-body.dark-mode) .people-department-form-footer{background:rgba(15,25,41,.95)}
@media(max-width:700px){.people-modal-panel.people-department-modal{width:100%;max-height:calc(100dvh - 16px);border-radius:16px}.people-department-modal>.people-modal-header{min-height:76px;padding:14px 15px}.people-department-form-scroll{padding:14px}.people-department-logo-card{align-items:flex-start}.people-department-form-footer{min-height:64px;padding:10px 14px}.people-department-form-footer button{flex:1;min-width:0;padding:0 9px}}

/* The managed self-evaluation editor always uses its light green theme,
   even when it is opened from a dark dashboard through a body portal. */
.managed-self-eval-editor .evaluation-form-modal .evaluation-nav-btn.secondary {
  border-color: rgba(22, 131, 88, 0.28) !important;
  background: linear-gradient(180deg, #ffffff, #f0faf5) !important;
  color: #126b48 !important;
  box-shadow: 0 8px 18px rgba(15, 81, 56, 0.08) !important;
}

.managed-self-eval-editor .evaluation-form-modal .evaluation-nav-btn.secondary:hover:not(:disabled) {
  border-color: rgba(18, 107, 72, 0.48) !important;
  background: #e7f7ef !important;
  box-shadow: 0 12px 24px rgba(15, 81, 56, 0.14) !important;
}

.managed-self-eval-editor .evaluation-form-modal :where(.evaluation-submit-btn, .review-nav-btn) {
  border-color: rgba(18, 107, 72, 0.5) !important;
  background: linear-gradient(135deg, #159764 0%, #08734d 100%) !important;
  color: #ffffff !important;
  box-shadow: 0 14px 30px rgba(8, 115, 77, 0.24) !important;
  animation: none !important;
}

.managed-self-eval-editor .evaluation-form-modal :where(.evaluation-submit-btn, .review-nav-btn):hover:not(:disabled) {
  border-color: rgba(6, 95, 70, 0.65) !important;
  background: linear-gradient(135deg, #168f60 0%, #065f46 100%) !important;
  box-shadow: 0 17px 34px rgba(8, 115, 77, 0.3) !important;
}

.managed-self-eval-editor .evaluation-form-modal :where(.evaluation-nav-btn, .evaluation-submit-btn, .review-nav-btn):focus-visible {
  outline-color: rgba(22, 131, 88, 0.34) !important;
}

.managed-self-eval-editor .evaluation-form-modal :where(.evaluation-nav-btn, .evaluation-submit-btn, .review-nav-btn):disabled {
  border-color: #d8e3dd !important;
  background: #eef3f0 !important;
  color: #8a9891 !important;
  box-shadow: none !important;
}

.self-eval-reviewer-signature-field {
  grid-column: 1 / -1;
  width: 100%;
}

.self-eval-reviewer-signature-card {
  display: grid;
  grid-template-columns: minmax(210px, 0.7fr) minmax(280px, 1.3fr);
  align-items: center;
  gap: 18px;
  padding: 16px;
  border: 1px solid rgba(22, 131, 88, 0.28);
  border-radius: 14px;
  background: linear-gradient(135deg, #f5fcf8, #ffffff);
  box-shadow: 0 10px 24px rgba(15, 81, 56, 0.06);
}

.self-eval-reviewer-signature-copy {
  display: grid;
  gap: 7px;
  min-width: 0;
}

.self-eval-reviewer-signature-copy > span {
  color: #08734d;
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.self-eval-reviewer-signature-copy > strong {
  color: var(--ui-text, #17231f);
  font-size: 1rem;
  overflow-wrap: anywhere;
}

.self-eval-reviewer-signature-copy > small {
  color: var(--ui-muted, #64748b);
  font-size: 0.72rem;
  font-weight: 750;
  overflow-wrap: anywhere;
}

.self-eval-reviewer-signature-date {
  display: grid;
  gap: 2px;
  margin-top: 2px;
  padding-top: 9px;
  border-top: 1px solid rgba(22, 131, 88, 0.16);
}

.self-eval-reviewer-signature-date span {
  color: var(--ui-muted, #64748b);
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.self-eval-reviewer-signature-date time {
  color: var(--ui-text, #17231f);
  font-size: 0.82rem;
  font-weight: 850;
}

.self-eval-reviewer-signature-card .self-eval-signature-preview {
  min-height: 104px;
  max-height: 120px;
}

.self-eval-reviewer-signature-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  width: fit-content;
  color: #08734d;
  font-size: 0.78rem;
  font-weight: 850;
}

@media (max-width: 640px) {
  .self-eval-reviewer-signature-card {
    grid-template-columns: 1fr;
    gap: 12px;
  }
}
@media(max-width:380px){.people-department-logo-card{display:grid;grid-template-columns:62px 1fr}.people-department-logo-preview{width:62px;height:62px}.people-department-logo-card .people-avatar-actions{grid-column:1/-1}.people-linked-programs{align-items:flex-start;flex-wrap:wrap}.people-linked-programs button{width:100%}}

/* Admin/HR dashboard hero — scoped to this dashboard only. */
.hero-card.admin-dashboard-hero {
  grid-template-columns: minmax(0, 72%) minmax(220px, 28%) !important;
  align-items: center !important;
  min-height: 360px !important;
  max-height: none !important;
  padding: clamp(26px, 3vw, 48px) !important;
  overflow: hidden !important;
  background:
    linear-gradient(90deg, rgba(248,255,252,.96) 0%, rgba(240,253,250,.86) 35%, rgba(230,250,240,.55) 65%, rgba(220,245,230,.28) 100%),
    url('/assets/images/pmas-campus-bg.jpg') center right / cover no-repeat !important;
}
.hero-card.admin-dashboard-hero > div:first-child {
  position: relative;
  z-index: 2;
  min-width: 0;
  animation: admin-hero-copy-in .55s ease-out both;
}
.hero-card.admin-dashboard-hero .hero-actions {
  width: fit-content !important;
  max-width: min(100%, 720px);
  margin-top: 18px;
  animation: admin-hero-controls-in .6s .12s ease-out both;
}
.hero-card.admin-dashboard-hero .dashboard-period-selector {
  display: flex !important;
  flex-wrap: nowrap !important;
  width: fit-content !important;
  max-width: 100% !important;
  padding: 8px 10px !important;
  gap: 9px !important;
}
.hero-card.admin-dashboard-hero .period-selector-select-wrapper {
  flex: 1 1 auto !important;
  width: clamp(300px, 36vw, 520px) !important;
  min-width: 0 !important;
}
.hero-card.admin-dashboard-hero .period-selector-select {
  width: 100% !important;
  min-width: 0 !important;
  min-height: 42px !important;
}
.hero-card.admin-dashboard-hero .period-selector-refresh {
  width: 42px !important;
  height: 42px !important;
  min-width: 42px !important;
  border-radius: 12px !important;
  transition: transform .22s ease, box-shadow .22s ease, background-color .22s ease !important;
}
.hero-card.admin-dashboard-hero .period-selector-refresh:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 16px rgba(15,118,78,.2) !important;
}
.hero-card.admin-dashboard-hero .period-selector-refresh:hover svg {
  transform: rotate(150deg);
}
.hero-card.admin-dashboard-hero .period-selector-refresh svg {
  transition: transform .35s ease;
}
.hero-card.admin-dashboard-hero .period-selector-refresh .animate-spin {
  animation: spin 1s linear infinite !important;
}
.hero-card.admin-dashboard-hero .hero-illustration {
  display: grid !important;
  place-items: center !important;
  align-self: stretch !important;
  min-height: 280px !important;
  max-height: none !important;
  overflow: visible !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  animation: admin-hero-robot-in .62s .08s ease-out both;
}
.hero-card.admin-dashboard-hero .hero-illustration::before,
.hero-card.admin-dashboard-hero .hero-illustration::after {
  display: none !important;
  content: none !important;
}
.hero-card.admin-dashboard-hero .hero-robot {
  position: relative !important;
  inset: auto !important;
  align-self: center !important;
  justify-self: center !important;
  width: clamp(220px, 17vw, 300px) !important;
  height: clamp(220px, 17vw, 300px) !important;
  max-width: none !important;
  margin: 0 !important;
  object-fit: contain !important;
  object-position: center !important;
  filter: drop-shadow(0 14px 28px rgba(16,185,129,.18)) !important;
  animation: admin-hero-robot-float 4s ease-in-out infinite !important;
  transition: scale .24s ease, filter .24s ease !important;
}
.hero-card.admin-dashboard-hero .hero-illustration:hover .hero-robot {
  scale: 1.03;
  filter: drop-shadow(0 18px 32px rgba(16,185,129,.26)) !important;
}
.admin-body.dark-mode .hero-card.admin-dashboard-hero,
.admin-dashboard-body.dark-mode .hero-card.admin-dashboard-hero,
body:has(.admin-dashboard-body.dark-mode) .hero-card.admin-dashboard-hero {
  background:
    linear-gradient(90deg, rgba(7,15,30,.97) 0%, rgba(15,23,42,.9) 40%, rgba(30,58,138,.58) 72%, rgba(15,23,42,.35) 100%),
    url('/assets/images/pmas-campus-bg.jpg') center right / cover no-repeat !important;
}
.admin-body.dark-mode .hero-card.admin-dashboard-hero .hero-robot,
.admin-dashboard-body.dark-mode .hero-card.admin-dashboard-hero .hero-robot,
body:has(.admin-dashboard-body.dark-mode) .hero-card.admin-dashboard-hero .hero-robot {
  filter: drop-shadow(0 14px 30px rgba(59,130,246,.25)) !important;
}
@keyframes admin-hero-copy-in { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
@keyframes admin-hero-controls-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
@keyframes admin-hero-robot-in { from { opacity: 0; transform: translateX(14px); } to { opacity: 1; transform: none; } }
@keyframes admin-hero-robot-float { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-5px); } }
@media (max-width: 1100px) {
  .hero-card.admin-dashboard-hero {
    grid-template-columns: minmax(0, 1fr) minmax(180px, 25%) !important;
    min-height: 310px !important;
  }
  .hero-card.admin-dashboard-hero .hero-robot {
    width: clamp(170px, 21vw, 220px) !important;
    height: clamp(170px, 21vw, 220px) !important;
  }
}
@media (max-width: 720px) {
  .hero-card.admin-dashboard-hero {
    grid-template-columns: 1fr !important;
    min-height: 0 !important;
    padding: 20px !important;
  }
  .hero-card.admin-dashboard-hero .hero-actions,
  .hero-card.admin-dashboard-hero .dashboard-period-selector,
  .hero-card.admin-dashboard-hero .period-selector-select-wrapper {
    width: 100% !important;
  }
  .hero-card.admin-dashboard-hero .dashboard-period-selector {
    display: grid !important;
    grid-template-columns: 20px minmax(0,1fr) 42px !important;
  }
  .hero-card.admin-dashboard-hero .period-selector-select-wrapper {
    grid-column: 1 / -1;
    grid-row: 2;
  }
  .hero-card.admin-dashboard-hero .period-selector-status {
    grid-column: 2;
    grid-row: 1;
    justify-self: start;
  }
  .hero-card.admin-dashboard-hero .period-selector-refresh {
    grid-column: 3;
    grid-row: 1;
  }
  .hero-card.admin-dashboard-hero .hero-illustration {
    display: grid !important;
    min-height: 150px !important;
    place-items: end center !important;
  }
  .hero-card.admin-dashboard-hero .hero-robot {
    width: clamp(120px, 38vw, 160px) !important;
    height: clamp(120px, 38vw, 160px) !important;
  }
}
@media (prefers-reduced-motion: reduce) {
  .hero-card.admin-dashboard-hero > div:first-child,
  .hero-card.admin-dashboard-hero .hero-actions,
  .hero-card.admin-dashboard-hero .hero-illustration,
  .hero-card.admin-dashboard-hero .hero-robot {
    animation: none !important;
    transform: none !important;
  }
}

.program-head-assigned-programs {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 10px;
}

.program-head-assigned-programs > span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 1px solid rgba(22,131,88,.22);
  border-radius: 999px;
  background: rgba(22,131,88,.08);
  color: #135e43;
  padding: 5px 9px;
  font-size: .7rem;
  font-weight: 850;
}

.program-head-assigned-programs b,
.program-head-assigned-programs em {
  border-left: 1px solid currentColor;
  padding-left: 6px;
  font-size: .58rem;
  font-style: normal;
  opacity: .76;
}

body:has(:is(.admin-body,.admin-dashboard-body).dark-mode) .program-head-assigned-programs > span {
  border-color: rgba(52,211,153,.26);
  background: rgba(16,185,129,.1);
  color: #a7f3d0;
}

/* Evaluation Assignments — scannable table, semantic statuses, responsive rows. */
.program-ai-modal-assignments {
  --assignment-primary: #147c68;
  --assignment-primary-soft: #eaf7f2;
  --assignment-complete: #157a55;
  --assignment-complete-soft: #e8f7f0;
  --assignment-pending: #9a6816;
  --assignment-pending-soft: #fff5dc;
  --assignment-missing: #b24a45;
  --assignment-missing-soft: #fff0ee;
  overflow: hidden;
  border: 1px solid #d4e6de;
  border-radius: 22px;
  background:
    radial-gradient(circle at 2% 0%, rgba(20, 124, 104, .07), transparent 26%),
    linear-gradient(160deg, #ffffff, #fbfdfc);
  box-shadow: 0 20px 48px rgba(20, 69, 54, .09);
}

.program-ai-modal-assignments .program-ai-modal-section-heading {
  min-height: 86px;
  margin: 0;
  border-bottom: 1px solid #dbeae4;
  background: linear-gradient(135deg, rgba(237, 249, 244, .9), rgba(249, 252, 251, .88));
  padding: 18px 20px;
}

.program-ai-modal-assignments .program-ai-modal-section-heading > span {
  position: relative;
  overflow: visible;
  border: 1px solid rgba(20, 124, 104, .16);
  background: linear-gradient(145deg, #dff7ed, #eef9f5);
  color: var(--assignment-primary);
  box-shadow: 0 9px 22px rgba(20, 124, 104, .14);
  animation: assignmentIconFloat 3.6s ease-in-out infinite;
}

.program-ai-modal-assignments .program-ai-modal-section-heading > span::after {
  position: absolute;
  inset: -6px;
  z-index: -1;
  border-radius: inherit;
  background: rgba(20, 124, 104, .12);
  content: "";
  filter: blur(9px);
  opacity: .7;
}

.program-ai-modal-assignments .program-ai-modal-section-heading h4 {
  margin: 0 0 5px;
  color: #153c2f;
  font-size: 1.05rem;
  font-weight: 850;
  letter-spacing: -.01em;
}

.program-ai-modal-assignments .program-ai-modal-section-heading small {
  color: #60766d;
  font-size: .74rem;
  font-weight: 650;
}

.program-ai-modal-assignments .dean-assignment-table-wrap {
  margin: 16px;
  width: calc(100% - 32px);
  border-color: #cfe2da;
  border-radius: 17px;
  box-shadow: 0 10px 28px rgba(29, 66, 54, .06);
}

.program-ai-modal-assignments .dean-assignment-table {
  font-size: .75rem;
}

.program-ai-modal-assignments .dean-assignment-table th {
  height: 50px;
  padding: 12px 16px;
  border-color: #cfe2da;
  background: linear-gradient(180deg, #edf7f3, #e8f3ee);
  color: #285b49;
  font-size: .64rem;
  letter-spacing: .065em;
}

.program-ai-modal-assignments .dean-assignment-table td {
  min-height: 76px;
  padding: 16px;
  border-color: #dce9e3;
  color: #476158;
  line-height: 1.45;
  transition: background-color 200ms ease, box-shadow 200ms ease, transform 200ms ease;
}

.program-ai-modal-assignments .dean-assignment-table tbody tr:hover td {
  background: #f6fbf9;
}

.program-ai-modal-assignments .dean-assignment-table tbody tr:hover td:first-child {
  transform: translateX(3px);
}

.program-ai-modal-assignments .dean-assignment-table td > strong {
  color: #173f32;
  font-size: .76rem;
  font-weight: 850;
}

.program-ai-modal-assignments .dean-assignment-role {
  border-color: #c7ddd4;
  background: linear-gradient(135deg, #f7fbf9, #eef6f2);
  color: #49675c;
  padding: 5px 9px;
  font-size: .63rem;
  letter-spacing: .01em;
  box-shadow: inset 0 1px rgba(255,255,255,.8);
}

.program-ai-modal-assignments .program-ai-assignment-pill {
  display: inline-flex;
  min-height: 29px;
  align-items: center;
  gap: 6px;
  border: 1px solid transparent;
  padding: 5px 10px;
  letter-spacing: .035em;
  box-shadow: 0 6px 14px rgba(15, 23, 42, .06);
}

.program-ai-modal-assignments .program-ai-assignment-pill svg {
  flex: 0 0 auto;
  animation: assignmentStatusFloat 3.2s ease-in-out infinite;
  filter: drop-shadow(0 2px 4px currentColor);
}

.program-ai-modal-assignments .program-ai-assignment-pill.is-completed {
  border-color: rgba(21, 122, 85, .18);
  background: var(--assignment-complete-soft);
  color: var(--assignment-complete);
}

.program-ai-modal-assignments .program-ai-assignment-pill.is-pending {
  border-color: rgba(154, 104, 22, .18);
  background: var(--assignment-pending-soft);
  color: var(--assignment-pending);
}

.program-ai-modal-assignments .program-ai-assignment-pill.is-missing {
  border-color: rgba(178, 74, 69, .18);
  background: var(--assignment-missing-soft);
  color: var(--assignment-missing);
}

.program-ai-modal-assignments .dean-assignment-note {
  margin-top: 7px;
  color: #647a91;
  line-height: 1.45;
}

.program-ai-modal-assignments .dean-assignment-required {
  display: inline-flex;
  align-items: center;
  border: 1px solid rgba(20, 124, 104, .14);
  background: linear-gradient(135deg, #dcf5e9, #e9f9f2);
  color: #0c7456;
  letter-spacing: .025em;
  box-shadow: 0 5px 12px rgba(20, 124, 104, .08);
}

.program-ai-modal-assignments .dean-assignment-table tr.is-current-dean td {
  background: linear-gradient(90deg, #f0faf6, #f8fcfa);
}

.program-ai-modal-assignments .dean-assignment-table tr.is-current-dean td:first-child {
  box-shadow: inset 4px 0 var(--assignment-primary);
}

.program-ai-modal-assignments .dean-assignment-table tr.is-current-dean:hover td {
  background: linear-gradient(90deg, #eaf7f2, #f4faf7);
}

.program-ai-modal-assignments .dean-assignment-action {
  position: relative;
  overflow: hidden;
  min-height: 40px;
  border: 1px solid rgba(255,255,255,.15);
  border-radius: 11px;
  background: linear-gradient(135deg, #147c68, #168f73 56%, #277f92);
  padding: 0 13px;
  box-shadow: 0 9px 20px rgba(20, 124, 104, .2);
  transition: transform 190ms ease, box-shadow 190ms ease, filter 190ms ease;
}

.program-ai-modal-assignments .dean-assignment-action::after {
  position: absolute;
  inset: 0;
  background: linear-gradient(110deg, transparent 20%, rgba(255,255,255,.25) 48%, transparent 76%);
  content: "";
  transform: translateX(-105%);
}

.program-ai-modal-assignments .dean-assignment-action svg {
  animation: assignmentActionFloat 2.8s ease-in-out infinite;
  filter: drop-shadow(0 2px 4px rgba(255,255,255,.28));
}

.program-ai-modal-assignments .dean-assignment-action:hover {
  transform: translateY(-3px);
  filter: saturate(1.08);
  box-shadow: 0 14px 28px rgba(20, 124, 104, .28), 0 0 20px rgba(39, 127, 146, .1);
}

.program-ai-modal-assignments .dean-assignment-action:hover::after {
  transform: translateX(105%);
  transition: transform 540ms ease;
}

.program-ai-modal-assignments .dean-assignment-action:active {
  transform: translateY(0) scale(.975);
  box-shadow: 0 6px 14px rgba(20, 124, 104, .2);
}

.program-ai-modal-assignments .dean-assignment-action:focus-visible {
  outline: 3px solid rgba(39, 127, 146, .3);
  outline-offset: 3px;
}

body:has(.dark-mode) .program-ai-modal-assignments {
