  --assignment-primary-soft: rgba(43, 112, 166, .16);
  --assignment-complete: #74d7ad;
  --assignment-complete-soft: rgba(31, 113, 80, .2);
  --assignment-pending: #f1c46f;
  --assignment-pending-soft: rgba(139, 91, 18, .21);
