}

@keyframes assignmentIconFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-4px); }
}

@keyframes assignmentStatusFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-2px); }
}

@keyframes assignmentActionFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-2px); }
}

@media (max-width: 980px) {
  .program-ai-modal-assignments .dean-assignment-table-wrap {
    overflow: visible;
    border: 0;
    background: transparent;
    box-shadow: none;
  }

  .program-ai-modal-assignments .dean-assignment-table {
    display: block;
    min-width: 0;
  }

  .program-ai-modal-assignments .dean-assignment-table thead {
    display: none;
  }

  .program-ai-modal-assignments .dean-assignment-table tbody {
    display: grid;
    gap: 12px;
  }

  .program-ai-modal-assignments .dean-assignment-table tr {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    overflow: hidden;
    border: 1px solid #d3e5dc;
    border-radius: 15px;
    background: #fff;
    box-shadow: 0 9px 22px rgba(15,23,42,.05);
  }

  .program-ai-modal-assignments .dean-assignment-table td {
    display: grid;
    grid-template-columns: 100px minmax(0, 1fr);
    align-content: start;
    gap: 8px;
    min-height: 0;
    padding: 12px 14px;
  }

  .program-ai-modal-assignments .dean-assignment-table td::before {
    color: #73877f;
    content: attr(data-label);
    font-size: .59rem;
    font-weight: 900;
    letter-spacing: .05em;
    text-transform: uppercase;
  }

  .program-ai-modal-assignments .dean-assignment-table td:last-child {
    border-bottom: 1px solid #d8e7e0;
  }

  body:has(.dark-mode) .program-ai-modal-assignments .dean-assignment-table tr {
    border-color: #294b66;
    background: #102438;
  }
}

@media (max-width: 620px) {
  .program-ai-modal-assignments {
    border-radius: 17px;
  }

  .program-ai-modal-assignments .program-ai-modal-section-heading {
    align-items: flex-start;
    padding: 16px;
  }

  .program-ai-modal-assignments .dean-assignment-table-wrap {
    width: calc(100% - 20px);
    margin: 10px;
  }

  .program-ai-modal-assignments .dean-assignment-table tr {
    grid-template-columns: 1fr;
  }

  .program-ai-modal-assignments .dean-assignment-table td {
    grid-template-columns: 92px minmax(0, 1fr);
  }

  .program-ai-modal-assignments .dean-assignment-action {
    width: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .program-ai-modal-assignments .program-ai-modal-section-heading > span,
  .program-ai-modal-assignments .program-ai-assignment-pill svg,
  .program-ai-modal-assignments .dean-assignment-action svg {
    animation: none !important;
  }

  .program-ai-modal-assignments .dean-assignment-table td,
  .program-ai-modal-assignments .dean-assignment-action,
  .program-ai-modal-assignments .dean-assignment-action::after {
    transition-duration: .01ms !important;
  }
}

/* Evaluation Details cards — coordinated semantic color system. */
.department-ai-page {
  --faculty-score: #0f8f83;
  --faculty-score-2: #19b69f;
  --faculty-score-soft: #edf9f6;
  --faculty-completion: #4f67c8;
  --faculty-completion-2: #2da9c5;
  --faculty-completion-soft: #f0f3ff;
  --faculty-weak: #b86d18;
  --faculty-weak-2: #d89a2b;
  --faculty-weak-soft: #fff7e9;
  --faculty-strength: #16815c;
  --faculty-strength-2: #35a875;
  --faculty-strength-soft: #edf9f3;
  --faculty-ai: #3569a8;
  --faculty-ai-2: #6a67b8;
  --faculty-ai-soft: #eef5fc;
}

.department-ai-page .program-ai-faculty-grid {
  align-items: stretch;
  gap: clamp(16px, 1.5vw, 24px);
}

.department-ai-page .program-ai-faculty-card {
  height: 100%;
  min-height: 100%;
  grid-template-rows: auto auto auto 1fr auto;
  align-content: start;
  gap: 14px;
  isolation: isolate;
  border: 1px solid color-mix(in srgb, var(--faculty-score) 18%, var(--dai-border)) !important;
  border-top: 0 !important;
  border-radius: 22px;
  background:
    radial-gradient(circle at 96% 2%, rgba(53, 105, 168, .08), transparent 27%),
    linear-gradient(155deg, #ffffff, #fbfdfd 54%, #f7fbfa) !important;
  padding: 22px;
  box-shadow:
    0 18px 46px rgba(23, 54, 45, .09),
    0 1px 2px rgba(15, 23, 42, .04);
  animation: facultyDetailEnter 460ms cubic-bezier(.2, .8, .2, 1) both;
  transition: transform 260ms cubic-bezier(.2, .8, .2, 1), border-color 260ms ease, box-shadow 260ms ease;
}

.department-ai-page .program-ai-faculty-card::before {
  height: 5px;
  background: linear-gradient(90deg, var(--faculty-score), #20a89b 48%, var(--faculty-completion-2)) !important;
  box-shadow: 0 2px 12px rgba(15, 143, 131, .24);
}

.department-ai-page .program-ai-faculty-card::after {
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  background: linear-gradient(115deg, transparent 12%, rgba(255, 255, 255, .38) 48%, transparent 72%);
  content: "";
  opacity: 0;
  transform: translateX(-45%);
  pointer-events: none;
}

.department-ai-page .program-ai-faculty-card:hover {
  transform: translateY(-5px);
  border-color: color-mix(in srgb, var(--faculty-score) 36%, var(--dai-border)) !important;
  box-shadow:
    0 26px 58px rgba(23, 76, 60, .14),
    0 0 28px rgba(15, 143, 131, .08);
}

.department-ai-page .program-ai-faculty-card:hover::after {
  opacity: .55;
  transform: translateX(45%);
  transition: opacity 180ms ease, transform 720ms ease;
}

.department-ai-page .program-ai-faculty-card-head {
  min-height: 66px;
  gap: 12px;
  padding: 2px 2px 16px;
}

.department-ai-page .program-ai-faculty-card-head .eval-monitor-faculty-avatar {
  width: 50px;
  height: 50px;
  border-radius: 16px;
  background: linear-gradient(145deg, #dff8ef, #e8f4ff);
  box-shadow: 0 10px 24px rgba(15, 143, 131, .14);
  transition: transform 260ms cubic-bezier(.2, .8, .2, 1), box-shadow 260ms ease;
}

.department-ai-page .program-ai-faculty-card:hover .eval-monitor-faculty-avatar {
  transform: translateY(-3px) rotate(-2deg);
  box-shadow: 0 14px 28px rgba(15, 143, 131, .2);
}

.department-ai-page .program-ai-faculty-card-head h4 {
  font-size: clamp(1rem, 1.15vw, 1.12rem);
  line-height: 1.28;
  letter-spacing: -.015em;
}

.department-ai-page .program-ai-faculty-card-head > div > span {
  display: block;
  margin-top: 4px;
  font-size: .75rem;
  line-height: 1.35;
}

.department-ai-page .program-ai-faculty-card-head > small {
  border-color: rgba(15, 143, 131, .2);
  background: linear-gradient(135deg, #edf9f6, #e9f7f3);
  color: #11715f;
  padding: 7px 11px;
}

.department-ai-page .program-ai-faculty-stats {
  gap: 12px;
}

.department-ai-page .program-ai-score-block {
  min-height: 132px;
  border-radius: 17px;
  padding: 15px 16px;
  box-shadow: inset 0 1px rgba(255,255,255,.75), 0 8px 20px rgba(27, 62, 52, .05);
  transition: transform 220ms ease, box-shadow 220ms ease;
}

.department-ai-page .program-ai-score-block:first-child {
  border-color: color-mix(in srgb, var(--faculty-score) 24%, transparent);
  background: linear-gradient(145deg, #f7fcfb, var(--faculty-score-soft));
}

.department-ai-page .program-ai-score-block:last-child {
  border-color: color-mix(in srgb, var(--faculty-completion) 21%, transparent);
  background: linear-gradient(145deg, #f8f9ff, var(--faculty-completion-soft));
}

.department-ai-page .program-ai-score-block:hover {
  transform: translateY(-2px);
  box-shadow: inset 0 1px rgba(255,255,255,.8), 0 12px 24px rgba(27, 62, 52, .09);
}

.department-ai-page .program-ai-score-block > span {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: .72rem;
  letter-spacing: .025em;
}

.department-ai-page .program-ai-score-block:first-child > span,
.department-ai-page .program-ai-score-block:first-child > span svg {
  color: var(--faculty-score) !important;
}

.department-ai-page .program-ai-score-block:last-child > span,
.department-ai-page .program-ai-score-block:last-child > span svg {
  color: var(--faculty-completion) !important;
}

.department-ai-page .program-ai-faculty-stats strong {
  margin: 9px 0 14px;
  font-size: 1.55rem;
  letter-spacing: -.035em;
}

.department-ai-page .program-ai-mini-bar {
  height: 9px;
  background: rgba(91, 114, 105, .13);
  box-shadow: inset 0 1px 3px rgba(15, 23, 42, .11);
}

.department-ai-page .program-ai-mini-bar i {
  background: linear-gradient(90deg, var(--faculty-score), var(--faculty-score-2));
  box-shadow: 0 0 12px rgba(15, 143, 131, .22);
  transition: width 620ms cubic-bezier(.2, .8, .2, 1);
}

.department-ai-page .program-ai-mini-bar.completion i {
  background: linear-gradient(90deg, var(--faculty-completion), var(--faculty-completion-2));
  box-shadow: 0 0 12px rgba(79, 103, 200, .2);
}

.department-ai-page .program-ai-analysis-item {
  min-height: 88px;
  border-radius: 16px;
  padding: 14px 15px;
  box-shadow: 0 8px 18px rgba(15, 23, 42, .035);
  transition: transform 220ms ease, box-shadow 220ms ease, border-color 220ms ease;
}

.department-ai-page .program-ai-analysis-item:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 24px rgba(15, 23, 42, .075);
}

.department-ai-page .program-ai-analysis-item.weak {
  border-color: color-mix(in srgb, var(--faculty-weak) 27%, transparent);
  background: linear-gradient(145deg, #fffaf2, var(--faculty-weak-soft));
}

.department-ai-page .program-ai-analysis-item.weak > span,
.department-ai-page .program-ai-analysis-item.weak > span svg {
  color: var(--faculty-weak) !important;
}

.department-ai-page .program-ai-analysis-item.strength {
  border-color: color-mix(in srgb, var(--faculty-strength) 25%, transparent);
  background: linear-gradient(145deg, #f6fcf9, var(--faculty-strength-soft));
}

.department-ai-page .program-ai-analysis-item.strength > span,
.department-ai-page .program-ai-analysis-item.strength > span svg {
  color: var(--faculty-strength) !important;
}

.department-ai-page .program-ai-analysis-item.recommendation {
  min-height: 94px;
  border-color: color-mix(in srgb, var(--faculty-ai) 24%, transparent);
  background: linear-gradient(145deg, #f6f9fd, var(--faculty-ai-soft));
}

.department-ai-page .program-ai-analysis-item.recommendation > span,
.department-ai-page .program-ai-analysis-item.recommendation > span svg {
  color: var(--faculty-ai) !important;
}

.department-ai-page .program-ai-analysis-item > span {
  margin-bottom: 8px;
  font-size: .7rem;
  letter-spacing: .06em;
}

.department-ai-page .program-ai-analysis-item strong,
.department-ai-page .program-ai-analysis-item p {
  line-height: 1.45;
}

.department-ai-page .program-ai-faculty-detail {
  align-self: stretch;
}

.department-ai-page .program-ai-faculty-detail > div {
  border-radius: 16px;
  padding: 14px;
  box-shadow: 0 8px 18px rgba(15, 23, 42, .03);
}

.department-ai-page .program-ai-faculty-detail > div:first-child {
  border-color: color-mix(in srgb, var(--faculty-weak) 18%, var(--dai-border));
  background: linear-gradient(160deg, #fffdfa, #fffbf2);
}

.department-ai-page .program-ai-faculty-detail > div:last-child {
  border-color: color-mix(in srgb, var(--faculty-strength) 18%, var(--dai-border));
  background: linear-gradient(160deg, #fbfefc, #f4fbf7);
}

.department-ai-page .program-ai-faculty-detail > div > span {
  display: block;
  margin-bottom: 10px;
  font-weight: 900;
  letter-spacing: .045em;
  text-transform: uppercase;
}

.department-ai-page .program-ai-chip-list small {
  border-radius: 11px;
  transition: transform 180ms ease, box-shadow 180ms ease;
}

.department-ai-page .program-ai-chip-list small:hover {
  transform: translateX(3px);
  box-shadow: 0 7px 16px rgba(15, 23, 42, .06);
}

.department-ai-page .program-ai-view-details {
  position: relative;
  overflow: hidden;
  justify-self: stretch;
  width: 100%;
  margin-top: auto;
  border-color: transparent !important;
  border-radius: 13px !important;
  background: linear-gradient(135deg, #147c68, #168f78 52%, #277f9e) !important;
  box-shadow: 0 11px 24px rgba(20, 124, 104, .2) !important;
  transition: transform 190ms ease, box-shadow 190ms ease, filter 190ms ease;
}

.department-ai-page .program-ai-view-details::after {
  position: absolute;
  inset: 0;
  background: linear-gradient(110deg, transparent 20%, rgba(255,255,255,.24) 48%, transparent 76%);
  content: "";
  transform: translateX(-100%);
}

.department-ai-page .program-ai-view-details:hover {
  transform: translateY(-2px);
  filter: saturate(1.08);
  box-shadow: 0 16px 30px rgba(20, 124, 104, .28), 0 0 20px rgba(39, 127, 158, .1) !important;
}

.department-ai-page .program-ai-view-details:hover::after {
  transform: translateX(100%);
  transition: transform 560ms ease;
}

.department-ai-page .program-ai-view-details:active {
  transform: translateY(0) scale(.985);
}

.department-ai-page .program-ai-view-details:focus-visible {
  outline: 3px solid rgba(45, 169, 197, .3);
  outline-offset: 3px;
}

:is(.admin-body.dark-mode, .admin-dashboard-body.dark-mode) .department-ai-page {
  --faculty-score: #55cbbb;
  --faculty-score-2: #6bd8bd;
  --faculty-score-soft: rgba(36, 127, 111, .15);
  --faculty-completion: #91a7ff;
  --faculty-completion-2: #60c4dd;
  --faculty-completion-soft: rgba(78, 99, 174, .16);
  --faculty-weak: #efbb67;
  --faculty-weak-soft: rgba(151, 98, 25, .17);
