  box-shadow: 0 20px 50px rgba(0,0,0,.28), 0 0 24px rgba(85,203,187,.04);
}

:is(.admin-body.dark-mode, .admin-dashboard-body.dark-mode) .department-ai-page .program-ai-score-block:first-child {
  background: linear-gradient(145deg, rgba(20, 51, 44, .92), var(--faculty-score-soft));
}

:is(.admin-body.dark-mode, .admin-dashboard-body.dark-mode) .department-ai-page .program-ai-score-block:last-child {
  background: linear-gradient(145deg, rgba(30, 42, 71, .88), var(--faculty-completion-soft));
}

:is(.admin-body.dark-mode, .admin-dashboard-body.dark-mode) .department-ai-page .program-ai-analysis-item.weak {
