}

:is(.admin-body.dark-mode, .admin-dashboard-body.dark-mode) .department-ai-page .program-ai-faculty-detail > div:last-child {
  background: linear-gradient(160deg, rgba(18, 48, 36, .8), rgba(17, 41, 32, .6));
}

@keyframes facultyDetailEnter {
  from { opacity: 0; transform: translateY(12px) scale(.99); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

@media (max-width: 760px) {
  .department-ai-page .program-ai-faculty-card {
    grid-template-rows: auto;
    border-radius: 18px;
    padding: 17px;
  }

  .department-ai-page .program-ai-faculty-stats {
    grid-template-columns: 1fr;
  }

  .department-ai-page .program-ai-score-block {
    min-height: 118px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .department-ai-page .program-ai-faculty-card,
  .department-ai-page .program-ai-faculty-card::after,
  .department-ai-page .program-ai-score-block,
  .department-ai-page .program-ai-analysis-item,
  .department-ai-page .program-ai-chip-list small,
  .department-ai-page .program-ai-view-details,
  .department-ai-page .program-ai-view-details::after {
    animation: none !important;
    transition-duration: .01ms !important;
  }
