/* VPAA report export controls: fluid sizing from desktop to mobile. */
.vpaa-report-controls {
  grid-template-columns: minmax(240px, 1fr) minmax(360px, 1.15fr) !important;
  align-items: end;
  width: 100%;
}

.vpaa-report-controls > label,
.vpaa-report-controls .role-report-export,
.vpaa-report-controls .role-report-export label,
.vpaa-report-controls select,
.vpaa-report-controls button {
  min-width: 0;
  max-width: 100%;
}

.vpaa-report-controls .role-report-export {
  grid-template-columns: minmax(120px, 1fr) minmax(150px, auto);
  gap: 12px;
}

.vpaa-report-controls .role-report-export button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  white-space: nowrap;
}

@media (max-width: 900px) {
  .vpaa-report-controls {
    grid-template-columns: 1fr !important;
  }

  .vpaa-report-controls .role-report-export {
    grid-template-columns: minmax(0, 1fr) minmax(150px, 0.55fr);
  }
}

@media (max-width: 520px) {
  .vpaa-report-workspace .role-report-hero {
    padding: 16px;
  }

  .vpaa-report-controls,
  .vpaa-report-controls .role-report-export {
    grid-template-columns: 1fr !important;
  }

  .vpaa-report-controls .role-report-export button {
    width: 100%;
  }
}

