.dipascaf-modal {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  background: rgba(2, 6, 23, 0.55);
  padding: 18px;
  backdrop-filter: blur(4px);
  animation: cardPop 220ms ease-out both;
}

.dipascaf-modal-panel {
  width: min(980px, 100%);
  max-width: 980px;
  max-height: min(840px, calc(100vh - 36px));
  overflow-y: auto;
  border: 1px solid #e5ece8;
  border-radius: 18px;
  background: #ffffff;
  padding: 24px;
  box-shadow: 0 24px 60px rgba(15, 23, 42, 0.22);
  scroll-behavior: smooth;
}

.evaluation-form-modal {
  width: min(1280px, calc(100vw - 28px));
  max-width: 1280px;
  max-height: calc(100vh - 28px);
  padding: 0;
  overflow: hidden;
}

.evaluation-form-modal .dipascaf-modal-header {
  margin: 0;
  padding: 22px 24px;
  border-bottom: 1px solid #e5ece8;
  background: linear-gradient(135deg, #f8fbfa 0%, #ffffff 100%);
}

.evaluation-form-modal .dipascaf-modal-header-text p {
  margin: 6px 0 0;
  color: #64748b;
  line-height: 1.45;
}

.evaluation-form-modal > .evaluation-form-meta,
.evaluation-form-modal > .notice,
.evaluation-form-modal > .dipascaf-empty,
.evaluation-form-modal > .evaluation-form,
.evaluation-form-modal > .dipascaf-analysis {
  margin-left: 24px;
  margin-right: 24px;
}

.evaluation-form-meta {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 10px;
  margin-top: 18px;
  margin-bottom: 16px;
}

.evaluation-form-meta > div {
  min-height: 76px;
  border: 1px solid #dfeae4;
  border-radius: 14px;
  background: #fbfdfc;
  padding: 12px;
}

.evaluation-form-meta span {
  display: block;
  color: #64748b;
  font-size: 0.7rem;
  font-weight: 900;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.evaluation-form-meta strong {
  display: block;
  margin-top: 6px;
  color: #123d35;
  font-size: 0.88rem;
  font-weight: 900;
  line-height: 1.3;
}

.evaluation-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding-bottom: 24px;
  min-width: 0;
}

.form-category-nav {
  display: grid;
  grid-template-columns: minmax(110px, max-content) minmax(240px, 520px);
  align-items: center;
  gap: 10px;
  overflow: visible;
  padding-bottom: 0;
}

.form-category-nav::-webkit-scrollbar {
  height: 6px;
}

.form-category-nav::-webkit-scrollbar-track {
  background: transparent;
}

.form-category-nav::-webkit-scrollbar-thumb {
  background: #cbd5e1;
  border-radius: 9999px;
}

.form-category-nav::-webkit-scrollbar-thumb:hover {
  background: #94a3b8;
}

.form-category-select-label {
  color: #123d35;
  font-size: 0.82rem;
  font-weight: 900;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.form-category-select {
  width: 100%;
  min-height: 46px;
  border: 1px solid #d6e2da;
  border-radius: 12px;
  background: #ffffff;
  padding: 0 42px 0 14px;
  color: #123d35;
  font: inherit;
  font-size: 0.9rem;
  font-weight: 800;
  cursor: pointer;
  outline: none;
  box-shadow: 0 8px 20px rgba(15, 23, 42, 0.04);
}

.form-category-select:focus {
  border-color: #1f7a4f;
  box-shadow: 0 0 0 3px rgba(31, 122, 79, 0.14);
}

.form-category-panel {
  display: grid;
  gap: 14px;
  border: 1px solid #dfeae4;
  border-radius: 18px;
  background: #ffffff;
  padding: 18px;
  min-height: 0;
  width: 100%;
  min-width: 0;
}

.form-category-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  border: 1px solid #dfeae4;
  border-radius: 14px;
  background: #f8fbfa;
  padding: 12px 14px;
  margin-bottom: 2px;
}

.form-category-header strong {
  color: #123d35;
  font-size: 1rem;
  font-weight: 900;
}

.form-category-header small {
  color: #64748b;
  font-size: 0.82rem;
  font-weight: 700;
}


.form-category-panel h3 {
