  padding: 0 12px;
  color: #123d35;
  font-size: 0.88rem;
  font-weight: 800;
}

.form-category-stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  gap: 10px;
}

.form-category-stats span {
  border: 1px solid #dfeae4;
  border-radius: 12px;
  background: #f8fbfa;
  padding: 10px;
  color: #64748b;
