  font-weight: 800;
  margin-bottom: 12px;
}

.form-required-summary strong {
  color: #1d4ed8;
}

.form-inline-notice {
  margin-top: 0;
}

.form-final-score {
  width: 100%;
  min-height: 0;
  border: 1px solid #86efac;
  border-radius: 18px;
  background: linear-gradient(135deg, #f0fdf4 0%, #ecfdf5 100%);
