.form-final-score strong {
  color: #14532d;
  font-size: 1.05rem;
  font-weight: 900;
}

.form-final-score p {
  margin: 4px 0 0;
  color: #166534;
  font-size: 0.88rem;
  font-weight: 700;
}

.evaluation-submit-btn {
  width: 100%;
  min-height: 48px;
  border-radius: 14px;
  font-size: 1rem;
}

.dipascaf-modal-panel h2 {
  margin: 0 0 4px;
  color: #123d35;
  font-size: 1.35rem;
  font-weight: 900;
}

.dipascaf-modal-panel > p {
  margin: 0 0 16px;
  color: #64748b;
  font-size: 0.9rem;
}

.dipascaf-modal-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 12px;
}

.dipascaf-modal-header-text {
  flex: 1;
  min-width: 0;
}

.dipascaf-modal-close {
  flex-shrink: 0;
  min-height: 36px;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  background: #ffffff;
  padding: 0 14px;
  color: #475569;
  font-weight: 600;
  font-size: 0.85rem;
  cursor: pointer;
  transition: all 0.2s ease;
