.form-explanation-fields {
  display: grid;
  gap: 14px;
  margin-top: 4px;
}

.form-explanation-fields label {
  display: grid;
  gap: 8px;
  color: #374151;
  font-size: 0.88rem;
  font-weight: 700;
}

.form-field-required span {
  font-weight: 400;
  font-size: 0.78rem;
}

.form-field-optional {
  opacity: 0.85;
}

.form-explanation-fields textarea {
  min-height: 72px;
  border: 1px solid #d1d5db;
  border-radius: 0.5rem;
  padding: 0.625rem;
  font-size: 0.875rem;
  font-family: inherit;
  outline: none;
  transition: border-color 0.2s ease;
  resize: vertical;
}

.form-explanation-fields textarea:focus {
  border-color: #2563eb;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.12);
}

.ai-decision-controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  border: 1px solid #dbeafe;
  border-radius: 12px;
  background: #eff6ff;
  padding: 10px;
  color: #1e40af;
  font-size: 0.82rem;
  font-weight: 800;
}

.ai-decision-controls span {
  margin-right: auto;
}

.ai-decision-controls button {
  min-height: 32px;
  border: 1px solid #93c5fd;
  border-radius: 10px;
  background: #ffffff;
  padding: 0 10px;
  color: #1e40af;
  font-weight: 800;
  cursor: pointer;
}

.ai-decision-controls button:hover {
  background: #dbeafe;
}

.form-field-block {
  margin-bottom: 8px;
}

.form-field-block label {
  display: block;
  font-weight: 700;
  font-size: 0.85rem;
  color: #374151;
  margin-bottom: 4px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.admin-body.dark-mode .department-card-body h3 {
  color: #ffffff;
}

.admin-body.dark-mode .people-filter-panel,
.admin-body.dark-mode .people-section,
.admin-body.dark-mode .people-department-card,
.admin-body.dark-mode .people-user-card,
.admin-body.dark-mode .people-modal-panel {
  border-color: #334155;
  background: #0f172a;
  color: #e2e8f0;
}

.modal-icon-close,
.people-modal-panel .modal-icon-close,
.dipascaf-modal-close.modal-icon-close,
.modal-close.modal-icon-close {
  display: grid;
  width: 40px;
  height: 40px;
  min-height: 40px;
  place-items: center;
  float: none;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 12px;
  background: var(--theme-surface-soft, #f8fafc);
  padding: 0;
  color: var(--theme-muted, #4d5f57);
  box-shadow: none;
}

.modal-icon-close:hover,
.people-modal-panel .modal-icon-close:hover,
.dipascaf-modal-close.modal-icon-close:hover,
.modal-close.modal-icon-close:hover {
  border-color: color-mix(in srgb, var(--theme-primary, #166a45) 34%, var(--theme-border, #dbe7e1));
  background: var(--theme-primary-soft, #e6f6ec);
  color: var(--theme-primary-strong, #0f5138);
  box-shadow: none;
}

.admin-body.dark-mode .modal-icon-close,
.admin-body.dark-mode .people-modal-panel .modal-icon-close,
.admin-body.dark-mode .dipascaf-modal-close.modal-icon-close,
.admin-body.dark-mode .modal-close.modal-icon-close {
  border-color: var(--theme-border, #2f4940);
  background: var(--theme-surface-soft, #152420);
  color: var(--theme-muted, #c0d2ca);
}

.admin-body.dark-mode .people-filter-panel label,
.admin-body.dark-mode .people-department-copy p,
.admin-body.dark-mode .people-user-copy p,
.admin-body.dark-mode .people-user-copy span,
.admin-body.dark-mode .people-user-copy small {
  color: #cbd5e1;
}

.admin-body.dark-mode .people-department-copy h3,
.admin-body.dark-mode .people-user-copy h3 {
  color: #ffffff;
}

.admin-body.dark-mode .people-filter-panel input,
.admin-body.dark-mode .people-filter-panel select,
.admin-body.dark-mode .people-search-field div {
  border-color: #334155;
  background: #020617;
  color: #f8fafc;
}

.admin-body.dark-mode .people-department-logo,
.admin-body.dark-mode .people-user-avatar,
.admin-body.dark-mode .people-upload-preview {
  background: #1e293b;
  color: #a7f3d0;
}

.admin-body.dark-mode .people-department-copy span {
  background: rgba(46, 150, 95, 0.2);
  color: #d1fae5;
}

.admin-body.dark-mode .department-ai-card {
  border-color: #334155;
  background: #0f172a;
  color: #e2e8f0;
}

.admin-body.dark-mode .department-ai-card-head h3,
.admin-body.dark-mode .department-ai-rank-row strong,
.admin-body.dark-mode .department-ai-recommendation strong {
  color: #ffffff;
}

.admin-body.dark-mode .department-ai-ranking h4,
.admin-body.dark-mode .department-ai-rank-row span,
.admin-body.dark-mode .department-ai-recommendation p {
  color: #cbd5e1;
}

.admin-body.dark-mode .department-ai-summary .weak {
  color: #ff6b6b;
}

/* Department Profile Page */
.department-profile-page {
  align-items: start;
}

.dept-profile-header {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 28px;
  min-height: 260px;
  padding: 26px;
  background:
    linear-gradient(135deg, rgba(15, 23, 42, 0.88) 0%, rgba(18, 61, 53, 0.72) 100%),
    url('/assets/images/pmas-campus-bg.jpg');
  background-position: center;
  background-size: cover;
  border: 1px solid rgba(110, 231, 183, 0.18);
  border-radius: 18px;
  margin-bottom: 0;
  animation: pageFade 280ms ease-out;
  position: relative;
  overflow: hidden;
  box-shadow: 0 24px 54px rgba(15, 23, 42, 0.18);
}

.dept-profile-header::before {
  content: '';
  position: absolute;
  right: -50px;
  top: -50px;
  width: 200px;
  height: 200px;
  background: radial-gradient(circle, rgba(3, 105, 161, 0.1) 0%, transparent 70%);
  border-radius: 50%;
}

.back-button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  position: absolute;
  left: 24px;
  top: 24px;
  z-index: 2;
  padding: 8px 14px;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 6px;
  cursor: pointer;
  font-size: 13px;
  color: #cbd5e1;
  transition: all 200ms ease;
  min-height: 36px;
  margin-top: 0;
  font-weight: 500;
}

.back-button:hover {
  background: rgba(255, 255, 255, 0.15);
  border-color: rgba(255, 255, 255, 0.3);
  color: #e2e8f0;
  transform: translateY(-1px);
}

.dept-header-content {
  display: grid;
  grid-template-columns: 156px minmax(0, 1fr);
  align-items: center;
  gap: 28px;
  flex: 1;
  max-width: 920px;
  padding-top: 24px;
  position: relative;
  z-index: 1;
}

.dept-header-logo {
  width: 156px;
  height: 156px;
  background: #ffffff;
  border: 1px solid rgba(255, 255, 255, 0.58);
  border-radius: 28px;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 18px;
  box-shadow: 0 18px 38px rgba(0, 0, 0, 0.26);
  flex-shrink: 0;
}

.dept-header-logo img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.dept-header-info {
  flex: 1;
  color: #ffffff;
}

.dept-header-info h1 {
  max-width: 720px;
  font-size: clamp(2rem, 4vw, 3.45rem);
  font-weight: 900;
  color: #ffffff;
  margin: 8px 0 10px 0;
  line-height: 1.05;
}

.dept-header-info .eyebrow {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #38bdf8;
}

.dept-description {
  font-size: 1rem;
  color: #cbd5e1;
  margin-top: 8px;
  font-weight: 700;
}

.module-stats {
  margin-bottom: 0;
}

.module-stats .stat-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 16px;
  padding: 20px;
}

.module-stats .stat-grid article {
  background: #ffffff;
  padding: 18px;
  border-radius: 12px;
  border: 1px solid #e2e8f0;
  display: flex;
  flex-direction: column;
  gap: 10px;
  transition: all 200ms ease;
}

.module-stats .stat-grid article:hover {
  border-color: #bfdbfe;
  box-shadow: 0 12px 26px rgba(15, 23, 42, 0.08);
  transform: translateY(-2px);
}

.module-stats .stat-grid article span {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: #94a3b8;
}

.module-stats .stat-grid article strong {
  font-size: 26px;
  font-weight: 800;
  color: #0f172a;
}

.module-stats .stat-grid article.dean-summary {
  grid-column: span 2;
}

.module-stats .stat-grid article.dean-summary strong {
  max-width: 100%;
  font-size: clamp(1rem, 1.8vw, 1.35rem);
  line-height: 1.22;
  overflow-wrap: anywhere;
}

/* Person Cards */
.dept-profile-person-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  transition: all 200ms ease;
}

.dept-profile-person-card:hover {
  border-color: #bfdbfe;
  box-shadow: 0 14px 30px rgba(15, 23, 42, 0.08);
  transform: translateY(-2px);
}

.dept-profile-person-card.dean-card {
  background: linear-gradient(135deg, #0f4c81 0%, #082856 100%);
  border-color: #0369a1;
  box-shadow: 0 4px 16px rgba(3, 105, 161, 0.3);
}

.dept-profile-person-card.dean-card .person-info h3,
.dept-profile-person-card.dean-card .person-info p,
.dept-profile-person-card.dean-card .detail-item {
  color: #e2e8f0;
}

.dept-profile-person-card.dean-card .person-avatar {
  border-color: rgba(255, 255, 255, 0.2);
  background: rgba(255, 255, 255, 0.1);
}

.dept-dean-showcase {
  overflow: hidden;
  width: min(100%, 420px);
  border: 1px solid #263a59;
  border-radius: 18px;
  background: #17233a;
  box-shadow: 0 18px 42px rgba(15, 23, 42, 0.14);
}

.dept-dean-cover {
  min-height: 108px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 18px;
  color: #ffffff;
  background-image: linear-gradient(135deg, rgba(15, 23, 42, 0.2), rgba(15, 23, 42, 0.94)), url('/assets/images/pmas-campus-bg.jpg');
  background-position: center;
  background-size: cover;
}

.dept-dean-cover span {
  display: inline-flex;
  min-height: 30px;
  align-items: center;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.18);
  padding: 0 13px;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.04em;
}

.dept-dean-cover strong {
  display: grid;
  width: 48px;
  height: 48px;
  place-items: center;
  border-radius: 14px;
  background: #d8f7df;
  color: #115e35;
  font-size: 20px;
  font-weight: 900;
}

.dept-dean-body {
  display: grid;
  gap: 12px;
  padding: 18px;
  background: #17233a;
}

.dept-dean-body h3 {
  margin: 0;
  color: #f8fafc;
  font-size: 17px;
  font-weight: 900;
  line-height: 1.3;
}

.dept-dean-body > small {
  color: #a7b4c8;
  font-size: 13px;
  font-weight: 800;
}

.dept-dean-profile-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  border-radius: 14px;
  background: #0f172a;
  padding: 10px;
}

.dept-dean-avatar {
  width: 48px;
  height: 48px;
  min-width: 48px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  overflow: hidden;
  background: #d8f7df;
  color: #115e35;
  font-size: 18px;
  font-weight: 900;
}

.dept-dean-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.dept-dean-copy {
  min-width: 0;
}

.dept-dean-copy strong,
.dept-dean-copy small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dept-dean-copy strong {
  color: #f8fafc;
  font-size: 15px;
  font-weight: 900;
}

.dept-dean-copy small {
  margin-top: 2px;
  color: #a7b4c8;
  font-size: 13px;
  font-weight: 600;
}

.person-avatar {
  width: 56px;
  height: 56px;
  min-width: 56px;
  border-radius: 12px;
  background: #f1f5f9;
  border: 2px solid #e2e8f0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  font-size: 18px;
  color: #64748b;
  overflow: hidden;
}

.person-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.person-info {
  flex: 1;
}

.person-info h3 {
  font-size: 15px;
  font-weight: 600;
  color: #0f172a;
  margin: 0 0 4px 0;
}

.role-badge {
  font-size: 11px;
  font-weight: 500;
  color: #475569;
  display: inline-block;
  padding: 2px 8px;
  background: #f1f5f9;
  border-radius: 999px;
  margin: 0;
}

.role-badge.program-head {
  background: #082856;
  color: #38bdf8;
}

.person-details {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 8px;
}

.detail-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: #475569;
}

.detail-item svg {
  width: 14px;
  height: 14px;
  opacity: 0.7;
}

.person-status {
  display: flex;
  gap: 8px;
}

.status-badge {
  font-size: 11px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 4px;
  background: #e0f2fe;
  color: #0369a1;
  text-transform: capitalize;
}

.status-badge.active {
  background: #dcfce7;
  color: #15803d;
}

.status-badge.inactive {
  background: #ffedd5;
  color: #c2410c;
}

/* Grid Layouts */
.dept-profile-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 16px;
  padding: 20px;
}

.dept-faculty-table {
  overflow-x: auto;
  padding: 0 20px 20px 20px;
}

.dept-faculty-table table {
  width: 100%;
  border-collapse: collapse;
}

.dept-faculty-table thead {
  background: #f8fafc;
  border-bottom: 2px solid #e2e8f0;
}

.dept-faculty-table th {
  padding: 12px 16px;
  text-align: left;
  font-weight: 600;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #64748b;
}

.dept-faculty-table tbody tr {
  border-bottom: 1px solid #e2e8f0;
  transition: background-color 200ms ease;
}

.dept-faculty-table tbody tr:hover {
  background-color: #f8fafc;
}

.dept-faculty-table td {
  padding: 12px 16px;
  font-size: 14px;
  color: #1e293b;
}

.faculty-cell-name {
  display: flex;
  align-items: center;
  gap: 10px;
}

.faculty-avatar {
  width: 32px;
  height: 32px;
  border-radius: 6px;
  background: #f1f5f9;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  font-size: 12px;
  color: #64748b;
  overflow: hidden;
  flex-shrink: 0;
}

.faculty-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.dept-faculty-program-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 18px;
  padding: 20px;
}

.dept-program-selector {
  display: grid;
  gap: 8px;
  padding: 0 20px 4px;
  max-width: 420px;
}

.dept-program-selector label {
  color: #475569;
  font-size: 13px;
  font-weight: 800;
}

.dept-program-selector select {
  min-height: 44px;
  border: 1px solid #cbd5e1;
  border-radius: 12px;
  background: #ffffff;
  padding: 0 14px;
  color: #0f172a;
  font-weight: 700;
  outline: none;
}

.dept-program-selector select:focus {
  border-color: #2563eb;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.16);
}

.dept-program-faculty-card {
  overflow: hidden;
  border: 1px solid #dbe6f3;
  border-radius: 18px;
  background: #ffffff;
  box-shadow: 0 18px 45px rgba(15, 23, 42, 0.08);
}

.dept-program-cover {
  min-height: 86px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 18px;
  color: #ffffff;
  background-image: linear-gradient(135deg, rgba(15, 23, 42, 0.25), rgba(15, 23, 42, 0.92)), url('/assets/images/pmas-campus-bg.jpg');
  background-size: cover;
  background-position: center;
}

.dept-program-cover span {
  display: inline-flex;
  min-height: 28px;
  align-items: center;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.16);
  padding: 0 12px;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.04em;
}

.dept-program-cover strong {
  display: grid;
  width: 44px;
  height: 44px;
  place-items: center;
  border-radius: 14px;
  background: #d8f7df;
  color: #115e35;
  font-size: 18px;
  font-weight: 900;
}

.dept-program-body {
  display: grid;
  gap: 10px;
  padding: 18px;
}

.dept-program-body h3 {
  margin: 0;
  color: #0f172a;
  font-size: 16px;
  font-weight: 900;
  line-height: 1.3;
}

.dept-program-body > small {
  color: #64748b;
  font-size: 13px;
  font-weight: 700;
}

.dept-program-faculty-list {
  display: grid;
  gap: 10px;
  margin-top: 4px;
}

.dept-program-faculty-list p {
  margin: 0;
  border-radius: 12px;
  background: #f8fafc;
  padding: 14px;
  color: #64748b;
  font-size: 13px;
}

.dept-program-faculty-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  border-radius: 14px;
  background: #f8fafc;
  padding: 10px;
}

.dept-program-faculty-row strong,
.dept-program-faculty-row small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dept-program-faculty-row strong {
  color: #0f172a;
  font-size: 14px;
  font-weight: 900;
}

.dept-program-faculty-row small {
  color: #64748b;
  font-size: 12px;
}

/* Summary Breakdown */
.dept-users-breakdown {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 16px;
  padding: 20px;
}

.breakdown-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  text-align: left;
  min-width: 0;
}

.breakdown-card svg {
  width: 24px;
  height: 24px;
  opacity: 0.6;
}

.breakdown-card svg.dean {
  color: #1e40af;
}

.breakdown-card svg.program-head {
  color: #0369a1;
}

.breakdown-card svg.faculty {
  color: #16a34a;
}

.breakdown-card svg.admin {
  color: #9333ea;
}

.breakdown-card div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.breakdown-card strong {
  font-size: 18px;
  font-weight: 700;
  color: #1e293b;
}

.breakdown-card span {
  font-size: 12px;
  color: #64748b;
  font-weight: 500;
}

@media (max-width: 760px) {
  .dept-profile-header {
    grid-template-columns: 1fr;
    min-height: auto;
    padding: 82px 18px 22px;
  }

  .dept-header-content {
    grid-template-columns: 104px minmax(0, 1fr);
    gap: 16px;
    width: 100%;
    align-items: flex-start;
    padding-top: 0;
  }

  .dept-header-logo {
    width: 104px;
    height: 104px;
    border-radius: 20px;
    padding: 12px;
  }

  .dept-header-info h1 {
    font-size: 22px;
    line-height: 1.2;
    overflow-wrap: anywhere;
  }

  .dept-profile-grid,
  .dept-faculty-program-grid,
  .dept-users-breakdown,
  .module-stats .stat-grid {
    grid-template-columns: 1fr;
    padding: 14px;
  }

  .module-stats .stat-grid article.dean-summary {
