  }

  .dept-profile-person-card {
    flex-wrap: wrap;
    align-items: flex-start;
  }

  .dept-program-faculty-row {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .dept-program-faculty-row .status-badge {
    grid-column: 2;
    justify-self: start;
  }

  .dept-dean-showcase {
    width: 100%;
  }

  .dept-dean-profile-row {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .dept-dean-profile-row .status-badge {
