  border-color: var(--theme-primary, #1f7a4f);
}

.eval-monitor-program-card-header {
  display: flex;
  gap: 12px;
  align-items: center;
  padding: 16px 16px 10px;
  border-bottom: 1px solid color-mix(in srgb, var(--theme-border, #dbe7e1) 72%, transparent);
}

.eval-monitor-program-card-icon {
  display: grid;
  width: 40px;
  height: 40px;
  place-items: center;
  border-radius: 10px;
  flex-shrink: 0;
  background: #fef3c7;
  color: #92400e;
}

.eval-monitor-program-card-header h3 {
  margin: 0;
  font-size: 1rem;
  font-weight: 900;
  color: var(--theme-text, #10201b);
  line-height: 1.3;
  overflow-wrap: anywhere;
}

.eval-monitor-program-card-body {
  display: grid;
  gap: 12px;
  padding: 14px 16px 16px;
}

.eval-monitor-program-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--theme-muted, #4d5f57);
}

.eval-monitor-program-meta span {
  display: flex;
  gap: 5px;
  align-items: center;
}

.eval-monitor-program-stats {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
}

.eval-monitor-program-stat {
  text-align: center;
  border-radius: 10px;
  padding: 9px 8px;
}

.eval-monitor-program-stat span {
  display: block;
  font-size: 0.65rem;
  font-weight: 800;
  text-transform: uppercase;
}

.eval-monitor-program-stat strong {
  display: block;
  font-size: 1.4rem;
  font-weight: 950;
  margin-top: 2px;
}

.eval-monitor-program-stat.primary {
  background: var(--theme-primary-soft, #e6f6ec);
  color: var(--theme-primary-strong, #0f5138);
}

.eval-monitor-program-stat.accent {
  background: #fef3c7;
  color: #92400e;
}

/* ─── Faculty Grid ─── */
.eval-monitor-faculty-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(330px, 100%), 1fr));
  gap: 16px;
  padding: 18px;
}

.eval-monitor-faculty-card {
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 14px;
  background: var(--theme-surface, #ffffff);
  cursor: pointer;
  transition: border-color 200ms, box-shadow 200ms, transform 200ms;
  overflow: hidden;
}

.eval-monitor-faculty-card:hover {
  box-shadow: 0 12px 32px rgba(15,23,42,0.08);
  transform: translateY(-2px);
  border-color: var(--theme-primary, #1f7a4f);
}

.eval-monitor-faculty-card-head {
  display: flex;
  gap: 12px;
  align-items: center;
  padding: 16px 16px 10px;
  border-bottom: 1px solid color-mix(in srgb, var(--theme-border, #dbe7e1) 72%, transparent);
}

.eval-monitor-faculty-avatar {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 999px;
  flex-shrink: 0;
  background: var(--theme-primary, #1f7a4f);
  color: #ffffff;
  font-size: 1.1rem;
  font-weight: 900;
}

.eval-monitor-faculty-info {
  flex: 1;
  min-width: 0;
}

.eval-monitor-faculty-info h3 {
  margin: 0;
  font-size: 0.95rem;
  font-weight: 900;
  color: var(--theme-text, #10201b);
  line-height: 1.3;
  overflow-wrap: anywhere;
}

.eval-monitor-faculty-info span {
  display: block;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--theme-subtle, #64748b);
}

.eval-monitor-score-pill {
  display: grid;
  width: 40px;
  height: 40px;
  place-items: center;
  border-radius: 999px;
  flex-shrink: 0;
  font-size: 0.85rem;
  font-weight: 950;
}

.eval-monitor-score-pill.high {
  background: #dcfce7;
  color: #166534;
}

.eval-monitor-score-pill.mid {
  background: #fef3c7;
  color: #92400e;
}

.eval-monitor-score-pill.low {
  background: #fee2e2;
  color: #991b1b;
}

.eval-monitor-score-pill.none {
  background: #f1f5f9;
  color: #94a3b8;
}

.eval-monitor-faculty-card-body {
  display: grid;
  gap: 10px;
  padding: 14px 16px 16px;
}

.eval-monitor-faculty-meta {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--theme-subtle, #64748b);
}

.eval-monitor-faculty-stats-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--theme-muted, #4d5f57);
}

.eval-monitor-faculty-stats-row .stat-item {
  display: flex;
  gap: 5px;
  align-items: center;
}

.eval-monitor-faculty-stats-row .stat-item.warning {
  color: #eab308;
}

.eval-monitor-faculty-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.eval-monitor-faculty-actions {
  margin-top: 4px;
}

.eval-monitor-faculty-ai-recommendation {
  display: grid;
  gap: 6px;
  padding: 10px 12px;
  border: 1px solid rgba(20, 184, 166, 0.24);
  border-radius: 12px;
  background:
    linear-gradient(135deg, rgba(236, 253, 245, 0.92), rgba(240, 249, 255, 0.82));
  color: #134e4a;
}

.eval-monitor-faculty-ai-recommendation > div {
  display: flex;
  align-items: center;
  gap: 6px;
  color: #0f766e;
  font-size: 0.72rem;
  font-weight: 900;
  text-transform: uppercase;
}

.eval-monitor-faculty-ai-recommendation p {
  margin: 0;
  color: #1f2937;
  font-size: 0.78rem;
  font-weight: 700;
  line-height: 1.45;
}

.eval-monitor-faculty-ai-recommendation > .eval-monitor-recommendation-presentation {
  display: grid;
  align-items: stretch;
  gap: 8px;
  color: inherit;
  font-size: inherit;
  font-weight: inherit;
  text-transform: none;
}

.eval-monitor-recommendation-focus,
.eval-monitor-recommendation-action {
  display: grid;
  gap: 3px;
}

.eval-monitor-recommendation-focus > span,
.eval-monitor-recommendation-action > span {
  color: #64748b;
  font-size: 0.64rem;
  font-weight: 900;
  letter-spacing: 0.055em;
  text-transform: uppercase;
}

.eval-monitor-recommendation-focus > strong {
  color: #17352a;
  font-size: 0.84rem;
  line-height: 1.35;
  text-transform: none;
}

.eval-monitor-recommendation-evidence {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.eval-monitor-recommendation-evidence > span {
  padding: 5px 8px;
  border: 1px solid rgba(15, 118, 110, 0.18);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.68);
  color: #475569;
  font-size: 0.68rem;
  font-weight: 750;
  text-transform: none;
}

.eval-monitor-recommendation-evidence b {
  color: #0f766e;
  font-size: 0.76rem;
}

.eval-monitor-recommendation-action {
  padding: 9px 10px;
  border-left: 3px solid #16a34a;
  border-radius: 8px;
  background: rgba(22, 163, 74, 0.07);
}

.eval-monitor-recommendation-action p,
.eval-monitor-recommendation-copy {
  margin: 0;
  color: #334155;
  font-size: 0.76rem;
  font-weight: 750;
  line-height: 1.5;
  text-transform: none;
}

:is(.admin-body.dark-mode, .admin-dashboard-body.dark-mode) .eval-monitor-recommendation-focus > span,
:is(.admin-body.dark-mode, .admin-dashboard-body.dark-mode) .eval-monitor-recommendation-action > span,
body:has(.admin-dashboard-body.dark-mode) .eval-monitor-recommendation-focus > span,
body:has(.admin-dashboard-body.dark-mode) .eval-monitor-recommendation-action > span {
  color: #94a3b8;
}

:is(.admin-body.dark-mode, .admin-dashboard-body.dark-mode) .eval-monitor-recommendation-focus > strong,
body:has(.admin-dashboard-body.dark-mode) .eval-monitor-recommendation-focus > strong {
  color: #ecfdf5;
}

:is(.admin-body.dark-mode, .admin-dashboard-body.dark-mode) .eval-monitor-recommendation-evidence > span,
body:has(.admin-dashboard-body.dark-mode) .eval-monitor-recommendation-evidence > span {
  border-color: rgba(94, 234, 212, 0.2);
  background: rgba(15, 23, 42, 0.42);
  color: #cbd5e1;
}

:is(.admin-body.dark-mode, .admin-dashboard-body.dark-mode) .eval-monitor-recommendation-action,
body:has(.admin-dashboard-body.dark-mode) .eval-monitor-recommendation-action {
  background: rgba(34, 197, 94, 0.1);
}

:is(.admin-body.dark-mode, .admin-dashboard-body.dark-mode) .eval-monitor-recommendation-action p,
:is(.admin-body.dark-mode, .admin-dashboard-body.dark-mode) .eval-monitor-recommendation-copy,
body:has(.admin-dashboard-body.dark-mode) .eval-monitor-recommendation-action p,
body:has(.admin-dashboard-body.dark-mode) .eval-monitor-recommendation-copy {
  color: #e2e8f0;
}

.eval-monitor-program-summary {
  margin-top: 8px;
  border-radius: 10px;
  background: var(--theme-primary-soft, #e6f6ec);
  padding: 10px 14px;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--theme-primary-strong, #0f5138);
}

/* ─── Empty / Error ─── */
.eval-monitor-empty {
  display: grid;
  place-items: center;
  padding: 48px 24px;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--theme-subtle, #64748b);
  text-align: center;
}

.eval-monitor-empty.error {
  color: #ef4444;
}

/* ─── Loading Skeleton ─── */
.eval-monitor-skeleton {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 14px;
  padding: 18px;
}

.eval-monitor-skeleton-card {
  display: grid;
  gap: 12px;
  border-radius: 16px;
  border: 1px solid var(--theme-border, #dbe7e1);
  padding: 20px;
  background: var(--theme-surface, #ffffff);
}

@keyframes skeletonPulse {
  0%, 100% { opacity: 0.4; }
  50% { opacity: 0.8; }
}

.eval-monitor-skeleton-card .skeleton-line {
  height: 14px;
  border-radius: 999px;
  background: linear-gradient(90deg, #e2e8f0 25%, #f1f5f9 50%, #e2e8f0 75%);
  background-size: 200% 100%;
  animation: skeletonPulse 1.6s ease-in-out infinite;
}

.eval-monitor-skeleton-card .skeleton-line.w-24 { width: 96px; }
.eval-monitor-skeleton-card .skeleton-line.w-32 { width: 128px; }
.eval-monitor-skeleton-card .skeleton-line.w-full { width: 100%; }

/* ─── Chatbot ─── */
.eval-monitor-container {
  grid-template-columns: minmax(0, 1fr);
}

.eval-monitor-chatbot-overlay {
  position: fixed;
  inset: 0;
  z-index: 500;
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
  padding: 24px;
  background: rgba(15, 23, 42, 0.10);
  backdrop-filter: blur(2px);
  animation: evalMonitorChatOverlayIn 180ms ease-out both;
}

.eval-monitor-chatbot-shell {
  width: min(360px, calc(100vw - 24px));
  height: min(680px, calc(100dvh - 48px));
  min-height: min(560px, calc(100dvh - 48px));
  display: flex;
  animation: evalMonitorChatSlideIn 220ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

.eval-monitor-chatbot-sidebar {
  width: 340px;
  position: sticky;
  top: 8px;
}

.eval-monitor-chatbot {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  max-height: none;
  min-height: 0;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 18px;
  background: var(--theme-surface, #ffffff);
  overflow: hidden;
  box-shadow: 0 24px 70px rgba(15, 23, 42, 0.22);
}

.eval-monitor-chatbot-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  border-bottom: 1px solid var(--theme-border, #dbe7e1);
  padding: 12px 16px;
}

.eval-monitor-chatbot-header h3 {
  display: flex;
  gap: 8px;
  align-items: center;
  margin: 0;
  font-size: 0.9rem;
  font-weight: 900;
  color: var(--theme-text, #10201b);
}

.eval-monitor-chatbot-header h3 svg {
  color: var(--theme-primary, #1f7a4f);
}

.eval-monitor-chatbot-messages {
  flex: 1;
  overflow-y: auto;
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  background: var(--theme-surface-soft, #f8fafc);
}

.eval-monitor-chatbot-welcome {
  display: grid;
  gap: 12px;
  place-items: center;
  text-align: center;
  padding: 24px 12px;
  color: var(--theme-muted, #4d5f57);
  font-size: 0.85rem;
  font-weight: 500;
}

.eval-monitor-chatbot-welcome svg {
  color: var(--theme-primary, #1f7a4f);
}

.eval-monitor-chatbot-suggestions {
  display: grid;
  gap: 10px;
  justify-content: stretch;
  width: 100%;
}

.eval-monitor-chatbot-suggestion-group {
  display: grid;
  gap: 6px;
  text-align: left;
}

.eval-monitor-chatbot-suggestion-group > span {
  color: var(--theme-muted, #4d5f57);
  font-size: 0.68rem;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.eval-monitor-chatbot-suggestion-group > div {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.eval-monitor-chatbot-suggestions button {
  min-height: auto;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 999px;
  background: var(--theme-surface, #ffffff);
  padding: 6px 14px;
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--theme-primary, #1f7a4f);
  cursor: pointer;
  transition: all 180ms;
  box-shadow: none;
}

.eval-monitor-chatbot-suggestions button:hover {
  border-color: var(--theme-primary, #1f7a4f);
  background: var(--theme-primary-soft, #e6f6ec);
}

.eval-monitor-chat-msg {
  display: flex;
}

.eval-monitor-chat-msg.user {
  justify-content: flex-end;
}

.eval-monitor-chat-msg.assistant {
  justify-content: flex-start;
}

.eval-monitor-chat-msg-content {
  max-width: 85%;
  border-radius: 14px;
  padding: 10px 14px;
  font-size: 0.82rem;
  font-weight: 500;
  line-height: 1.5;
  white-space: pre-wrap;
}

.eval-monitor-chat-msg.user .eval-monitor-chat-msg-content {
  background: var(--theme-primary, #1f7a4f);
  color: #ffffff;
  border-bottom-right-radius: 4px;
}

.eval-monitor-chat-msg.assistant .eval-monitor-chat-msg-content {
  background: var(--theme-surface-raised, #ffffff);
  color: var(--theme-text, #10201b);
  border: 1px solid var(--theme-border, #dbe7e1);
  border-bottom-left-radius: 4px;
}

.eval-monitor-chatbot-input {
  display: flex;
  gap: 8px;
  border-top: 1px solid var(--theme-border, #dbe7e1);
  padding: 12px 16px;
}

.eval-monitor-chatbot-input input {
  flex: 1;
  min-height: 38px;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 10px;
  background: var(--theme-surface-soft, #f8fafc);
  padding: 0 12px;
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--theme-text, #10201b);
  outline: none;
}

.eval-monitor-chatbot-input input:focus {
  border-color: var(--theme-primary, #1f7a4f);
}

.eval-monitor-chatbot-input button {
  min-height: 38px;
  border: 0;
  border-radius: 10px;
  background: var(--theme-primary, #1f7a4f);
  padding: 0 16px;
  font-size: 0.82rem;
  font-weight: 800;
  color: #ffffff;
  cursor: pointer;
  transition: all 180ms;
  white-space: nowrap;
}

.eval-monitor-chatbot-input button:hover {
  background: var(--theme-primary-strong, #0f5138);
}

.eval-monitor-chatbot-input button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

@keyframes evalMonitorChatOverlayIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes evalMonitorChatSlideIn {
  from {
    opacity: 0;
    transform: translateY(18px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* ─── Export Menu ─── */
.eval-monitor-export-menu {
  position: relative;
}

.eval-monitor-export-dropdown {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  z-index: 50;
  min-width: 200px;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 12px;
  background: var(--theme-surface, #ffffff);
  padding: 6px;
  box-shadow: 0 12px 32px rgba(15,23,42,0.12);
}

.eval-monitor-export-dropdown button {
  display: block;
  width: 100%;
  text-align: left;
  min-height: auto;
  border: 0;
  border-radius: 8px;
  background: transparent;
  padding: 8px 12px;
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--theme-text, #10201b);
  cursor: pointer;
  transition: all 120ms;
  box-shadow: none;
}

.eval-monitor-export-dropdown button:hover {
  background: var(--theme-surface-soft, #f8fafc);
  color: var(--theme-primary, #1f7a4f);
}

.eval-monitor-export-dropdown hr {
  margin: 4px 8px;
  border: 0;
  border-top: 1px solid var(--theme-border, #dbe7e1);
}

/* ─── Faculty Detail Modal ─── */
.eval-monitor-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: grid;
  place-items: center;
  background: rgba(15,23,42,0.6);
  padding: clamp(12px, 2vw, 24px);
  overflow: hidden;
  backdrop-filter: blur(3px);
}

.eval-monitor-modal {
  display: flex;
  flex-direction: column;
  width: min(1440px, calc(100vw - 32px));
  max-height: min(920px, calc(100dvh - 32px));
  overflow: hidden;
  border-radius: 20px;
  background: var(--theme-surface, #ffffff);
  box-shadow: 0 24px 60px rgba(15,23,42,0.2);
  min-width: 0;
}

.eval-monitor-modal-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
  flex-shrink: 0;
  border-bottom: 1px solid var(--theme-border, #dbe7e1);
  padding: 20px 24px;
}

.eval-monitor-modal-header h3 {
  margin: 0;
  font-size: 1.3rem;
  font-weight: 900;
  color: var(--theme-text, #10201b);
}

.eval-monitor-modal-header p {
  margin: 4px 0 0;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--theme-subtle, #64748b);
}

.eval-monitor-modal-body {
  display: grid;
  gap: 20px;
  padding: 20px 24px 24px;
  overflow-y: auto;
  overflow-x: hidden;
  min-height: 0;
  overscroll-behavior: contain;
}

.eval-monitor-faculty-score {
  display: flex;
  gap: 20px;
  align-items: center;
  border-radius: 14px;
  background: var(--theme-surface-soft, #f8fafc);
  padding: 16px;
}

.eval-monitor-score-ring {
  position: relative;
  display: grid;
  width: 72px;
  height: 72px;
  place-items: center;
  flex-shrink: 0;
  border-radius: 999px;
  background: conic-gradient(var(--theme-primary,#1f7a4f) 0% var(--score,0), #e2e8f0 var(--score,0) 100%);
}

.eval-monitor-score-ring::before {
  content: "";
  position: absolute;
  inset: 6px;
  border-radius: 999px;
  background: var(--theme-surface, #ffffff);
}

.eval-monitor-score-ring strong {
  position: relative;
  z-index: 1;
  font-size: 1.1rem;
  font-weight: 950;
  color: var(--theme-primary-strong, #0f5138);
  line-height: 1;
}

.eval-monitor-score-ring span {
  position: relative;
  z-index: 1;
  font-size: 0.6rem;
  font-weight: 700;
  color: var(--theme-subtle, #64748b);
}

.eval-monitor-faculty-stats {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.eval-monitor-faculty-stats span {
  display: flex;
  gap: 6px;
  align-items: center;
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--theme-muted, #4d5f57);
  white-space: nowrap;
}

/* ─── Modal Sections ─── */
.eval-monitor-section {
  display: grid;
  gap: 12px;
}

.eval-monitor-section-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.eval-monitor-section-head > span {
  color: var(--theme-subtle, #64748b);
  font-size: 0.76rem;
  font-weight: 800;
}

.eval-monitor-section h4 {
  display: flex;
  gap: 8px;
  align-items: center;
  margin: 0;
  font-size: 0.9rem;
  font-weight: 900;
  color: var(--theme-text, #10201b);
}

.eval-monitor-section h4 svg {
  color: var(--theme-primary, #1f7a4f);
}

/* ─── Category Grid ─── */
.eval-monitor-category-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(260px, 100%), 1fr));
  gap: 10px;
}

.eval-monitor-category-card {
  appearance: none;
  width: 100%;
  text-align: left;
  cursor: pointer;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 12px;
  background: var(--theme-surface, #ffffff);
  color: inherit;
  padding: 12px;
  transition: border-color 180ms ease, box-shadow 180ms ease, transform 180ms ease, background-color 180ms ease;
}

.eval-monitor-category-card:hover,
.eval-monitor-category-card:focus-visible {
  border-color: var(--theme-primary, #1f7a4f);
  box-shadow: 0 12px 28px rgba(15, 118, 110, 0.14);
  transform: translateY(-2px);
  outline: none;
}

.eval-monitor-category-card.is-selected {
  border-color: var(--theme-primary, #1f7a4f);
  background: color-mix(in srgb, var(--theme-primary-soft, #e6f6ec) 48%, var(--theme-surface, #ffffff));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--theme-primary, #1f7a4f) 16%, transparent);
}

.eval-monitor-category-detail {
  display: grid;
  grid-template-columns: minmax(220px, 1fr) repeat(2, minmax(120px, max-content));
  gap: 12px;
  align-items: center;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 14px;
  background: var(--theme-surface-soft, #f8fafc);
  padding: 14px;
}

.eval-monitor-category-detail div {
  display: grid;
  gap: 3px;
}

.eval-monitor-category-detail span {
  color: var(--theme-subtle, #64748b);
  font-size: 0.7rem;
  font-weight: 900;
  text-transform: uppercase;
}

.eval-monitor-category-detail strong {
  color: var(--theme-text, #10201b);
  font-size: 0.9rem;
  font-weight: 950;
}

.eval-monitor-category-detail p {
  grid-column: 1 / -1;
  margin: 0;
  color: var(--theme-muted, #4d5f57);
  font-size: 0.82rem;
  font-weight: 700;
  line-height: 1.45;
}

.eval-monitor-category-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}

.eval-monitor-category-head strong {
  font-size: 0.8rem;
  font-weight: 900;
  color: var(--theme-text, #10201b);
  line-height: 1.3;
}

.eval-monitor-category-head span {
  font-size: 0.9rem;
  font-weight: 950;
  flex-shrink: 0;
}

.eval-monitor-category-head span.high { color: #22c55e; }
.eval-monitor-category-head span.mid { color: #eab308; }
.eval-monitor-category-head span.low { color: #ef4444; }

.eval-monitor-evidence {
  display: block;
  margin-top: 6px;
  font-size: 0.72rem;
  font-weight: 500;
  color: var(--theme-subtle, #64748b);
  line-height: 1.4;
}

.eval-monitor-recommendation {
  display: block;
  margin-top: 4px;
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--theme-primary, #1f7a4f);
  line-height: 1.4;
}

/* ─── Strengths & Weaknesses ─── */
.eval-monitor-strength-weak-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.eval-monitor-strengths,
.eval-monitor-weaknesses {
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 12px;
  padding: 14px;
}

.eval-monitor-strengths h4,
.eval-monitor-weaknesses h4 {
  display: flex;
  gap: 8px;
  align-items: center;
  margin: 0 0 10px;
  font-size: 0.85rem;
  font-weight: 900;
  color: var(--theme-text, #10201b);
}

.eval-monitor-strengths { border-left: 3px solid #22c55e; }
.eval-monitor-weaknesses { border-left: 3px solid #eab308; }

.eval-monitor-strength-item,
.eval-monitor-weakness-item {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  padding: 6px 0;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--theme-muted, #4d5f57);
}

.eval-monitor-strength-item svg { color: #22c55e; flex-shrink: 0; margin-top: 2px; }
.eval-monitor-weakness-item svg { color: #eab308; flex-shrink: 0; margin-top: 2px; }

.eval-monitor-weakness-item small {
  display: block;
  margin-top: 2px;
  font-size: 0.72rem;
  font-weight: 500;
  color: var(--theme-subtle, #64748b);
}

/* ─── Insight Card ─── */
.eval-monitor-insight-card {
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 12px;
  padding: 12px 14px;
}

.eval-monitor-insight-card p {
  margin: 6px 0;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--theme-text, #10201b);
  line-height: 1.45;
}

.eval-monitor-insight-card small {
  font-size: 0.7rem;
  font-weight: 600;
  color: var(--theme-subtle, #64748b);
}

.eval-monitor-insight-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

/* ─── Intervention ─── */
.eval-monitor-intervention-item {
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 12px;
  padding: 12px 14px;
}

.eval-monitor-intervention-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}

.eval-monitor-intervention-area {
  font-size: 0.85rem;
  font-weight: 800;
  color: var(--theme-text, #10201b);
}

.eval-monitor-intervention-status {
  font-size: 0.65rem;
  font-weight: 800;
  text-transform: uppercase;
  padding: 2px 10px;
  border-radius: 999px;
}

.eval-monitor-intervention-status.planned { background: #fef3c7; color: #92400e; }
.eval-monitor-intervention-status.in_progress { background: #dbeafe; color: #1e40af; }
.eval-monitor-intervention-status.completed { background: #dcfce7; color: #166534; }

.eval-monitor-intervention-item p {
  margin: 4px 0;
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--theme-muted, #4d5f57);
  line-height: 1.4;
}

.eval-monitor-intervention-item small {
  font-size: 0.7rem;
  font-weight: 600;
  color: var(--theme-subtle, #64748b);
}

/* ─── Table ─── */
.eval-monitor-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.82rem;
}

.eval-monitor-table th {
  border-bottom: 1px solid var(--theme-border, #dbe7e1);
  padding: 10px 12px;
  text-align: left;
  font-size: 0.7rem;
  font-weight: 800;
  text-transform: uppercase;
  color: var(--theme-subtle, #64748b);
  background: var(--theme-surface-soft, #f8fafc);
}

.eval-monitor-table td {
  border-bottom: 1px solid var(--theme-border, #dbe7e1);
  padding: 10px 12px;
  color: var(--theme-text, #10201b);
  font-weight: 600;
}

.eval-monitor-table tr:hover td {
  background: var(--theme-primary-soft, #e6f6ec);
}

