/* ═══════════════════════════════════════════════════════════════════
   RESPONSIVE — Program Performance, Evaluation Monitor, AI Insights
   ═══════════════════════════════════════════════════════════════════ */

/* ─── Tablet / Small Desktop (≤1080px) ─────────────────────────── */
@media (max-width: 1080px) {
  .program-performance-header {
    padding: 20px;
  }

  .eval-monitor-container {
    grid-template-columns: 1fr;
  }

  .eval-monitor-chatbot-sidebar {
    position: fixed;
    inset: 0;
    z-index: 200;
    width: 100%;
    height: 100dvh;
    background: rgba(2, 6, 23, 0.55);
    backdrop-filter: blur(4px);
    animation: cardPop 220ms ease-out both;
  }

  .eval-monitor-chatbot-sidebar .eval-monitor-chatbot {
    position: absolute;
    right: 0;
    top: 0;
    width: min(400px, 100%);
    height: 100%;
    border-radius: 0;
    box-shadow: -8px 0 30px rgba(0, 0, 0, 0.18);
  }

  .eval-monitor-hero {
    grid-template-columns: 1fr;
    gap: 16px;
  }

  .eval-monitor-hero-chart {
    flex-wrap: wrap;
  }

  .eval-monitor-hero-stats {
    grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
  }

  .eval-monitor-metrics {
    grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  }

  .eval-monitor-dept-grid,
  .eval-monitor-program-grid,
  .eval-monitor-faculty-grid {
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  }

  .department-ai-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .department-ai-hero {
    grid-template-columns: 1fr;
  }

  .department-ai-filters {
    flex-wrap: wrap;
  }
}

/* ─── Mobile (≤720px) ──────────────────────────────────────────── */
@media (max-width: 720px) {
  .program-performance-shell {
    gap: 14px;
  }

  .program-performance-header {
    padding: 18px;
  }

  .program-performance-header h2 {
    font-size: 1.5rem;
  }

  .program-performance-header p {
    font-size: 0.88rem;
  }

  .program-performance-tabs {
    flex-direction: column;
    gap: 6px;
    padding: 6px;
  }

  .program-perf-tab {
    min-height: 40px;
    padding: 0 14px;
    font-size: 0.85rem;
    justify-content: center;
    width: 100%;
  }

  .tab-active-indicator {
    display: none;
  }

  .eval-monitor-header {
    flex-direction: column;
    gap: 10px;
  }

  .eval-monitor-header h2 {
    font-size: 1.2rem;
  }

  .eval-monitor-header-actions {
    width: 100%;
    flex-wrap: wrap;
  }

  .eval-monitor-header-actions .eval-monitor-btn {
    flex: 1;
    min-width: 0;
    justify-content: center;
  }

  .eval-monitor-hero {
    padding: 18px;
    border-radius: 14px;
  }

