/* Evaluation monitor detail modal: keep the overlay viewport-sized even when
   the dashboard shell has transformed or scrollable parents. */
body:has(.eval-monitor-modal-backdrop) {
  overflow: hidden;
}

.eval-monitor-modal-backdrop {
  position: fixed !important;
  inset: 0 !important;
  width: 100vw;
  height: 100vh;
  height: 100dvh;
  display: flex !important;
  align-items: center;
  justify-content: center;
  padding: clamp(12px, 1.6vw, 24px) !important;
  overflow: hidden !important;
}

.eval-monitor-modal {
  width: min(1560px, calc(100vw - 32px)) !important;
  height: min(900px, calc(100dvh - 32px));
  max-height: calc(100dvh - 32px) !important;
}

.eval-monitor-modal-body {
  flex: 1 1 auto;
  min-height: 0;
  grid-template-columns: 1fr;
}

.eval-monitor-category-grid {
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}

@media (min-width: 1400px) {
  .eval-monitor-category-grid {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }
}

@media (min-width: 1700px) {
  .eval-monitor-modal {
    width: min(1680px, calc(100vw - 40px)) !important;
  }

  .eval-monitor-category-grid {
    grid-template-columns: repeat(6, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .eval-monitor-modal-backdrop {
    padding: 8px !important;
  }

  .eval-monitor-modal {
    width: calc(100vw - 16px) !important;
    height: calc(100dvh - 16px);
    max-height: calc(100dvh - 16px) !important;
  }
}

@media (max-width: 1100px) {
  .eval-monitor-modal {
    width: min(1040px, calc(100vw - 24px));
  }

  .eval-monitor-category-grid {
    grid-template-columns: repeat(auto-fit, minmax(min(220px, 100%), 1fr));
  }
}

@media (max-width: 760px) {
  .eval-monitor-modal-backdrop {
    place-items: stretch;
    padding: 8px;
  }

  .eval-monitor-modal {
    width: 100%;
    max-height: calc(100dvh - 16px);
    border-radius: 14px;
  }

  .eval-monitor-modal-header {
    flex-direction: row;
    align-items: flex-start;
    padding: 14px;
  }

  .eval-monitor-modal-header h3 {
    font-size: 1rem;
    line-height: 1.25;
    overflow-wrap: anywhere;
  }

  .eval-monitor-modal-header p {
    font-size: 0.74rem;
    overflow-wrap: anywhere;
  }

  .eval-monitor-modal-body {
    padding: 14px;
    gap: 14px;
  }

  .eval-monitor-faculty-score {
    align-items: stretch;
  }

  .eval-monitor-faculty-stats {
    display: grid;
    grid-template-columns: 1fr;
    justify-content: stretch;
  }

  .eval-monitor-faculty-stats span {
    white-space: normal;
  }
}

/* ─── Mobile-only Chatbot Toggle ───────────────────────────── */
.eval-monitor-mobile-nav-btn {
