/* DIPASCAF 2026 UI Refresh: frontend-only visual system overrides */
:root {
  color-scheme: light;
  --ui-bg: #f5f7f6;
  --ui-bg-soft: #eef4f1;
  --ui-surface: #ffffff;
  --ui-surface-soft: #f8faf9;
  --ui-text: #17231f;
  --ui-muted: #53645e;
  --ui-subtle: #71827b;
  --ui-border: #dce6e1;
  --ui-primary: #176447;
  --ui-primary-strong: #0f4d38;
  --ui-primary-soft: #e4f3eb;
  --ui-accent: #b18418;
  --ui-danger: #b42318;
  --ui-warning: #a16207;
  --ui-success: #16723f;
  --ui-radius: 14px;
  --ui-radius-sm: 10px;
  --ui-shadow: 0 14px 32px rgba(32, 48, 42, 0.08);
  --ui-shadow-soft: 0 8px 20px rgba(32, 48, 42, 0.06);
}

.admin-body.dark-mode,
.admin-body.dark {
  color-scheme: dark;
  --ui-bg: #111917;
  --ui-bg-soft: #17231f;
  --ui-surface: #1c2824;
  --ui-surface-soft: #22312c;
  --ui-text: #edf5f1;
  --ui-muted: #c3d1ca;
  --ui-subtle: #9db0a7;
  --ui-border: #344640;
  --ui-primary: #69d09a;
  --ui-primary-strong: #9ee8bf;
  --ui-primary-soft: rgba(105, 208, 154, 0.14);
  --ui-accent: #f2c85f;
  --ui-shadow: 0 16px 34px rgba(0, 0, 0, 0.22);
  --ui-shadow-soft: 0 8px 20px rgba(0, 0, 0, 0.18);
}

html {
  font-size: 16px;
}

body,
button,
input,
select,
textarea {
  font-family: Poppins, Inter, "Segoe UI", Arial, sans-serif;
  letter-spacing: 0;
}

button,
a,
input,
select,
textarea {
  transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease, box-shadow 150ms ease, transform 150ms ease;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 1ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 1ms !important;
  }
}

.login-page {
  min-height: 100dvh;
  display: grid;
  place-items: center;
  position: relative;
  overflow: hidden;
  padding: clamp(18px, 4vw, 48px);
  background: #10231d;
}

.login-bg {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(135deg, rgba(7, 19, 15, 0.76), rgba(16, 44, 34, 0.64)),
    url("/assets/images/pmas-campus-bg.jpg") center / cover no-repeat;
  filter: saturate(0.96);
  transform: scale(1.02);
}

.login-shell {
  position: relative;
  z-index: 1;
  width: min(440px, 100%);
  display: grid;
}

.login-card {
  width: 100%;
  border: 1px solid rgba(255, 255, 255, 0.32);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.9);
  box-shadow: 0 28px 70px rgba(0, 0, 0, 0.28);
  padding: clamp(24px, 5vw, 34px);
  color: #16231e;
  backdrop-filter: blur(16px);
