}

.login-card .login-input-wrap input {
  min-height: 50px;
  width: 100%;
  border: 0;
  border-radius: 0;
  background: transparent;
  padding: 0;
  color: #16231e;
  box-shadow: none;
}

.login-card .login-input-wrap input:focus {
  border: 0;
  box-shadow: none;
}

.show-password-button {
  width: 38px;
  height: 38px;
  display: inline-grid;
