/* ─── Evaluation Form Validation Styles ─────────────────────────── */

/* Question row with error */
.form-question-row.has-validation-error {
  border-color: #ef4444;
  background: linear-gradient(135deg, rgba(255, 241, 242, 0.96), #ffffff);
  box-shadow: inset 3px 0 0 #dc2626, 0 0 0 2px rgba(239, 68, 68, 0.12), 0 10px 24px rgba(153, 27, 27, 0.08);
}

.form-question-row p.error-text {
  color: #991b1b;
}

.form-question-row p.error-text,
.evidence-label-line {
  display: flex;
  align-items: flex-start;
  gap: 7px;
}

.field-warning-dot {
  flex-shrink: 0;
  margin-top: 2px;
  color: #dc2626;
  filter: drop-shadow(0 1px 4px rgba(220, 38, 38, 0.18));
}

/* Rating group with error */
.rating-group-error {
  outline: 1px solid #fecaca;
  border-radius: 12px;
  margin: -8px;
  padding: 8px;
  background: rgba(254, 242, 242, 0.72);
  box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.07);
}

.rating-group-required {
  outline: 1px solid #fecaca;
  border-radius: 12px;
  margin: -8px;
  padding: 8px;
  background: rgba(254, 242, 242, 0.72);
