/* ─── Interactive Submission Success ───────────────────────── */
.evaluation-submit-success {
  position: relative;
  display: grid;
  gap: 16px;
  overflow: hidden;
  margin-top: 18px;
  padding: 22px;
  border: 1px solid #bbf7d0;
  border-radius: 16px;
  background:
    radial-gradient(circle at 14% 0%, rgba(52, 211, 153, 0.2), transparent 30%),
    linear-gradient(135deg, #f0fdf4, #ffffff);
  box-shadow: 0 18px 42px rgba(15, 118, 79, 0.12);
}

.evaluation-submit-success.all-done {
  border-color: #a7f3d0;
  background:
    radial-gradient(circle at 50% 0%, rgba(16, 185, 129, 0.24), transparent 35%),
    linear-gradient(135deg, #ecfdf5, #ffffff);
}

.evaluation-confetti {
  pointer-events: none;
  position: absolute;
  inset: 0;
  overflow: hidden;
  z-index: 2;
}

.evaluation-confetti span {
  position: absolute;
  top: -22px;
  left: calc((var(--piece) * 29px) % 100%);
  width: 9px;
  height: 16px;
  border-radius: 4px;
  background: hsl(calc(var(--piece) * 41), 82%, 58%);
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.12);
  animation: evaluationConfettiFall 2400ms cubic-bezier(0.16, 1, 0.3, 1) forwards;
  animation-delay: calc((var(--piece) % 12) * 55ms);
  transform: rotate(calc(var(--piece) * 18deg));
}

.evaluation-confetti span:nth-child(3n) {
  width: 7px;
  height: 7px;
  border-radius: 999px;
}

.evaluation-confetti span:nth-child(4n) {
  width: 12px;
  height: 8px;
}

@keyframes evaluationConfettiFall {
  0% {
    opacity: 0;
    transform: translate3d(0, -20px, 0) rotate(0deg);
  }
  15% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: translate3d(calc(((var(--piece) % 7) - 3) * 20px), 360px, 0) rotate(calc(var(--piece) * 92deg));
  }
}

@media (prefers-reduced-motion: reduce) {
  .evaluation-confetti {
    display: none;
  }
}

