/* Period Participants now lives inside the Peer Assignment module. */
.peer-assignment-module {
  display: grid;
  gap: 16px;
  min-width: 0;
}

.peer-assignment-module-panel {
  min-width: 0;
  transform-origin: top center;
  animation: peerModulePanelEnter .34s cubic-bezier(.22, .8, .25, 1) both;
}

@keyframes peerModulePanelEnter {
  from {
    opacity: 0;
    transform: translateY(10px) scale(.995);
    filter: blur(2px);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
    filter: blur(0);
  }
}

.peer-assignment-module-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 17px 19px;
