/* Circuit glass login experience */
.login-page {
  isolation: isolate;
  min-height: 100dvh;
  padding: clamp(18px, 4vw, 52px);
  background:
    radial-gradient(circle at 18% 16%, rgba(34, 197, 94, 0.2), transparent 30%),
    radial-gradient(circle at 82% 24%, rgba(20, 184, 166, 0.16), transparent 28%),
    linear-gradient(135deg, #03130d 0%, #062018 46%, #071a1d 100%);
}

.login-bg {
  overflow: hidden;
  background:
    linear-gradient(135deg, rgba(2, 8, 6, 0.34), rgba(5, 32, 22, 0.42)),
    url("/assets/images/pmas-campus-bg.jpg") center / cover no-repeat;
  filter: saturate(1.06) contrast(1.04) brightness(1.04);
  transform: none;
}

.login-bg::before,
.login-bg::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.login-bg::before {
  background:
    linear-gradient(rgba(96, 165, 250, 0.08) 1px, transparent 1px),
    linear-gradient(90deg, rgba(45, 212, 191, 0.07) 1px, transparent 1px);
  background-size: 52px 52px;
  mask-image: radial-gradient(circle at center, black, transparent 76%);
  animation: circuitGridDrift 22s linear infinite;
}

.login-bg::after {
  background:
    radial-gradient(circle at 50% 45%, rgba(34, 197, 94, 0.16), transparent 24%),
    radial-gradient(circle at 48% 48%, transparent 0 44%, rgba(2, 20, 13, 0.28) 78%),
    linear-gradient(180deg, rgba(2, 20, 13, 0.04), rgba(2, 20, 13, 0.34));
}

.circuit-grid,
.circuit,
.circuit-pulse {
  position: absolute;
  pointer-events: none;
}

.circuit-grid {
  inset: -10%;
  opacity: 0.62;
  background:
    linear-gradient(90deg, transparent 0 22%, rgba(34, 211, 238, 0.36) 22% 22.4%, transparent 22.4% 48%, rgba(168, 85, 247, 0.28) 48% 48.35%, transparent 48.35%),
    linear-gradient(0deg, transparent 0 30%, rgba(45, 212, 191, 0.32) 30% 30.4%, transparent 30.4% 62%, rgba(96, 165, 250, 0.22) 62% 62.35%, transparent 62.35%);
  background-size: 260px 190px;
  animation: circuitLayerSlide 18s linear infinite;
}

.circuit {
  width: min(560px, 78vw);
  height: 160px;
  border: 1px solid rgba(34, 211, 238, 0.28);
  border-left: 0;
  border-bottom: 0;
  opacity: 0.86;
  filter: drop-shadow(0 0 16px rgba(34, 211, 238, 0.24));
}

.circuit::before,
.circuit::after,
.circuit span {
  content: "";
  position: absolute;
  background: linear-gradient(90deg, transparent, rgba(125, 249, 255, 0.92), transparent);
  box-shadow: 0 0 18px rgba(34, 211, 238, 0.6);
}

.circuit::before {
  top: -1px;
  left: 0;
  width: 34%;
  height: 2px;
  animation: circuitRunX 4.8s ease-in-out infinite;
}

.circuit::after {
  right: -1px;
  top: 0;
  width: 2px;
  height: 46%;
  background: linear-gradient(180deg, transparent, rgba(196, 181, 253, 0.9), transparent);
  animation: circuitRunY 5.4s ease-in-out infinite;
}

.circuit span {
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: #67e8f9;
  animation: nodePulse 2.8s ease-in-out infinite;
}

.circuit span:nth-child(1) {
  top: -4px;
  right: 20%;
}

.circuit span:nth-child(2) {
  right: -4px;
  top: 54%;
  animation-delay: 600ms;
}

.circuit span:nth-child(3) {
  left: 18%;
  top: 44%;
  background: #c4b5fd;
  animation-delay: 1.1s;
}

.circuit-a {
  top: 9%;
  left: 5%;
}

.circuit-b {
  right: -5%;
  top: 18%;
  transform: rotate(180deg);
}

.circuit-c {
  bottom: 7%;
  left: 18%;
  transform: rotate(8deg);
}

.circuit-pulse {
  width: 9px;
  height: 9px;
  border-radius: 999px;
  background: #67e8f9;
  box-shadow: 0 0 0 8px rgba(34, 211, 238, 0.12), 0 0 26px rgba(34, 211, 238, 0.72);
  animation: roamingPulse 7s ease-in-out infinite;
}

.pulse-a {
  left: 18%;
  top: 25%;
}

.pulse-b {
  right: 22%;
  top: 66%;
  background: #c4b5fd;
  animation-delay: 1.7s;
}

.pulse-c {
  left: 62%;
  top: 18%;
  animation-delay: 3.1s;
}

.login-shell {
  z-index: 2;
  width: min(460px, 100%);
}

.login-card {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(167, 243, 208, 0.42);
  border-radius: 24px;
  background:
    linear-gradient(145deg, rgba(6, 78, 59, 0.58), rgba(5, 46, 22, 0.34)),
    rgba(236, 253, 245, 0.14);
  padding: clamp(24px, 4vw, 38px);
  color: #eef8ff;
  box-shadow:
    0 28px 80px rgba(0, 0, 0, 0.34),
    0 0 44px rgba(16, 185, 129, 0.18),
    inset 0 1px 0 rgba(255, 255, 255, 0.22);
  backdrop-filter: blur(22px) saturate(1.35);
}

.login-card::before {
  height: auto;
  margin: 0;
  border-radius: inherit;
  background:
    linear-gradient(90deg, transparent, rgba(52, 211, 153, 0.7), rgba(20, 184, 166, 0.52), transparent);
  opacity: 0.8;
  position: absolute;
  inset: 0;
  padding: 1px;
  mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  mask-composite: exclude;
  pointer-events: none;
}

.login-card::after {
  content: "";
  position: absolute;
  inset: -35% -20% auto;
  height: 180px;
  background: radial-gradient(circle, rgba(52, 211, 153, 0.24), transparent 68%);
  pointer-events: none;
}

.login-card-brand,
.login-card h1,
.login-subtitle,
.login-welcome,
.login-card .form,
.login-card .alert,
.login-success,
.login-security-chip {
  position: relative;
  z-index: 1;
}

.login-card-brand {
  color: #dbeafe;
}

.login-card-brand img {
  width: 72px;
  height: 72px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.9);
  padding: 6px;
  box-shadow: 0 0 28px rgba(34, 211, 238, 0.28);
}

.login-card-brand span {
  color: #bfdbfe;
}

.login-security-chip {
  width: fit-content;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin: 0 auto 12px;
  border: 1px solid rgba(167, 243, 208, 0.36);
  border-radius: 999px;
  background: rgba(16, 185, 129, 0.16);
  padding: 7px 12px;
  color: #bbf7d0;
  font-size: 0.75rem;
  font-weight: 850;
}

.login-card h1 {
  color: #ffffff;
  text-shadow: 0 0 24px rgba(34, 211, 238, 0.38);
}

.login-subtitle,
.login-welcome {
  color: #cbd5e1;
}

.login-welcome {
  color: #e0f2fe;
}

.login-card label {
  color: #ffffff;
}

.login-card .form > label,
.login-card .password-toggle,
.login-options .password-toggle {
  color: #ffffff;
}

.login-card .login-options label.password-toggle[for="remember-email"] {
  color: #ffffff !important;
}

.login-input-wrap {
  border-color: rgba(167, 243, 208, 0.3);
  background: rgba(6, 78, 59, 0.38);
  color: #bbf7d0;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
  transition: border-color 180ms ease, box-shadow 180ms ease, background-color 180ms ease, transform 180ms ease;
}

.login-input-wrap:hover {
  border-color: rgba(134, 239, 172, 0.58);
  background: rgba(6, 95, 70, 0.48);
}

.login-input-wrap:focus-within {
  border-color: rgba(134, 239, 172, 0.9);
  box-shadow: 0 0 0 4px rgba(34, 197, 94, 0.16), 0 0 26px rgba(16, 185, 129, 0.2);
  transform: translateY(-1px);
}

.login-card .login-input-wrap input {
  color: #f8fafc;
}

.login-card .login-input-wrap input::placeholder {
  color: #94a3b8;
}

.login-card .login-input-wrap input:disabled {
  cursor: wait;
  opacity: 0.76;
}

.login-card .show-password-button {
  color: #bfdbfe;
}

.login-card .show-password-button:hover:not(:disabled) {
  background: rgba(34, 197, 94, 0.16);
  color: #ffffff;
}

.login-card .show-password-button:disabled {
  cursor: wait;
  opacity: 0.62;
}

.login-options {
  color: #cbd5e1;
}

.login-options .password-toggle {
  color: #ffffff;
}

.login-options a {
  color: #86efac;
}

.login-options a:hover {
  color: #ccfbf1;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.password-toggle input {
  accent-color: #22c55e;
}

.login-card button[type="submit"] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  border: 1px solid rgba(187, 247, 208, 0.46);
  background: linear-gradient(135deg, #047857, #16a34a 52%, #0f766e);
  box-shadow: 0 16px 34px rgba(22, 163, 74, 0.34), 0 0 24px rgba(52, 211, 153, 0.22);
}

.login-card button[type="submit"]:hover:not(:disabled) {
  background: linear-gradient(135deg, #059669, #22c55e 52%, #14b8a6);
  box-shadow: 0 20px 42px rgba(22, 163, 74, 0.42), 0 0 30px rgba(52, 211, 153, 0.3);
}

.login-card button[type="submit"]:disabled {
  opacity: 0.78;
}

.login-spinner {
  animation: loginSpin 900ms linear infinite;
}

.login-card .alert,
.login-success {
  border-radius: 14px;
  padding: 12px 14px;
  font-size: 0.88rem;
  line-height: 1.4;
  backdrop-filter: blur(12px);
}

.login-card .alert {
  border-color: rgba(248, 113, 113, 0.44);
  background: rgba(127, 29, 29, 0.36);
  color: #fecaca;
}

.login-success {
  margin-bottom: 16px;
  border-color: rgba(45, 212, 191, 0.42);
  background: rgba(20, 184, 166, 0.16);
  color: #ccfbf1;
}

@keyframes circuitGridDrift {
  from {
    transform: translate3d(0, 0, 0);
  }
  to {
    transform: translate3d(52px, 52px, 0);
  }
}

@keyframes circuitLayerSlide {
  from {
    transform: translate3d(0, 0, 0);
  }
  to {
    transform: translate3d(260px, 190px, 0);
  }
}

@keyframes circuitRunX {
  0%,
  100% {
    transform: translateX(0);
    opacity: 0;
  }
  20%,
  75% {
    opacity: 1;
  }
  100% {
    transform: translateX(190%);
  }
}

@keyframes circuitRunY {
  0%,
  100% {
    transform: translateY(0);
    opacity: 0;
  }
  22%,
  76% {
    opacity: 1;
  }
  100% {
    transform: translateY(130%);
  }
}

@keyframes nodePulse {
  0%,
  100% {
    transform: scale(0.8);
    opacity: 0.58;
  }
  50% {
    transform: scale(1.35);
    opacity: 1;
  }
}

@keyframes roamingPulse {
  0%,
  100% {
    transform: translate3d(0, 0, 0) scale(0.8);
    opacity: 0.55;
  }
  35% {
    transform: translate3d(58px, 24px, 0) scale(1.18);
    opacity: 1;
  }
  70% {
    transform: translate3d(-28px, 62px, 0) scale(0.94);
    opacity: 0.72;
  }
}

@keyframes loginSpin {
  to {
    transform: rotate(360deg);
  }
}

@media (max-width: 640px) {
  .login-page {
    padding: 16px;
  }

  .login-shell {
    width: min(100%, 430px);
  }

  .login-card {
    border-radius: 20px;
    padding: 24px 18px;
  }

  .login-card-brand img {
    width: 62px;
    height: 62px;
  }

  .login-input-wrap {
    min-height: 52px;
  }

  .circuit {
    opacity: 0.46;
  }
}

/* ── VPAA Evaluation Overview ──────────────────────────────────── */
.vpaa-overview {
  display: grid;
  gap: 20px;
  animation: pageFade 280ms ease-out both;
}

/* ── Sticky Filter Bar ─────────────────────────────────────────── */
.vpaa-filter-bar {
  position: sticky;
  top: 0;
  z-index: 50;
  background: var(--theme-surface, #ffffff);
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 18px;
  padding: 16px 20px;
  box-shadow: 0 12px 28px rgba(31, 54, 45, 0.08);
  backdrop-filter: blur(12px);
}

.vpaa-filter-bar-inner {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.vpaa-filter-label {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--theme-primary, #166a45);
  font-size: 0.82rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  white-space: nowrap;
}

.vpaa-filter-label span {
  color: var(--theme-text, #10201b);
}

/* ── Dropdown ──────────────────────────────────────────────────── */
.vpaa-dropdown {
  position: relative;
  flex: 1;
  min-width: 200px;
  max-width: 480px;
}

.vpaa-dropdown-trigger {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-height: 44px;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 14px;
  background: var(--theme-surface-soft, #f8fafc);
  padding: 0 14px;
  color: var(--theme-text, #10201b);
  font-size: 0.92rem;
  font-weight: 700;
  cursor: pointer;
  transition: all 200ms ease;
  text-align: left;
}

.vpaa-dropdown-trigger:hover {
  border-color: var(--theme-primary, #166a45);
}

.vpaa-dropdown-trigger .vpaa-placeholder {
  color: var(--theme-muted, #94a3b8);
  font-weight: 500;
}

.vpaa-dropdown-arrow {
  margin-left: auto;
  transition: transform 200ms ease;
  color: var(--theme-muted, #94a3b8);
  flex-shrink: 0;
}

.vpaa-dropdown-arrow.open {
  transform: rotate(180deg);
}

.vpaa-dropdown-menu {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  right: 0;
  z-index: 100;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 14px;
  background: var(--theme-surface, #ffffff);
  box-shadow: 0 18px 42px rgba(15, 23, 42, 0.14);
  overflow: hidden;
  animation: cardPop 180ms ease-out both;
}

.vpaa-dropdown-search {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--theme-border, #dbe7e1);
  color: var(--theme-muted, #94a3b8);
}

.vpaa-dropdown-search input {
  flex: 1;
  border: 0;
  background: transparent;
  padding: 6px 0;
  color: var(--theme-text, #10201b);
  font-size: 0.92rem;
  outline: none;
}

.vpaa-dropdown-search input::placeholder {
  color: var(--theme-muted, #94a3b8);
}

.vpaa-dropdown-options {
  max-height: 280px;
  overflow-y: auto;
}

.vpaa-dropdown-option {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  min-height: 48px;
  border: 0;
  background: transparent;
  padding: 10px 14px;
  color: var(--theme-text, #10201b);
  font-size: 0.9rem;
  cursor: pointer;
  text-align: left;
  transition: background 150ms ease;
}

.vpaa-dropdown-option:hover {
  background: var(--theme-primary-soft, #e6f6ec);
}

.vpaa-dropdown-option.active {
  background: var(--theme-primary-soft, #d9f2e2);
  font-weight: 800;
}

.vpaa-dropdown-option-info strong {
  display: block;
  font-size: 0.92rem;
  font-weight: 800;
  color: var(--theme-text, #10201b);
}

.vpaa-dropdown-option-code {
  font-size: 0.76rem;
  color: var(--theme-muted, #64748b);
  font-weight: 700;
}

.vpaa-dropdown-option-dean {
  font-size: 0.82rem;
  color: var(--theme-muted, #64748b);
  white-space: nowrap;
}

.vpaa-dropdown-empty {
  padding: 24px;
  text-align: center;
  color: var(--theme-muted, #94a3b8);
  font-size: 0.9rem;
}

.vpaa-dropdown-empty.error {
  color: #dc2626;
}

.vpaa-clear-btn {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 10px;
  background: transparent;
  color: var(--theme-muted, #94a3b8);
  cursor: pointer;
  flex-shrink: 0;
  transition: all 200ms ease;
}

.vpaa-clear-btn:hover {
  border-color: #dc2626;
  color: #dc2626;
  background: #fef2f2;
}

.vpaa-refresh-btn {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 10px;
  background: transparent;
  color: var(--theme-muted, #64748b);
  cursor: pointer;
  flex-shrink: 0;
  transition: all 200ms ease;
}

.vpaa-refresh-btn:hover {
  border-color: var(--theme-primary, #166a45);
  color: var(--theme-primary, #166a45);
  background: var(--theme-primary-soft, #e6f6ec);
}

/* ── Summary Cards ─────────────────────────────────────────────── */
.vpaa-summary-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 14px;
}

.vpaa-summary-card {
  display: flex;
  align-items: center;
  gap: 14px;
  min-height: 84px;
  border-radius: 16px;
  padding: 18px;
  border: 1px solid var(--theme-border, #dbe7e1);
  background: var(--theme-surface, #ffffff);
  box-shadow: 0 8px 20px rgba(31, 54, 45, 0.06);
}

.vpaa-summary-card svg {
  flex-shrink: 0;
}

.vpaa-summary-card div {
  display: grid;
  gap: 2px;
}

.vpaa-summary-card strong {
  color: var(--theme-text, #10201b);
  font-size: clamp(1.4rem, 3vw, 2rem);
  font-weight: 900;
  line-height: 1;
}

.vpaa-summary-card span {
  color: var(--theme-muted, #4d5f57);
  font-size: 0.8rem;
  font-weight: 800;
}

.vpaa-summary-primary svg { color: #166a45; }
.vpaa-summary-info svg { color: #2563eb; }
.vpaa-summary-warning svg { color: #b45309; }
.vpaa-summary-success svg { color: #15803d; }

/* ── Content Area ──────────────────────────────────────────────── */
.vpaa-content {
  display: grid;
  gap: 20px;
}

.vpaa-error {
  border-radius: 16px;
  background: #fef2f2;
  border: 1px solid #fecaca;
  padding: 18px;
  color: #b91c1c;
  font-weight: 700;
  text-align: center;
}

.vpaa-empty-state {
  display: grid;
  place-items: center;
  gap: 12px;
  padding: 48px 20px;
  text-align: center;
  color: var(--theme-muted, #94a3b8);
  border: 1px dashed var(--theme-border, #dbe7e1);
  border-radius: 18px;
  background: var(--theme-surface-soft, #f8fafc);
}

.vpaa-empty-state p {
  font-size: 0.95rem;
  font-weight: 700;
  max-width: 360px;
}

.vpaa-empty-inset {
  padding: 16px;
  text-align: center;
  color: var(--theme-muted, #64748b);
  font-size: 0.88rem;
  font-weight: 700;
  background: var(--theme-surface-soft, #f8fafc);
  border-radius: 12px;
  border: 1px dashed var(--theme-border, #dbe7e1);
}

/* ── Skeleton Loading ──────────────────────────────────────────── */
.vpaa-skeleton {
  display: grid;
  gap: 14px;
}

.vpaa-skeleton-card {
  display: grid;
  gap: 12px;
  padding: 20px;
  border-radius: 14px;
  border: 1px solid var(--theme-border, #dbe7e1);
  background: var(--theme-surface, #ffffff);
}

.vpaa-skeleton-line {
  height: 14px;
  border-radius: 999px;
  background: linear-gradient(90deg, #e5ece8 25%, #f0f5f2 50%, #e5ece8 75%);
  background-size: 200% 100%;
  animation: shimmer 1.5s ease-in-out infinite;
}

.vpaa-skeleton-line.w-32 { width: 8rem; }
.vpaa-skeleton-line.w-48 { width: 12rem; }

@keyframes shimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

/* ── Department Hero ───────────────────────────────────────────── */
.vpaa-dept-hero {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 22px;
  border-radius: 18px;
  background: linear-gradient(135deg, #123d35, #1f7a4f 58%, #2e965f);
  color: #000000;
  box-shadow: 0 18px 45px rgba(18, 61, 53, 0.12);
}

.vpaa-dept-hero-icon {
  display: grid;
  place-items: center;
  width: 56px;
  height: 56px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.15);
  color: #ffffff;
  flex-shrink: 0;
}

.vpaa-dept-hero-info h2 {
  margin: 4px 0 6px;
  color: #ffffff;
  font-size: clamp(1.4rem, 3vw, 2.2rem);
  font-weight: 900;
}

.vpaa-dept-hero-eyebrow {
  color: #bbf7d0;
  font-size: 0.78rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin: 0;
}


/* ── VPAA Evaluation Overview (continued) ───────────────────────── */

/* ── Dropdown Options ──────────────────────────────────────────── */
.vpaa-dropdown-options {
  max-height: 280px;
  overflow-y: auto;
  padding: 4px;
}

.vpaa-dropdown-empty {
  padding: 24px 16px;
  text-align: center;
  color: var(--theme-muted, #64748b);
  font-size: 0.88rem;
  font-weight: 700;
}

.vpaa-dropdown-empty.error {
  color: #dc2626;
}

.vpaa-dropdown-option {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  border: none;
  border-radius: 10px;
  background: transparent;
  padding: 10px 12px;
  color: var(--theme-text, #10201b);
  font-size: 0.9rem;
  text-align: left;
  cursor: pointer;
  transition: background 160ms ease;
}

.vpaa-dropdown-option:hover {
  background: color-mix(in srgb, var(--theme-primary, #166a45) 8%, transparent);
}

.vpaa-dropdown-option.active {
  background: color-mix(in srgb, var(--theme-primary, #166a45) 14%, transparent);
