/* ── Clear & Refresh Buttons ────────────────────────────────────── */
.vpaa-clear-btn,
.vpaa-refresh-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 10px;
  background: var(--theme-surface-soft, #f8fafc);
  color: var(--theme-muted, #64748b);
  cursor: pointer;
  transition: all 160ms ease;
  flex-shrink: 0;
}

.vpaa-clear-btn:hover,
.vpaa-refresh-btn:hover {
  border-color: color-mix(in srgb, var(--theme-primary, #166a45) 34%, var(--theme-border, #dbe7e1));
  background: color-mix(in srgb, var(--theme-primary, #166a45) 8%, transparent);
  color: var(--theme-primary, #166a45);
}

.vpaa-refresh-btn {
  margin-left: auto;
}

/* ── Summary Grid ───────────────────────────────────────────────── */
.vpaa-summary-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 14px;
}

.vpaa-summary-card {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 18px 20px;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 16px;
  background: var(--theme-surface, #ffffff);
  box-shadow: 0 8px 20px rgba(31, 54, 45, 0.06);
  transition: transform 180ms ease, box-shadow 180ms ease;
}

.vpaa-summary-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 28px rgba(31, 54, 45, 0.1);
}

.vpaa-summary-card svg {
  flex-shrink: 0;
  color: var(--summary-color, #166a45);
}

.vpaa-summary-card div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.vpaa-summary-card strong {
  font-size: clamp(1.4rem, 2.5vw, 1.85rem);
  font-weight: 900;
  line-height: 1;
  color: var(--summary-color, #10201b);
}

.vpaa-summary-card span {
  color: var(--theme-muted, #4d5f57);
  font-size: 0.78rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.vpaa-summary-card.vpaa-summary-primary { --summary-color: #166a45; }
.vpaa-summary-card.vpaa-summary-info { --summary-color: #2563eb; }
.vpaa-summary-card.vpaa-summary-warning { --summary-color: #b45309; }
.vpaa-summary-card.vpaa-summary-danger { --summary-color: #dc2626; }
.vpaa-summary-card.vpaa-summary-success { --summary-color: #15803d; }

/* ── Content Area ───────────────────────────────────────────────── */
.vpaa-content {
  display: grid;
  gap: 20px;
}

/* ── Department Hero ────────────────────────────────────────────── */
.vpaa-dept-hero {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 24px 26px;
  border-radius: 18px;
  background: linear-gradient(135deg, #123d35, #1f7a4f 58%, #2e965f);
  box-shadow: 0 18px 45px rgba(18, 61, 53, 0.12);
}

.vpaa-dept-hero-icon {
  display: grid;
  place-items: center;
  width: 56px;
  height: 56px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.15);
  color: #ffffff;
  flex-shrink: 0;
}

.vpaa-dept-hero-info {
  flex: 1;
  min-width: 0;
}

.vpaa-dept-hero-eyebrow {
  margin: 0;
  color: #bbf7d0;
  font-size: 0.78rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.vpaa-dept-hero-info h2 {
  margin: 4px 0 6px;
  color: #ffffff;
  font-size: clamp(1.4rem, 3vw, 2.2rem);
  font-weight: 900;
}

.vpaa-dept-hero-details {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 12px;
  margin: 0;
  color: rgba(255, 255, 255, 0.84);
  font-size: 0.9rem;
  font-weight: 700;
}

.vpaa-dept-hero-sep {
  opacity: 0.4;
}

/* ── Programs List ──────────────────────────────────────────────── */
.vpaa-programs-list {
  display: grid;
  gap: 16px;
}

/* ── Program Card ───────────────────────────────────────────────── */
.vpaa-program-card {
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 18px;
  background: var(--theme-surface, #ffffff);
  box-shadow: 0 10px 24px rgba(31, 54, 45, 0.06);
  overflow: hidden;
  transition: box-shadow 200ms ease;
}

.vpaa-program-card:hover {
  box-shadow: 0 14px 32px rgba(31, 54, 45, 0.1);
}

.vpaa-program-card-header {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  border: none;
  border-radius: 0;
  background: transparent;
  padding: 16px 20px;
  color: var(--theme-text, #10201b);
  text-align: left;
  cursor: pointer;
  transition: background 160ms ease;
}

.vpaa-program-card-header:hover {
  background: color-mix(in srgb, var(--theme-primary, #166a45) 4%, transparent);
}

.vpaa-program-card-title {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: 1;
  min-width: 0;
}

.vpaa-program-card-title svg {
  flex-shrink: 0;
  color: var(--theme-primary, #166a45);
}

.vpaa-program-card-title strong {
  display: block;
  font-size: 1rem;
  font-weight: 900;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.vpaa-program-code {
  display: inline-block;
  margin-top: 2px;
  padding: 2px 8px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--theme-primary, #166a45) 12%, transparent);
  color: var(--theme-primary, #166a45);
  font-size: 0.68rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.vpaa-program-card-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}

.vpaa-program-head {
  display: none;
  color: var(--theme-muted, #64748b);
  font-size: 0.78rem;
  font-weight: 800;
}

@media (min-width: 700px) {
  .vpaa-program-head {
    display: inline;
  }
}

.vpaa-program-stats {
  color: var(--theme-muted, #4d5f57);
  font-size: 0.82rem;
  font-weight: 800;
  white-space: nowrap;
}

.vpaa-program-bar-wrapper {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 100px;
}

.vpaa-program-bar {
  flex: 1;
  height: 8px;
  border-radius: 999px;
  background: var(--theme-border, #e5ece8);
  overflow: hidden;
}

.vpaa-program-bar span {
  display: block;
  height: 100%;
  border-radius: inherit;
  transition: width 500ms ease;
}

.vpaa-program-bar-wrapper small {
  color: var(--theme-muted, #64748b);
  font-size: 0.72rem;
  font-weight: 800;
  min-width: 32px;
  text-align: right;
}

.vpaa-program-card-body {
  border-top: 1px solid var(--theme-border, #e5ece8);
  padding: 16px 20px 20px;
  display: grid;
  gap: 12px;
}

.vpaa-empty-inset {
  padding: 24px;
  text-align: center;
  color: var(--theme-muted, #94a3b8);
  font-size: 0.88rem;
  font-weight: 700;
  border: 1px dashed var(--theme-border, #dbe7e1);
  border-radius: 12px;
}

/* ── Evaluation Section (expandable) ────────────────────────────── */
.vpaa-eval-section {
  border: 1px solid var(--theme-border, #e5ece8);
  border-radius: 14px;
  background: var(--theme-surface-soft, #f8fafc);
  overflow: hidden;
}

.vpaa-eval-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  border: none;
  border-radius: 0;
  background: transparent;
  padding: 12px 16px;
  color: var(--theme-text, #10201b);
  cursor: pointer;
  transition: background 160ms ease;
}

.vpaa-eval-section-header:hover {
  background: color-mix(in srgb, var(--theme-primary, #166a45) 4%, transparent);
}

.vpaa-eval-section-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.9rem;
}

.vpaa-eval-section-title svg {
  color: var(--theme-primary, #166a45);
}

.vpaa-eval-section-title strong {
  font-weight: 900;
}

.vpaa-eval-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 22px;
  padding: 0 6px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--theme-primary, #166a45) 12%, transparent);
  color: var(--theme-primary, #166a45);
  font-size: 0.72rem;
  font-weight: 900;
}

.vpaa-eval-section-summary {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.vpaa-eval-section-body {
  border-top: 1px solid var(--theme-border, #e5ece8);
  padding: 12px 16px;
}

/* ── Status Badges ──────────────────────────────────────────────── */
.vpaa-badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0.02em;
  white-space: nowrap;
  transition: all 160ms ease;
}

.vpaa-badge-success {
  background: #dcfce7;
  color: #15803d;
  border: 1px solid #bbf7d0;
}

.vpaa-badge-warning {
  background: #fef3c7;
  color: #b45309;
  border: 1px solid #fde68a;
}

.vpaa-badge-danger {
  background: #fee2e2;
  color: #b91c1c;
  border: 1px solid #fecaca;
}

.vpaa-badge-default {
  background: #f1f5f9;
  color: #64748b;
  border: 1px solid #e2e8f0;
}

/* ── Evaluation Table ───────────────────────────────────────────── */
.vpaa-eval-table {
  display: grid;
  gap: 2px;
}

.vpaa-eval-table-head {
  display: grid;
  grid-template-columns: minmax(140px, 1.4fr) minmax(140px, 1.4fr) 100px 100px;
  gap: 8px;
  padding: 8px 10px;
  color: var(--theme-muted, #64748b);
  font-size: 0.68rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-bottom: 1px solid var(--theme-border, #dbe7e1);
}

.vpaa-eval-table-row {
  display: grid;
  grid-template-columns: minmax(140px, 1.4fr) minmax(140px, 1.4fr) 100px 100px;
  gap: 8px;
  align-items: center;
  padding: 10px;
  border-radius: 8px;
  color: var(--theme-text, #1e293b);
  font-size: 0.84rem;
  font-weight: 700;
  transition: background 120ms ease;
}

.vpaa-eval-table-row:hover {
  background: color-mix(in srgb, var(--theme-primary, #166a45) 4%, transparent);
}

.vpaa-eval-col-name,
.vpaa-eval-col-evaluator {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.vpaa-eval-col-status,
.vpaa-eval-col-deadline {
  text-align: center;
}

@media (max-width: 700px) {
  .vpaa-eval-table-head,
  .vpaa-eval-table-row {
    grid-template-columns: 1fr 1fr;
  }
  .vpaa-eval-col-status {
    grid-column: 1;
  }
  .vpaa-eval-col-deadline {
    grid-column: 2;
  }
  .vpaa-summary-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* ── Skeleton Loading ───────────────────────────────────────────── */
.vpaa-skeleton {
  display: grid;
  gap: 16px;
}

.vpaa-skeleton-card {
  padding: 20px;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 18px;
  background: var(--theme-surface, #ffffff);
  display: grid;
  gap: 12px;
}

.vpaa-skeleton-line {
  height: 14px;
  border-radius: 999px;
  background: linear-gradient(90deg, #e5ece8 30%, #f0f5f1 60%, #e5ece8 100%);
  background-size: 200% 100%;
  animation: vpaaShimmer 1.4s ease-in-out infinite;
}

.vpaa-skeleton-line.w-32 { width: 120px; }
.vpaa-skeleton-line.w-48 { width: 200px; }
.vpaa-skeleton-line.w-full { width: 100%; }

@keyframes vpaaShimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

/* ── Empty State ────────────────────────────────────────────────── */
.vpaa-empty-state {
  display: grid;
  place-items: center;
  gap: 14px;
  padding: 50px 24px;
  border: 1px dashed var(--theme-border, #dbe7e1);
  border-radius: 18px;
  background: var(--theme-surface-soft, #f8fafc);
  text-align: center;
}

.vpaa-empty-state svg {
  color: var(--theme-muted, #94a3b8);
}

.vpaa-empty-state p {
  max-width: 360px;
  color: var(--theme-muted, #64748b);
  font-size: 0.95rem;
  font-weight: 700;
  line-height: 1.5;
}

/* ── Error State ────────────────────────────────────────────────── */
.vpaa-error {
  padding: 18px 22px;
  border-radius: 14px;
  background: #fef2f2;
  border: 1px solid #fecaca;
  color: #b91c1c;
  font-size: 0.92rem;
  font-weight: 800;
}

/* ════════════════════════════ DARK MODE ════════════════════════════ */
