/* ── Evaluation Overview visual refinement ─────────────────────── */
.vpaa-overview {
  gap: 18px;
}

.vpaa-filter-bar {
  border-radius: 14px;
  padding: 14px 16px;
  box-shadow: 0 10px 24px rgba(31, 54, 45, 0.07);
}

.vpaa-filter-bar-inner {
  gap: 10px;
}

.vpaa-dropdown {
  min-width: min(100%, 260px);
  max-width: 560px;
}

.vpaa-dropdown-trigger {
  min-height: 46px;
  border-radius: 12px;
  background: #fbfdfc;
  padding: 0 13px;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.8);
}

.vpaa-dropdown-trigger:hover,
.vpaa-dropdown-trigger:focus-visible {
  border-color: color-mix(in srgb, var(--theme-primary, #166a45) 48%, var(--theme-border, #dbe7e1));
  background: #ffffff;
  box-shadow: 0 0 0 3px rgba(22, 106, 69, 0.09);
  outline: none;
}

.vpaa-dropdown-trigger span:not(.vpaa-placeholder) {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.vpaa-dropdown-menu {
  top: calc(100% + 8px);
  border-radius: 12px;
  padding: 6px;
}

.vpaa-dropdown-search {
  min-height: 42px;
  border: 1px solid color-mix(in srgb, var(--theme-border, #dbe7e1) 78%, transparent);
  border-radius: 10px;
  background: var(--theme-surface-soft, #f8fafc);
  padding: 0 11px;
  margin-bottom: 6px;
}

.vpaa-dropdown-options {
  max-height: min(330px, 52vh);
  padding: 0;
}

.vpaa-dropdown-option {
  min-height: 54px;
  border-radius: 10px;
  padding: 10px 11px;
}

.vpaa-dropdown-option:hover {
  background: color-mix(in srgb, var(--theme-primary, #166a45) 9%, #ffffff);
}

.vpaa-dropdown-option.active {
  background: color-mix(in srgb, var(--theme-primary, #166a45) 14%, #ffffff);
  box-shadow: inset 3px 0 0 var(--theme-primary, #166a45);
}

.vpaa-summary-section {
  display: grid;
  gap: 12px;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 16px;
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--theme-primary, #166a45) 4%, transparent), transparent 52%),
    var(--theme-surface, #ffffff);
  padding: 16px;
  box-shadow: 0 10px 24px rgba(31, 54, 45, 0.06);
}

.vpaa-summary-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.vpaa-summary-heading p {
