/* Evaluation monitor readability pass */
.admin-header {
  display: grid;
  grid-template-columns: auto minmax(180px, 1fr) minmax(260px, 420px) auto;
  align-items: center;
  gap: 14px;
  min-height: 64px;
  padding-block: 10px;
}

.admin-header-info {
  min-width: 0;
}

.admin-header-info h1 {
  margin: 0;
  font-size: clamp(1.05rem, 1.5vw, 1.35rem);
  line-height: 1.15;
}

.admin-header-note {
  margin: 3px 0 0;
  font-size: 0.78rem;
  line-height: 1.35;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-search {
  min-width: 0;
}

.admin-search label {
  margin-bottom: 4px;
  font-size: 0.68rem;
  line-height: 1;
}

.admin-search input,
.admin-body .admin-search input {
  min-height: 38px;
  font-size: 0.84rem;
}

.admin-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  min-width: 0;
}

.admin-actions .role-context,
.admin-actions .dean-header-context {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 38px;
  width: auto;
  max-width: 180px;
  border-radius: 12px;
  padding: 0 12px;
  font-size: 0.78rem;
  line-height: 1;
  white-space: nowrap;
}

.notification-button,
.profile-button,
.menu-toggle {
  width: 38px;
  height: 38px;
  min-height: 38px;
  flex: 0 0 38px;
}

.profile-button .admin-avatar,
.admin-avatar {
  width: 32px;
  height: 32px;
  font-size: 0.86rem;
}

.account-menu {
  position: relative;
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
}

.account-menu-trigger {
  position: relative;
}

.account-menu-trigger::after {
  content: "";
  position: absolute;
  right: 3px;
  bottom: 3px;
  width: 8px;
  height: 8px;
  border: 2px solid var(--theme-surface, #ffffff);
  border-radius: 999px;
  background: var(--theme-primary, #168358);
}

.account-dropdown {
  position: absolute;
  top: calc(100% + 10px);
  right: 0;
  z-index: 80;
  display: grid;
  gap: 6px;
  width: min(280px, calc(100vw - 24px));
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 16px;
  background: color-mix(in srgb, var(--theme-surface, #ffffff) 94%, transparent);
  padding: 10px;
  box-shadow: 0 22px 48px rgba(15, 23, 42, 0.18);
  backdrop-filter: blur(16px);
  animation: cardPop 160ms ease-out both;
}

.account-dropdown-head {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr);
  gap: 10px;
  align-items: center;
  border-bottom: 1px solid var(--theme-border, #dbe7e1);
  padding: 6px 6px 10px;
  margin-bottom: 2px;
}

.account-dropdown-avatar {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  overflow: hidden;
  border-radius: 14px;
  background: var(--theme-primary-soft, #dff6e8);
  color: var(--theme-primary-strong, #0f6b46);
  font-weight: 900;
}

.account-dropdown-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.account-dropdown-head strong,
.account-dropdown-head small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.account-dropdown-head strong {
  color: var(--theme-text, #10201b);
  font-size: 0.92rem;
  font-weight: 900;
}

.account-dropdown-head small {
  color: var(--theme-muted, #4d5f57);
  font-size: 0.78rem;
  font-weight: 800;
}

.account-dropdown button {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  align-items: center;
  gap: 9px;
  width: 100%;
  min-height: 42px;
  border: 1px solid transparent;
  border-radius: 12px;
  background: transparent;
  padding: 5px 8px;
  color: var(--theme-text, #10201b);
  font-size: 0.86rem;
  font-weight: 850;
  text-align: left;
}

.account-dropdown button svg {
  justify-self: center;
  color: var(--theme-primary, #168358);
}

.account-dropdown button:hover {
  border-color: color-mix(in srgb, var(--theme-primary, #168358) 24%, var(--theme-border, #dbe7e1));
  background: color-mix(in srgb, var(--theme-primary, #168358) 8%, transparent);
}

.account-dropdown button.danger {
  color: #b42318;
}

.account-dropdown button.danger svg {
  color: #dc2626;
}

.account-dropdown button.danger:hover {
  border-color: rgba(248, 113, 113, 0.36);
  background: rgba(248, 113, 113, 0.12);
}

.admin-body.dark-mode .account-menu-trigger::after {
  border-color: #111827;
  background: #5eead4;
}

.admin-body.dark-mode .account-dropdown,
.admin-dashboard-body.dark-mode .account-dropdown {
  border-color: rgba(45, 212, 191, 0.22);
  background: rgba(15, 23, 42, 0.94);
  box-shadow: 0 22px 54px rgba(0, 0, 0, 0.36);
}

.admin-body.dark-mode .account-dropdown-head,
.admin-dashboard-body.dark-mode .account-dropdown-head {
  border-color: rgba(148, 163, 184, 0.18);
}

.admin-body.dark-mode .account-dropdown-head strong,
.admin-dashboard-body.dark-mode .account-dropdown-head strong,
.admin-body.dark-mode .account-dropdown button,
.admin-dashboard-body.dark-mode .account-dropdown button {
  color: #f8fafc;
}

.admin-body.dark-mode .account-dropdown-head small,
.admin-dashboard-body.dark-mode .account-dropdown-head small {
  color: #94a3b8;
}

.admin-body.dark-mode .account-dropdown-avatar,
.admin-dashboard-body.dark-mode .account-dropdown-avatar {
  background: rgba(20, 184, 166, 0.18);
  color: #99f6e4;
}

.admin-body.dark-mode .account-dropdown button svg,
.admin-dashboard-body.dark-mode .account-dropdown button svg {
  color: #5eead4;
}

.admin-body.dark-mode .account-dropdown button:hover,
.admin-dashboard-body.dark-mode .account-dropdown button:hover {
  border-color: rgba(45, 212, 191, 0.26);
  background: rgba(20, 184, 166, 0.12);
}

.admin-body.dark-mode .account-dropdown button.danger,
.admin-dashboard-body.dark-mode .account-dropdown button.danger {
  color: #fecaca;
}

.admin-body.dark-mode .account-dropdown button.danger svg,
.admin-dashboard-body.dark-mode .account-dropdown button.danger svg {
  color: #fca5a5;
}

/* Account dropdown needs to override broad button styles. */
.admin-body:not(.dark-mode) .account-dropdown,
.admin-dashboard-body:not(.dark-mode) .account-dropdown {
  border-color: rgba(22, 131, 88, 0.18) !important;
  background: rgba(255, 255, 255, 0.98) !important;
  box-shadow:
    0 18px 42px rgba(15, 77, 56, 0.14),
    0 0 0 1px rgba(22, 131, 88, 0.05) !important;
}

.admin-body:not(.dark-mode) .account-dropdown button,
.admin-dashboard-body:not(.dark-mode) .account-dropdown button {
  grid-template-columns: 38px minmax(0, 1fr);
  min-height: 48px;
  border-color: rgba(22, 131, 88, 0.12) !important;
  background: #ffffff !important;
  color: #10201b !important;
  box-shadow: none !important;
}

.admin-body:not(.dark-mode) .account-dropdown button svg,
.admin-dashboard-body:not(.dark-mode) .account-dropdown button svg {
  width: 30px;
  height: 30px;
  padding: 6px;
  border: 1px solid rgba(22, 131, 88, 0.16);
  border-radius: 10px;
  background: rgba(22, 131, 88, 0.1);
  color: #0f6b46 !important;
  box-sizing: border-box;
}

.admin-body:not(.dark-mode) .account-dropdown button:hover,
.admin-dashboard-body:not(.dark-mode) .account-dropdown button:hover {
  border-color: rgba(22, 131, 88, 0.28) !important;
  background: #f0fdf4 !important;
  color: #0f5138 !important;
  transform: none;
}

.admin-body:not(.dark-mode) .account-dropdown button.danger,
.admin-dashboard-body:not(.dark-mode) .account-dropdown button.danger {
  border-color: rgba(220, 38, 38, 0.16) !important;
  background: #fffafa !important;
  color: #b42318 !important;
}

.admin-body:not(.dark-mode) .account-dropdown button.danger svg,
.admin-dashboard-body:not(.dark-mode) .account-dropdown button.danger svg {
  border-color: rgba(220, 38, 38, 0.18);
  background: rgba(220, 38, 38, 0.1);
  color: #dc2626 !important;
}

.admin-body:not(.dark-mode) .account-dropdown button.danger:hover,
.admin-dashboard-body:not(.dark-mode) .account-dropdown button.danger:hover {
  border-color: rgba(220, 38, 38, 0.28) !important;
  background: #fef2f2 !important;
  color: #991b1b !important;
}

.admin-module.evaluation-monitor-page {
  gap: 18px;
}

.admin-module .eval-monitor-container {
  gap: 14px;
}

.admin-module .eval-monitor-main {
  gap: 14px;
}

.admin-module .eval-monitor-header {
  min-height: 42px;
  gap: 12px;
  padding: 0;
}

.admin-module .eval-monitor-header h2 {
  font-size: clamp(1.1rem, 1.55vw, 1.35rem);
}

.admin-module .eval-monitor-header-actions,
.admin-module .eval-monitor-toolbar-actions {
  gap: 8px;
  align-items: center;
}

.admin-module .eval-monitor-btn,
.admin-module .eval-monitor-export-menu > .eval-monitor-btn {
  min-height: 36px;
  min-width: 104px;
  border-radius: 10px;
  padding: 0 12px;
  font-size: 0.78rem;
}

.admin-module .eval-monitor-btn.compact {
  min-height: 32px;
  min-width: 96px;
}

.admin-module .eval-monitor-export-menu {
  position: relative;
}

.admin-module .eval-monitor-export-dropdown {
  right: 0;
  min-width: 150px;
  border-radius: 10px;
}

.admin-module .eval-monitor-export-dropdown button {
  min-height: 36px;
  font-size: 0.78rem;
}

.admin-module .eval-monitor-hero,
.hero-card.eval-monitor-hero {
  grid-template-columns: minmax(0, 1fr) minmax(260px, auto);
  gap: 14px;
  align-items: center;
  border-radius: 14px;
  padding: 16px 18px;
}

.admin-module .eval-monitor-hero.compact {
  grid-template-columns: minmax(0, 1fr);
  padding-block: 14px;
}

.admin-module .eval-monitor-hero h2 {
  margin-top: 2px;
  font-size: clamp(1.28rem, 2vw, 1.65rem);
  line-height: 1.16;
}

.admin-module .eval-monitor-hero p {
  max-width: 620px;
  margin-top: 6px;
  font-size: 0.84rem;
  line-height: 1.45;
}

.admin-module .eval-monitor-hero .eyebrow {
  margin: 0;
  font-size: 0.72rem;
}

.admin-module .eval-monitor-hero-chart {
  min-width: 0;
  gap: 12px;
}

.admin-module .eval-monitor-donut {
  width: 76px;
  height: 76px;
}

.admin-module .eval-monitor-donut::before {
  inset: 7px;
}

.admin-module .eval-monitor-donut strong {
  font-size: 1rem;
}

.admin-module .eval-monitor-donut span {
  font-size: 0.56rem;
}

.admin-module .eval-monitor-hero-stats {
  gap: 5px;
  grid-template-columns: repeat(2, minmax(0, auto));
}

.admin-module .eval-monitor-hero-stats span {
  min-height: 26px;
  padding: 4px 8px;
  font-size: 0.72rem;
}

.admin-module .eval-monitor-metrics {
  grid-template-columns: repeat(5, minmax(130px, 1fr));
  gap: 10px;
}

.admin-module .eval-monitor-metrics article {
  display: grid;
  align-content: center;
  min-height: 86px;
  border-radius: 12px;
  padding: 12px 14px;
}

.admin-module .eval-monitor-metrics span {
  font-size: 0.66rem;
  line-height: 1.2;
}

.admin-module .eval-monitor-metrics strong {
  margin: 5px 0 3px;
  font-size: 1.55rem;
}

.admin-module .eval-monitor-metrics small {
  font-size: 0.72rem;
  line-height: 1.25;
}

.admin-module .eval-monitor-table-container {
  border-radius: 14px;
}

.admin-module .eval-monitor-toolbar {
  display: grid;
  grid-template-columns: minmax(240px, 1fr) auto;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
}

.admin-module .eval-monitor-search {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr) auto;
  align-items: center;
  column-gap: 10px;
  width: 100%;
  min-width: 0;
  max-width: none;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 12px;
  background: var(--theme-surface-raised, #ffffff);
  padding: 0 12px;
}

.admin-module .eval-monitor-search input {
  min-height: 38px;
  border: 0;
  background: transparent;
  padding: 0;
}

.admin-module .eval-monitor-search:focus-within {
  border-color: var(--theme-primary, #1f7a4f);
  box-shadow: 0 0 0 3px var(--theme-focus, rgba(22, 106, 69, 0.2));
}

.admin-module .eval-monitor-search input:focus {
  box-shadow: none;
}

.eval-monitor-search .eval-monitor-search-clear {
  width: 30px;
  height: 30px;
  display: inline-grid;
  place-items: center;
  flex: 0 0 30px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: var(--theme-muted, #64748b);
  box-shadow: none;
  cursor: pointer;
  transition: color 160ms ease, background 160ms ease, border-color 160ms ease;
}

.eval-monitor-search .eval-monitor-search-clear:hover,
.eval-monitor-search .eval-monitor-search-clear:focus-visible {
  border-color: var(--theme-border, #dbe7e1);
  background: var(--theme-surface-soft, #f1f5f3);
  color: var(--theme-text, #10201b);
  outline: none;
}

/* ── Personal Performance Summary — visual dashboard polish ───────── */
.personal-performance-summary {
  --pps-accent: #159a68;
  --pps-accent-2: #2dd4bf;
  --pps-blue: #3b82f6;
  --pps-amber: #d99b18;
  position: relative;
  gap: 18px;
  padding: clamp(8px, 1.2vw, 18px);
}

.personal-performance-summary::before {
  position: absolute;
  z-index: -1;
  inset: 0;
  border-radius: 28px;
  background:
    radial-gradient(circle at 8% 4%, rgba(45, 212, 191, .11), transparent 25%),
    radial-gradient(circle at 92% 18%, rgba(59, 130, 246, .08), transparent 28%);
  content: "";
  pointer-events: none;
}

.personal-performance-summary .personal-charts-row {
  grid-template-columns: minmax(0, 880px) minmax(300px, 1fr);
  justify-content: start;
  align-items: stretch;
  gap: clamp(16px, 2vw, 24px);
  margin: 0;
}

.personal-performance-summary .personal-chart-card {
  position: relative;
  isolation: isolate;
  width: 100%;
  max-width: 880px;
  min-height: 0;
  border-color: rgba(21, 154, 104, .22);
  border-radius: 22px;
  background:
    linear-gradient(155deg, rgba(255, 255, 255, .98), rgba(245, 253, 249, .94));
  box-shadow:
    0 22px 55px rgba(19, 88, 64, .11),
    0 0 0 1px rgba(45, 212, 191, .04),
    inset 0 1px 0 rgba(255, 255, 255, .86);
  transition: transform .32s cubic-bezier(.2, .8, .2, 1), border-color .32s ease, box-shadow .32s ease;
  animation: ppsCardReveal .56s cubic-bezier(.2, .8, .2, 1) both;
}

.personal-performance-summary .personal-chart-card::after {
  position: absolute;
  z-index: -1;
  width: 240px;
  height: 240px;
  right: -110px;
  bottom: -125px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(45, 212, 191, .15), transparent 68%);
  content: "";
  transition: transform .5s ease, opacity .3s ease;
  pointer-events: none;
}

.personal-performance-summary .personal-chart-card:hover {
  border-color: rgba(21, 154, 104, .4);
  box-shadow:
    0 28px 65px rgba(19, 88, 64, .16),
    0 0 28px rgba(45, 212, 191, .11),
    inset 0 1px 0 rgba(255, 255, 255, .9);
  transform: translateY(-4px);
}

.personal-performance-summary .personal-chart-card:hover::after {
  opacity: .85;
  transform: scale(1.18);
}

.personal-performance-summary .personal-chart-head {
  min-height: 58px;
  padding: 14px 18px;
  border-color: rgba(21, 154, 104, .16);
  background:
    linear-gradient(90deg, rgba(21, 154, 104, .1), rgba(45, 212, 191, .045), transparent);
  font-size: .94rem;
  letter-spacing: .01em;
}

.personal-performance-summary .personal-chart-head svg {
  width: 32px;
  height: 32px;
  padding: 7px;
  border: 1px solid rgba(21, 154, 104, .18);
  border-radius: 10px;
  background: rgba(21, 154, 104, .1);
  filter: drop-shadow(0 5px 8px rgba(21, 154, 104, .15));
}

.personal-performance-summary .personal-chart-head small {
  padding: 5px 9px;
  border: 1px solid rgba(21, 154, 104, .14);
  border-radius: 999px;
  background: rgba(255, 255, 255, .72);
}

.personal-performance-summary .personal-chart-body {
  padding: clamp(10px, 1.2vw, 16px);
}

@media (max-width: 980px) {
  .personal-performance-summary .personal-charts-row {
    grid-template-columns: minmax(0, 1fr);
  }

  .personal-performance-summary .personal-chart-card {
    max-width: 100%;
  }
}

.personal-performance-snapshot {
  position: relative;
  isolation: isolate;
  display: grid;
  align-content: start;
  gap: 18px;
  min-width: 0;
  overflow: hidden;
  border: 1px solid rgba(59, 130, 246, .2);
  border-radius: 22px;
  background:
    radial-gradient(circle at 90% 8%, rgba(59, 130, 246, .15), transparent 31%),
    linear-gradient(150deg, rgba(248, 252, 255, .98), rgba(239, 250, 246, .96));
  padding: clamp(18px, 2vw, 26px);
  box-shadow: 0 22px 55px rgba(30, 64, 175, .1), inset 0 1px 0 rgba(255, 255, 255, .86);
  animation: ppsCardReveal .62s .12s cubic-bezier(.2, .8, .2, 1) both;
}

.personal-performance-snapshot::after {
  position: absolute;
  z-index: -1;
  width: 260px;
  height: 260px;
  right: -120px;
  bottom: -145px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(45, 212, 191, .17), transparent 68%);
  content: "";
}

.personal-performance-snapshot > header {
  display: flex;
  align-items: center;
  gap: 11px;
}

.personal-performance-snapshot > header > span {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: linear-gradient(145deg, #2563eb, #0ea5e9);
  color: #fff;
  box-shadow: 0 10px 22px rgba(37, 99, 235, .23);
}

.personal-performance-snapshot h3,
.personal-performance-snapshot small,
.personal-performance-snapshot p {
  margin: 0;
}

.personal-performance-snapshot h3 {
  color: var(--theme-text, #10201b);
  font-size: 1.05rem;
}

.personal-performance-snapshot header small,
.personal-snapshot-score small {
  color: var(--theme-muted, #64748b);
  font-size: .7rem;
  font-weight: 850;
  letter-spacing: .035em;
  text-transform: uppercase;
}

.personal-snapshot-score {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 18px;
  padding: 15px;
  border: 1px solid rgba(59, 130, 246, .12);
  border-radius: 18px;
  background: rgba(255, 255, 255, .65);
}

.personal-snapshot-ring {
  width: 98px;
  aspect-ratio: 1;
  display: grid;
  place-content: center;
  border-radius: 50%;
  background:
    radial-gradient(circle closest-side, #fff 76%, transparent 78% 99%),
    conic-gradient(#22a66f var(--snapshot-pct), #dce8f4 0);
  text-align: center;
  box-shadow: 0 10px 24px rgba(21, 154, 104, .12);
}

.personal-snapshot-ring strong {
  color: #087451;
  font-size: 1.45rem;
  line-height: 1;
}

.personal-snapshot-ring span,
.personal-snapshot-score > div:last-child > span {
  margin-top: 4px;
  color: var(--theme-muted, #64748b);
  font-size: .7rem;
  font-weight: 700;
}

.personal-snapshot-score > div:last-child {
  display: grid;
  gap: 4px;
}

.personal-snapshot-score > div:last-child > strong {
  color: var(--theme-text, #10201b);
  font-size: 1rem;
}

.personal-snapshot-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 9px;
}

.personal-snapshot-grid article {
  display: grid;
  justify-items: start;
  gap: 5px;
  min-width: 0;
  border: 1px solid rgba(21, 154, 104, .12);
  border-radius: 14px;
  background: rgba(255, 255, 255, .65);
  padding: 12px;
}

.personal-snapshot-grid svg { color: #159a68; }
.personal-snapshot-grid span { color: var(--theme-muted, #64748b); font-size: .68rem; font-weight: 750; }
.personal-snapshot-grid strong { color: var(--theme-text, #10201b); font-size: 1rem; }

.personal-performance-snapshot > p {
  padding: 12px 14px;
  border-left: 3px solid #3b82f6;
  border-radius: 0 12px 12px 0;
  background: rgba(59, 130, 246, .07);
  color: var(--theme-muted, #64748b);
  font-size: .76rem;
  line-height: 1.45;
}

:is(.admin-body.dark-mode, .admin-dashboard-body.dark-mode) .personal-performance-snapshot {
  border-color: rgba(96, 165, 250, .24);
  background:
    radial-gradient(circle at 90% 8%, rgba(59, 130, 246, .18), transparent 32%),
    linear-gradient(150deg, rgba(12, 32, 52, .98), rgba(6, 20, 35, .98));
  box-shadow: 0 22px 55px rgba(0, 0, 0, .32), 0 0 26px rgba(34, 211, 238, .06);
}

:is(.admin-body.dark-mode, .admin-dashboard-body.dark-mode) .personal-performance-snapshot h3,
