.program-ai-faculty-directory-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 2px;
}

.program-ai-faculty-directory-head span {
  display: block;
  color: #0f766e;
  font-size: 0.78rem;
  font-weight: 900;
