}

.program-ai-faculty-directory-head strong {
  display: block;
  margin-top: 2px;
  color: #1f2937;
  font-size: 1.05rem;
}

.program-ai-directory-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(72px, 1fr));
