}

.program-ai-directory-metrics > div {
  border: 1px solid rgba(15, 118, 110, 0.14);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.78);
  padding: 10px 12px;
  text-align: center;
}

.program-ai-directory-metrics strong {
  margin: 0;
