  font-size: 1.25rem;
  line-height: 1;
}

.program-ai-directory-metrics span {
  margin-top: 4px;
  color: #64748b;
  font-size: 0.7rem;
}

.program-ai-faculty-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 12px;
}

.program-ai-faculty-card {
  display: grid;
  gap: 14px;
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(15, 118, 110, 0.15);
  border-radius: 16px;
  background: #ffffff;
  padding: 16px;
  box-shadow: 0 14px 34px rgba(15, 23, 42, 0.06);
}

.program-ai-faculty-card::before {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  height: 4px;
  background: linear-gradient(90deg, #10b981, #38bdf8);
}

.program-ai-faculty-card.pending::before {
  background: linear-gradient(90deg, #f59e0b, #f97316);
}

.program-ai-faculty-card-head {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
}

.program-ai-faculty-card-head h4 {
  margin: 0;
  color: #111827;
  font-size: 0.98rem;
  line-height: 1.25;
}

