  background: rgba(245, 158, 11, 0.16);
  color: #92400e;
}

.program-ai-faculty-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.program-ai-faculty-stats > div,
.program-ai-faculty-analysis {
  border: 1px solid rgba(148, 163, 184, 0.18);
