/* ── Manage Programs Section ──────────────────────────────────────────── */
.manage-programs-section {
  display: grid;
  position: relative;
  overflow: hidden;
  gap: 14px;
  border-color: rgba(22, 131, 88, 0.16) !important;
  background:
    radial-gradient(circle at 12% 0%, rgba(34, 168, 101, 0.11), transparent 28%),
    radial-gradient(circle at 86% 10%, rgba(15, 159, 143, 0.09), transparent 30%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.98), rgba(248, 253, 250, 0.94)) !important;
  box-shadow:
    0 20px 48px rgba(15, 77, 56, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.88) !important;
}

.manage-programs-section::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(115deg, transparent 0 38%, rgba(255, 255, 255, 0.34) 48%, transparent 58% 100%);
  transform: translateX(-100%);
  animation: manageProgramsSweep 8s ease-in-out infinite;
}

@keyframes manageProgramsSweep {
  0%, 46% {
    transform: translateX(-100%);
    opacity: 0;
  }
  58% {
    opacity: 1;
  }
  74%, 100% {
    transform: translateX(100%);
    opacity: 0;
  }
}

.manage-programs-section .box-title {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 20px 20px 0;
}

.manage-programs-section .box-title h2 {
  margin: 0;
  color: var(--theme-text, #10201b);
  font-size: 1.1rem;
  font-weight: 900;
}

.manage-programs-section .box-title span {
  display: block;
  margin-top: 2px;
  color: var(--theme-muted, #4d5f57);
  font-size: 0.78rem;
  font-weight: 700;
}

.manage-programs-section .primary-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 40px;
  border: 1px solid transparent;
  border-radius: 13px;
  background:
    radial-gradient(circle at 24% 20%, rgba(255, 255, 255, 0.24), transparent 32%),
    linear-gradient(135deg, #22a865, #168358 58%, #0f766e);
  padding: 0 14px;
  color: #ffffff;
  font-size: 0.85rem;
  font-weight: 900;
  cursor: pointer;
  transition: transform 0.22s ease, box-shadow 0.22s ease, filter 0.22s ease;
  box-shadow:
    0 14px 30px rgba(22, 131, 88, 0.22),
    0 0 24px rgba(15, 159, 143, 0.14);
}

.manage-programs-section .primary-button:hover {
  transform: translateY(-2px);
  filter: saturate(1.08);
  box-shadow:
    0 18px 36px rgba(22, 131, 88, 0.3),
    0 0 0 4px rgba(22, 131, 88, 0.1);
}

.manage-programs-section .ghost-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 40px;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 12px;
  background: var(--theme-surface, #ffffff);
  padding: 0 14px;
  color: var(--theme-text, #10201b);
  font-size: 0.85rem;
  font-weight: 800;
  cursor: pointer;
  transition: all 0.2s ease;
}

.manage-programs-section .ghost-button:hover {
  border-color: color-mix(in srgb, var(--theme-primary, #166a45) 34%, var(--theme-border, #dbe7e1));
  background: var(--theme-primary-soft, #e6f6ec);
}

.manage-programs-section .danger-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 40px;
  border: 1px solid #fecaca;
  border-radius: 12px;
  background: #fef2f2;
  padding: 0 14px;
  color: #b91c1c;
  font-size: 0.85rem;
  font-weight: 800;
  cursor: pointer;
  transition: all 0.2s ease;
}

.manage-programs-section .danger-action:hover {
  background: #fee2e2;
  border-color: #fca5a5;
}

.manage-programs-section .module-empty {
  display: grid;
  place-items: center;
  gap: 6px;
  padding: 40px 20px;
  text-align: center;
  color: var(--theme-muted, #4d5f57);
}

.manage-programs-section .module-empty p {
  margin: 0;
  font-size: 0.9rem;
  font-weight: 700;
}

/* Programs Toolbar */
.programs-toolbar-actions {
  display: flex;
  gap: 8px;
  flex-shrink: 0;
}

.programs-insight-strip {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  padding: 0 20px;
}

.programs-insight-strip article {
  min-height: 76px;
  border: 1px solid rgba(22, 131, 88, 0.14);
  border-radius: 15px;
  background:
    radial-gradient(circle at 20% 15%, rgba(255, 255, 255, 0.82), transparent 38%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.9), rgba(238, 250, 244, 0.78));
  padding: 13px 15px;
  box-shadow:
    0 14px 32px rgba(15, 77, 56, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.8);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.programs-insight-strip article:hover {
  transform: translateY(-2px);
  box-shadow:
    0 18px 38px rgba(15, 77, 56, 0.13),
    0 0 0 4px rgba(22, 131, 88, 0.06);
}

.programs-insight-strip span {
  display: block;
  color: #5d7168;
  font-size: 0.72rem;
  font-weight: 900;
  text-transform: uppercase;
}

