/* Program Form */
.program-form {
  display: grid;
  gap: 16px;
  padding: 0 20px 20px;
}

.program-form-error {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 14px;
  border-radius: 12px;
  background: #fef2f2;
  border: 1px solid #fecaca;
  color: #b91c1c;
  font-size: 0.85rem;
  font-weight: 700;
}

