  flex-shrink: 0;
  color: #ef4444;
}

.program-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.program-form-grid label {
  display: grid;
  gap: 7px;
  color: var(--theme-text, #10201b);
  font-size: 0.82rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.program-form-full {
  grid-column: 1 / -1;
}

.program-form-grid input[type="text"],
.program-form-grid select {
  min-height: 44px;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 12px;
  background: var(--theme-surface, #ffffff);
  padding: 0 12px;
  color: var(--theme-text, #10201b);
  font-size: 0.9rem;
  font-weight: 700;
  outline: none;
  transition: border-color 0.2s ease;
}

.program-form-grid input[type="text"]:focus,
.program-form-grid select:focus {
  border-color: var(--theme-primary, #166a45);
  box-shadow: 0 0 0 3px rgba(22, 106, 69, 0.1);
}

.program-form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding: 18px 0 0;
  border-top: 1px solid var(--theme-border, #dbe7e1);
}

.program-form-actions button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 40px;
  border-radius: 12px;
  padding: 0 16px;
  font-size: 0.85rem;
  font-weight: 900;
  cursor: pointer;
  transition: all 0.2s ease;
}

.program-form-actions .primary-button {
  border: 1px solid transparent;
  background: linear-gradient(135deg, #123d35, #1f7a4f);
  color: #ffffff;
  box-shadow: 0 8px 20px rgba(18, 61, 53, 0.18);
}

