  transform: translateY(-1px);
  box-shadow: 0 12px 28px rgba(18, 61, 53, 0.24);
}

.program-form-actions .ghost-button {
  border: 1px solid var(--theme-border, #dbe7e1);
  background: var(--theme-surface, #ffffff);
  color: var(--theme-text, #10201b);
}

.program-form-actions .ghost-button:hover {
  border-color: var(--theme-muted, #4d5f57);
}

.program-form-actions button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

