/* Sidebar navigation consistency */
.admin-body .admin-sidebar {
  --sidebar-bg: var(--ui-surface, #ffffff);
  --sidebar-bg-soft: var(--ui-surface-soft, #f8faf9);
  --sidebar-border: var(--ui-border, #dce6e1);
  --sidebar-text: var(--ui-muted, #53645e);
  --sidebar-text-strong: var(--ui-text, #17231f);
  --sidebar-active: var(--ui-primary, #176447);
  --sidebar-active-strong: var(--ui-primary-strong, #0f4d38);
  --sidebar-active-bg: color-mix(in srgb, var(--ui-primary, #176447) 11%, transparent);
  --sidebar-hover-bg: color-mix(in srgb, var(--ui-primary, #176447) 8%, transparent);
  --sidebar-danger: #b42318;
  border-right: 1px solid var(--sidebar-border) !important;
  background: var(--sidebar-bg) !important;
  color: var(--sidebar-text-strong);
}

.admin-body.dark-mode .admin-sidebar {
  --sidebar-bg: #0d1f18;
  --sidebar-bg-soft: #132b22;
  --sidebar-border: rgba(74, 222, 128, 0.22);
  --sidebar-text: #bdd8c8;
  --sidebar-text-strong: #f4fff8;
  --sidebar-active: #86efac;
  --sidebar-active-strong: #bbf7d0;
  --sidebar-active-bg: rgba(34, 197, 94, 0.16);
  --sidebar-hover-bg: rgba(134, 239, 172, 0.1);
  --sidebar-danger: #fca5a5;
  background: #0d1f18 !important;
  box-shadow: none !important;
}

.admin-body .sidebar-brand {
  border-bottom-color: var(--sidebar-border);
}

.admin-body .sidebar-menu,
.admin-body .sidebar-bottom {
  display: grid;
  gap: 8px;
}

.admin-body .sidebar-menu {
  padding: 14px 12px;
}

.admin-body .sidebar-bottom {
  margin-top: auto;
  border-top: 1px solid var(--sidebar-border);
  padding: 12px;
}

.admin-body .sidebar-menu a,
.admin-body .sidebar-logout,
.admin-body .dark-mode-switch {
  position: relative;
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-height: 46px;
  width: 100%;
  border: 1px solid transparent !important;
  border-radius: 12px;
  background: transparent !important;
  background-image: none !important;
  box-shadow: none !important;
  padding: 6px 10px;
  color: var(--sidebar-text) !important;
  font-size: 0.92rem;
  font-weight: 800;
  text-align: left;
  text-decoration: none;
  line-height: 1.2;
  transition: background-color 160ms ease, border-color 160ms ease, color 160ms ease, transform 160ms ease;
}

.admin-body .sidebar-menu a::before,
.admin-body .sidebar-logout::before,
.admin-body .dark-mode-switch::before {
  content: "";
  position: absolute;
  left: 7px;
  top: 50%;
  bottom: auto;
  width: 3px;
  height: 26px;
  border-radius: 999px;
  background: transparent;
  transform: translateY(-50%);
  transition: background-color 160ms ease;
}

.admin-body .sidebar-menu a:hover,
.admin-body .sidebar-logout:hover,
.admin-body .dark-mode-switch:hover {
  border-color: var(--sidebar-border) !important;
  background: var(--sidebar-hover-bg) !important;
  color: var(--sidebar-active-strong) !important;
  transform: translateX(1px);
}

.admin-body .sidebar-menu a.active {
  border-left: 1px solid transparent !important;
  border-color: color-mix(in srgb, var(--sidebar-active) 34%, var(--sidebar-border)) !important;
  background: var(--sidebar-active-bg) !important;
  color: var(--sidebar-active-strong) !important;
}

.admin-body .sidebar-menu a.active::before {
  background: #168358;
}

.admin-body .sidebar-logout:hover {
  border-color: color-mix(in srgb, var(--sidebar-danger) 24%, var(--sidebar-border)) !important;
  background: color-mix(in srgb, var(--sidebar-danger) 9%, transparent) !important;
  color: var(--sidebar-danger) !important;
}

.admin-body .menu-icon {
  display: inline-grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border: 1px solid var(--sidebar-border);
  border-radius: 10px;
  background: var(--sidebar-bg-soft) !important;
  color: currentColor !important;
  flex: 0 0 34px;
}

.admin-body .menu-icon svg {
  display: block;
  width: 18px;
  height: 18px;
  stroke: currentColor;
}

.admin-body .sidebar-menu a.active .menu-icon {
  border-color: color-mix(in srgb, var(--sidebar-active) 42%, var(--sidebar-border));
  background: color-mix(in srgb, var(--sidebar-active) 14%, var(--sidebar-bg-soft)) !important;
  color: var(--sidebar-active-strong) !important;
}

.admin-body .sidebar-item-label {
  min-width: 0;
  overflow: hidden;
  color: inherit !important;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-body .dark-mode-switch .auto-badge {
  margin-left: 0;
  border: 1px solid color-mix(in srgb, var(--sidebar-active) 28%, var(--sidebar-border));
  background: color-mix(in srgb, var(--sidebar-active) 12%, transparent);
  color: var(--sidebar-active-strong);
}

.admin-body .dark-mode-switch .dark-mode-input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.admin-body .dark-mode-switch .toggle-track {
  position: relative;
  justify-self: end;
  width: 38px;
  height: 22px;
  border: 1px solid color-mix(in srgb, var(--sidebar-active) 24%, var(--sidebar-border));
  border-radius: 999px;
  background: var(--sidebar-bg-soft);
}

.admin-body .dark-mode-switch .toggle-track::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 3px;
  width: 16px;
  height: 16px;
  border-radius: 999px;
  background: var(--sidebar-text);
  transform: translateY(-50%);
  transition: transform 160ms ease, background-color 160ms ease;
}

.admin-body .dark-mode-switch .dark-mode-input:checked + .toggle-track::before {
  background: var(--sidebar-active);
  transform: translate(16px, -50%);
}

.admin-body.sidebar-collapsed .sidebar-brand-copy,
.admin-body.sidebar-collapsed .sidebar-item-label,
.admin-body.sidebar-collapsed .auto-badge {
  display: none;
}

.admin-body.sidebar-collapsed .sidebar-menu,
.admin-body.sidebar-collapsed .sidebar-bottom {
  padding-inline: 8px;
}

.admin-body.sidebar-collapsed .sidebar-menu a,
.admin-body.sidebar-collapsed .sidebar-logout,
.admin-body.sidebar-collapsed .dark-mode-switch {
  grid-template-columns: 40px;
  justify-content: center;
  padding: 6px;
}

.admin-body.sidebar-collapsed .dark-mode-switch .menu-icon {
  display: none;
}

.admin-body.sidebar-collapsed .dark-mode-switch .toggle-track {
  justify-self: center;
}

/* In icon-only mode the active icon is the indicator; hide the side bar. */
@media (min-width: 1121px) {
  .admin-body.sidebar-collapsed .sidebar-menu a.active::before {
    display: none;
  }

  .admin-body.sidebar-collapsed .sidebar-menu a.active {
    border-color: transparent !important;
