  }

  .admin-body:not(.sidebar-open) .sidebar-menu a.active {
    border-color: transparent !important;
    background: transparent !important;
    box-shadow: none !important;
  }

  .admin-body:not(.sidebar-open) .sidebar-menu a.active .menu-icon {
    border-color: #168358 !important;
