/* Login viewport fit: keeps the portal usable when the browser is zoomed or the screen is short. */
.login-page {
  min-height: 100dvh;
  align-items: center;
  overflow: hidden;
  padding: clamp(10px, 2.2vh, 24px) clamp(12px, 3vw, 28px);
}

.login-shell {
  width: min(100%, 720px);
  max-height: calc(100dvh - clamp(20px, 4.4vh, 48px));
  overflow: visible;
}

.login-card {
  width: 100%;
  max-height: calc(100dvh - clamp(20px, 4.4vh, 48px));
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
  padding:
    clamp(20px, 4.2vh, 56px)
    clamp(18px, 4.4vw, 62px)
    clamp(18px, 3.6vh, 42px);
}

.login-card-brand {
  gap: clamp(8px, 1.3vh, 14px);
  margin-bottom: clamp(10px, 1.8vh, 20px);
}

.login-card-brand img {
  width: clamp(58px, 8.4vh, 86px);
  height: clamp(58px, 8.4vh, 86px);
}

.login-security-chip {
  min-height: clamp(34px, 4.8vh, 46px);
  padding: 0 clamp(14px, 2.4vw, 24px);
  font-size: clamp(0.78rem, 1.75vh, 0.95rem);
}

.login-card h1 {
  margin-block: clamp(16px, 3vh, 34px) clamp(10px, 1.8vh, 18px);
  font-size: clamp(2.15rem, 6.4vh, 4.1rem);
  line-height: 0.96;
}

.login-subtitle {
  max-width: 100%;
  font-size: clamp(0.98rem, 2.25vh, 1.38rem);
  line-height: 1.42;
}

.login-welcome {
  margin-top: clamp(12px, 2vh, 22px);
  font-size: clamp(0.98rem, 2.15vh, 1.2rem);
  line-height: 1.38;
}

.login-card .form {
  gap: clamp(11px, 1.8vh, 18px);
  margin-top: clamp(16px, 2.8vh, 30px);
}

.login-card label {
  gap: 7px;
  font-size: clamp(0.92rem, 1.9vh, 1.1rem);
}

.login-input-wrap {
  min-height: clamp(48px, 7vh, 68px);
  border-radius: clamp(14px, 2vh, 20px);
  padding-inline: clamp(14px, 2.4vw, 22px);
}

.login-card .login-input-wrap input {
  font-size: clamp(0.98rem, 2.25vh, 1.28rem);
}

.login-options {
  gap: 10px;
  margin-top: clamp(2px, 0.8vh, 8px);
  font-size: clamp(0.88rem, 1.9vh, 1.04rem);
}

.login-card button[type="submit"] {
  min-height: clamp(48px, 7vh, 64px);
  margin-top: clamp(8px, 1.5vh, 16px);
  border-radius: clamp(14px, 2vh, 20px);
  font-size: clamp(0.98rem, 2.15vh, 1.16rem);
}

@media (max-height: 760px) and (min-width: 641px) {
  .login-card {
    padding-block: 18px;
  }

  .login-card-brand span,
  .login-subtitle {
    font-size: 0.95rem;
  }

  .login-card h1 {
    margin-block: 12px 8px;
    font-size: 2.65rem;
  }

  .login-welcome {
    margin-top: 8px;
    font-size: 0.98rem;
  }
}

@media (max-width: 640px) {
  .login-page {
    overflow-y: auto;
  }

  .login-shell,
  .login-card {
    max-height: none;
  }

  .login-card {
    overflow: visible;
  }
}

