  min-height: 180px;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 18px;
  background: var(--theme-surface, #ffffff);
  padding: 18px;
  box-shadow: 0 14px 30px rgba(15, 23, 42, 0.06);
}

.faculty-insight-card.recommendations {
  grid-column: span 1;
}

.faculty-insight-head {
  display: flex;
  align-items: center;
  gap: 10px;
}

.faculty-insight-head > svg {
  flex: 0 0 auto;
  color: var(--theme-primary, #2563eb);
}

.faculty-insight-head span {
  display: block;
  color: var(--theme-muted, #64748b);
  font-size: 0.72rem;
  font-weight: 900;
  text-transform: uppercase;
}

.faculty-insight-head strong {
  display: block;
  color: var(--theme-text, #10201b);
  font-size: 0.98rem;
}

.faculty-insight-row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  border-radius: 12px;
  background: var(--theme-surface-soft, #f8fafc);
  padding: 10px 12px;
}

.faculty-insight-row span,
.faculty-recommendation-row p {
  color: var(--theme-muted, #64748b);
}

.faculty-insight-row strong {
  white-space: nowrap;
}

.faculty-recommendation-row {
  display: flex;
  gap: 10px;
  border-radius: 14px;
  background: var(--theme-surface-soft, #f8fafc);
  padding: 12px;
}

.faculty-recommendation-row svg {
  flex: 0 0 auto;
  color: var(--theme-primary, #2563eb);
  margin-top: 2px;
}

.faculty-recommendation-row strong {
  display: block;
  margin-bottom: 4px;
  font-size: 0.92rem;
}

.faculty-recommendation-row p {
  margin: 0;
  font-size: 0.84rem;
  line-height: 1.45;
}

.admin-body.dark-mode .faculty-results-locked {
  border-color: rgba(251, 191, 36, 0.34);
  background: rgba(120, 53, 15, 0.22);
}

.admin-body.dark-mode .faculty-insight-card {
  border-color: rgba(96, 165, 250, 0.18);
  background: rgba(15, 23, 42, 0.72);
  box-shadow: 0 16px 34px rgba(0, 0, 0, 0.18);
}

.admin-body.dark-mode .faculty-insight-row,
.admin-body.dark-mode .faculty-recommendation-row {
  background: rgba(30, 41, 59, 0.72);
}

@media (max-width: 1180px) {
  .faculty-ai-insights {
    grid-template-columns: 1fr;
  }
}

/* Login compact desktop presentation */
@media (min-width: 641px) {
  .login-page {
    padding: clamp(18px, 3vh, 32px);
  }

  .login-shell {
    width: min(100%, 576px);
  }

  .login-card {
    max-height: calc(100dvh - clamp(36px, 6vh, 64px));
    padding: clamp(30px, 4vh, 44px) 50px clamp(26px, 3.4vh, 34px);
  }

  .login-card-brand {
    margin-bottom: 14px;
  }

  .login-card-brand img {
    width: 64px;
    height: 64px;
  }

  .login-card-brand span {
    font-size: 0.72rem;
  }

  .login-security-chip {
    min-height: 38px;
    padding-inline: 18px;
    font-size: 0.82rem;
  }

  .login-card h1 {
    margin-block: 24px 16px;
    font-size: 3.05rem;
    line-height: 1;
  }

  .login-subtitle {
    font-size: 1.04rem;
    line-height: 1.42;
  }

  .login-welcome {
    margin-top: 18px;
    font-size: 0.96rem;
    line-height: 1.4;
  }

  .login-card .form {
    gap: 14px;
    margin-top: 24px;
  }

  .login-card label {
    font-size: 0.9rem;
  }

  .login-input-wrap {
    min-height: 54px;
    border-radius: 15px;
    padding-inline: 18px;
  }

  .login-card .login-input-wrap input {
    font-size: 1rem;
  }

  .login-options {
    margin-top: 2px;
    font-size: 0.9rem;
  }

  .login-card button[type="submit"] {
    min-height: 52px;
    margin-top: 10px;
    border-radius: 15px;
    font-size: 0.96rem;
  }
}

@media (min-width: 641px) and (max-height: 820px) {
  .login-card {
    padding-block: 24px;
  }

  .login-card-brand img {
    width: 56px;
    height: 56px;
  }

  .login-card h1 {
    margin-block: 16px 10px;
    font-size: 2.65rem;
  }

  .login-subtitle,
  .login-welcome {
    font-size: 0.92rem;
  }

  .login-card .form {
    gap: 11px;
    margin-top: 18px;
  }

  .login-input-wrap {
    min-height: 48px;
  }

  .login-card button[type="submit"] {
    min-height: 48px;
  }
}

