.floating-chat-toggle {
  isolation: isolate;
  transition:
    transform 180ms ease,
    box-shadow 180ms ease,
    border-color 180ms ease;
}

.floating-chat-toggle::before,
.floating-chat-toggle::after {
  content: "";
  position: absolute;
  inset: -7px;
  z-index: -1;
  border-radius: 26px;
  pointer-events: none;
}

.floating-chat-toggle::before {
  border: 1px solid rgba(96, 165, 250, 0.36);
  animation: chatbotOrbitGlow 3.2s ease-in-out infinite;
}

.floating-chat-toggle::after {
  inset: 7px;
  border-radius: 18px;
  background:
    radial-gradient(circle at 30% 24%, rgba(255, 255, 255, 0.46), transparent 18%),
    radial-gradient(circle at 74% 76%, rgba(125, 211, 252, 0.32), transparent 22%);
  mix-blend-mode: screen;
  opacity: 0.72;
}

.floating-chat-toggle:hover {
  transform: translateY(-3px) scale(1.04);
}

.floating-chat-toggle:hover .floating-chat-logo {
  transform: scale(1.2) rotate(-3deg);
}

.floating-chat-logo {
  transition:
    transform 180ms ease,
    filter 180ms ease;
}

.admin-body .floating-chat-toggle,
.admin-dashboard-body .floating-chat-toggle {
  border-color: rgba(96, 165, 250, 0.5) !important;
  background:
    radial-gradient(circle at 42% 28%, rgba(255, 255, 255, 0.34), transparent 38%),
    linear-gradient(135deg, #1d4ed8, #2563eb 54%, #0891b2) !important;
  box-shadow:
    0 18px 42px rgba(37, 99, 235, 0.32),
    0 0 0 8px rgba(37, 99, 235, 0.08) !important;
}

