  background:
    radial-gradient(circle at 42% 28%, rgba(191, 219, 254, 0.28), transparent 38%),
    linear-gradient(135deg, #0b1f45, #1d4ed8 52%, #0e7490) !important;
  box-shadow:
    0 20px 44px rgba(4, 14, 31, 0.52),
    0 0 0 8px rgba(59, 130, 246, 0.1) !important;
}

.admin-body.dark-mode .floating-chat-logo,
.admin-dashboard-body.dark-mode .floating-chat-logo,
