  filter: brightness(1.28) contrast(1.08) saturate(1.04) drop-shadow(0 8px 14px rgba(96, 165, 250, 0.28)) !important;
}

@keyframes chatbotOrbitGlow {
  0%,
  100% {
    opacity: 0.42;
    transform: scale(0.95) rotate(0deg);
  }

  50% {
    opacity: 0.86;
    transform: scale(1.08) rotate(8deg);
  }
}

