/* Topbar polish: cleaner search/actions cluster */
.admin-header {
  gap: clamp(14px, 2vw, 24px);
  min-height: 78px;
}

.admin-search {
  flex: 1 1 420px;
  max-width: 560px;
}

.admin-search label {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

.admin-search .relative {
  position: relative;
  display: flex;
  align-items: center;
}

.admin-search .relative svg {
  left: 16px !important;
  width: 18px !important;
  height: 18px !important;
  color: #8fb2e3 !important;
  opacity: 0.9;
  transition: color 180ms ease, opacity 180ms ease, transform 180ms ease;
}

.admin-search input,
.admin-body .admin-search input,
.admin-dashboard-body .admin-search input {
  width: 100%;
  min-height: 52px;
  border-radius: 18px;
  border: 1px solid rgba(132, 178, 239, 0.28);
  background:
    linear-gradient(135deg, rgba(17, 31, 55, 0.82), rgba(10, 22, 42, 0.72));
  color: #e6eefb;
  padding: 0 18px 0 48px !important;
  font-size: 0.98rem;
  font-weight: 650;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.04),
    0 10px 24px rgba(3, 10, 24, 0.16);
  transition:
    border-color 180ms ease,
    background 180ms ease,
    box-shadow 180ms ease,
    transform 180ms ease;
}

.admin-search input::placeholder,
.admin-body .admin-search input::placeholder,
.admin-dashboard-body .admin-search input::placeholder {
  color: #9fb5d3;
  opacity: 0.88;
}

.admin-search .relative:focus-within svg {
  color: #bfdbfe !important;
  opacity: 1;
  transform: translateY(-50%) scale(1.05) !important;
}

.admin-search input:focus,
.admin-body .admin-search input:focus,
.admin-dashboard-body .admin-search input:focus {
  border-color: rgba(147, 197, 253, 0.72) !important;
  background:
    radial-gradient(circle at 10% 50%, rgba(96, 165, 250, 0.16), transparent 32%),
    linear-gradient(135deg, rgba(19, 38, 70, 0.94), rgba(11, 24, 47, 0.92)) !important;
  box-shadow:
    0 0 0 4px rgba(96, 165, 250, 0.13),
    0 16px 34px rgba(3, 10, 24, 0.22) !important;
}

.admin-actions {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
}

.admin-actions .dean-header-context,
.admin-actions .role-context {
  min-height: 52px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 18px;
  border: 1px solid rgba(132, 178, 239, 0.28);
  background:
    radial-gradient(circle at 20% 15%, rgba(147, 197, 253, 0.14), transparent 34%),
    linear-gradient(135deg, rgba(30, 48, 82, 0.9), rgba(17, 31, 55, 0.84));
  color: #dce8f7;
  padding: 0 18px;
  font-size: 0.94rem;
  font-weight: 900;
  white-space: nowrap;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.05),
    0 12px 28px rgba(3, 10, 24, 0.16);
}

.notification-center,
.account-menu {
  position: relative;
}

.notification-button {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: 52px;
  height: 52px;
  min-height: 52px;
  border-radius: 18px;
  border: 1px solid rgba(132, 178, 239, 0.34);
  background:
    radial-gradient(circle at 30% 20%, rgba(219, 234, 254, 0.24), transparent 34%),
