}

.notification-button .notification-bell-icon {
  width: 34px !important;
  height: 34px !important;
  stroke-width: 2.35;
}

.notification-button.has-new::after {
  content: "";
  position: absolute;
  top: 10px;
  right: 10px;
  width: 9px;
  height: 9px;
  border: 2px solid #315fa7;
  border-radius: 999px;
  background: #bfdbfe;
