}

.profile-button.account-menu-trigger {
  display: inline-grid;
  place-items: center;
  width: 58px;
  height: 58px;
  min-height: 58px;
  padding: 0;
  border-radius: 20px;
  border: 1px solid rgba(147, 197, 253, 0.42);
  background:
    linear-gradient(135deg, rgba(96, 165, 250, 0.18), rgba(13, 25, 46, 0.88));
  box-shadow:
    0 16px 34px rgba(3, 10, 24, 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
