  object-fit: cover;
}

.admin-body.dark-mode .admin-header,
.admin-dashboard-body.dark-mode .admin-header,
body:has(.admin-dashboard-body.dark-mode) .admin-header {
  border-color: rgba(132, 178, 239, 0.18) !important;
  background:
    radial-gradient(circle at 18% 0%, rgba(79, 142, 232, 0.18), transparent 34%),
    linear-gradient(135deg, rgba(11, 23, 43, 0.94), rgba(8, 17, 31, 0.9)) !important;
  box-shadow: 0 18px 42px rgba(3, 10, 24, 0.22);
}

.admin-body.dark-mode .admin-actions .dean-header-context,
.admin-body.dark-mode .admin-actions .role-context,
.admin-dashboard-body.dark-mode .admin-actions .dean-header-context,
.admin-dashboard-body.dark-mode .admin-actions .role-context,
body:has(.admin-dashboard-body.dark-mode) .admin-actions .dean-header-context,
body:has(.admin-dashboard-body.dark-mode) .admin-actions .role-context {
  border-color: rgba(132, 178, 239, 0.3) !important;
