/* Department profile hero: professional logo, typography, and smooth interaction */
.dept-profile-header {
  isolation: isolate;
  min-height: clamp(290px, 25vw, 360px);
  padding: clamp(24px, 3vw, 38px);
  border-radius: 26px;
  border: 1px solid rgba(132, 178, 239, 0.24) !important;
  background:
    linear-gradient(90deg, rgba(8, 17, 31, 0.94) 0%, rgba(12, 29, 55, 0.82) 46%, rgba(10, 23, 43, 0.76) 100%),
    url('/assets/images/pmas-campus-bg.jpg') !important;
  background-position: center !important;
  background-size: cover !important;
  box-shadow:
    0 26px 70px rgba(3, 10, 24, 0.3),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.dept-profile-header::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: inherit;
  background:
    radial-gradient(circle at 10% 24%, rgba(96, 165, 250, 0.24), transparent 30%),
    radial-gradient(circle at 72% 20%, rgba(14, 116, 144, 0.16), transparent 32%),
    linear-gradient(90deg, rgba(147, 197, 253, 0.09) 1px, transparent 1px),
    linear-gradient(0deg, rgba(147, 197, 253, 0.07) 1px, transparent 1px);
  background-size: auto, auto, 84px 84px, 84px 84px;
  opacity: 0.72;
}

.dept-profile-header::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: inherit;
  background: linear-gradient(115deg, transparent 0 28%, rgba(191, 219, 254, 0.09) 42%, transparent 56% 100%);
  transform: translateX(-58%);
  animation: deptHeroSheen 7.5s ease-in-out infinite;
  pointer-events: none;
}

.dept-profile-header .back-button,
.dept-header-content {
  position: relative;
  z-index: 2;
}

.dept-profile-header .back-button {
  min-height: 50px;
  padding: 0 18px;
  border-radius: 16px;
  border-color: rgba(147, 197, 253, 0.36);
  background:
    radial-gradient(circle at 24% 20%, rgba(255, 255, 255, 0.2), transparent 36%),
    linear-gradient(135deg, #315fa7, #4f8ee8);
  color: #f1f7ff;
  font-size: 0.94rem;
  font-weight: 900;
  box-shadow:
    0 16px 32px rgba(37, 99, 235, 0.26),
    inset 0 1px 0 rgba(255, 255, 255, 0.16);
}

.dept-profile-header .back-button:hover {
  border-color: rgba(191, 219, 254, 0.68);
  background: linear-gradient(135deg, #2563eb, #60a5fa);
  color: #ffffff;
  transform: translateY(-2px);
  box-shadow:
    0 20px 38px rgba(37, 99, 235, 0.32),
    0 0 0 5px rgba(96, 165, 250, 0.12);
}

.dept-header-content {
  grid-template-columns: clamp(150px, 13vw, 210px) minmax(0, 1fr);
  gap: clamp(24px, 3.4vw, 42px);
  max-width: 1120px;
  padding-top: clamp(44px, 5vw, 60px);
}

.dept-header-logo {
  position: relative;
  width: clamp(150px, 13vw, 210px);
  height: clamp(150px, 13vw, 210px);
  padding: clamp(16px, 1.7vw, 24px);
  overflow: visible;
  border-radius: 34px;
  border: 1px solid rgba(219, 234, 254, 0.68) !important;
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.96), rgba(226, 238, 255, 0.92)) !important;
  box-shadow:
    0 24px 56px rgba(3, 10, 24, 0.36),
    0 0 0 10px rgba(96, 165, 250, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.95);
  transform-origin: center;
  animation: deptLogoFloat 5.8s ease-in-out infinite;
  transition:
    transform 240ms ease,
    box-shadow 240ms ease,
    border-color 240ms ease;
}

.dept-header-logo::before,
.dept-header-logo::after {
  content: "";
  position: absolute;
  border-radius: inherit;
  pointer-events: none;
}

.dept-header-logo::before {
  inset: -10px;
  z-index: -1;
  border: 1px solid rgba(147, 197, 253, 0.3);
  background: radial-gradient(circle at 50% 50%, rgba(96, 165, 250, 0.16), transparent 66%);
  animation: deptLogoPulse 4.2s ease-in-out infinite;
}

.dept-header-logo::after {
  inset: 10px;
  border-radius: 24px;
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.4), transparent 42%);
  opacity: 0.55;
  mix-blend-mode: screen;
}

.dept-header-logo:hover {
  transform: translateY(-7px) scale(1.025) rotate(-1.4deg);
  border-color: rgba(191, 219, 254, 0.9) !important;
  box-shadow:
    0 30px 68px rgba(3, 10, 24, 0.42),
    0 0 0 12px rgba(96, 165, 250, 0.1),
    0 0 36px rgba(96, 165, 250, 0.18),
    inset 0 1px 0 rgba(255, 255, 255, 0.96);
}

.dept-header-logo img {
  position: relative;
  z-index: 1;
  width: 100%;
  height: 100%;
  object-fit: contain;
  filter:
    saturate(0.92)
    contrast(1.02)
    drop-shadow(0 12px 18px rgba(3, 10, 24, 0.16));
  transition:
    transform 260ms cubic-bezier(0.16, 1, 0.3, 1),
    filter 220ms ease;
}

.dept-header-logo:hover img {
  transform: scale(1.05) rotate(1.5deg);
  filter:
    saturate(0.98)
    contrast(1.04)
    drop-shadow(0 14px 20px rgba(3, 10, 24, 0.2));
}

.dept-header-info {
  max-width: 860px;
  animation: deptTextRise 520ms ease-out both;
}

.dept-header-info .eyebrow {
  display: inline-flex;
  min-height: 34px;
  align-items: center;
  border: 1px solid rgba(147, 197, 253, 0.34);
  border-radius: 999px;
  background: rgba(96, 165, 250, 0.13);
  color: #bfdbfe !important;
  padding: 0 14px;
  font-size: 0.78rem;
  font-weight: 950;
  letter-spacing: 0.12em;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.dept-header-info h1 {
  max-width: min(820px, 100%);
  color: #eef6ff !important;
  font-size: clamp(2.35rem, 5.2vw, 5rem);
  font-weight: 950;
  line-height: 0.98;
  letter-spacing: 0;
  margin: 18px 0 16px;
  text-wrap: balance;
  text-shadow:
    0 2px 0 rgba(255, 255, 255, 0.03),
    0 18px 38px rgba(3, 10, 24, 0.36);
}

.dept-description {
  display: inline-flex;
  min-height: 36px;
  align-items: center;
  gap: 8px;
  border-radius: 999px;
  background: rgba(8, 17, 31, 0.32);
  color: #d4e4f7 !important;
  padding: 0 14px;
  font-size: clamp(0.92rem, 1.2vw, 1.08rem);
  font-weight: 850;
  box-shadow: inset 0 0 0 1px rgba(147, 197, 253, 0.12);
}

.admin-body.dark-mode .dept-profile-header,
.admin-dashboard-body.dark-mode .dept-profile-header,
body:has(.admin-dashboard-body.dark-mode) .dept-profile-header {
  background:
    linear-gradient(90deg, rgba(8, 17, 31, 0.94) 0%, rgba(12, 29, 55, 0.84) 46%, rgba(10, 23, 43, 0.78) 100%),
    url('/assets/images/pmas-campus-bg.jpg') !important;
  border-color: rgba(132, 178, 239, 0.26) !important;
}

.admin-body.dark-mode .dept-header-logo,
.admin-dashboard-body.dark-mode .dept-header-logo,
body:has(.admin-dashboard-body.dark-mode) .dept-header-logo {
  background: linear-gradient(145deg, rgba(248, 250, 252, 0.94), rgba(219, 234, 254, 0.9)) !important;
  border-color: rgba(191, 219, 254, 0.7) !important;
}

@keyframes deptLogoFloat {
  0%,
  100% {
    transform: translateY(0) rotate(0deg);
  }

  50% {
    transform: translateY(-8px) rotate(-0.8deg);
  }
}

@keyframes deptLogoPulse {
  0%,
  100% {
    opacity: 0.48;
    transform: scale(0.96);
  }

  50% {
    opacity: 0.86;
    transform: scale(1.04);
  }
}

@keyframes deptHeroSheen {
  0%,
  24% {
    transform: translateX(-58%);
    opacity: 0;
  }

  46% {
    opacity: 0.58;
  }

  72%,
  100% {
    transform: translateX(62%);
    opacity: 0;
  }
}

@keyframes deptTextRise {
  from {
    opacity: 0;
    transform: translateY(14px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 720px) {
  .dept-profile-header {
    min-height: auto;
    padding: 22px;
  }

  .dept-header-content {
    grid-template-columns: 1fr;
    justify-items: start;
    padding-top: 58px;
  }

  .dept-header-logo {
    width: 132px;
    height: 132px;
    border-radius: 28px;
  }

  .dept-header-info h1 {
    font-size: clamp(2rem, 11vw, 3.2rem);
  }

  .dept-description {
    border-radius: 16px;
    padding: 8px 12px;
    min-height: auto;
  }
}

@media (prefers-reduced-motion: reduce) {
  .dept-profile-header::after,
  .dept-header-logo,
  .dept-header-logo::before,
  .dept-header-info {
    animation: none !important;
  }
}

