}

.dept-profile-person-card .person-status {
  display: grid;
  justify-items: end;
  gap: 10px;
  min-width: 112px;
}

.rating-view-button {
  display: inline-flex;
  min-height: 38px;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid rgba(147, 197, 253, 0.36);
  border-radius: 13px;
  background:
    radial-gradient(circle at 24% 20%, rgba(255, 255, 255, 0.15), transparent 36%),
    linear-gradient(135deg, #254d8b, #4f8ee8);
  color: #f1f7ff;
  padding: 0 13px;
  font-size: 0.76rem;
  font-weight: 950;
  white-space: nowrap;
  cursor: pointer;
  box-shadow:
    0 12px 24px rgba(37, 99, 235, 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.1);
  transition:
    transform 180ms ease,
    box-shadow 180ms ease,
    border-color 180ms ease,
    background 180ms ease;
}

.rating-view-button:hover {
  transform: translateY(-1px);
  border-color: rgba(191, 219, 254, 0.66);
  background: linear-gradient(135deg, #2563eb, #60a5fa);
  box-shadow:
    0 16px 30px rgba(37, 99, 235, 0.3),
    0 0 0 4px rgba(96, 165, 250, 0.11);
}

.dept-dean-showcase {
  width: min(520px, calc(100% - 40px));
  margin: 20px;
  border-radius: 22px;
  border: 1px solid rgba(132, 178, 239, 0.2) !important;
  background:
    linear-gradient(145deg, rgba(30, 48, 82, 0.92), rgba(17, 31, 55, 0.88)) !important;
  box-shadow: 0 18px 42px rgba(3, 10, 24, 0.18);
}

.dept-dean-cover {
  border-radius: 20px 20px 0 0;
}

.dept-dean-profile-row {
  grid-template-columns: 54px minmax(0, 1fr) auto auto;
  gap: 12px;
  border-radius: 16px;
  background: rgba(8, 17, 31, 0.36) !important;
}

@media (max-width: 900px) {
  .dept-profile-grid {
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    padding: 16px;
  }

  .dept-profile-person-card {
    grid-template-columns: 50px minmax(0, 1fr);
  }

  .dept-profile-person-card .person-status {
    grid-column: 1 / -1;
    grid-template-columns: auto 1fr;
    justify-items: stretch;
    align-items: center;
    min-width: 0;
  }

  .rating-view-button.compact {
    width: 100%;
  }

  .dept-dean-profile-row {
    grid-template-columns: 50px minmax(0, 1fr);
  }

  .dept-dean-profile-row .status-badge,
  .dept-dean-profile-row .rating-view-button {
    grid-column: 1 / -1;
    width: 100%;
  }
}

