@keyframes monitorRise {
  from {
    opacity: 0;
    transform: translateY(10px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes monitorCardIn {
  from {
    opacity: 0;
    transform: translateY(12px) scale(0.985);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes monitorFloat {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-5px);
  }
}

@keyframes monitorSheen {
  0%,
  26% {
    opacity: 0;
    transform: translateX(-62%);
  }

  50% {
    opacity: 0.62;
  }

  78%,
  100% {
    opacity: 0;
    transform: translateX(62%);
  }
}

@media (prefers-reduced-motion: reduce) {
  .eval-monitor-hero,
  .eval-monitor-hero::after,
  .eval-monitor-hero-chart,
  .eval-monitor-metrics article,
  .eval-monitor-dept-card {
    animation: none !important;
  }
}

