/* Evaluation monitor hero summary widget */
.eval-monitor-hero-chart {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(180px, 1fr);
  align-items: center;
  gap: 18px;
  min-width: min(380px, 100%);
  padding: 16px;
  border: 1px solid rgba(96, 165, 250, 0.18);
  border-radius: 24px;
  background:
    radial-gradient(circle at 12% 10%, rgba(96, 165, 250, 0.18), transparent 34%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.86), rgba(239, 246, 255, 0.72));
  box-shadow:
    0 18px 42px rgba(37, 99, 235, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.72);
}

.eval-monitor-hero-chart::before {
  content: "";
  position: absolute;
  inset: -1px;
  z-index: -1;
  border-radius: inherit;
  background: linear-gradient(135deg, rgba(96, 165, 250, 0.32), transparent 42%, rgba(147, 197, 253, 0.22));
  opacity: 0.45;
  filter: blur(12px);
}

.eval-monitor-donut {
  position: relative;
  width: 108px;
  height: 108px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  background:
    conic-gradient(#60a5fa 0% var(--pct, 0%), rgba(148, 163, 184, 0.18) var(--pct, 0%) 100%) !important;
  box-shadow:
    0 16px 34px rgba(37, 99, 235, 0.18),
