/* Department directory cards: premium glow and motion */
.people-department-grid {
  grid-template-columns: repeat(auto-fit, minmax(270px, 1fr));
  gap: 18px;
  padding: 18px;
}

.people-department-card {
  position: relative;
  isolation: isolate;
  min-height: 100%;
  border-radius: 22px !important;
  border: 1px solid rgba(96, 165, 250, 0.18) !important;
  background:
    radial-gradient(circle at 12% 0%, rgba(96, 165, 250, 0.12), transparent 32%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.98), rgba(239, 246, 255, 0.94)) !important;
  box-shadow:
    0 16px 38px rgba(15, 23, 42, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
  transform: translateZ(0);
  animation: deptCardRise 440ms ease-out both;
  transition:
    transform 220ms cubic-bezier(0.16, 1, 0.3, 1),
    border-color 220ms ease,
    box-shadow 220ms ease,
    background 220ms ease;
}

.people-department-card::before {
  content: "";
  position: absolute;
  inset: -1px;
  z-index: -1;
  border-radius: inherit;
  background: linear-gradient(135deg, rgba(96, 165, 250, 0.38), transparent 34%, rgba(147, 197, 253, 0.2));
  opacity: 0;
  filter: blur(10px);
  transition: opacity 220ms ease;
  pointer-events: none;
}

.people-department-card::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  background: linear-gradient(115deg, transparent 0 32%, rgba(191, 219, 254, 0.14) 44%, transparent 58% 100%);
  transform: translateX(-70%);
  opacity: 0;
  pointer-events: none;
}

.people-department-card:hover {
  transform: translateY(-7px) scale(1.012);
  border-color: rgba(147, 197, 253, 0.48) !important;
  box-shadow:
    0 26px 60px rgba(37, 99, 235, 0.16),
    0 0 0 5px rgba(96, 165, 250, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.92) !important;
}

.people-department-card:hover::before {
  opacity: 0.78;
}

.people-department-card:hover::after {
  animation: deptCardSheen 1.2s ease-out;
}

.people-department-card:nth-child(2) { animation-delay: 40ms; }
.people-department-card:nth-child(3) { animation-delay: 80ms; }
.people-department-card:nth-child(4) { animation-delay: 120ms; }
.people-department-card:nth-child(5) { animation-delay: 160ms; }
.people-department-card:nth-child(6) { animation-delay: 200ms; }

.people-department-card-cover {
  min-height: 118px;
