  display: grid;
  gap: clamp(18px, 2.2vw, 28px);
}

.dean-content > .hero-card {
  position: relative;
  isolation: isolate;
  min-height: 220px;
  align-items: center;
  border-radius: 24px;
  padding: clamp(24px, 3vw, 38px);
  overflow: hidden;
}

.dean-content > .hero-card::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background:
    linear-gradient(115deg, transparent 0 34%, rgba(255, 255, 255, 0.34) 45%, transparent 58% 100%);
  opacity: 0;
  transform: translateX(-60%);
  pointer-events: none;
}

.dean-content > .hero-card:hover::before {
  animation: lightSheen 1.5s ease-out;
}

.dean-content > .hero-card h2 {
  max-width: 900px;
  margin: 0;
  font-size: clamp(1.9rem, 3vw, 3.1rem);
  line-height: 1.02;
  letter-spacing: 0;
  text-wrap: balance;
}

.dean-content > .hero-card p:not(.eyebrow) {
  max-width: 760px;
  margin-top: 10px;
  font-size: clamp(0.95rem, 1.1vw, 1.1rem);
  line-height: 1.55;
}

.dean-content > .hero-card .hero-actions {
  margin-top: 22px;
}

.dean-content > .hero-card .period-selector {
  width: min(100%, 620px);
}

.dean-content > .hero-card .period-selector-select {
  min-width: 0;
  width: min(48vw, 430px);
}

.dean-content > .hero-card .hero-illustration {
  align-self: stretch;
  min-height: 150px;
  border-radius: 22px;
}

.dean-content > .hero-card .hero-robot {
  width: clamp(115px, 11vw, 170px);
  filter: drop-shadow(0 20px 28px rgba(25, 69, 49, 0.18));
  animation: deanRobotFloat 4.8s ease-in-out infinite;
}

.dean-content .admin-dashboard-unified {
  display: grid;
  gap: 18px;
  border-radius: 24px;
  padding: clamp(18px, 2vw, 26px);
  overflow: hidden;
}

.dean-content .action-center-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  align-items: center;
}

.dean-content .action-center-head h2 {
  margin: 2px 0 4px;
  font-size: clamp(1.35rem, 1.8vw, 2rem);
  line-height: 1.08;
}

.dean-content .action-center-head p:not(.eyebrow) {
  max-width: 780px;
  margin: 0;
  font-size: 0.92rem;
  line-height: 1.5;
}

.dean-content .action-center-summary {
  min-width: 160px;
  border-radius: 18px;
  padding: 16px 18px;
  text-align: center;
  transition: transform 220ms ease, box-shadow 220ms ease, border-color 220ms ease;
}

.dean-content .action-center-summary:hover {
  transform: translateY(-3px);
}

.dean-content .action-center-summary strong {
  display: block;
  font-size: clamp(2rem, 3vw, 3rem);
  line-height: 0.95;
  font-weight: 950;
}

.dean-content .action-center-summary span,
.dean-content .action-center-summary small {
  display: block;
  text-transform: uppercase;
  letter-spacing: 0;
}

.dean-content .action-center-summary span {
  margin-top: 6px;
  font-size: 0.7rem;
  font-weight: 950;
}

.dean-content .action-center-summary small {
  margin-top: 4px;
  font-size: 0.7rem;
  font-weight: 850;
}

.dean-quick-actions {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 12px;
}

.dean-quick-action {
  position: relative;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  min-height: 84px;
  border-radius: 18px;
  padding: 14px;
  text-decoration: none;
  overflow: hidden;
  transition:
    transform 220ms ease,
    border-color 220ms ease,
    box-shadow 220ms ease,
    background 220ms ease;
}

.dean-quick-action::after {
  content: "";
  position: absolute;
  inset: auto 16px 0;
  height: 3px;
  border-radius: 999px 999px 0 0;
  opacity: 0.7;
  transition: opacity 220ms ease, transform 220ms ease;
}

.dean-quick-action:hover {
  transform: translateY(-4px);
}

.dean-quick-action:hover::after {
  opacity: 1;
  transform: scaleX(1.04);
}

.dean-quick-action-icon {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 14px;
  flex: 0 0 auto;
}

.dean-quick-action strong,
.dean-quick-action small {
  display: block;
  min-width: 0;
}

.dean-quick-action strong {
  font-size: 0.84rem;
  font-weight: 950;
  line-height: 1.2;
}

.dean-quick-action small {
  margin-top: 4px;
  font-size: 0.72rem;
  font-weight: 750;
  line-height: 1.35;
}

.dean-content .dashboard-metric-grid.compact {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
  border: 0 !important;
  background: transparent !important;
  padding: 0 !important;
  box-shadow: none !important;
}

.dean-content .dashboard-metric-card {
  min-height: 156px;
  border-radius: 20px !important;
  padding: 18px !important;
  overflow: hidden;
  transition:
    transform 220ms ease,
    border-color 220ms ease,
    box-shadow 220ms ease,
    background 220ms ease;
}

.dean-content .dashboard-metric-card:hover {
  transform: translateY(-5px);
}

.dean-content .metric-card-head {
  align-items: flex-start;
}

.dean-content .metric-card-head > span:first-child {
  font-size: 0.76rem;
  line-height: 1.25;
  text-transform: uppercase;
  letter-spacing: 0;
}

.dean-content .metric-card-icon {
  width: 38px;
  height: 38px;
  border-radius: 13px;
}

.dean-content .dashboard-metric-card > strong {
  margin-top: 16px;
  font-size: clamp(2rem, 3vw, 3rem);
  line-height: 0.95;
}

.dean-content .dashboard-metric-card small {
  margin-top: 10px;
  font-size: 0.76rem;
  line-height: 1.45;
}

.dean-content .dashboard-metric-cta {
  width: fit-content;
  margin-top: 14px;
  border-radius: 999px;
  padding: 7px 10px;
  font-size: 0.7rem;
  font-weight: 900;
}

