    grid-template-columns: 1fr;
  }

  .dean-quick-action {
    min-height: 76px;
  }

  .dean-content .dashboard-metric-card {
    min-height: 136px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .dean-content > .hero-card .hero-robot,
  .dean-content > .hero-card:hover::before {
    animation: none !important;
  }
}

