/* Assignment workbench metric cards */
.assignment-workbench-metric {
  position: relative;
  isolation: isolate;
  min-height: 112px;
  overflow: hidden;
  border-radius: 18px !important;
  padding: 20px 22px !important;
  transition:
    transform 240ms ease,
    border-color 240ms ease,
    box-shadow 240ms ease,
    background 240ms ease;
}

.assignment-workbench-metric::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background:
    radial-gradient(circle at 12% 0%, color-mix(in srgb, var(--metric-accent, #168358) 20%, transparent), transparent 34%),
    linear-gradient(135deg, color-mix(in srgb, var(--metric-accent, #168358) 8%, transparent), transparent 64%);
  opacity: 0.9;
}

.assignment-workbench-metric::after {
  content: "";
  position: absolute;
  inset: auto 18px 0;
  height: 3px;
  border-radius: 999px 999px 0 0;
  background: linear-gradient(90deg, var(--metric-accent, #168358), var(--metric-accent-2, #22a06b));
  opacity: 0.7;
  transition: opacity 220ms ease, transform 220ms ease;
}

.assignment-workbench-metric:hover {
  transform: translateY(-5px);
}

.assignment-workbench-metric:hover::after {
  opacity: 1;
  transform: scaleX(1.03);
}

.assignment-workbench-metric-icon {
  display: grid;
  width: 52px;
  height: 52px;
  place-items: center;
  border-radius: 14px !important;
  flex: 0 0 auto;
}

.assignment-workbench-metric-copy p {
  margin: 0;
}

.assignment-workbench-metric-copy p:first-child {
  font-size: 0.84rem !important;
  font-weight: 850 !important;
  letter-spacing: 0;
}

.assignment-workbench-metric-copy p:last-child {
  margin-top: 4px;
  font-size: clamp(1.55rem, 2vw, 2rem) !important;
  line-height: 1 !important;
  font-weight: 950 !important;
}

.assignment-workbench-tabs {
  display: grid;
  grid-template-columns: repeat(6, minmax(150px, 1fr));
  gap: 8px;
  width: 100%;
  overflow-x: auto;
  overflow-y: hidden;
  margin: 0 0 24px;
  padding: 8px;
  border: 1px solid rgba(22, 131, 88, 0.22);
  border-radius: 18px;
  background: rgba(22, 131, 88, 0.08);
  scrollbar-width: thin;
  scrollbar-color: rgba(31, 122, 79, 0.55) transparent;
}

.assignment-workbench-tab {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-width: 150px;
  min-height: 43px;
  border: 1px solid rgba(22, 131, 88, 0.28);
  border-radius: 11px;
  background: linear-gradient(135deg, #23885b, #249763);
  color: #ffffff;
  font-size: 0.88rem;
  font-weight: 900;
  line-height: 1.12;
  text-align: center;
  white-space: normal;
  word-break: normal;
  overflow-wrap: normal;
  cursor: pointer;
  box-shadow: none;
  transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease, background 180ms ease;
}

.assignment-workbench-tab svg {
  flex: 0 0 auto;
}

.assignment-workbench-tab span {
  min-width: 0;
  max-width: 24ch;
  white-space: normal;
  word-break: normal;
  overflow-wrap: normal;
}

.assignment-workbench-tab:hover {
  transform: translateY(-1px);
  border-color: rgba(22, 131, 88, 0.62);
  background: linear-gradient(135deg, #1f7a4f, #2c955f);
  box-shadow: 0 10px 22px rgba(22, 131, 88, 0.18);
}

.assignment-workbench-tab.active {
  border-color: rgba(194, 119, 24, 0.36);
  background: linear-gradient(135deg, #c47218, #e09225);
  color: #ffffff;
  box-shadow: 0 8px 18px rgba(194, 119, 24, 0.18);
}

.assignment-workbench-tab.active svg {
  color: currentColor;
}

.admin-body.dark-mode .assignment-workbench-tabs,
.admin-dashboard-body.dark-mode .assignment-workbench-tabs,
body:has(.admin-dashboard-body.dark-mode) .assignment-workbench-tabs {
  border-color: rgba(96, 165, 250, 0.18);
  background: rgba(8, 20, 42, 0.72);
}

.admin-body.dark-mode .assignment-workbench-tab,
.admin-dashboard-body.dark-mode .assignment-workbench-tab,
body:has(.admin-dashboard-body.dark-mode) .assignment-workbench-tab {
  border-color: rgba(147, 197, 253, 0.22);
  background: linear-gradient(135deg, #214f98, #3f7ac8);
  color: #f8fbff;
}

.admin-body.dark-mode .assignment-workbench-tab.active,
.admin-dashboard-body.dark-mode .assignment-workbench-tab.active,
body:has(.admin-dashboard-body.dark-mode) .assignment-workbench-tab.active {
  border-color: rgba(147, 197, 253, 0.22);
  background: linear-gradient(135deg, #214f98, #3f7ac8);
  box-shadow: 0 10px 22px rgba(37, 99, 235, 0.18);
}

@media (max-width: 920px) {
  .assignment-workbench-tabs {
    grid-template-columns: repeat(6, minmax(150px, 1fr));
  }
}

@media (max-width: 560px) {
