/* Floating assistant panel presentation fix */
.floating-chat-panel {
  display: grid;
  grid-template-rows: auto auto auto minmax(180px, 1fr) auto auto auto;
  max-height: min(680px, calc(100dvh - 110px));
  border-radius: 22px !important;
}

.floating-chat-context {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  padding: 12px 14px;
  border-bottom: 1px solid var(--ui-border);
  background: var(--ui-surface);
}

.floating-chat-context > div {
  display: grid;
  gap: 3px;
  min-width: 0;
  border: 1px solid var(--ui-border);
  border-radius: 14px;
  background: var(--ui-surface-soft);
  padding: 10px;
}

.floating-chat-context span,
.floating-chat-context small {
  overflow: hidden;
  color: var(--ui-muted);
  font-size: 0.68rem;
  font-weight: 850;
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.floating-chat-context span {
  color: var(--ui-primary-strong);
  text-transform: uppercase;
}

.floating-chat-context strong {
  overflow: hidden;
  color: var(--ui-text);
  font-size: 0.82rem;
  font-weight: 950;
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.floating-chat-modes,
.floating-chat-quick-actions {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  border-bottom: 1px solid var(--ui-border);
  background: var(--ui-surface);
  padding: 10px 14px;
}

.floating-chat-modes button,
.floating-chat-quick-actions button,
.chat-message-actions button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 34px;
  border: 1px solid var(--ui-border);
  border-radius: 999px;
  background: var(--ui-surface-soft);
  color: var(--ui-primary-strong);
  padding: 0 11px;
  font-size: 0.72rem;
  font-weight: 900;
  white-space: nowrap;
  box-shadow: none;
}

.floating-chat-modes button.active {
  border-color: rgba(31, 122, 79, 0.35);
  background: var(--ui-primary);
  color: #ffffff;
}

.floating-chat-quick-actions {
  border-top: 1px solid var(--ui-border);
}

.floating-chat-quick-actions button {
  min-height: 32px;
  background: transparent;
}

.chat-message-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding-top: 4px;
}

.chat-message-actions button {
  min-height: 28px;
  border-radius: 9px;
  padding: 0 8px;
}

.floating-chat-log {
  display: flex;
  flex-direction: column;
  gap: 12px;
