/* Shared interactive assistant robot asset */
.hero-illustration,
.floating-chat-toggle {
  isolation: isolate;
}

.hero-robot,
.floating-chat-logo {
  transform-origin: 50% 62%;
  will-change: transform, filter;
}

.hero-illustration::before,
.floating-chat-toggle::before {
  background:
    radial-gradient(circle at 50% 54%, rgba(34, 197, 94, 0.28), transparent 54%),
    radial-gradient(circle at 50% 72%, rgba(59, 130, 246, 0.18), transparent 62%);
  filter: blur(8px);
  opacity: 0.9;
}

.hero-robot {
  animation: assistantRobotFloat 5.8s ease-in-out infinite;
  filter: drop-shadow(0 20px 30px rgba(22, 101, 52, 0.18));
}

.floating-chat-logo {
  animation: assistantRobotFloat 4.8s ease-in-out infinite, assistantRobotGlow 3.8s ease-in-out infinite;
  filter: drop-shadow(0 12px 18px rgba(37, 99, 235, 0.24));
}

.hero-illustration:hover .hero-robot,
.floating-chat-toggle:hover .floating-chat-logo {
  transform: translateY(-5px) scale(1.06) rotate(-2deg);
  filter: drop-shadow(0 18px 28px rgba(37, 99, 235, 0.36));
