/* Completed evaluation details: polished output and useful actions */
.evaluation-view-summary {
  display: grid;
  grid-template-columns: minmax(220px, 0.32fr) minmax(0, 1fr);
  gap: 16px;
  margin-top: 18px;
  animation: evaluationSummaryIn 360ms ease both;
}

.evaluation-view-score,
.evaluation-view-output {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(22, 131, 88, 0.22);
  border-radius: 18px;
  background:
    radial-gradient(circle at 12% 0%, rgba(34, 197, 94, 0.13), transparent 38%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.98), rgba(239, 253, 246, 0.94));
  box-shadow: 0 18px 42px rgba(25, 69, 49, 0.11);
}

.evaluation-view-score {
  display: grid;
  align-content: center;
  justify-items: center;
  min-height: 210px;
  padding: 22px;
  text-align: center;
}

.evaluation-view-score::before {
  content: "";
  position: absolute;
  inset: auto 18% 18px;
  height: 46px;
  border-radius: 999px;
  background: rgba(34, 197, 94, 0.16);
  filter: blur(22px);
}

.evaluation-view-score span,
.evaluation-view-output-head span {
  color: #607365;
  font-size: 0.78rem;
  font-weight: 900;
  text-transform: uppercase;
}

.evaluation-view-score strong {
  position: relative;
  margin-top: 8px;
  color: #0f241d;
  font-size: clamp(2.6rem, 5vw, 4.4rem);
  font-weight: 950;
  line-height: 0.95;
}

.evaluation-view-score strong small {
  color: #5b7168;
  font-size: 0.32em;
}

.evaluation-view-score p {
  position: relative;
  margin-top: 10px;
  color: #168358;
  font-weight: 900;
}

.evaluation-view-output {
  display: grid;
  gap: 14px;
  padding: 18px;
}

.evaluation-view-output-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.evaluation-view-output-head strong {
  display: block;
  color: #10201b;
  font-size: 1.05rem;
  font-weight: 950;
}

.evaluation-view-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

