  display: inline-flex;
  min-height: 38px;
  align-items: center;
  gap: 7px;
  border: 1px solid rgba(22, 131, 88, 0.22);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.82);
  padding: 0 13px;
  color: #14543b;
  font-size: 0.84rem;
  font-weight: 900;
  transition: transform 180ms ease, box-shadow 180ms ease, background 180ms ease;
}

