/* Evaluation cards: clearer content hierarchy with professional glow */
.admin-body,
.admin-dashboard-body {
  --eval-card-bg: #ffffff;
  --eval-card-bg-soft: #f8fafc;
  --eval-card-border: rgba(148, 163, 184, 0.28);
  --eval-card-text: #0f172a;
  --eval-card-muted: #475569;
  --eval-card-subtle: #64748b;
  --eval-card-primary: #2563eb;
  --eval-card-primary-strong: #1d4ed8;
  --eval-card-primary-soft: rgba(37, 99, 235, 0.1);
  --eval-card-accent: #38bdf8;
  --eval-card-warning: #d97706;
  --eval-card-warning-soft: rgba(217, 119, 6, 0.12);
  --eval-card-danger: #dc2626;
  --eval-card-danger-soft: rgba(220, 38, 38, 0.12);
}

.admin-body.dark-mode,
.admin-dashboard-body.dark-mode {
  --eval-card-bg: #0b1628;
  --eval-card-bg-soft: #101f36;
  --eval-card-border: rgba(96, 165, 250, 0.26);
  --eval-card-text: #f8fbff;
  --eval-card-muted: #c8d4e6;
  --eval-card-subtle: #9fb0c7;
  --eval-card-primary: #60a5fa;
  --eval-card-primary-strong: #93c5fd;
  --eval-card-primary-soft: rgba(96, 165, 250, 0.14);
  --eval-card-accent: #22d3ee;
  --eval-card-warning: #fbbf24;
  --eval-card-warning-soft: rgba(251, 191, 36, 0.14);
  --eval-card-danger: #fb7185;
  --eval-card-danger-soft: rgba(251, 113, 133, 0.14);
}

.admin-body .dipascaf-eval-card,
.admin-dashboard-body .dipascaf-eval-card {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border: 1px solid var(--eval-card-border) !important;
  border-radius: 18px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--eval-card-bg-soft) 72%, transparent), var(--eval-card-bg) 36%),
    var(--eval-card-bg) !important;
  color: var(--eval-card-text) !important;
  box-shadow:
    0 18px 44px color-mix(in srgb, #020617 12%, transparent),
    0 0 0 1px color-mix(in srgb, var(--eval-card-primary) 6%, transparent),
    inset 0 1px 0 color-mix(in srgb, #ffffff 28%, transparent) !important;
  transition: transform 220ms ease, border-color 220ms ease, box-shadow 220ms ease;
  animation: evaluationCardGlow 5.8s ease-in-out infinite;
}

.admin-body.dark-mode .dipascaf-eval-card,
.admin-dashboard-body.dark-mode .dipascaf-eval-card {
  box-shadow:
    0 18px 46px rgba(2, 6, 23, 0.34),
    0 0 28px rgba(96, 165, 250, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.08) !important;
}

.admin-body .dipascaf-eval-card::before,
.admin-dashboard-body .dipascaf-eval-card::before {
  content: "";
  position: absolute;
  inset: -1px;
  z-index: -1;
  border-radius: inherit;
  background:
    linear-gradient(120deg, transparent 18%, color-mix(in srgb, var(--eval-card-primary) 22%, transparent) 44%, transparent 70%);
  opacity: 0;
  transform: translateX(-38%);
  transition: opacity 220ms ease;
}

.admin-body .dipascaf-eval-card:hover,
.admin-dashboard-body .dipascaf-eval-card:hover {
  transform: translateY(-4px);
  border-color: color-mix(in srgb, var(--eval-card-primary) 48%, transparent) !important;
  box-shadow:
    0 24px 56px color-mix(in srgb, #020617 18%, transparent),
    0 0 32px color-mix(in srgb, var(--eval-card-primary) 18%, transparent),
    inset 0 1px 0 color-mix(in srgb, #ffffff 34%, transparent) !important;
}

.admin-body .dipascaf-eval-card:hover::before,
.admin-dashboard-body .dipascaf-eval-card:hover::before {
  opacity: 1;
  animation: evaluationCardSheen 1200ms ease;
}

.admin-body .dipascaf-card-cover,
.admin-dashboard-body .dipascaf-card-cover {
  min-height: 118px;
  margin: -1px -1px 0;
  border-radius: 18px 18px 0 0;
  background:
    linear-gradient(180deg, rgba(15, 23, 42, 0.08), rgba(15, 23, 42, 0.76)),
    linear-gradient(90deg, rgba(37, 99, 235, 0.28), rgba(15, 23, 42, 0.26)),
    url('/assets/images/pmas-campus-bg.jpg') center 36% / cover no-repeat;
}

.admin-body.dark-mode .dipascaf-card-cover,
.admin-dashboard-body.dark-mode .dipascaf-card-cover {
  background:
    linear-gradient(180deg, rgba(2, 6, 23, 0.18), rgba(2, 6, 23, 0.84)),
    linear-gradient(90deg, rgba(96, 165, 250, 0.2), rgba(15, 23, 42, 0.36)),
    url('/assets/images/pmas-campus-bg.jpg') center 36% / cover no-repeat;
}

.admin-body .dipascaf-card-top,
.admin-dashboard-body .dipascaf-card-top {
  position: relative;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 14px;
  margin-top: -66px;
  padding: 0 20px;
}

.admin-body .dipascaf-avatar,
.admin-dashboard-body .dipascaf-avatar {
  width: 70px;
  height: 70px;
  flex: 0 0 70px;
  border: 4px solid var(--eval-card-bg);
  border-radius: 18px;
  background: linear-gradient(135deg, #dbeafe, #c7f9e7);
  color: #0f5138;
  box-shadow:
    0 14px 28px rgba(2, 6, 23, 0.22),
    0 0 0 1px color-mix(in srgb, var(--eval-card-primary) 24%, transparent);
  font-size: 1.22rem;
  font-weight: 900;
}

.admin-body.dark-mode .dipascaf-avatar,
.admin-dashboard-body.dark-mode .dipascaf-avatar {
  border-color: var(--eval-card-bg);
  background: linear-gradient(135deg, #bfdbfe, #cffafe);
