/* Login polish: clearer hierarchy, helpful states, distinct CTA */
.login-page {
  --login-primary: #3b82f6;
  --login-primary-strong: #1d4ed8;
  --login-accent: #06b6d4;
  --login-panel: rgba(7, 17, 31, 0.86);
  --login-panel-strong: rgba(10, 22, 42, 0.94);
  --login-border: rgba(147, 197, 253, 0.34);
  --login-text: #f8fbff;
  --login-muted: #c2d1e8;
}

.login-card {
  border-color: var(--login-border) !important;
  background:
    linear-gradient(180deg, rgba(96, 165, 250, 0.1), rgba(8, 20, 38, 0.24)),
    var(--login-panel) !important;
  box-shadow:
    0 28px 80px rgba(2, 8, 23, 0.44),
    0 0 42px rgba(59, 130, 246, 0.14),
    inset 0 1px 0 rgba(255, 255, 255, 0.1) !important;
}

.login-card h1 {
  color: var(--login-text) !important;
  text-shadow: 0 0 24px rgba(96, 165, 250, 0.22);
}

.login-subtitle,
.login-welcome {
  color: var(--login-muted) !important;
}

.login-feature-row {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin: 10px 0 14px;
}

.login-feature-row span,
.login-support-strip,
.login-inline-hint {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: 1px solid rgba(96, 165, 250, 0.28);
  border-radius: 999px;
  background: rgba(96, 165, 250, 0.1);
  color: #dbeafe;
  font-size: 0.74rem;
  font-weight: 850;
  line-height: 1.2;
}

.login-feature-row span {
  min-height: 30px;
  padding: 0 11px;
}

.login-feature-row svg,
.login-support-strip svg,
.login-inline-hint svg {
  color: #7dd3fc;
  flex-shrink: 0;
}

.login-card .form {
  gap: 12px;
}

.login-card label {
  color: #eaf2ff !important;
}

.login-input-wrap {
  border-color: rgba(147, 197, 253, 0.28) !important;
  background: rgba(8, 20, 38, 0.88) !important;
  box-shadow:
    0 10px 26px rgba(2, 8, 23, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.06) !important;
}

.login-input-wrap:hover,
.login-input-wrap:focus-within {
  border-color: rgba(125, 211, 252, 0.72) !important;
  background: rgba(10, 24, 45, 0.96) !important;
  box-shadow:
    0 14px 32px rgba(37, 99, 235, 0.18),
    0 0 0 3px rgba(96, 165, 250, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.08) !important;
}

.login-card .login-input-wrap input {
  color: #f8fbff !important;
}

.login-card .login-input-wrap input::placeholder {
  color: #94a9c7 !important;
}

.login-inline-hint {
  width: fit-content;
  border-radius: 10px;
  background: rgba(251, 191, 36, 0.12);
  border-color: rgba(251, 191, 36, 0.34);
  color: #fde68a;
  padding: 7px 10px;
}

.login-inline-hint svg {
  color: #fbbf24;
}

.login-options {
  align-items: center;
}

.login-options .password-toggle {
  color: #dbeafe !important;
}

.login-options a {
  color: #93c5fd !important;
  text-decoration: none;
}

.login-options a:hover {
  color: #ffffff !important;
  text-shadow: 0 0 16px rgba(96, 165, 250, 0.42);
}

.login-card button[type="submit"] {
  position: relative;
  isolation: isolate;
  display: inline-flex;
  min-height: 50px;
  align-items: center;
  justify-content: center;
  gap: 10px;
  overflow: hidden;
  border: 1px solid rgba(125, 211, 252, 0.58) !important;
  border-radius: 14px !important;
  background:
    linear-gradient(135deg, #1d4ed8 0%, #3b82f6 52%, #06b6d4 100%) !important;
  color: #ffffff !important;
  box-shadow:
    0 18px 38px rgba(37, 99, 235, 0.34),
    0 0 34px rgba(56, 189, 248, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.28) !important;
  font-size: 0.96rem;
  font-weight: 950;
  letter-spacing: 0;
  transition: transform 180ms ease, box-shadow 180ms ease, filter 180ms ease;
  animation: loginCtaPulse 4s ease-in-out infinite;
}

.login-card button[type="submit"]::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background: linear-gradient(120deg, transparent 14%, rgba(255, 255, 255, 0.28) 46%, transparent 74%);
  opacity: 0;
  transform: translateX(-82%);
}

.login-card button[type="submit"]:hover:not(:disabled) {
  transform: translateY(-2px);
  filter: saturate(1.12) brightness(1.04);
  box-shadow:
    0 22px 48px rgba(37, 99, 235, 0.42),
    0 0 42px rgba(56, 189, 248, 0.28),
    inset 0 1px 0 rgba(255, 255, 255, 0.32) !important;
}

.login-card button[type="submit"]:hover:not(:disabled)::after {
  opacity: 1;
  animation: loginCtaSheen 950ms ease;
}

.login-card button[type="submit"]:active:not(:disabled) {
  transform: translateY(0) scale(0.99);
}

.login-card button[type="submit"]:disabled {
  border-color: rgba(148, 163, 184, 0.3) !important;
  background: rgba(15, 23, 42, 0.74) !important;
  color: rgba(226, 232, 240, 0.72) !important;
  box-shadow: none !important;
  animation: none;
}

.login-support-strip {
  width: 100%;
  justify-content: center;
  border-radius: 12px;
  margin-top: 14px;
  padding: 10px 12px;
  background: rgba(8, 20, 38, 0.62);
}

@keyframes loginCtaPulse {
  0%,
  100% {
    filter: saturate(1);
  }

  50% {
    filter: saturate(1.16) brightness(1.05);
  }
}

@keyframes loginCtaSheen {
  from {
    transform: translateX(-84%);
  }

  to {
    transform: translateX(84%);
  }
}

@media (max-width: 520px) {
  .login-feature-row {
    justify-content: stretch;
  }

  .login-feature-row span {
    flex: 1 1 100%;
    justify-content: center;
  }
}

@media (prefers-reduced-motion: reduce) {
.login-card button[type="submit"],
  .login-card button[type="submit"]:hover:not(:disabled)::after {
    animation: none !important;
  }
}

