}

.settings-page .settings-tab {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 42px;
  border: 1px solid transparent;
  border-radius: 12px;
  padding: 0 15px;
  color: #597066;
  font-weight: 800;
}

.settings-page .settings-tab.active {
  border-color: rgba(22, 131, 88, 0.18);
  background: #e7f5ee;
  color: #126b49;
}

.settings-tab-count {
  display: inline-grid;
  min-width: 23px;
  height: 23px;
  place-items: center;
  border-radius: 999px;
  background: rgba(22,131,88,.12);
  padding-inline: 6px;
  font-size: .72rem;
}

.settings-feature-form {
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) !important;
  align-items: start !important;
  padding: 18px;
  gap: 18px;
}

.settings-feature-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.settings-control-card {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(22, 131, 88, 0.16);
  border-radius: 16px;
  background:
    radial-gradient(circle at 12% 0%, rgba(34, 168, 101, 0.12), transparent 36%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.98), rgba(246, 253, 249, 0.94));
  padding: 18px;
  box-shadow:
    0 10px 28px rgba(15, 77, 56, 0.07),
    inset 0 1px 0 rgba(255, 255, 255, 0.88);
}

.settings-control-card::after {
  content: '';
  position: absolute;
  inset: auto 18px 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(34, 168, 101, 0.34), transparent);
}

.settings-security-card {
  grid-column: 1 / -1;
}

.settings-card-head {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 16px;
}

.settings-card-icon {
  display: inline-grid;
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  place-items: center;
  border-radius: 14px;
  background: linear-gradient(135deg, rgba(34, 168, 101, 0.18), rgba(15, 159, 143, 0.12));
  color: #126b49;
  box-shadow: 0 12px 28px rgba(22, 131, 88, 0.13);
}

.settings-card-head h3 {
  margin: 0;
  color: #0d1f18;
