  line-height: 1.2;
}

.settings-card-head p {
  margin: 4px 0 0;
  color: #5d7168;
  font-size: 0.84rem;
  font-weight: 650;
  line-height: 1.45;
}

.settings-feature-form label {
  color: #40564c;
  font-size: 0.78rem;
  font-weight: 850;
  letter-spacing: 0;
}

.settings-field-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.settings-password-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.settings-feature-form :where(input, select) {
  width: 100%;
  min-height: 42px;
  margin-top: 7px;
  border: 1px solid rgba(22, 131, 88, 0.16);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.86);
  color: #0d1f18;
  padding: 0 12px;
  font-weight: 800;
  outline: none;
  transition: border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
}

.settings-feature-form :where(input, select):focus {
  border-color: rgba(22, 131, 88, 0.52);
  box-shadow: 0 0 0 4px rgba(22, 131, 88, 0.12);
}

.settings-feature-form input[readonly] {
  color: #667a70;
  background: rgba(240, 247, 244, 0.8);
}

.settings-toggle-list {
  display: grid;
  gap: 10px;
  margin-bottom: 12px;
}

.settings-toggle-row {
  display: flex !important;
  align-items: center;
  gap: 12px;
  min-height: 52px;
  border: 1px solid rgba(22, 131, 88, 0.14);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.58);
  padding: 10px 12px;
}

.settings-toggle-row input {
  width: 18px !important;
  height: 18px;
  min-height: 18px;
  margin: 0 !important;
  accent-color: #168358;
}

.settings-toggle-row span {
  display: grid;
  gap: 2px;
}

.settings-toggle-row strong {
  color: #123327;
  font-size: 0.84rem;
}

.settings-toggle-row small {
  color: #63796f;
  font-size: 0.75rem;
  font-weight: 700;
}

.settings-live-pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  width: fit-content;
  margin-top: 12px;
  border: 1px solid rgba(22, 131, 88, 0.18);
  border-radius: 999px;
  background: rgba(22, 131, 88, 0.1);
  color: #126b49;
  padding: 7px 11px;
  font-size: 0.76rem;
  font-weight: 900;
}

.settings-message {
  border-radius: 12px;
  padding: 12px 14px;
  font-weight: 850;
}

.settings-message.success {
  border: 1px solid rgba(22, 131, 88, 0.22);
  background: rgba(220, 252, 231, 0.76);
  color: #126b49;
}

.settings-message.error {
  border: 1px solid rgba(220, 38, 38, 0.22);
  background: rgba(254, 226, 226, 0.76);
  color: #991b1b;
}

.settings-save-row {
  position: sticky;
  z-index: 5;
  bottom: 12px;
  display: flex !important;
  justify-content: flex-end;
  align-items: center;
  width: 100%;
  padding: 12px 0 0;
  border-top: 1px solid rgba(22, 131, 88, 0.12);
  background: linear-gradient(180deg, transparent, rgba(247, 251, 249, 0.96) 35%);
  pointer-events: none;
}

.settings-save-row .primary-button {
  position: relative;
  isolation: isolate;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: auto !important;
  min-width: 190px !important;
  max-width: max-content !important;
  min-height: 48px !important;
  height: auto !important;
  align-self: center !important;
  overflow: hidden;
  border-radius: 14px;
  padding: 0 22px !important;
  pointer-events: auto;
  white-space: nowrap;
  box-shadow:
    0 18px 38px rgba(22, 131, 88, 0.24),
    0 0 30px rgba(15, 159, 143, 0.15) !important;
  animation: settingsSaveFloat 3.4s ease-in-out infinite;
  transition: transform 0.22s ease, box-shadow 0.22s ease, filter 0.22s ease;
}

.settings-save-row .primary-button::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  background: linear-gradient(120deg, transparent 16%, rgba(255, 255, 255, 0.26) 48%, transparent 76%);
  opacity: 0;
  transform: translateX(-88%);
}

.settings-save-row .primary-button:hover:not(:disabled) {
  transform: translateY(-4px);
  filter: saturate(1.08);
  box-shadow:
    0 24px 48px rgba(22, 131, 88, 0.32),
    0 0 0 5px rgba(22, 131, 88, 0.1),
    0 0 36px rgba(15, 159, 143, 0.2) !important;
}

.settings-save-row .primary-button:hover:not(:disabled)::after {
  opacity: 1;
  animation: settingsSaveSheen 850ms ease forwards;
}

.settings-save-row .primary-button:active:not(:disabled) {
  transform: translateY(-1px) scale(0.99);
}

@keyframes settingsSaveFloat {
  0%,
  100% {
    translate: 0 0;
  }

  50% {
    translate: 0 -3px;
  }
}

@keyframes settingsSaveSheen {
  from {
    transform: translateX(-88%);
  }

  to {
    transform: translateX(88%);
  }
}

@media (prefers-reduced-motion: reduce) {
  .settings-save-row .primary-button {
    animation: none !important;
  }
}

@media (max-width: 720px) {
  .settings-page-hero { align-items: flex-start; padding: 18px; }
  .settings-page-status { display: none; }
  .settings-page .settings-tabs { overflow-x: auto; padding-inline: 14px; }
  .settings-save-row {
    bottom: 116px;
    padding-inline: 0;
  }
}

