/* Department profile stat card glow */
.module-stats .stat-grid article {
  position: relative;
  overflow: hidden;
  border-color: rgba(22, 131, 88, 0.16);
  background:
    radial-gradient(circle at 12% 0%, rgba(34, 168, 101, 0.1), transparent 36%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.98), rgba(248, 253, 250, 0.94));
  box-shadow:
    0 16px 34px rgba(15, 77, 56, 0.08),
    0 0 0 1px rgba(255, 255, 255, 0.72) inset;
}

.module-stats .stat-grid article::before {
  content: '';
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  pointer-events: none;
  background:
    linear-gradient(135deg, rgba(34, 168, 101, 0.36), transparent 34%, rgba(15, 159, 143, 0.26));
  opacity: 0;
  transition: opacity 0.24s ease;
}

.module-stats .stat-grid article::after {
  content: '';
  position: absolute;
  top: -50%;
  left: -35%;
  width: 34%;
  height: 200%;
  pointer-events: none;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.45), transparent);
  transform: rotate(18deg) translateX(-120%);
  opacity: 0;
}

.module-stats .stat-grid article:hover {
  border-color: rgba(22, 131, 88, 0.38);
  box-shadow:
    0 20px 44px rgba(15, 77, 56, 0.16),
    0 0 0 4px rgba(22, 131, 88, 0.08),
    0 0 34px rgba(34, 168, 101, 0.12);
}

.module-stats .stat-grid article:hover::before {
  opacity: 1;
}

.module-stats .stat-grid article:hover::after {
  animation: statCardShine 0.9s ease forwards;
  opacity: 1;
}

.module-stats .stat-grid article > * {
  position: relative;
  z-index: 1;
}

@keyframes statCardShine {
  from {
    transform: rotate(18deg) translateX(-120%);
  }
  to {
    transform: rotate(18deg) translateX(520%);
  }
}

