/* Official PMAS Form 3b paper presentation. These rules intentionally affect
   presentation only; form controls, field names, and handlers remain unchanged. */
.self-eval-paper.self-eval-paper-form,
.admin-self-eval-paper-preview {
  width: min(900px, 100%);
  gap: 14px;
  padding: clamp(24px, 4vw, 54px) clamp(20px, 5vw, 64px);
  border: 1px solid #b8b8b8;
  background: #fff;
  color: #111;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 15px;
  line-height: 1.25;
}

.self-eval-paper .self-eval-paper-head {
  min-height: 154px;
  padding-top: 24px;
}

.self-eval-paper .self-eval-form-code {
  top: 0;
  right: 0;
  font-size: 14px;
  letter-spacing: .01em;
}

.self-eval-paper .self-eval-school-brand {
  grid-template-columns: 104px minmax(0, 1fr);
  gap: 22px;
  width: min(690px, 100%);
  margin: 20px auto 0;
}

.self-eval-paper .self-eval-school-brand img {
  width: 100px;
  height: 100px;
}

.self-eval-paper .self-eval-school-brand h1 {
  font-size: clamp(1.35rem, 3vw, 1.75rem);
  line-height: 1.08;
}

.self-eval-paper .self-eval-school-brand h2,
.self-eval-paper-form .self-eval-school-brand h2 {
  margin-top: 24px;
  font-size: clamp(1.2rem, 2.5vw, 1.55rem);
  line-height: 1.08;
  text-transform: none;
}

.self-eval-paper .self-eval-school-brand p,
.self-eval-paper-form .self-eval-school-brand p {
  margin-top: 2px;
  font-size: 1rem;
  font-weight: 800;
}

.self-eval-paper .self-eval-paper-fields {
  width: 100%;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, .85fr);
  gap: 7px 16px;
  margin: 8px 0 16px;
}

.self-eval-paper .paper-line-field {
  font-size: 14px;
}

.self-eval-paper .paper-line-field strong {
  min-height: 21px;
  border-bottom-width: 1px;
  font-size: 14px;
}

.self-eval-paper .paper-section {
  gap: 8px;
}

.self-eval-paper .paper-section h3,
.self-eval-paper-continuation > h3,
.self-eval-paper-continuation > section > h3 {
  margin: 8px 0 0;
  border: 0;
  padding: 0;
  font-size: 1.08rem;
  line-height: 1.2;
  text-transform: none;
}

.self-eval-paper .paper-subtitle {
  margin: -7px 0 4px;
  font-size: .88rem;
  font-style: normal;
}

.self-eval-paper .self-eval-question {
  grid-template-columns: 22px minmax(0, 1fr);
  gap: 7px;
  margin-top: 10px;
}

.self-eval-paper .self-eval-question > strong,
.self-eval-paper .self-eval-question p {
  font-family: Arial, Helvetica, sans-serif;
  font-size: 14px;
  line-height: 1.25;
}

.self-eval-paper .self-eval-question p {
  margin: 0;
  font-weight: 700;
}

.self-eval-paper .self-eval-table-wrap {
  overflow: hidden;
  border: 1.4px solid #111;
}

.self-eval-paper .self-eval-table {
  min-width: 600px;
  table-layout: fixed;
  font-family: Arial, Helvetica, sans-serif;
}

.self-eval-paper .self-eval-table th {
  background: #fff;
  padding: 6px 7px;
  font-size: 12px;
  line-height: 1.15;
}

.self-eval-paper .self-eval-table td {
  min-height: 38px;
  font-size: 13px;
}

.self-eval-paper .self-eval-table textarea,
.self-eval-paper .self-eval-table input,
.self-eval-paper .self-eval-table select {
  min-height: 48px;
  padding: 7px;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 14px;
}

.self-eval-paper .self-eval-table textarea {
  min-height: 58px;
}

.self-eval-paper .paper-answer-box span {
  border-width: 1.4px;
  padding: 5px 8px;
  background: #fff;
  font-size: 12px;
}

.self-eval-paper .paper-answer-box textarea,
.self-eval-paper .preview-answer-box div {
  min-height: 112px;
  border-width: 1.4px;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 14px;
}

.self-eval-paper .paper-checkbox-grid {
  grid-template-columns: repeat(2, minmax(180px, 1fr));
  gap: 7px 34px;
  margin-left: 22px;
}

.self-eval-paper .paper-checkbox.self-eval-radio {
  grid-template-columns: 28px minmax(0, 1fr);
  align-items: center;
  min-height: 28px;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 14px;
}

.self-eval-paper .paper-checkbox input {
  width: 24px !important;
  height: 20px;
  min-height: 20px;
  border: 1.4px solid #111;
  border-radius: 0;
}

.self-eval-paper .paper-checkbox input:checked::after {
  font-size: 18px;
}

.self-eval-preview-rating-list span {
  display: flex;
  align-items: center;
  gap: 9px;
  color: #111;
  font-size: 14px;
  font-weight: 700;
}

.self-eval-preview-rating-list i {
  width: 25px;
  height: 20px;
  border: 1.4px solid #111;
  background: #fff;
}

.self-eval-paper-continuation .self-eval-summary-entry {
  gap: 0;
  border: 1.4px solid #111;
  background: #fff;
  padding: 0;
}

.self-eval-paper-continuation .self-eval-summary-prompt {
  grid-template-columns: 1fr;
  gap: 3px;
  padding: 8px 10px;
  border-bottom: 1.4px solid #111;
}

.self-eval-paper-continuation .self-eval-summary-prompt strong {
  color: #111;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 14px;
  text-transform: uppercase;
}

.self-eval-paper-continuation .self-eval-summary-prompt p {
  color: #111;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 13px;
  line-height: 1.25;
}

.self-eval-paper-continuation .self-eval-summary-entry .paper-answer-box textarea {
  border: 0;
}

.self-eval-original-preview .paper-section + .paper-section {
  margin-top: 24px;
  padding-top: 24px;
  border-top: 1px dashed #aaa;
}

.self-eval-original-preview .self-eval-reference-page-break {
  margin-top: 40px !important;
  padding-top: 34px !important;
  border-top: 2px solid #777 !important;
}

.self-eval-original-preview .self-eval-reference-page-break::before {
  content: "CONTINUATION";
  justify-self: end;
  margin-bottom: -2px;
  color: #777;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .12em;
}

.self-eval-original-preview .self-eval-preview-supplemental {
  display: grid;
  gap: 10px;
  margin-top: 18px;
  padding-top: 16px;
  border-top: 1px dashed #777;
}

.self-eval-original-preview .self-eval-preview-supplemental > strong {
  color: #111;
  font-size: 13px;
  text-transform: uppercase;
}

@media (max-width: 700px) {
  .self-eval-paper.self-eval-paper-form,
  .admin-self-eval-paper-preview {
    padding: 18px 12px;
    font-size: 14px;
  }

  .self-eval-paper .self-eval-paper-head { min-height: 132px; }
  .self-eval-paper .self-eval-school-brand { grid-template-columns: 70px minmax(0, 1fr); gap: 10px; }
  .self-eval-paper .self-eval-school-brand img { width: 68px; height: 68px; }
  .self-eval-paper .self-eval-school-brand h1 { font-size: 1rem; }
  .self-eval-paper .self-eval-school-brand h2,
  .self-eval-paper-form .self-eval-school-brand h2 { margin-top: 11px; font-size: 1rem; }
  .self-eval-paper .self-eval-school-brand p,
  .self-eval-paper-form .self-eval-school-brand p { font-size: .82rem; }
  .self-eval-paper .self-eval-paper-fields { grid-template-columns: 1fr; }
  .self-eval-paper .paper-line-field.wide { grid-column: auto; }
  .self-eval-paper .paper-checkbox-grid { grid-template-columns: 1fr; margin-left: 0; }
  .self-eval-paper .self-eval-table-wrap { overflow-x: auto; }
}

@media print {
  .self-eval-paper,
  .admin-self-eval-paper-preview {
    width: 100% !important;
    padding: 10mm 12mm !important;
    border: 0 !important;
    box-shadow: none !important;
    font-size: 10pt !important;
  }

  .self-eval-original-preview .self-eval-reference-page-break {
    break-before: page;
    border-top: 0 !important;
  }

  .self-eval-original-preview .self-eval-reference-page-break::before { display: none; }
  .self-eval-paper .no-print { display: none !important; }
}

.paper-answer-box textarea {
  width: 100%;
  min-height: 92px;
  border: 1.5px solid #111111;
  border-radius: 0;
  background: #ffffff;
  color: #111111;
  padding: 8px;
  resize: vertical;
}

.preview-answer-box div {
  min-height: 92px;
  border: 1.5px solid #111111;
  background: #ffffff;
}

.paper-checkbox-grid {
  grid-template-columns: repeat(2, minmax(180px, 1fr));
  gap: 8px 46px;
  width: min(680px, 100%);
  margin: 0 0 6px 28px;
}

.paper-checkbox.self-eval-radio {
  border: 0;
  border-radius: 0;
  background: transparent;
  padding: 0;
  color: #111111;
  font-size: 0.92rem;
  font-weight: 800;
}

.paper-checkbox input {
  position: relative;
  appearance: none;
  flex: 0 0 auto;
  width: 34px !important;
  height: 42px;
  border: 1.5px solid #b8d7ff;
  border-radius: 14px;
  background: #ffffff;
}

.paper-checkbox input:checked {
  background: #ffffff;
}

.paper-checkbox input:checked::after {
  content: "\2713";
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: #0f7f4f;
  font-family: Arial, sans-serif;
  font-size: 26px;
  font-weight: 900;
  line-height: 1;
}

.self-eval-paper .no-print {
  width: 52px;
  text-align: center;
}

.self-eval-paper .self-eval-total {
  border: 1.5px solid #111111;
  border-radius: 0;
  background: #ffffff;
}

.self-eval-toolbar,
.self-eval-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: flex-end;
  align-items: center;
}

.self-eval-toolbar.bottom {
  border-top: 1px solid var(--theme-border, #dbe7e1);
  padding-top: 16px;
}

.self-eval-section {
  display: grid;
  gap: 14px;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 16px;
  background: var(--theme-surface, #ffffff);
  padding: clamp(14px, 2vw, 20px);
}

.self-eval-section h3 {
  margin: 0;
  color: var(--theme-text, #10201b);
  font-size: 1rem;
  font-weight: 900;
}

.self-eval-section label {
  display: grid;
  gap: 7px;
  color: var(--theme-muted, #4d5f57);
  font-size: 0.82rem;
  font-weight: 800;
}

.self-eval-section input,
.self-eval-section select,
.self-eval-section textarea,
.self-eval-title select {
  width: 100%;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 12px;
  background: var(--theme-surface, #ffffff);
  color: var(--theme-text, #10201b);
  padding: 10px 12px;
  font: inherit;
  outline: none;
}

.self-eval-section textarea {
  min-height: 96px;
  resize: vertical;
}

.self-eval-section input:focus,
.self-eval-section select:focus,
.self-eval-section textarea:focus {
  border-color: var(--theme-primary, #166a45);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--theme-primary, #166a45) 15%, transparent);
}

.employee-info-grid,
.self-eval-computation,
.self-eval-template-grid {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 230px), 1fr));
}

.employee-info-grid h3,
.employee-info-grid .self-eval-helper,
.self-eval-template-grid {
  grid-column: 1 / -1;
}

.self-eval-question {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 10px;
  align-items: start;
}

.self-eval-question strong {
  min-width: 32px;
  color: var(--theme-primary, #166a45);
  font-size: 0.82rem;
  font-weight: 900;
}

.self-eval-question p,
.self-eval-helper {
  margin: 0;
  color: var(--theme-muted, #4d5f57);
  line-height: 1.55;
}

.self-eval-table-block {
  display: grid;
  gap: 10px;
}

.self-eval-table-wrap {
  width: 100%;
  overflow-x: auto;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 12px;
}

.self-eval-table {
  width: 100%;
  min-width: 760px;
  border-collapse: collapse;
  background: var(--theme-surface, #ffffff);
}

.self-eval-table th,
.self-eval-table td {
  border-bottom: 1px solid var(--theme-border, #dbe7e1);
  padding: 10px;
  text-align: left;
  vertical-align: top;
  color: var(--theme-text, #10201b);
}

.self-eval-table th {
  background: color-mix(in srgb, var(--theme-primary, #166a45) 8%, var(--theme-surface, #ffffff));
  color: var(--theme-text, #10201b);
  font-size: 0.74rem;
  font-weight: 900;
  text-transform: uppercase;
}

.self-eval-table td textarea {
  min-height: 76px;
}

.self-eval-add-row {
  justify-self: start;
}

.self-eval-remove {
  display: inline-grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border: 1px solid #fecaca;
  border-radius: 10px;
  background: #fff1f2;
  color: #b91c1c;
}

.self-eval-remove:disabled {
  opacity: 0.45;
}

/* Keep the editable self-evaluation row delete control visible over global button themes. */
.self-evaluation-page .self-eval-table .self-eval-action-cell {
  width: 74px;
  text-align: center;
}

.self-evaluation-page .self-eval-table .self-eval-remove {
  display: inline-grid !important;
  place-items: center !important;
  width: 42px !important;
  height: 42px !important;
  min-width: 42px !important;
  min-height: 42px !important;
  padding: 0 !important;
  border: 1px solid #fecaca !important;
  border-radius: 12px !important;
  background: #fff1f2 !important;
  color: #b91c1c !important;
  box-shadow: 0 5px 12px rgba(185, 28, 28, .1) !important;
}

.self-evaluation-page .self-eval-table .self-eval-remove > span {
  display: inline-grid !important;
  place-items: center !important;
  width: 22px !important;
  height: 22px !important;
  color: #b91c1c !important;
  line-height: 0 !important;
}

.self-evaluation-page .self-eval-table .self-eval-remove svg,
.self-evaluation-page .self-eval-table .self-eval-remove svg * {
  display: block !important;
  stroke: currentColor !important;
  fill: none !important;
  opacity: 1 !important;
  visibility: visible !important;
}

.self-evaluation-page .self-eval-table .self-eval-remove:hover:not(:disabled) {
  border-color: #fca5a5 !important;
  background: #ffe4e6 !important;
  color: #991b1b !important;
  transform: translateY(-1px);
}

:is(.admin-body.dark-mode, .admin-dashboard-body.dark-mode) .self-evaluation-page .self-eval-table .self-eval-remove {
  border-color: rgba(248, 113, 113, .45) !important;
  background: rgba(127, 29, 29, .28) !important;
  color: #fca5a5 !important;
}

.self-eval-rating-grid,
.self-eval-guide {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 210px), 1fr));
  gap: 10px;
}

.self-eval-radio,
.self-eval-guide span,
.self-eval-total,
.self-eval-status {
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 12px;
  background: color-mix(in srgb, var(--theme-surface, #ffffff) 94%, var(--theme-primary, #166a45));
  padding: 10px 12px;
}

.self-eval-radio {
  display: flex !important;
  grid-template-columns: none !important;
  flex-direction: row;
  align-items: center;
}

.self-eval-radio input {
  width: auto;
}

.self-eval-total {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  color: var(--theme-text, #10201b);
  font-weight: 800;
}

.self-eval-weight-total {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  border: 1px solid;
  border-radius: 12px;
  padding: 11px 14px;
  font-weight: 850;
}

.self-eval-weight-total span {
  display: grid;
  gap: 2px;
}

.self-eval-weight-total small {
  font-size: 0.74rem;
  font-weight: 750;
}

.self-eval-weight-total.is-incomplete {
  border-color: rgba(245, 158, 11, 0.42);
  background: rgba(245, 158, 11, 0.1);
  color: #b45309;
}

.self-eval-weight-total.is-complete {
  border-color: rgba(16, 185, 129, 0.38);
  background: rgba(16, 185, 129, 0.1);
  color: #047857;
}

.admin-body.dark-mode .self-eval-weight-total.is-incomplete,
.admin-dashboard-body.dark-mode .self-eval-weight-total.is-incomplete,
body:has(.admin-body.dark-mode) .self-eval-weight-total.is-incomplete,
body:has(.admin-dashboard-body.dark-mode) .self-eval-weight-total.is-incomplete {
  color: #fcd34d;
}

.admin-body.dark-mode .self-eval-weight-total.is-complete,
.admin-dashboard-body.dark-mode .self-eval-weight-total.is-complete,
body:has(.admin-body.dark-mode) .self-eval-weight-total.is-complete,
body:has(.admin-dashboard-body.dark-mode) .self-eval-weight-total.is-complete {
  color: #6ee7b7;
}

.self-eval-status {
  display: inline-flex;
  width: fit-content;
  color: var(--theme-primary, #166a45);
  font-size: 0.76rem;
  font-weight: 900;
  text-transform: uppercase;
}

.self-eval-status.submitted {
  border-color: #bbf7d0;
  background: #dcfce7;
  color: #166534;
}

.self-eval-status.draft,
.self-eval-status.reopened {
  border-color: #fde68a;
  background: #fffbeb;
  color: #92400e;
