/* Dedicated VPAA overview — intentionally separate from the Admin/HR dashboard. */
.vpaa-role-dashboard {
  display: grid;
  gap: 18px;
  padding: clamp(18px, 2vw, 28px);
}

.vpaa-role-dashboard-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
}

.vpaa-live-status {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex: 0 0 auto;
  padding: 8px 12px;
  border: 1px solid rgba(22, 163, 74, 0.22);
  border-radius: 999px;
  background: rgba(240, 253, 244, 0.88);
  color: #166534;
  font-size: 0.78rem;
  font-weight: 800;
}

.vpaa-live-status span {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #22c55e;
  box-shadow: 0 0 0 5px rgba(34, 197, 94, 0.12), 0 0 14px rgba(34, 197, 94, 0.55);
}

.vpaa-live-status.is-error { color: #b91c1c; border-color: rgba(220, 38, 38, 0.25); background: rgba(254, 242, 242, 0.9); }
.vpaa-live-status.is-error span { background: #ef4444; box-shadow: 0 0 0 5px rgba(239, 68, 68, 0.12); }

.vpaa-role-dashboard .dashboard-metric-card.metric-danger { --metric-color: #dc2626; }

.vpaa-evaluation-chart-panel {
  display: grid;
  grid-template-columns: minmax(230px, 0.8fr) minmax(300px, 1fr) minmax(190px, 0.55fr);
  align-items: center;
  gap: clamp(18px, 3vw, 38px);
  min-height: 240px;
  padding: clamp(18px, 2vw, 26px);
  border: 1px solid rgba(22, 106, 69, 0.18);
  border-radius: 20px;
  background:
    radial-gradient(circle at 92% 12%, rgba(34, 197, 94, 0.13), transparent 30%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.98), rgba(242, 250, 246, 0.95));
  box-shadow: 0 18px 42px rgba(15, 80, 55, 0.09), 0 0 30px rgba(34, 197, 94, 0.07);
  overflow: hidden;
}

.vpaa-chart-copy h3 { margin: 4px 0 8px; font-size: clamp(1.1rem, 1.7vw, 1.4rem); }
.vpaa-chart-copy > p:last-of-type { margin: 0; max-width: 48ch; color: var(--muted, #64748b); line-height: 1.55; }
.vpaa-chart-total { display: flex; align-items: center; gap: 12px; margin-top: 18px; }
.vpaa-chart-total strong { color: #166a45; font-size: 2rem; line-height: 1; }
.vpaa-chart-total span { color: var(--muted, #64748b); font-size: 0.82rem; font-weight: 700; }
.vpaa-pie-wrap { position: relative; min-width: 0; height: 205px; }
.vpaa-chart-empty { display: grid; place-items: center; height: 100%; color: var(--muted, #64748b); text-align: center; }
.vpaa-chart-breakdown { display: grid; gap: 10px; }
.vpaa-chart-breakdown > span { display: grid; grid-template-columns: 10px minmax(0, 1fr) auto; align-items: center; gap: 9px; padding: 10px 12px; border-radius: 12px; background: rgba(255, 255, 255, 0.7); font-size: 0.82rem; font-weight: 700; }
.vpaa-chart-breakdown i { width: 9px; height: 9px; border-radius: 50%; box-shadow: 0 0 10px currentColor; }
.vpaa-chart-breakdown .completed { color: #15803d; }
.vpaa-chart-breakdown .pending { color: #a16207; }
