  background: rgba(255, 255, 255, 0.92);
  padding: 18px;
  box-shadow: 0 16px 36px rgba(15, 23, 42, 0.08);
}

.category-evaluator-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(240px, 340px);
  gap: 14px;
  align-items: end;
}

.category-evaluator-head h3 {
  margin: 2px 0 0;
  color: #10201b;
  font-size: 1.08rem;
  font-weight: 900;
}

.category-evaluator-filter {
  display: grid;
  gap: 7px;
