  font-size: 0.8rem;
  font-weight: 800;
}

.category-evaluator-filter select {
  width: 100%;
  min-height: 44px;
  border: 1px solid #bfdbfe;
  border-radius: 12px;
  background: #ffffff;
  color: #1f2937;
  padding: 0 12px;
  font-weight: 700;
}

.category-evaluator-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.category-evaluator-summary article {
  border: 1px solid rgba(37, 99, 235, 0.14);
  border-radius: 14px;
  background: linear-gradient(135deg, #ffffff, #f4f8ff);
  padding: 12px;
}

.category-evaluator-summary span {
  display: block;
  color: #52627a;
  font-size: 0.76rem;
  font-weight: 800;
}

.category-evaluator-summary strong {
  display: flex;
  align-items: baseline;
  gap: 3px;
  margin-top: 4px;
  color: #1d4ed8;
  font-size: 1.18rem;
  font-weight: 900;
}

.category-evaluator-summary small {
  color: #64748b;
  font-size: 0.76rem;
}

.category-evaluator-list {
  display: grid;
  gap: 12px;
  max-height: 540px;
  overflow: auto;
  padding-right: 4px;
}

.category-evaluator-card {
  display: grid;
  gap: 12px;
  border: 1px solid rgba(22, 106, 69, 0.14);
  border-radius: 16px;
  background: #ffffff;
  padding: 14px;
}

.category-evaluator-card-head {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: flex-start;
}

.category-evaluator-card-head span {
  display: inline-flex;
  width: fit-content;
  border-radius: 999px;
  background: #eaf7ef;
  padding: 4px 9px;
  color: #166a45;
  font-size: 0.72rem;
  font-weight: 900;
}

.category-evaluator-card-head strong {
  display: block;
  margin-top: 7px;
  color: #10201b;
  font-size: 0.96rem;
  font-weight: 900;
}

.category-evaluator-card-head small {
  display: block;
  margin-top: 4px;
  color: #64748b;
  font-size: 0.78rem;
  font-weight: 700;
}

.category-evaluator-score {
  flex: 0 0 auto;
  min-width: 70px;
  border-radius: 14px;
  background: #eff6ff;
  padding: 8px 10px;
