/* ── Personal Performance Summary (PHP) ────────────────────────────── */
.pps-hero {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 20px;
  align-items: center;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 18px;
  background: var(--theme-surface, #ffffff);
  padding: 20px 24px;
  margin-bottom: 18px;
  box-shadow: 0 12px 28px rgba(31, 54, 45, 0.08);
}

.pps-hero-eyebrow {
  display: block;
  font-size: 0.78rem;
  font-weight: 800;
  color: var(--theme-primary, #166a45);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 4px;
}

.pps-hero h2 {
  margin: 0;
  font-size: clamp(1.35rem, 2.5vw, 1.8rem);
  font-weight: 900;
  color: var(--theme-text, #10201b);
}

.pps-hero p {
  margin: 6px 0 0;
  color: var(--theme-muted, #4d5f57);
  font-size: 0.9rem;
  line-height: 1.5;
  max-width: 600px;
}

.pps-hero-chart {
  display: grid;
  grid-template-columns: 120px 1fr;
  align-items: center;
  gap: 16px;
  border: 1px solid var(--theme-border, #dbe7e1);
  border-radius: 18px;
  background: var(--theme-primary-soft, #e6f6ec);
  padding: 16px;
  min-width: 320px;
}

.pps-hero-chart .completion-donut {
  width: 112px;
  height: 112px;
  background: rgba(22, 106, 69, 0.06);
  border-radius: 999px;
}

.pps-hero-chart .completion-donut strong {
  font-size: 1.15rem;
}

.pps-hero-chart .completion-donut span {
  font-size: 0.68rem;
  font-weight: 800;
  color: var(--theme-muted, #4d5f57);
  text-transform: uppercase;
}

.pps-hero-stats {
  display: grid;
  gap: 6px;
}

.pps-hero-stat {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--theme-muted, #4d5f57);
}

.pps-hero-stat-dot {
  display: grid;
  width: 18px;
  height: 18px;
  place-items: center;
  font-size: 0.55rem;
  flex-shrink: 0;
}

.pps-hero-stat-dot.is-safe { color: #166a45; }
.pps-hero-stat-dot.is-warning { color: #b45309; }
.pps-hero-stat-dot.is-info { color: #2563eb; }
.pps-hero-stat-dot.is-accent { color: #7c3aed; }

.pps-insight-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 16px;
  margin-bottom: 18px;
}

.pps-insight-card {
  border-radius: 16px;
  padding: 16px;
}

.pps-insight-card.is-strength {
  border: 1px solid #b5e5c9;
  background: #effaf3;
}

.pps-insight-card.is-weakness {
  border: 1px solid #fde68a;
  background: #fffbeb;
}

.pps-insight-card.is-recommendation {
  border: 1px solid #bfdbfe;
  background: #eff6ff;
}

.pps-insight-head {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}

.pps-insight-icon {
  display: grid;
  width: 36px;
  height: 36px;
  place-items: center;
  border-radius: 10px;
  flex-shrink: 0;
  font-size: 0.9rem;
}

.is-strength .pps-insight-icon {
  background: #d9f2e2;
  color: #166a45;
}

.is-weakness .pps-insight-icon {
  background: #fef3c7;
  color: #b45309;
}

.is-recommendation .pps-insight-icon {
  background: #dbeafe;
  color: #2563eb;
}

.pps-insight-label {
  display: block;
  font-size: 0.78rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.is-strength .pps-insight-label {
  color: #166a45;
}

.is-weakness .pps-insight-label {
  color: #b45309;
}

.is-recommendation .pps-insight-label {
  color: #2563eb;
}

.pps-insight-subtitle {
  font-size: 0.88rem;
}

.is-strength .pps-insight-subtitle {
  color: #123d35;
}

.is-weakness .pps-insight-subtitle {
  color: #78350f;
}

.is-recommendation .pps-insight-subtitle {
  color: #1e3a8a;
}

.pps-insight-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 0;
  border-bottom: 1px solid rgba(22, 106, 69, 0.1);
  font-size: 0.88rem;
}

.is-strength .pps-insight-row {
  border-color: rgba(22, 106, 69, 0.1);
}

.is-weakness .pps-insight-row {
  border-color: rgba(180, 83, 9, 0.1);
}

.is-strength .pps-insight-row span {
  color: #18584c;
  font-weight: 700;
}

.is-weakness .pps-insight-row span {
  color: #92400e;
  font-weight: 700;
}

.is-strength .pps-insight-row strong {
  color: #166a45;
}

.is-weakness .pps-insight-row strong {
  color: #b45309;
}

.pps-recommendation-item {
  padding: 10px 0;
  border-bottom: 1px solid rgba(37, 99, 235, 0.1);
}

.pps-recommendation-item:last-child {
  border-bottom: none;
}

.pps-recommendation-item strong {
  display: block;
  color: #1e40af;
  font-size: 0.85rem;
}

.pps-recommendation-item p {
  margin: 4px 0 0;
  color: #475569;
  font-size: 0.82rem;
  line-height: 1.45;
}

.pps-empty-text {
  color: #64748b;
  font-size: 0.88rem;
}

.pps-section-title {
  margin-top: 8px;
}

.pps-table-status {
  color: #166a45;
  font-weight: 800;
}

