.evaluator-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: grid;
  place-items: center;
  background: rgba(15, 23, 42, 0.52);
  padding: 20px;
}

.evaluator-detail-modal {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  width: min(1120px, calc(100vw - 40px));
  height: min(860px, 90vh);
  max-width: 100%;
  max-height: 90vh;
  overflow: hidden;
  border-radius: 18px;
  background: #ffffff;
  box-shadow: 0 28px 80px rgba(15, 23, 42, 0.28);
}

.evaluator-modal-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.18);
  padding: 18px 20px;
}

.evaluator-modal-head h3 {
  margin: 0;
  color: #172033;
  font-size: 1.2rem;
  font-weight: 950;
}

.evaluator-modal-head span {
  color: #64748b;
  font-size: 0.82rem;
  font-weight: 800;
}

.evaluator-modal-head button {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 10px;
  background: #ffffff;
  color: #334155;
  cursor: pointer;
}

.evaluator-detail-grid {
  display: grid;
  grid-template-columns: 260px minmax(0, 1fr);
  height: 100%;
  min-height: 0;
  overflow: hidden;
}

.evaluator-detail-sidebar {
  display: grid;
  align-content: start;
  gap: 12px;
  border-right: 1px solid rgba(148, 163, 184, 0.18);
  background: #f8fafc;
  padding: 18px;
}

.evaluator-detail-sidebar div {
  display: grid;
  gap: 4px;
}

.evaluator-detail-sidebar span {
  color: #64748b;
  font-size: 0.72rem;
  font-weight: 900;
  text-transform: uppercase;
}

.evaluator-detail-sidebar strong {
  color: #172033;
  font-weight: 950;
}

.evaluator-detail-categories {
  display: grid;
  gap: 12px;
  align-content: start;
  min-width: 0;
  max-width: 100%;
  min-height: 0;
  height: 100%;
  overflow-x: auto;
  overflow-y: auto;
  padding: 18px;
  scrollbar-gutter: stable;
  scrollbar-width: thin;
  scrollbar-color: #4386cf rgba(15, 35, 59, 0.72);
}

