  .evaluator-detail-grid {
    grid-template-columns: 1fr;
    max-height: calc(100dvh - 105px);
    overflow-y: auto;
  }

  .evaluator-detail-sidebar {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    border-right: 0;
    border-bottom: 1px solid rgba(148, 163, 184, 0.18);
  }

  .evaluator-detail-sidebar > :first-child {
    grid-column: 1 / -1;
  }

  .evaluator-detail-categories {
    overflow: visible;
    padding: 14px;
  }

  .evaluator-category-card {
    overflow: hidden;
  }

