/* Teacher dashboard: dean-inspired color, glow, and motion */
.role-dashboard-content:has(.faculty-dashboard-hero) {
  --faculty-primary: #166a45;
  --faculty-strong: #0f5138;
  --faculty-mint: #2e965f;
  --faculty-sky: #5da8ff;
  --faculty-gold: #f59e0b;
}

.faculty-dashboard-hero {
  position: relative;
  isolation: isolate;
  min-height: 270px;
  border-color: rgba(46, 150, 95, 0.24) !important;
  background:
    radial-gradient(circle at 84% 28%, rgba(93, 168, 255, 0.24), transparent 34%),
    linear-gradient(135deg, rgba(255, 255, 255, 0.98), rgba(239, 250, 243, 0.92)) !important;
  box-shadow:
    0 26px 58px rgba(15, 81, 56, 0.14),
    0 0 38px rgba(46, 150, 95, 0.14),
    inset 0 1px 0 rgba(255, 255, 255, 0.78) !important;
  overflow: hidden;
  animation: facultyPanelIn 0.65s cubic-bezier(0.16, 1, 0.3, 1) both;
}

.faculty-dashboard-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background:
    linear-gradient(90deg, rgba(22, 106, 69, 0.08) 1px, transparent 1px),
    linear-gradient(0deg, rgba(93, 168, 255, 0.08) 1px, transparent 1px);
  background-size: 44px 44px;
  mask-image: linear-gradient(90deg, #000 0%, transparent 72%);
  animation: facultyGridDrift 15s linear infinite;
}

.faculty-dashboard-hero::after {
  content: "";
  position: absolute;
  right: -120px;
  top: -120px;
  z-index: -1;
  width: 340px;
  height: 340px;
  border-radius: 999px;
  pointer-events: none;
  background: radial-gradient(circle, rgba(93, 168, 255, 0.3), rgba(46, 150, 95, 0.16) 48%, transparent 70%);
  animation: facultyGlowPulse 3.8s ease-in-out infinite;
}

.faculty-dashboard-hero .eyebrow {
  color: var(--faculty-primary) !important;
  text-shadow: 0 0 18px rgba(46, 150, 95, 0.24);
}

.faculty-dashboard-hero h2 {
  color: #07120f !important;
}

.faculty-dashboard-hero p:not(.eyebrow) {
  color: #40544b !important;
  font-weight: 650;
}

.faculty-dashboard-hero .hero-illustration {
  position: relative;
  min-height: 220px;
  overflow: hidden;
  border: 1px solid rgba(93, 168, 255, 0.24) !important;
  border-radius: 18px;
  background: linear-gradient(135deg, rgba(7, 18, 15, 0.9), rgba(15, 81, 56, 0.74)) !important;
  box-shadow:
    inset 0 0 34px rgba(93, 168, 255, 0.2),
    0 20px 44px rgba(15, 81, 56, 0.18) !important;
}

.faculty-dashboard-hero .hero-campus-building {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.44;
  filter: saturate(1.12) contrast(1.06);
  transform: scale(1.05);
  animation: facultyCampusPan 13s ease-in-out infinite alternate;
