      conic-gradient(var(--preview-ring-fill, #1f7a4f) 0%, var(--preview-ring-track, #dce8e1) 0);
  }
  to {
    background:
      radial-gradient(circle at center, var(--preview-ring-center, #ffffff) 58%, transparent 60%),
      conic-gradient(var(--preview-ring-fill, #1f7a4f) var(--preview-score, 0%), var(--preview-ring-track, #dce8e1) 0);
  }
}

