/* Report workspace refinement: compact, responsive, and easier to scan. */
.role-report-workspace {
  gap: clamp(14px, 2vw, 22px);
}

.role-report-hero {
  display: grid;
  grid-template-columns: 1fr;
  gap: 18px;
  padding: clamp(18px, 2.4vw, 28px);
}

.role-report-hero-copy {
  max-width: 920px;
}

.role-report-hero h2 {
  max-width: 720px;
  font-size: clamp(1.45rem, 2.1vw, 2.2rem);
  line-height: 1.08;
}

.role-report-hero p {
  max-width: 780px;
}

.role-report-section-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}

.role-report-section-nav a {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 34px;
  border: 1px solid rgba(15, 118, 110, 0.18);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.78);
  color: #0f766e;
  padding: 0 12px;
  font-size: 0.78rem;
  font-weight: 900;
  text-decoration: none;
}

.role-report-section-nav a:hover {
  border-color: rgba(15, 118, 110, 0.34);
  background: #ecfdf5;
}

.role-report-controls {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  align-items: end;
  gap: 12px;
  width: 100%;
  padding: 14px;
}

.role-report-controls label,
.role-report-export label {
  min-width: 0;
}

.role-report-controls select,
.role-report-export select,
.role-report-search span {
  width: 100%;
  min-width: 0;
}

.role-report-search input {
  width: 100%;
}

.role-report-export {
  display: grid;
  grid-template-columns: minmax(120px, 1fr) auto;
  align-items: end;
}

.role-report-export button {
  white-space: nowrap;
}

.role-report-section {
  padding: clamp(14px, 2vw, 20px);
}

.role-report-section-title {
  gap: 12px;
}

.role-report-section-title > div {
  min-width: 0;
}

.role-report-section-title p {
  max-width: 760px;
}

.role-report-metrics {
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
}

.role-report-summary-grid,
.role-report-overall {
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
}

.role-report-summary-grid .wide,
.role-report-overall .wide {
  grid-column: 1 / -1;
}

.role-report-metrics article,
.role-report-summary-grid article,
.role-report-overall article,
.role-report-analytics-grid article {
  min-width: 0;
  padding: 15px 16px;
}

.role-report-summary-grid strong,
.role-report-overall strong,
.role-report-summary-grid p,
.role-report-overall p {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
}

.role-report-summary-grid strong,
.role-report-overall strong {
  -webkit-line-clamp: 3;
}

.role-report-summary-grid p,
.role-report-overall p {
  -webkit-line-clamp: 4;
}

.role-report-analytics-grid {
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.role-report-analytics-grid article {
  min-height: unset;
}

.role-report-bar-row,
.role-report-program-list > div,
.role-report-distribution > div {
  grid-template-columns: minmax(0, 1.15fr) minmax(110px, 0.85fr) auto;
  gap: 12px;
}

.role-report-bar-row strong {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-height: 1.25;
}

.role-report-result-layout {
  grid-template-columns: minmax(230px, 300px) minmax(0, 1fr);
}

.role-report-category-sidebar {
  max-height: 560px;
  overflow: auto;
}

.role-report-category-sidebar button {
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  column-gap: 12px;
  min-height: unset;
  padding: 10px 11px;
}

.role-report-category-sidebar strong {
  display: -webkit-box;
  grid-column: 1;
  grid-row: 1;
  min-width: 0;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.role-report-category-sidebar span {
  grid-column: 2;
  grid-row: 1;
  align-self: start;
  justify-self: end;
  font-size: 0.82rem;
  white-space: nowrap;
}

.role-report-category-sidebar em {
  grid-column: 1 / -1;
  grid-row: 2;
  justify-self: end;
  white-space: nowrap;
}

.role-report-category-head {
  flex-wrap: wrap;
}

.role-report-result-summary {
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
}

.role-report-score-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  max-width: 560px;
}

.role-report-score-pills span,
.role-report-score-pills small,
.role-report-muted {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 28px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 999px;
  background: #f8fafc;
  color: #475569;
  padding: 0 10px;
  font-size: 0.75rem;
  font-weight: 850;
}

.role-report-score-pills strong {
  max-width: 180px;
  overflow: hidden;
  color: #10221f;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.role-report-score-pills em {
  color: #0f766e;
  font-style: normal;
  font-weight: 950;
  white-space: nowrap;
}

.role-report-score-pills small {
  background: #ecfdf5;
  color: #0f766e;
}

.role-report-table {
  min-width: 980px;
}

.role-report-table th,
.role-report-table td {
  padding: 11px 12px;
}

@media (max-width: 1180px) {
  .role-report-result-layout {
    grid-template-columns: 1fr;
  }

  .role-report-category-sidebar {
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    max-height: none;
    border-right: 0;
    border-bottom: 1px solid rgba(226, 232, 240, 0.95);
  }
