  animation-delay: calc(var(--report-row-index, 0) * 45ms);
}

.role-report-bar-row b,
.role-report-program-list b,
.role-report-distribution b {
  transform-origin: left center;
  animation: role-report-bar-grow 650ms cubic-bezier(0.22, 1, 0.36, 1) both;
  animation-delay: calc(100ms + (var(--report-row-index, 0) * 45ms));
}

.role-report-program-list > div {
  grid-template-columns: minmax(220px, 1.35fr) minmax(220px, 1fr) 48px;
  min-height: 38px;
}

.role-report-program-list span {
  overflow: visible;
  text-overflow: clip;
