  line-height: 1.25;
}

.role-report-analytics-grid {
  animation: role-report-analytics-enter 320ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes role-report-analytics-enter {
  from {
    transform: translateY(8px);
    opacity: 0;
  }

  to {
    transform: translateY(0);
    opacity: 1;
  }
}

@keyframes role-report-row-enter {
  from {
    transform: translateY(7px);
    opacity: 0;
  }

  to {
    transform: translateY(0);
    opacity: 1;
  }
}

@keyframes role-report-bar-grow {
  from {
    transform: scaleX(0);
  }

  to {
    transform: scaleX(1);
  }
}

.role-report-individual-section {
