/* Dean Self Evaluation Review */
.dean-self-review {
  position: relative;
  display: grid;
  gap: 1.25rem;
  padding-bottom: 5.5rem;
  border-radius: 18px;
  font-family: Inter, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background:
    linear-gradient(135deg, rgba(239, 250, 243, 0.96), rgba(255, 255, 255, 0.9) 42%, rgba(230, 246, 236, 0.88)),
    linear-gradient(90deg, rgba(255, 255, 255, 0.95) 0%, rgba(255, 255, 255, 0.82) 48%, rgba(255, 255, 255, 0.5) 100%),
    url('/assets/images/pmas-campus-bg.jpg') right 8% top / min(54vw, 720px) auto no-repeat;
  background-attachment: local;
}

.dean-self-review-head {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  gap: 1.25rem;
  overflow: hidden;
  border: 1px solid rgba(22, 131, 88, 0.16);
  border-radius: 22px;
  background:
    linear-gradient(90deg, rgba(236, 250, 244, 0.94) 0%, rgba(246, 253, 249, 0.9) 48%, rgba(255, 255, 255, 0.5) 100%),
    radial-gradient(circle at 94% 12%, rgba(34, 160, 107, 0.12), transparent 34%);
  padding: 26px 22px 28px;
  box-shadow: none;
  backdrop-filter: blur(10px);
}

.dean-self-review-head > *:not(.dean-self-review-campus) {
  position: relative;
  z-index: 1;
}

.dean-self-review-campus {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, rgba(236, 250, 244, 0.96) 0%, rgba(246, 253, 249, 0.88) 54%, rgba(255, 255, 255, 0.2) 100%),
    linear-gradient(180deg, rgba(239, 250, 243, 0.08), rgba(12, 52, 37, 0.08)),
    url('/assets/images/pmas-campus-bg.jpg') right center / min(60%, 780px) auto no-repeat;
  opacity: 0.78;
}

.dean-self-review-campus::after {
  content: "";
  position: absolute;
  inset: auto 0 0;
  height: 1px;
  background: rgba(22, 131, 88, 0.2);
}

.dean-self-review-title {
  display: block;
  min-width: 0;
  max-width: 880px;
}

.dean-self-review-building {
  display: none;
}

.dean-self-review-building::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.82), rgba(236, 253, 245, 0.5));
}

.dean-self-review-building svg {
  position: relative;
  z-index: 1;
  filter: drop-shadow(0 4px 10px rgba(15, 81, 56, 0.14));
}

.dean-self-review-building::after {
  content: "";
  position: absolute;
  inset: auto 10px 9px;
  height: 3px;
  border-radius: 999px;
  background: rgba(31, 122, 79, 0.18);
}

.dean-self-review-title h2,
.dean-self-review-title p {
  min-width: 0;
}

.dean-self-review-title .eyebrow {
  margin: 0 0 10px;
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 850;
  letter-spacing: 0;
  line-height: 1.2;
  text-transform: uppercase;
  color: #506175;
}

.dean-self-review-title h2 {
  margin: 0;
  font-family: inherit;
  font-size: clamp(2rem, 4vw, 2.55rem);
  font-weight: 900;
  letter-spacing: 0;
  line-height: 1.08;
  color: #10201b;
}

.dean-self-review-title p:not(.eyebrow) {
  margin: 12px 0 0;
  max-width: 760px;
  font-family: inherit;
  font-size: clamp(1rem, 1.7vw, 1.12rem);
  font-weight: 600;
  letter-spacing: 0;
  line-height: 1.55;
  color: #53645e;
}

.dean-self-review-actions,
.dean-self-reopen-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.dean-self-review-actions {
  align-content: center;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  backdrop-filter: blur(8px);
}

.dean-self-review-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.85rem;
}

.dean-self-review-card {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.85rem;
  padding: 1rem;
  overflow: hidden;
  border: 1px solid rgba(22, 131, 88, 0.14);
  border-radius: 14px;
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.96), rgba(248, 253, 250, 0.9)),
    radial-gradient(circle at 92% 12%, rgba(34, 160, 107, 0.12), transparent 38%);
  box-shadow: 0 14px 34px rgba(15, 81, 56, 0.09);
  transition: transform 180ms ease, border-color 180ms ease, box-shadow 180ms ease;
}

.dean-self-review-card::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(120deg, rgba(255, 255, 255, 0.26), transparent 42%);
}

.dean-self-review-card > * {
  position: relative;
  z-index: 1;
}

.dean-self-review-card:hover {
  transform: translateY(-2px);
  border-color: rgba(22, 131, 88, 0.28);
  box-shadow: 0 20px 42px rgba(15, 81, 56, 0.14);
}

.dean-self-review-card > span {
  display: grid;
  width: 2.35rem;
  height: 2.35rem;
  place-items: center;
  border-radius: 12px;
  color: #047857;
  background: rgba(16, 185, 129, 0.12);
}

.dean-self-review-card strong {
  display: block;
  color: var(--text-primary, #0f172a);
  font-size: 1.35rem;
  line-height: 1;
}

.dean-self-review-card small {
  color: var(--text-muted, #64748b);
  font-weight: 700;
}

.dean-self-review-card.tone-warning > span {
  color: #b45309;
  background: rgba(245, 158, 11, 0.14);
}

.dean-self-review-card.tone-success > span {
  color: #047857;
  background: rgba(16, 185, 129, 0.14);
}

.dean-self-review-card.tone-danger > span {
  color: #b91c1c;
  background: rgba(239, 68, 68, 0.12);
}

.dean-self-review-panel {
  display: grid;
  gap: 1rem;
  padding: 1.1rem;
  border: 1px solid rgba(22, 131, 88, 0.16);
  border-radius: 16px;
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.97), rgba(248, 253, 250, 0.92)),
    radial-gradient(circle at 12% 0%, rgba(34, 160, 107, 0.1), transparent 34%);
  box-shadow: 0 18px 46px rgba(15, 81, 56, 0.1);
  scroll-margin-top: 92px;
}

.dean-self-review-toolbar {
  display: grid;
  grid-template-columns: minmax(220px, 1.3fr) repeat(2, minmax(150px, 0.75fr));
  gap: 0.75rem;
}

.dean-self-review-toolbar label {
  display: flex;
  align-items: center;
  gap: 0.55rem;
}

.dean-self-review-toolbar label,
.dean-self-review-toolbar select,
.dean-self-review-notes textarea,
.dean-self-reopen-modal textarea {
  width: 100%;
  border: 1px solid var(--border-color, rgba(15, 23, 42, 0.14));
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.92);
  color: var(--text-primary, #0f172a);
  box-shadow: 0 8px 18px rgba(15, 81, 56, 0.04);
  transition: border-color 180ms ease, box-shadow 180ms ease, transform 180ms ease;
}

.dean-self-review-toolbar label:focus-within,
.dean-self-review-toolbar select:focus {
  border-color: rgba(22, 131, 88, 0.42);
  box-shadow: 0 0 0 4px rgba(22, 131, 88, 0.12);
}

.dean-self-review-toolbar input,
.dean-self-review-toolbar select {
  min-height: 2.65rem;
  border: 0;
  background: transparent;
  color: inherit;
  outline: 0;
}

.dean-self-review-toolbar select {
  padding: 0 0.75rem;
  border: 1px solid var(--border-color, rgba(15, 23, 42, 0.14));
}

.dean-self-review-table-wrap {
  overflow-x: auto;
  border: 1px solid rgba(22, 131, 88, 0.12);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.86);
}

.dean-self-review-pagination {
  display: grid;
  grid-template-columns: minmax(220px, 1fr) auto auto;
  gap: 0.85rem;
  align-items: center;
  padding: 0.8rem 0.9rem;
  border: 1px solid rgba(22, 131, 88, 0.14);
