  bottom: 7.5rem;
  z-index: 75;
  display: grid;
  gap: 0.65rem;
  pointer-events: none;
}

.dean-self-review-fab button {
  pointer-events: auto;
  display: grid;
  width: 3.1rem;
  min-height: 3.1rem;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.72);
  border-radius: 16px;
  background:
    linear-gradient(145deg, rgba(22, 131, 88, 0.96), rgba(15, 81, 56, 0.94));
  color: #fff;
  padding: 0;
  box-shadow: 0 18px 34px rgba(15, 81, 56, 0.28);
  animation: deanSelfFloat 3.8s ease-in-out infinite;
}

.dean-self-review-fab button:nth-child(2) {
  animation-delay: 520ms;
}

.dean-self-review-fab button:hover {
  animation-play-state: paused;
  transform: translateY(-3px) scale(1.03);
  background:
    linear-gradient(145deg, rgba(28, 150, 95, 0.98), rgba(15, 81, 56, 0.96));
  box-shadow: 0 22px 42px rgba(15, 81, 56, 0.34);
}

.dean-self-review-fab button:disabled {
  cursor: not-allowed;
  opacity: 0.7;
}

@keyframes deanSelfFloat {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-5px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .dean-self-review-card,
  .dean-self-review-fab button,
  .dean-self-review-table tbody tr {
    animation: none;
    transition: none;
  }
}

.dean-self-status.approved-by-dean {
  color: #047857;
  background: rgba(16, 185, 129, 0.14);
}

.dean-self-status.reopened-for-revision {
  color: #b45309;
  background: rgba(245, 158, 11, 0.16);
}

.dean-self-status.submitted-to-admin {
  color: #4338ca;
  background: rgba(99, 102, 241, 0.14);
}

.dean-self-review-skeleton {
  display: grid;
  gap: 0.75rem;
}

.dean-self-review-skeleton span {
  min-height: 4.25rem;
  border-radius: 8px;
  background: linear-gradient(90deg, rgba(148, 163, 184, 0.16), rgba(148, 163, 184, 0.28), rgba(148, 163, 184, 0.16));
  background-size: 200% 100%;
  animation: skeletonPulse 1.4s ease infinite;
}

.dean-self-review-modal-backdrop {
  position: fixed;
  inset: 64px 0 0;
  height: calc(100dvh - 64px);
  z-index: 1200;
  display: grid;
  place-items: center;
  padding: clamp(0.75rem, 2vw, 1.75rem);
  background: rgba(15, 23, 42, 0.5);
  backdrop-filter: blur(10px);
}

.dean-self-review-modal,
.dean-self-reopen-modal {
  width: min(1480px, calc(100% - clamp(1rem, 3vw, 3.5rem)));
  max-width: 100%;
  max-height: calc(100dvh - 80px);
  overflow: hidden;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  gap: 0.85rem;
  padding: 0.9rem;
  scrollbar-gutter: stable;
  border: 1px solid rgba(22, 131, 88, 0.18);
  border-radius: 18px;
  background:
    linear-gradient(180deg, rgba(248, 253, 250, 0.98), rgba(255, 255, 255, 0.98)),
    radial-gradient(circle at 100% 0%, rgba(16, 185, 129, 0.12), transparent 34%);
  color: var(--text-primary, #0f172a);
  box-shadow: 0 28px 80px rgba(15, 23, 42, 0.34);
  animation: deanSelfModalIn 160ms ease-out;
}

.dean-self-review-modal-scroll {
  display: grid;
  align-content: start;
  gap: 0.85rem;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  padding-right: 0.2rem;
  scrollbar-gutter: stable;
  scrollbar-width: thin;
  scrollbar-color: rgba(22, 131, 88, 0.62) rgba(22, 131, 88, 0.08);
}

.dean-self-review-modal-scroll::-webkit-scrollbar {
  width: 10px;
}

.dean-self-review-modal-scroll::-webkit-scrollbar-track {
  border-radius: 999px;
  background: rgba(22, 131, 88, 0.08);
}

.dean-self-review-modal-scroll::-webkit-scrollbar-thumb {
  border: 2px solid transparent;
  border-radius: 999px;
  background: rgba(22, 131, 88, 0.62);
  background-clip: padding-box;
}

.dean-self-review-modal.compact {
