/* Admin monitor self-evaluation submission section */
.self-eval-submission-section {
  border: 1px solid var(--border-color, rgba(15, 23, 42, 0.12));
  border-radius: 8px;
  background: rgba(16, 185, 129, 0.04);
}

.eval-monitor-empty.compact {
  min-height: 0;
  padding: 1rem;
  border-radius: 8px;
}

.self-eval-admin-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.55rem;
  flex-wrap: wrap;
}

.self-eval-submission-section {
  overflow: hidden;
  border: 1px solid #cbe2d7;
  border-radius: 16px;
  background: var(--theme-surface, #fff);
  transition: border-color .2s ease, box-shadow .2s ease;
}

.self-eval-submission-section.is-open {
  border-color: #9fd3ba;
  box-shadow: 0 12px 28px rgba(13, 111, 73, .08);
}

.self-eval-submission-section > .eval-monitor-section-head {
  flex-wrap: nowrap;
  min-height: 70px;
  padding: 10px 12px;
  background: linear-gradient(135deg, #f1faf6, #f8fcfa);
}

.self-eval-submission-toggle {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) 34px;
  align-items: center;
  gap: 11px;
  min-width: 280px;
  flex: 1 1 auto;
  border: 0;
  border-radius: 12px;
  background: transparent;
  padding: 4px;
  color: #174b39;
  text-align: left;
  cursor: pointer;
  transition: background .18s ease;
}

.self-eval-submission-toggle:hover,
.self-eval-submission-toggle:focus-visible {
  background: rgba(17, 139, 91, .07);
  outline: none;
}

.self-eval-submission-toggle-icon {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 12px;
  background: #e0f5ea;
  color: #08734d;
}

.self-eval-submission-toggle > span:nth-child(2) {
  display: grid;
  gap: 3px;
}

.self-eval-submission-toggle strong { font-size: .88rem; }
.self-eval-submission-toggle small {
  color: #71837b;
  font-size: .68rem;
  font-weight: 650;
}

.self-eval-submission-chevron {
  color: #35735b;
  transition: transform .22s ease;
}

.self-eval-submission-section.is-open .self-eval-submission-chevron {
  transform: rotate(180deg);
}

.self-eval-submission-content {
  display: grid;
  gap: 12px;
  padding: 0 14px 14px;
  animation: evalMonitorListIn .2s ease both;
}

.admin-body.dark-mode .self-eval-submission-section,
.admin-dashboard-body.dark-mode .self-eval-submission-section {
  border-color: #294866;
  background: #101f34;
}

.admin-body.dark-mode .self-eval-submission-section > .eval-monitor-section-head,
.admin-dashboard-body.dark-mode .self-eval-submission-section > .eval-monitor-section-head {
  background: linear-gradient(135deg, #142b45, #102139);
}

.admin-body.dark-mode .self-eval-submission-toggle,
.admin-dashboard-body.dark-mode .self-eval-submission-toggle {
  color: #e5f2ff;
}

.admin-body.dark-mode .self-eval-submission-toggle-icon,
.admin-dashboard-body.dark-mode .self-eval-submission-toggle-icon {
  background: rgba(49, 134, 220, .18);
  color: #8bc9ff;
}

@media (max-width: 760px) {
  .self-eval-submission-section > .eval-monitor-section-head {
