/* Role-based chatbot page guide */
.page-chatbot-intro {
  position: fixed;
  right: 166px;
  bottom: 34px;
  z-index: 88;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: start;
  gap: 10px;
  width: min(360px, calc(100vw - 196px));
  padding: 12px 12px 12px 14px;
  border: 1px solid rgba(22, 131, 88, 0.14);
  border-radius: 14px;
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.98), rgba(246, 253, 249, 0.96)),
    radial-gradient(circle at 100% 0%, rgba(34, 160, 107, 0.08), transparent 38%);
  color: #10201b;
  box-shadow: 0 16px 36px rgba(15, 81, 56, 0.14);
  backdrop-filter: blur(12px);
  pointer-events: auto;
  transform: translateY(18px) scale(0.965);
  opacity: 0;
  filter: blur(2px);
  transition:
    opacity 360ms cubic-bezier(0.16, 1, 0.3, 1),
    transform 420ms cubic-bezier(0.16, 1, 0.3, 1),
    filter 360ms ease;
  will-change: opacity, transform, filter;
}

.page-chatbot-intro.is-visible {
  transform: translateY(0) scale(1);
  opacity: 1;
  filter: blur(0);
}

.page-chatbot-intro.is-hidden {
  pointer-events: none;
  transform: translateY(10px) scale(0.985);
  opacity: 0;
  filter: blur(1px);
}

.page-chatbot-intro-icon {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border: 1px solid rgba(22, 131, 88, 0.16);
  border-radius: 11px;
  background: #e8f6ef;
  color: #166a45;
  box-shadow: none;
  transform: translateY(1px);
  transition: transform 420ms cubic-bezier(0.16, 1, 0.3, 1);
}

.page-chatbot-intro.is-visible .page-chatbot-intro-icon {
  transform: translateY(0);
}

.page-chatbot-intro-copy {
  min-width: 0;
}

.page-chatbot-intro-copy strong {
  display: block;
  color: #0f5138;
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.page-chatbot-intro-copy p {
  margin: 4px 0 0;
  color: #4d5f57;
  font-size: 0.8rem;
  font-weight: 700;
  line-height: 1.42;
}

.page-chatbot-intro-close {
  display: grid;
  width: 28px;
  min-height: 28px;
  place-items: center;
  align-self: start;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: #166a45;
  padding: 0;
}

.page-chatbot-intro-close:hover {
  background: #e8f6ef;
  transform: translateY(-1px);
}

