/* View-details portal: always centered against the viewport, never the page container. */
.program-ai-faculty-modal {
  position: fixed !important;
  inset: 0 !important;
  z-index: 10000 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 100vw;
  height: 100dvh;
  overflow: hidden !important;
  padding: clamp(12px, 2vw, 28px);
  animation: program-ai-modal-backdrop-in 0.2s ease-out both;
}

.program-ai-faculty-modal-panel {
  width: min(1560px, calc(100vw - clamp(24px, 4vw, 56px)));
  max-height: 85dvh !important;
  overflow-x: hidden !important;
  overflow-y: auto !important;
  overscroll-behavior: contain;
  animation: program-ai-modal-panel-in 0.28s cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes program-ai-modal-backdrop-in {
  from { background-color: rgba(4, 12, 9, 0); }
  to { background-color: rgba(4, 12, 9, 0.48); }
}

@keyframes program-ai-modal-panel-in {
  from {
    opacity: 0;
    transform: translateY(18px) scale(0.975);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@media (max-width: 900px) {
  .program-ai-faculty-modal-panel {
    width: calc(100vw - 24px);
    max-height: 88dvh !important;
  }
}

@media (max-width: 640px) {
  .program-ai-faculty-modal {
    padding: 8px;
  }

  .program-ai-faculty-modal-panel {
    width: calc(100vw - 16px);
    max-height: 92dvh !important;
    border-width: 1px;
    border-radius: 16px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .program-ai-faculty-modal,
  .program-ai-faculty-modal-panel {
    animation: none;
  }
}

