/* Goals Record review — green daylight theme and blue-glow dark theme. */
.goals-record-page {
  --goals-accent: #128158;
  --goals-accent-strong: #075c3e;
  --goals-accent-soft: #e9f8f0;
  --goals-surface: #ffffff;
  --goals-surface-soft: #f4fbf7;
  --goals-text: #142b23;
  --goals-muted: #587067;
  --goals-line: #c9e5d7;
  --goals-glow: rgba(18, 129, 88, .16);
  color: var(--goals-text);
  transition: color .3s ease, background-color .3s ease;
}

.goals-record-page .goals-module-head {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  min-height: 136px;
  border-color: var(--goals-line);
  background:
    radial-gradient(circle at 92% 20%, var(--goals-glow), transparent 30%),
    linear-gradient(135deg, var(--goals-surface) 0%, var(--goals-surface-soft) 100%);
  color: var(--goals-text);
  box-shadow: 0 16px 38px rgba(10, 91, 61, .09);
  transition: border-color .3s ease, background .3s ease, box-shadow .3s ease, transform .25s ease;
}

.goals-module-copy { display: flex; align-items: center; gap: 14px; min-width: 0; }
.goals-module-copy > i,
.goals-review-summary article > i {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 48px;
  height: 48px;
  border: 1px solid color-mix(in srgb, var(--goals-accent) 28%, transparent);
  border-radius: 15px;
  background: linear-gradient(145deg, var(--goals-accent), #20a875);
  color: #fff;
  box-shadow: 0 10px 24px var(--goals-glow);
}
.goals-module-copy > div { min-width: 0; }
.goals-module-copy > div > span { color: var(--goals-accent); font-size: .68rem; font-weight: 900; letter-spacing: .09em; }
.goals-record-page .goals-module-head h2 { color: var(--goals-text); font-size: clamp(1.2rem, 2vw, 1.65rem); }
.goals-record-page .goals-module-head p { max-width: 660px; color: var(--goals-muted); line-height: 1.5; }

.goals-record-page .goals-review-summary { gap: 14px; }
.goals-record-page .goals-review-summary article {
  grid-template-columns: auto 1fr;
  align-items: center;
  gap: 12px;
  min-width: 0;
  min-height: 112px;
  padding: 17px;
