.goals-record-page .goals-review-summary article:nth-child(4) { animation-delay: -2.1s; }
.goals-record-page .goals-review-summary article:nth-child(5) { animation-delay: -2.8s; }
.goals-record-page .goals-review-summary article:hover { transform: translateY(-4px); border-color: var(--goals-accent); box-shadow: 0 16px 34px var(--goals-glow); }
.goals-record-page .goals-review-summary article > i { width: 42px; height: 42px; border-radius: 13px; }
.goals-record-page .goals-review-summary article > div { display: grid; gap: 4px; }
.goals-record-page .goals-review-summary strong { color: var(--goals-accent-strong); font-size: 1.7rem; line-height: 1; }
.goals-record-page .goals-review-summary span { color: var(--goals-muted); font-weight: 750; }
.goals-status-submitted > i { background: linear-gradient(145deg, #158f70, #2bbd93) !important; }
