/* Animated completion rings: keep the percentage and completed arc prominent. */
.role-summary-donut {
  position: relative;
  isolation: isolate;
  background:
    radial-gradient(circle at center, var(--theme-surface, #ffffff) 0 48%, transparent 49%),
    conic-gradient(from -90deg, #10b981 0 var(--pct, 0%), #d9eee5 var(--pct, 0%) 100%) !important;
  box-shadow: 0 10px 26px rgba(16, 185, 129, 0.18), inset 0 0 0 1px rgba(16, 185, 129, 0.12);
  animation: completion-ring-enter 700ms cubic-bezier(.2,.8,.2,1) both;
}

.role-summary-donut::after {
  content: '';
  position: absolute;
  inset: -5px;
  z-index: -1;
  border: 2px solid transparent;
  border-top-color: rgba(16, 185, 129, 0.75);
  border-right-color: rgba(20, 184, 166, 0.3);
  border-radius: 50%;
  filter: drop-shadow(0 0 5px rgba(16, 185, 129, 0.35));
  animation: completion-ring-orbit 2.4s linear infinite;
}

.role-summary-donut strong {
  color: #047857 !important;
  font-weight: 900 !important;
  text-shadow: 0 1px 0 #ffffff, 0 0 10px rgba(16, 185, 129, 0.22);
}

.role-summary-donut span {
  color: #166534 !important;
  font-weight: 800 !important;
}

@keyframes completion-ring-enter {
  from { opacity: 0; transform: scale(.72) rotate(-18deg); }
  to { opacity: 1; transform: scale(1) rotate(0); }
}

@keyframes completion-ring-orbit {
  to { transform: rotate(360deg); }
}

@media (prefers-reduced-motion: reduce) {
  .role-summary-donut,
  .role-summary-donut::after { animation: none; }
}

