/* Integrated login and recovery slider. */
.login-form-viewport{width:100%;overflow:hidden;margin-top:2px;border-radius:18px;transition:height .38s cubic-bezier(.22,.8,.24,1)}
.login-form-track{display:flex;width:200%;align-items:flex-start;transform:translateX(0);transition:transform .48s cubic-bezier(.22,.8,.24,1);will-change:transform}
.login-form-track.show-recovery{transform:translateX(-50%)}
.login-card .login-form-panel{flex:0 0 50%;width:50%;padding:0 2px;box-sizing:border-box;opacity:1;transition:opacity .28s ease,transform .48s cubic-bezier(.22,.8,.24,1)}
.login-form-track.show-recovery .login-form-panel:first-child{opacity:.2;transform:scale(.965)}
.login-form-track:not(.show-recovery) .login-recovery-panel{opacity:.2;transform:scale(.965)}
.login-text-action{width:auto!important;min-height:0!important;padding:2px!important;border:0!important;background:transparent!important;color:#89f2d0!important;box-shadow:none!important;font:inherit;font-weight:750!important;text-decoration:none;cursor:pointer}
.login-text-action:hover{color:#fff!important;text-decoration:underline;transform:none!important}
.login-text-action.admin-recovery-action{padding:6px 9px!important;border:1px solid rgba(122,239,204,.24)!important;border-radius:9px!important;background:rgba(20,136,96,.13)!important;color:#a7f3d0!important;text-decoration:none!important}
.login-text-action.admin-recovery-action:hover{border-color:rgba(122,239,204,.48)!important;background:rgba(28,178,119,.23)!important;color:#fff!important;box-shadow:0 5px 14px rgba(0,0,0,.13)!important}
.login-recovery-heading{display:flex;align-items:center;gap:12px;margin:0 0 3px;padding:13px 14px;border:1px solid rgba(123,239,205,.19);border-radius:14px;background:linear-gradient(135deg,rgba(42,166,119,.19),rgba(12,77,69,.15))}
.login-recovery-heading>div{display:grid;gap:2px;min-width:0}
.login-recovery-heading strong{color:#f4fffb;font-size:.98rem}
.login-recovery-heading span{color:#a9cfc5;font-size:.72rem}
.login-back-button{flex:0 0 36px;width:36px!important;height:36px!important;min-height:36px!important;padding:0!important;display:grid!important;place-items:center;border:1px solid rgba(134,239,208,.25)!important;border-radius:10px!important;background:rgba(6,43,42,.52)!important;color:#b9f5df!important;box-shadow:none!important}
.login-back-button:hover{background:rgba(33,160,112,.3)!important;transform:translateX(-2px)!important}
.login-return-link{width:max-content!important;min-height:32px!important;padding:0 3px!important;display:inline-flex!important;align-items:center;gap:6px;border:0!important;background:transparent!important;color:#b9d8cf!important;box-shadow:none!important;font-size:.78rem;font-weight:750!important}
.login-return-link:hover{color:#fff!important;transform:translateX(-2px)!important}

