/* Primary notification action: clearly opens the related workflow. */
.notification-action-btn{
  width:max-content;
  min-height:34px;
  margin-top:10px;
  padding:0 12px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:7px;
  border:1px solid rgba(16,136,91,.22);
  border-radius:9px;
  background:linear-gradient(135deg,#159764,#08734d);
  color:#fff;
  font-size:.72rem;
  font-weight:800;
  cursor:pointer;
  box-shadow:0 7px 16px rgba(8,115,77,.16);
  transition:transform .18s ease,box-shadow .18s ease,filter .18s ease;
}
.notification-action-btn:hover{
  transform:translateY(-1px);
  filter:brightness(1.06);
  box-shadow:0 10px 20px rgba(8,115,77,.24);
}
.notification-action-btn:active{
  transform:translateY(0) scale(.97);
  filter:brightness(1.18);
  box-shadow:
    0 0 0 4px rgba(74,222,128,.28),
    0 0 22px 8px rgba(34,197,94,.48),
    0 8px 22px rgba(8,115,77,.3);
  transition-duration:.06s;
}
.notification-action-btn:focus-visible{outline:3px solid rgba(34,197,94,.3);outline-offset:2px}
.admin-body.dark-mode .notification-action-btn,
.admin-dashboard-body.dark-mode .notification-action-btn{border-color:rgba(134,239,172,.28);background:linear-gradient(135deg,#1bab70,#0b7751)}
@media(max-width:520px){.notification-action-btn{width:100%}}

