/* Use a coordinated blue edit state instead of the previous green highlight. */
.assignment-schedule-edit-button{
  border:1px solid transparent!important;
  color:#3b82f6!important;
  transition:color .18s ease,background .18s ease,border-color .18s ease,box-shadow .18s ease,transform .18s ease!important;
}
.assignment-schedule-edit-button:hover{
  border-color:rgba(96,165,250,.5)!important;
  background:rgba(59,130,246,.11)!important;
  color:#2563eb!important;
  box-shadow:0 0 14px rgba(59,130,246,.22)!important;
  transform:translateY(-1px);
}
.assignment-schedule-edit-button.is-active,
.assignment-schedule-edit-button[aria-pressed="true"]{
  border-color:#60a5fa!important;
  background:rgba(37,99,235,.16)!important;
  color:#2563eb!important;
  box-shadow:0 0 0 3px rgba(59,130,246,.16),0 0 20px rgba(59,130,246,.38)!important;
}
.assignment-schedule-edit-button:focus-visible{
  outline:2px solid #60a5fa!important;
  outline-offset:3px!important;
  box-shadow:0 0 18px rgba(59,130,246,.36)!important;
}
.admin-body.dark-mode .assignment-schedule-edit-button,
.admin-dashboard-body.dark-mode .assignment-schedule-edit-button{
  color:#93c5fd!important;
}
.admin-body.dark-mode .assignment-schedule-edit-button.is-active,
.admin-dashboard-body.dark-mode .assignment-schedule-edit-button.is-active{
  border-color:#60a5fa!important;
  background:rgba(37,99,235,.24)!important;
  color:#bfdbfe!important;
  box-shadow:0 0 0 3px rgba(59,130,246,.2),0 0 22px rgba(59,130,246,.46)!important;
}
.assignment-schedule-card.is-editing-schedule{
  border-color:#3b82f6!important;
  box-shadow:0 0 0 5px rgba(59,130,246,.14),0 18px 42px rgba(37,99,235,.16)!important;
  animation:assignment-edit-glow-blue 1.15s ease-out;
}
.assignment-edit-mode-badge{
  border-color:rgba(59,130,246,.3)!important;
  background:rgba(219,234,254,.8)!important;
  color:#1d4ed8!important;
}
.assignment-schedule-card.is-editing-schedule .assignment-schedule-input{border-color:rgba(59,130,246,.55)!important}
.assignment-schedule-card.is-editing-schedule .assignment-schedule-input:focus{border-color:#3b82f6!important;box-shadow:0 0 0 4px rgba(59,130,246,.17)!important}
tr.is-selected-for-edit>td{background:rgba(59,130,246,.08)!important}
tr.is-selected-for-edit>td:first-child{box-shadow:inset 4px 0 0 #3b82f6}
.admin-body.dark-mode .assignment-edit-mode-badge,.admin-dashboard-body.dark-mode .assignment-edit-mode-badge{border-color:rgba(96,165,250,.34)!important;background:rgba(30,64,175,.3)!important;color:#bfdbfe!important}
@keyframes assignment-edit-glow-blue{
  0%{transform:scale(.992);box-shadow:0 0 0 0 rgba(59,130,246,.52),0 8px 20px rgba(37,99,235,.08)}
  55%{transform:scale(1);box-shadow:0 0 0 10px rgba(59,130,246,.13),0 22px 48px rgba(37,99,235,.2)}
  100%{box-shadow:0 0 0 5px rgba(59,130,246,.14),0 18px 42px rgba(37,99,235,.16)}
}
@media(prefers-reduced-motion:reduce){.assignment-schedule-card.is-editing-schedule{animation:none}}

/* Presentable Admin Monitor self-evaluation review card. */
.self-eval-submission-section{
  overflow:hidden;
  padding:clamp(16px,2vw,24px)!important;
  border:1px solid rgba(22,151,100,.2)!important;
  border-radius:18px!important;
  background:linear-gradient(145deg,rgba(247,253,250,.98),rgba(237,249,243,.88))!important;
  box-shadow:0 16px 38px rgba(15,81,56,.09)!important;
}
.self-eval-submission-section>.eval-monitor-section-head{
  display:flex;
  align-items:flex-start;
