/* Evaluation gallery — isolated from the workbench's wide assignment rows. */
.admin-body .eval-card-grid,
.admin-dashboard-body .eval-card-grid {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 290px), 1fr));
  align-items: stretch;
  gap: clamp(16px, 1.6vw, 24px);
  padding: clamp(16px, 2vw, 24px);
}

.admin-body .dipascaf-eval-card,
.admin-dashboard-body .dipascaf-eval-card {
  display: flex;
  min-width: 0;
  min-height: 455px;
  flex-direction: column;
  /*
   * These cards are refreshed in the background every few seconds. Replaying
   * their entrance/glow animation after a data refresh makes stable cards look
   * as though they are blinking.
   */
  animation: none !important;
  will-change: auto;
}

.eval-card-grid .dipascaf-eval-card { animation-delay: 0ms !important; }

.admin-body .dipascaf-card-cover,
.admin-dashboard-body .dipascaf-card-cover {
  flex: 0 0 128px;
  min-height: 128px;
  transition: filter 260ms ease, transform 420ms cubic-bezier(.2, .8, .2, 1);
}

.admin-body .dipascaf-eval-card:hover .dipascaf-card-cover,
.admin-dashboard-body .dipascaf-eval-card:hover .dipascaf-card-cover {
  transform: scale(1.025);
  filter: saturate(1.08) brightness(1.04);
}

.admin-body .dipascaf-eval-card .dipascaf-avatar,
.admin-dashboard-body .dipascaf-eval-card .dipascaf-avatar {
  transition: transform 260ms cubic-bezier(.2, .8, .2, 1), box-shadow 260ms ease;
}

.admin-body .dipascaf-eval-card:hover .dipascaf-avatar,
.admin-dashboard-body .dipascaf-eval-card:hover .dipascaf-avatar {
  transform: translateY(-3px) rotate(-1deg);
}

.admin-body .dipascaf-card-actions,
.admin-dashboard-body .dipascaf-card-actions {
  width: auto;
}

.admin-body .dipascaf-card-actions > button,
.admin-dashboard-body .dipascaf-card-actions > button {
  width: 100%;
  min-width: 0;
  position: relative;
  overflow: hidden;
  isolation: isolate;
}

.admin-body .dipascaf-card-actions > button::after,
.admin-dashboard-body .dipascaf-card-actions > button::after {
  position: absolute;
  inset: 0;
  z-index: -1;
  background: linear-gradient(110deg, transparent 20%, rgba(255,255,255,.22) 48%, transparent 76%);
  content: "";
  opacity: 0;
  transform: translateX(-75%);
}

.admin-body .dipascaf-card-actions > button:hover::after,
.admin-dashboard-body .dipascaf-card-actions > button:hover::after {
  opacity: 1;
  transform: translateX(75%);
  transition: opacity 160ms ease, transform 520ms ease;
}

.admin-body .dipascaf-card-actions > button:active,
.admin-dashboard-body .dipascaf-card-actions > button:active {
  transform: translateY(0) scale(.985);
}

.admin-body .dipascaf-card-actions > button:focus-visible,
.admin-dashboard-body .dipascaf-card-actions > button:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--eval-card-primary) 34%, transparent);
  outline-offset: 3px;
}

.admin-body.dark-mode .dipascaf-status.in-progress,
.admin-dashboard-body.dark-mode .dipascaf-status.in-progress {
  border-color: rgba(96, 165, 250, .46);
  background: rgba(59, 130, 246, .18);
  color: #bfdbfe;
}

.admin-body.dark-mode .dipascaf-eval-card,
.admin-dashboard-body.dark-mode .dipascaf-eval-card {
  background:
    radial-gradient(circle at 88% 4%, rgba(96, 165, 250, .11), transparent 30%),
    linear-gradient(165deg, #12233a 0%, #0b1628 58%, #081321 100%) !important;
  border-color: rgba(96, 165, 250, .25) !important;
}

@keyframes evaluationCardEnter {
  from { opacity: 0; transform: translateY(14px) scale(.985); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

@media (max-width: 680px) {
  .admin-body .eval-card-grid,
  .admin-dashboard-body .eval-card-grid {
    grid-template-columns: 1fr;
    padding: 12px 0;
  }

  .admin-body .dipascaf-eval-card,
