  padding-top: 18px;
}
.program-ai-assignment-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: 9px;
}
.program-ai-assignment-summary > span {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 44px;
  border: 1px solid var(--dai-border, #dbe5e1);
  border-radius: 11px;
