}
.program-ai-assignment-summary .completed { border-color:#b9e3cf;background:#edf9f3;color:#08734d }
.program-ai-assignment-summary .pending { border-color:#f1d59d;background:#fff8e9;color:#94600a }
.program-ai-assignment-summary .missing { border-color:#edbbb7;background:#fff2f1;color:#ad352e }
.program-ai-assignment-list { display:grid;gap:9px }
.program-ai-assignment-row {
  display:grid;
  grid-template-columns:auto minmax(0,1fr) auto auto;
  align-items:center;
  gap:11px;
  min-width:0;
  border:1px solid var(--dai-border,#dbe5e1);
