}
.program-ai-assignment-row.is-missing { border-style:dashed;background:#fffafa }
.program-ai-assignment-status {
  display:grid;
  place-items:center;
  width:36px;
  height:36px;
  border-radius:11px;
  background:#eef5f1;
  color:#61736b;
}
.program-ai-assignment-row.is-completed .program-ai-assignment-status { background:#ddf5e9;color:#08734d }
.program-ai-assignment-row.is-pending .program-ai-assignment-status { background:#fff1cf;color:#9b6508 }
.program-ai-assignment-row.is-missing .program-ai-assignment-status { background:#ffe5e3;color:#b33831 }
.program-ai-assignment-row > div { display:grid;min-width:0;gap:3px }
.program-ai-assignment-row > div > strong { color:var(--dai-text,#14231e);font-size:.82rem }
.program-ai-assignment-row > div > small { overflow:hidden;color:var(--dai-muted,#62736c);font-size:.68rem;text-overflow:ellipsis;white-space:nowrap }
.program-ai-dean-required {
  width:max-content;
  margin-top:2px;
  border-radius:999px;
  background:#dcf5e8;
  color:#08734d;
  padding:4px 7px;
  font-size:.61rem;
  text-transform:uppercase;
}
.program-ai-assignment-pill {
  border-radius:999px;
  padding:5px 8px;
  font-size:.62rem;
  font-weight:900;
  text-transform:uppercase;
}
.program-ai-assignment-pill.is-completed { background:#dcf5e8;color:#08734d }
.program-ai-assignment-pill.is-pending { background:#fff0cc;color:#8d5900 }
.program-ai-assignment-pill.is-missing { background:#ffe3e1;color:#ae322c }
.program-ai-assignment-row > button {
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:6px;
  min-height:38px;
  border:0;
  border-radius:10px;
  background:linear-gradient(135deg,#168358,#0f9d70);
  color:#fff;
  padding:0 11px;
  font-size:.7rem;
  font-weight:900;
  cursor:pointer;
  box-shadow:0 8px 18px rgba(22,131,88,.18);
}
.program-ai-assignment-row > button:hover { transform:translateY(-1px);box-shadow:0 11px 22px rgba(22,131,88,.25) }

