/* Dedicated Dean dashboard, aligned visually with the VPAA dashboard. */
.dean-role-dashboard { display:grid; gap:18px; padding:clamp(18px,2vw,28px); border-radius:24px; overflow:hidden; }
.dean-role-dashboard-head { display:flex; align-items:center; justify-content:space-between; gap:18px; }
.dean-live-status { display:inline-flex; align-items:center; gap:8px; flex:0 0 auto; padding:8px 12px; border:1px solid rgba(22,163,74,.22); border-radius:999px; background:rgba(240,253,244,.88); color:#166534; font-size:.78rem; font-weight:800; }
.dean-live-status span { width:8px; height:8px; border-radius:50%; background:#22c55e; box-shadow:0 0 0 5px rgba(34,197,94,.12),0 0 14px rgba(34,197,94,.55); }
.dean-live-status.is-error { color:#b91c1c; border-color:rgba(220,38,38,.25); background:rgba(254,242,242,.9); }
.dean-live-status.is-error span { background:#ef4444; box-shadow:0 0 0 5px rgba(239,68,68,.12); }
.dean-role-dashboard .dashboard-metric-card.metric-danger { --metric-color:#dc2626; }
.dean-evaluation-chart-panel { display:grid; grid-template-columns:minmax(230px,.8fr) minmax(300px,1fr) minmax(190px,.55fr); align-items:center; gap:clamp(18px,3vw,38px); min-height:240px; padding:clamp(18px,2vw,26px); border:1px solid rgba(22,106,69,.18); border-radius:20px; background:radial-gradient(circle at 92% 12%,rgba(59,130,246,.13),transparent 30%),linear-gradient(145deg,rgba(255,255,255,.98),rgba(242,248,252,.95)); box-shadow:0 18px 42px rgba(15,80,55,.09),0 0 30px rgba(59,130,246,.07); overflow:hidden; }
.dean-chart-copy h3 { margin:4px 0 8px; font-size:clamp(1.1rem,1.7vw,1.4rem); }
.dean-chart-copy>p:last-of-type { margin:0; max-width:48ch; color:var(--muted,#64748b); line-height:1.55; }
.dean-chart-total { display:flex; align-items:center; gap:12px; margin-top:18px; }
.dean-chart-total strong { color:#166a45; font-size:2rem; line-height:1; }
.dean-chart-total span { color:var(--muted,#64748b); font-size:.82rem; font-weight:700; }
.dean-pie-wrap { position:relative; min-width:0; height:205px; }
.dean-chart-empty { display:grid; place-items:center; height:100%; color:var(--muted,#64748b); text-align:center; }
.dean-chart-breakdown { display:grid; gap:10px; }
.dean-chart-breakdown>span { display:grid; grid-template-columns:10px minmax(0,1fr) auto; align-items:center; gap:9px; padding:10px 12px; border-radius:12px; background:rgba(255,255,255,.7); font-size:.82rem; font-weight:700; }
.dean-chart-breakdown i { width:9px; height:9px; border-radius:50%; box-shadow:0 0 10px currentColor; }
.dean-chart-breakdown .completed { color:#15803d; }.dean-chart-breakdown .pending { color:#a16207; }.dean-chart-breakdown .overdue { color:#b91c1c; }

/* Faculty dashboard progress and next-action workspace. */
.faculty-dashboard-focus-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(300px, .65fr);
  gap: 18px;
  margin: 22px 0;
}
.faculty-progress-panel,
.faculty-next-action {
  position: relative;
  overflow: hidden;
  min-height: 250px;
  border: 1px solid rgba(22, 131, 88, .2);
  border-radius: 22px;
  background: linear-gradient(135deg, rgba(255,255,255,.94), rgba(239,250,245,.82));
  box-shadow: 0 16px 35px rgba(16, 84, 59, .09);
}
.faculty-progress-panel { display:grid; grid-template-columns:minmax(0,1fr) 270px; align-items:center; padding:24px 28px; }
.faculty-focus-copy h3,
.faculty-next-action h3 { margin:5px 0 9px; color:#092b20; font-size:clamp(1.12rem,1.6vw,1.4rem); }
.faculty-focus-copy>p:not(.eyebrow),
.faculty-next-action>div>p:not(.eyebrow) { margin:0; color:#587067; line-height:1.55; }
.faculty-progress-chart { position:relative; height:205px; min-width:0; }
.faculty-progress-center { position:absolute; inset:0; display:grid; place-content:center; text-align:center; pointer-events:none; }
.faculty-progress-center strong { color:#126b47; font-size:1.9rem; line-height:1; }
.faculty-progress-center span { margin-top:5px; color:#6b7d76; font-size:.7rem; font-weight:800; text-transform:uppercase; letter-spacing:.08em; }
.faculty-progress-empty { height:100%; display:grid; place-content:center; justify-items:center; gap:8px; color:#168358; font-weight:800; }
.faculty-progress-legend { display:flex; flex-wrap:wrap; gap:10px; margin-top:22px; }
.faculty-progress-legend span { display:grid; grid-template-columns:9px auto auto; align-items:center; gap:7px; padding:8px 11px; border-radius:11px; background:rgba(255,255,255,.8); color:#53675f; font-size:.76rem; font-weight:700; }
.faculty-progress-legend i { width:9px; height:9px; border-radius:50%; }
.faculty-progress-legend .submitted i { background:#22c55e; }.faculty-progress-legend .pending i { background:#f59e0b; }
.faculty-progress-legend strong { color:#173d30; }
.faculty-next-action { display:flex; flex-direction:column; align-items:flex-start; padding:24px; }
.faculty-next-action.has-pending { border-color:rgba(217,157,17,.35); background:linear-gradient(145deg,rgba(255,255,255,.96),rgba(255,248,225,.9)); }
.faculty-next-icon { display:grid; place-items:center; width:44px; height:44px; margin-bottom:14px; border-radius:13px; background:#e4f8ed; color:#168358; }
.faculty-next-action.has-pending .faculty-next-icon { background:#fff1c7; color:#b57900; }
.faculty-next-meta { display:flex; align-items:center; gap:7px; margin-top:auto; padding-top:16px; color:#6b7d76; font-size:.77rem; font-weight:700; }
.faculty-next-action>a { display:inline-flex; align-items:center; gap:8px; margin-top:13px; padding:10px 15px; border-radius:999px; background:#168358; color:#fff; font-size:.78rem; font-weight:800; text-decoration:none; box-shadow:0 8px 18px rgba(22,131,88,.2); transition:transform .2s ease,box-shadow .2s ease; }
.faculty-next-action.has-pending>a { background:#b77900; box-shadow:0 8px 18px rgba(183,121,0,.2); }
.faculty-next-action>a:hover { transform:translateY(-2px); box-shadow:0 12px 24px rgba(22,131,88,.26); }
.admin-body.dark-mode .faculty-progress-panel,
.admin-body.dark-mode .faculty-next-action,
.admin-dashboard-body.dark-mode .faculty-progress-panel,
.admin-dashboard-body.dark-mode .faculty-next-action { background:linear-gradient(145deg,rgba(13,38,72,.94),rgba(7,23,46,.97)); border-color:rgba(96,165,250,.22); }
.admin-body.dark-mode :is(.faculty-focus-copy h3,.faculty-next-action h3),
.admin-dashboard-body.dark-mode :is(.faculty-focus-copy h3,.faculty-next-action h3) { color:#edf6ff; }
.admin-body.dark-mode :is(.faculty-focus-copy>p:not(.eyebrow),.faculty-next-action>div>p:not(.eyebrow),.faculty-next-meta),
.admin-dashboard-body.dark-mode :is(.faculty-focus-copy>p:not(.eyebrow),.faculty-next-action>div>p:not(.eyebrow),.faculty-next-meta) { color:#aebfd7; }
@media(max-width:900px){.faculty-dashboard-focus-grid{grid-template-columns:1fr}.faculty-next-action{min-height:235px}}
@media(max-width:600px){.faculty-progress-panel{grid-template-columns:1fr;padding:22px}.faculty-progress-chart{height:210px;margin-top:8px}.faculty-dashboard-focus-grid{margin:18px 0}}
@media(prefers-reduced-motion:reduce){.faculty-next-action>a{transition:none}.faculty-next-action>a:hover{transform:none}}

