  :is(.admin-body,.admin-dashboard-body,.dean-body,.program-head-body,.faculty-body):not(.dark-mode)
  .admin-header>.menu-toggle{
    border:1px solid rgba(15,118,110,.24) !important;
    background:linear-gradient(145deg,#ffffff,#e8f7f1) !important;
    color:#0f6048 !important;
    box-shadow:0 7px 18px rgba(15,96,72,.12) !important;
  }
  :is(.admin-body,.admin-dashboard-body,.dean-body,.program-head-body,.faculty-body):not(.dark-mode)
  .admin-header>.menu-toggle span{
    background:#0f6048 !important;
    color:#0f6048 !important;
    opacity:1 !important;
  }
