    border-color:#168358 !important;
    background:#dcf4e8 !important;
    color:#0b513d !important;
  }
  :is(.admin-body,.admin-dashboard-body,.dean-body,.program-head-body,.faculty-body).dark-mode
  .admin-header>.menu-toggle{
    border-color:rgba(96,165,250,.38) !important;
    background:#102b4d !important;
    color:#dbeafe !important;
