}

/* Dashboard Summary theme balance: clean emerald light mode, navy/slate dark mode. */
:is(.admin-body,.admin-dashboard-body):not(.dark-mode) .admin-content.admin-module>.admin-dashboard-unified{
  --overview-surface:#f8fcfa;
  --overview-surface-strong:#fff;
  --overview-border:rgba(22,131,88,.2);
