.questionnaire-editor-title{width:100%;padding:0!important;border:0!important;background:transparent!important;color:#17372c!important;font-size:clamp(1.2rem,1.7vw,1.6rem)!important;font-weight:850!important;line-height:1.25;box-shadow:none!important;outline:none}.questionnaire-editor-description{width:100%;min-height:44px;padding:7px 0!important;border:0!important;background:transparent!important;color:#647a71!important;font-size:.86rem!important;line-height:1.45;resize:none;box-shadow:none!important;outline:none}
