.questionnaire-editor-actions{display:flex;align-items:center;justify-content:flex-end;gap:9px;flex-wrap:wrap}.questionnaire-editor-actions button{min-height:44px;padding:0 15px;display:inline-flex;align-items:center;justify-content:center;gap:7px;border-radius:11px;font-size:.76rem;font-weight:850;transition:transform .18s ease,box-shadow .18s ease,background .18s ease}.questionnaire-add-category{border:1px solid #a9d7be;background:#edf9f2;color:#08734d}.questionnaire-save{border:1px solid #08734d;background:linear-gradient(135deg,#168358,#08734d);color:#fff;box-shadow:0 9px 20px rgba(8,115,77,.2)}.questionnaire-editor-actions button:hover{transform:translateY(-2px)}.questionnaire-add-category:hover{background:#daf3e5}.questionnaire-save:hover{box-shadow:0 13px 27px rgba(8,115,77,.28)}
.questionnaire-total-weight{min-width:76px;padding:7px 10px;display:grid;justify-items:center;border:1px solid;border-radius:11px;line-height:1}.questionnaire-total-weight b{font-size:.9rem}.questionnaire-total-weight small{margin-top:4px;font-size:.58rem;font-weight:800;text-transform:uppercase;letter-spacing:.035em}.questionnaire-total-weight.is-valid{border-color:#9bd8b8;background:#eaf9f1;color:#08734d}.questionnaire-total-weight.is-warning{border-color:#f0c86f;background:#fff7df;color:#925b00}
