.questionnaire-category-card-main{display:flex;align-items:center;gap:10px;flex:1;min-width:0}.questionnaire-category-number{flex:0 0 auto;color:#8ca198;font-size:.65rem;font-weight:900;letter-spacing:.06em}.questionnaire-category-toggle{flex:0 0 40px;width:40px;height:40px;display:grid;place-items:center;border:1px solid #168358;border-radius:11px;background:#168358;color:#fff;box-shadow:0 7px 15px rgba(22,131,88,.18);transition:transform .18s ease,background .18s ease}.questionnaire-category-toggle:hover{transform:scale(1.05);background:#08734d}.questionnaire-category-title-input{min-width:180px;flex:1;height:44px;padding:0 13px;border:1px solid transparent;border-radius:10px;background:transparent;color:#21332b;font-size:.9rem;font-weight:800;outline:none}.questionnaire-category-title-input:hover{border-color:#d3e4dc;background:#fff}.questionnaire-category-title-input:focus{border-color:#65b98f;background:#fff;box-shadow:0 0 0 3px rgba(22,131,88,.1)}
.questionnaire-category-weight{display:grid;grid-template-columns:auto 76px auto;align-items:center;gap:7px;color:#315848;font-size:.68rem;font-weight:850}.questionnaire-category-weight input{width:76px;height:42px;padding:0 8px;border:1px solid #bfdacb;border-radius:10px;background:#fff;color:#19392d;font-size:.9rem;font-weight:850;text-align:center;outline:none}.questionnaire-category-weight input:focus{border-color:#22a06b;box-shadow:0 0 0 3px rgba(34,160,107,.11)}.questionnaire-category-weight b{color:#168358}
