/* Polished questionnaire evaluation preview */
.evaluation-preview-panel {
  overflow: hidden;
  border: 1px solid #dbe7e2;
  border-radius: 22px;
  background: #fff;
  box-shadow: 0 18px 45px rgba(15, 69, 51, 0.08);
}

.evaluation-preview-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 24px 28px;
  border-bottom: 1px solid #deebe6;
  background: linear-gradient(135deg, #f5fbf8 0%, #fff 70%);
}

.evaluation-preview-heading { display: flex; align-items: center; gap: 14px; }
.evaluation-preview-heading-icon {
  display: grid; place-items: center; width: 46px; height: 46px; flex: 0 0 46px;
  border-radius: 14px; color: #087a50; background: #dcf5e9; border: 1px solid #b9e6d1;
}
.evaluation-preview-eyebrow { display: block; color: #16805c; font-size: 11px; font-weight: 800; letter-spacing: .09em; text-transform: uppercase; }
.evaluation-preview-heading h2 { margin: 2px 0; color: #142921; font-size: 20px; }
.evaluation-preview-heading p { margin: 0; color: #687a73; font-size: 13px; }
.evaluation-preview-picker { min-width: 245px; }
.evaluation-preview-picker label { display: block; margin: 0 0 6px 2px; color: #5d7069; font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: .06em; }
.evaluation-preview-picker select { width: 100%; min-height: 48px; padding: 0 42px 0 14px; border: 1px solid #cbded6; border-radius: 13px; color: #23342e; background-color: #fff; font-weight: 650; outline: none; }
.evaluation-preview-picker select:focus { border-color: #19976a; box-shadow: 0 0 0 4px rgba(25, 151, 106, .12); }
.evaluation-preview-content { padding: 28px; }
.evaluation-preview-intro { display: flex; justify-content: space-between; gap: 28px; margin-bottom: 24px; }
.evaluation-preview-intro h3 { margin: 5px 0 6px; color: #172a23; font-size: 22px; }
.evaluation-preview-intro p { max-width: 700px; margin: 0; color: #61736c; line-height: 1.55; }
.evaluation-preview-scale { display: grid; grid-template-columns: repeat(3, auto); gap: 7px; align-self: start; min-width: 340px; }
.evaluation-preview-scale > span { grid-column: 1 / -1; color: #71827b; font-size: 10px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
.evaluation-preview-scale div { padding: 7px 9px; border: 1px solid #dce9e4; border-radius: 10px; color: #63756e; background: #f7faf9; font-size: 10px; white-space: nowrap; }
.evaluation-preview-scale b { color: #087a50; margin-right: 3px; }
.evaluation-preview-category { overflow: hidden; margin-top: 18px; border: 1px solid #dce8e3; border-radius: 18px; background: #fbfdfc; }
.evaluation-preview-category-head { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 14px; padding: 18px 20px; border-bottom: 1px solid #deebe6; background: linear-gradient(90deg, #edf8f3, #f9fcfb); }
.evaluation-preview-category-number { display: grid; place-items: center; width: 40px; height: 40px; border-radius: 12px; color: #fff; background: linear-gradient(135deg, #087a50, #19a36f); font-size: 12px; font-weight: 800; box-shadow: 0 7px 16px rgba(8, 122, 80, .2); }
.evaluation-preview-category-head h4 { margin: 3px 0 0; color: #1c2e27; font-size: 15px; line-height: 1.4; }
.evaluation-preview-weight { padding: 8px 11px; border-radius: 10px; color: #60746c; background: #fff; border: 1px solid #d4e5de; font-size: 11px; white-space: nowrap; }
.evaluation-preview-weight b { color: #087a50; font-size: 14px; margin-right: 3px; }
.evaluation-preview-category-description { margin: 0; padding: 13px 20px; color: #667a72; background: #fff; border-bottom: 1px solid #e5eeea; font-size: 12px; }
.evaluation-preview-questions { padding: 8px 12px 12px; }
.evaluation-preview-question { display: grid; grid-template-columns: 34px minmax(0, 1fr) auto; align-items: center; gap: 12px; min-height: 64px; margin-top: 6px; padding: 10px 10px 10px 8px; border: 1px solid transparent; border-radius: 13px; transition: .18s ease; }
.evaluation-preview-question:hover { border-color: #cfe2da; background: #fff; box-shadow: 0 5px 16px rgba(24, 74, 57, .06); }
.evaluation-preview-question.is-rated { background: #f2faf6; border-color: #cce9db; }
.evaluation-preview-question-number { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 9px; color: #207457; background: #e8f4ef; font-size: 11px; font-weight: 800; }
.evaluation-preview-question-copy p { margin: 0; color: #455b52; font-size: 13px; line-height: 1.45; }
.evaluation-preview-ratings { display: grid; grid-template-columns: repeat(5, 40px); gap: 5px; }
.evaluation-preview-ratings button { width: 40px; height: 40px; border: 1px solid #d3e3dc; border-radius: 11px; color: #14704f; background: #edf6f2; font-size: 12px; font-weight: 800; cursor: pointer; transition: transform .15s ease, background .15s ease, border-color .15s ease, box-shadow .15s ease; }
.evaluation-preview-ratings button:hover { transform: translateY(-2px); border-color: #43ae84; background: #e2f4ec; box-shadow: 0 5px 12px rgba(16, 115, 78, .12); }
.evaluation-preview-ratings button.is-selected { color: #fff; border-color: #087a50; background: linear-gradient(145deg, #087a50, #159968); box-shadow: 0 6px 14px rgba(8, 122, 80, .25); }

