@media (max-width: 900px) {
  .evaluation-preview-toolbar, .evaluation-preview-intro { align-items: stretch; flex-direction: column; }
  .evaluation-preview-picker, .evaluation-preview-scale { width: 100%; min-width: 0; }
  .evaluation-preview-question { grid-template-columns: 34px minmax(0, 1fr); }
