/* Interactive confirmation modal polish */
.app-confirm-modal {
  isolation: isolate;
  animation: appConfirmEnter 220ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.app-confirm-icon {
  position: relative;
  animation: appConfirmIconFloat 2.8s ease-in-out infinite;
  box-shadow:
    0 0 0 6px rgba(37, 99, 235, 0.07),
    0 10px 26px rgba(37, 99, 235, 0.24),
    0 0 24px rgba(59, 130, 246, 0.2);
}

.app-confirm-icon::after {
  content: "";
  position: absolute;
  inset: -7px;
  z-index: -1;
  border: 1px solid rgba(59, 130, 246, 0.2);
  border-radius: 20px;
  animation: appConfirmGlow 2.8s ease-in-out infinite;
}

.app-confirm-modal.warning .app-confirm-icon {
  box-shadow:
    0 0 0 6px rgba(245, 158, 11, 0.08),
    0 10px 26px rgba(180, 83, 9, 0.24),
    0 0 24px rgba(245, 158, 11, 0.2);
}

.app-confirm-modal.danger .app-confirm-icon {
  box-shadow:
    0 0 0 6px rgba(220, 38, 38, 0.08),
    0 10px 26px rgba(220, 38, 38, 0.24),
    0 0 24px rgba(239, 68, 68, 0.22);
}

.app-confirm-close {
  top: 1rem !important;
  right: 1rem !important;
  width: 2.75rem !important;
  min-width: 2.75rem !important;
  height: 2.75rem !important;
  min-height: 2.75rem !important;
  margin: 0 !important;
  border: 1px solid rgba(148, 163, 184, 0.28) !important;
  border-radius: 14px !important;
  background: rgba(248, 250, 252, 0.94) !important;
  color: #526174 !important;
  box-shadow: 0 8px 20px rgba(15, 23, 42, 0.08) !important;
  padding: 0 !important;
  transform: none;
  transition: transform 160ms ease, border-color 160ms ease, background 160ms ease, color 160ms ease, box-shadow 160ms ease;
}

.app-confirm-close svg {
  display: block;
  width: 20px;
  height: 20px;
  stroke-width: 2.35;
}

.app-confirm-close:hover:not(:disabled) {
  border-color: rgba(220, 38, 38, 0.3) !important;
  background: #fff1f2 !important;
  color: #dc2626 !important;
  box-shadow:
    0 0 0 4px rgba(239, 68, 68, 0.08),
    0 10px 24px rgba(220, 38, 38, 0.15) !important;
  transform: translateY(-2px) rotate(3deg);
}

.app-confirm-close:active:not(:disabled) {
  transform: translateY(0) scale(0.92);
}

.app-confirm-close:focus-visible {
  outline: 3px solid rgba(37, 99, 235, 0.3);
  outline-offset: 3px;
}

.app-confirm-actions button {
  transition: transform 160ms ease, box-shadow 160ms ease, border-color 160ms ease, background 160ms ease;
}

.app-confirm-actions button:hover:not(:disabled) {
  transform: translateY(-2px);
}

.app-confirm-submit:hover:not(:disabled) {
  filter: brightness(1.06);
  box-shadow:
    0 14px 30px rgba(37, 99, 235, 0.32),
    0 0 20px rgba(59, 130, 246, 0.18);
}

.app-confirm-cancel:hover:not(:disabled) {
  border-color: rgba(100, 116, 139, 0.42);
  background: #f8fafc;
  box-shadow: 0 10px 22px rgba(15, 23, 42, 0.09);
}

.app-confirm-actions button:active:not(:disabled) {
  transform: translateY(0) scale(0.97);
}

